        // boundary (no blending). One dim → solid. None → brand fallback.
        function projectStripStyle(p) {
            var cols = projectDimHexes(p);
            if (!cols.length) cols = ['#5a9fd4', '#8e3b5f'];
            if (cols.length === 1) return 'background:' + cols[0] + ';';
            var seg = 100 / cols.length, parts = [];
            cols.forEach(function(c, i) { parts.push(c + ' ' + (seg * i).toFixed(2) + '%'); parts.push(c + ' ' + (seg * (i + 1)).toFixed(2) + '%'); });
            return 'background:linear-gradient(158deg,' + parts.join(',') + ');';
        }

        // ── Cadence / flavor ──────────────────────────────────────────────
        function prFreqLabel(p) { var c = p && p.cadence; return (c && c.type === 'recurring') ? 'Repeating' : 'One-off'; }
        function questFlavor(p) {
            var c = p.currentCycle || 1, days = questDaysActive(p), stats = questStats(p);
            if (p.status === 'completed') return 'Sealed. A finished quest.';
            if (c >= 12) return c + ' cycles in — you don’t skip this anymore.';
            if (c >= 6) return c + ' cycles deep. This is who you are now.';
            if (c >= 3) return 'Cycle ' + c + ' — the habit is forming.';
            if (c === 2) return 'Second time around. Momentum.';
            if (stats.total > 0 && stats.done === stats.total) return 'Everything’s done. Seal it.';
            if (days >= 21) return 'Three weeks of showing up.';
            return '';
        }
        function cadenceFooterText(p) {
            var isRecurring = p.cadence && p.cadence.type === 'recurring';
            if (!isRecurring) return 'One-off quest — finishes when everything is done.';
            var hist = p.cycleHistory || [];
            var cycleNum = p.currentCycle || 1;
            if (!hist.length) return 'Cycle ' + cycleNum + ' — seals when everything in it is done.';
            var last = hist[hist.length - 1];
            var days = (last.startedAt && last.completedAt) ? Math.max(1, Math.round((new Date(last.completedAt) - new Date(last.startedAt)) / 86400000)) : null;
            return 'Cycle ' + cycleNum + (days !== null ? ' — last one took ' + days + ' day' + (days === 1 ? '' : 's') + '.' : '.');
        }

        // ═══ Passive progress (from completeActivity/undoActivity) ═══
        // A linked activity's own XP is always paid immediately through the
        // normal completeActivity path — untouched here. The quest's 20%
        // bonus is NOT trickled in per completion anymore; it's paid as one
        // lump sum when the quest/cycle is actually sealed (see
        // completeProjectCycle + payQuestBonus below). This hook only keeps
        // each linked leaf's progress (completedCount) in sync with real
        // completions, wherever they happen — main tracker, another quest,
        // this quest — so the tree/pipeline UI stays accurate.
        function updateQuestProgress(activityId) {
            var projects = (window.userData && window.userData.projects) || [];
            if (!projects.length) return;
            projects.forEach(function(p) {
                if (p.status !== 'active') return;
                migrateProject(p);
                allLeaves(p).forEach(function(leaf) {
                    if (leaf.type === 'activity' && leaf.linkedActivityId === activityId && (leaf.completedCount || 0) < itemReq(leaf)) {
                        leaf.completedCount = (leaf.completedCount || 0) + 1;
                    }
                });
                settleAll(p);
            });
        }
        function undoQuestProgress(activityId) {
            var projects = (window.userData && window.userData.projects) || [];
            if (!projects.length) return;
            projects.forEach(function(p) {
                if (p.status !== 'active') return;
                migrateProject(p);
                allLeaves(p).forEach(function(leaf) {
                    if (leaf.type === 'activity' && leaf.linkedActivityId === activityId && (leaf.completedCount || 0) > 0) {
                        leaf.completedCount = Math.max(0, (leaf.completedCount || 0) - 1);
                    }
                });
                settleAll(p); // note: undo can't un-bank an already-banked rep (hard-reset model)
            });
        }

        // ═══ Lump-sum quest bonus — paid once, on actual completion ═══
        // One ledger, the user's: currentXP / totalXP and the same level-up
        // loop used everywhere else XP is granted. The quest no longer keeps
        // a parallel score of its own — a quest is scaffolding, not a thing
        // that accumulates.
        function payQuestBonus(p, amount) {
            amount = Math.max(0, Math.round(amount || 0));
            if (amount <= 0) return;
            if (!window.userData) return;
            window.userData.currentXP = (window.userData.currentXP || 0) + amount;
            window.userData.totalXP = (window.userData.totalXP || 0) + amount;
            var leveledUp = false;
            while (window.userData.currentXP >= calculateXPForLevel(window.userData.level) && window.userData.level < 100) {
                window.userData.currentXP -= calculateXPForLevel(window.userData.level);
                window.userData.level += 1;
                leveledUp = true;
            }
            if (window.userData.level >= 100) window.userData.level = 100;
            if (leveledUp) {
                window.userData.cardLevelStartedAt = window.userData.levelStartedAt || new Date(Date.now() - 5 * 60 * 1000).toISOString();
                window.userData.levelStartedAt = new Date().toISOString();
                try { showLevelUpAnimation(); } catch (e) {}
            }
            try { if (typeof updateDashboard === 'function') updateDashboard(); } catch (e) {}
        }
        // ── Quest Grit grant ──────────────────────────────────────────────
        // Routed through gritAwardOnce, which is the Grit system's own
        // idempotency primitive (§8.5): the marker is checked and set inside
        // gritState().awarded, so a double-tap or a second device replaying
        // the same seal pays once. A recurring quest keys its marker on the
        // cycle number, so cycle 2 is a genuinely new award and cycle 1 can
        // never re-pay.
        //
        // Grit is one-way here. There is deliberately no refund counterpart to
        // this function: nothing in the quest lifecycle may reduce a user's
        // Grit balance.
        function payQuestGrit(p, amount, cycleNum) {
            amount = Math.max(0, Math.round(amount || 0));
            if (amount <= 0) return 0;
            if (typeof gritAwardOnce !== 'function') return 0;
            var isRec = p.cadence && p.cadence.type === 'recurring';
            var marker = 'quest:' + p.id + (isRec ? ':cycle:' + cycleNum : '');
            var paid = gritAwardOnce(marker, amount, 'quest_completion',
                { projectId: p.id, projectTitle: p.name || '', cycleNumber: cycleNum },
                (isRec ? 'Sealed cycle ' + cycleNum + ' — ' : 'Completed ') + (p.name || 'quest'));
            return paid ? amount : 0;
        }

        // ═══ LIST VIEW ══════════════════════════════════════════════════════
        function renderProjects() {
            _buildActIdx();
            var lv = document.getElementById('projectsListView');
            var dv = document.getElementById('projectsDetailView');
            if (dv) { dv.style.display = 'none'; dv.innerHTML = ''; }
            if (lv) lv.style.display = '';
            var container = document.getElementById('projectsContainer');
            if (!container) return;

            var projects = getProjects();
            if (projects.length === 0) {
                container.innerHTML =
                    '<div class="pr-empty">' +
                        '<div class="pr-empty-pipe">' +
                            '<span class="pr-empty-node done"></span><span class="pr-empty-line"></span>' +
                            '<span class="pr-empty-node cur"></span><span class="pr-empty-line dim"></span>' +
                            '<span class="pr-empty-node"></span><span class="pr-empty-line dim"></span>' +
                            '<span class="pr-empty-node"></span>' +
                        '</div>' +
                        '<div class="pr-empty-title">Turn a big goal into a quest</div>' +
                        '<div class="pr-empty-text">A Quest is built from <strong>groups</strong> of activities and tasks — a checklist, a sequence, or a repeating pipeline — and pays you bonus XP as you go. One group for a simple checklist, or chain several — Research → Script → Shoot → Edit → Publish — and repeat it every cycle.</div>' +
                        '<button class="pr-empty-cta" onclick="openProjectModal()">' +
                            '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>' +
                            'Start your first quest' +
                        '</button>' +
                        '<div class="qc-empty-line">Not sure how to break it up? <button class="qc-empty-link" onclick="openQuestComposer()">Let me plan it for you</button></div>' +
                    '</div>';
                return;
            }

            var active    = projects.filter(function(p) { return p.status === 'active' || !p.status; });
            var paused    = projects.filter(function(p) { return p.status === 'paused'; });
            var completed = projects.filter(function(p) { return p.status === 'completed'; });
            var archived  = projects.filter(function(p) { return p.status === 'archived'; });

            if (!window._prSectionOpen) window._prSectionOpen = { paused: false, completed: false, archived: false };
            var open = window._prSectionOpen;
            var chev = function(isOpen) { return '<svg class="pr-sec-chev' + (isOpen ? ' open' : '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>'; };
            var cards = function(list) { return list.map(renderProjectCard).join(''); };
            var html = '';
            if (active.length) {
                html += '<div class="pr-sec-head"><div class="pr-sec-head-left"><h3 class="pr-sec-title">Active</h3><span class="pr-sec-count">' + active.length + '</span></div></div>';
                html += cards(active);
            }
            [['paused', 'Paused', paused, ''], ['completed', 'Completed', completed, ' pr-count-green'], ['archived', 'Archived', archived, '']].forEach(function(sec) {
                var key = sec[0], label = sec[1], list = sec[2], cls = sec[3];
                if (!list.length) return;
                html += '<div class="pr-sec-head pr-collapsible" onclick="toggleProjectsSection(\'' + key + '\')">' +
                            '<div class="pr-sec-head-left"><h3 class="pr-sec-title">' + label + '</h3>' +
                            '<span class="pr-sec-count' + cls + '">' + list.length + '</span></div>' + chev(open[key]) + '</div>' +
                        '<div style="display:' + (open[key] ? 'block' : 'none') + ';">' + cards(list) + '</div>';
            });
            container.innerHTML = html;
        }
        window.toggleProjectsSection = function(key) {
            if (!window._prSectionOpen) window._prSectionOpen = { paused: false, completed: false, archived: false };
            window._prSectionOpen[key] = !window._prSectionOpen[key];
            renderProjects();
        };

        // One row per group on the quest card. A sequence is drawn as a path —
        // dots strung along a rail with the live step lit — because order is the
        // whole point of it. A list has no order, and dots bunched at the left
        // end of that same rail read as a sequence someone abandoned early, so
        // it gets its own primitive: one segment per item, spread across the
        // full row, each lighting up as it is ticked off, with the tally beside
        // them. Same slot, same width, no implied direction.
        function renderThreadRow(g) {
            var kids = g.children || [];
            var rep = (g.repeat || 1) > 1;
            var done = kids.filter(nodeDone).length;
            var line;
            if (g.ordered) {
                var cur = currentIndex(g);
                var dots = kids.map(function(c, idx) {
                    var cls = nodeDone(c) ? 'pr-tdot-done' : (idx === cur ? 'pr-tdot-cur' : '');
                    return '<span class="pr-tdot ' + cls + '"></span>';
                }).join('');
                line = '<span class="pr-thread-rail"></span><div class="pr-thread-dots">' + dots + '</div>';
            } else {
                var segs = kids.map(function(c) {
                    return '<span class="pr-tseg' + (nodeDone(c) ? ' pr-tseg-done' : '') + '"></span>';
                }).join('');
                line = '<div class="pr-thread-segs">' + segs + '</div>' +
                    '<span class="pr-thread-frac">' + done + '/' + kids.length + '</span>';
            }
            var tagCls = rep ? 'pr-tag-rep' : (g.ordered ? 'pr-tag-ord' : 'pr-tag-un');
            var tagText = rep ? ('×' + g.repeat) : (g.ordered ? 'sequence' : 'list');
            return '<div class="pr-thread' + (g.ordered ? ' pr-thread-ordered' : ' pr-thread-un') + '">' +
                '<span class="pr-thread-name">' + escapeHtml(g.name || 'Group') + '</span>' +
                '<div class="pr-thread-line">' + line + '</div>' +
                '<span class="pr-thread-tag ' + tagCls + '">' + tagText + '</span>' +
            '</div>';
        }

        function renderProjectCard(p) {
            var counts = questCounts(p);
            var stats = questStats(p);
            var potential = questPotentialBonus(p);
            var gritPotential = questGritBonus(p);
            var pct = stats.total ? Math.round(stats.done / stats.total * 100) : 0;
            var statusCls = p.status === 'completed' ? ' pr-card-gold' : p.status === 'archived' ? ' pr-card-muted' : p.status === 'paused' ? ' pr-card-paused' : '';
            var unit = counts.tasks === 0 ? 'activities' : (counts.activities === 0 ? 'tasks' : 'items');
            var groupCount = (p.groups || []).length;

            var bits = [];
            if (potential > 0) bits.push('<span class="pr-cd-bonus">+' + potential + ' XP</span>');
            if (gritPotential > 0) bits.push('<span class="pr-cd-grit">+' + gritPotential + ' Grit</span>');
            bits.push('<span>' + escapeHtml(prFreqLabel(p)) + '</span>');
            bits.push('<span>' + groupCount + ' group' + (groupCount === 1 ? '' : 's') + '</span>');
            var detailLine = bits.join('<span class="pr-cd-sep">·</span>');

            var chip = '';
            if (p.status === 'paused') chip = '<span class="pr-chip pr-chip-muted">Paused</span>';
            if (p.status === 'completed') chip = '<span class="pr-chip pr-chip-gold">Complete</span>';

            var editSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>';
            var trashSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg>';

            var threadsHtml = (p.groups || []).map(renderThreadRow).join('');

            return '' +
            '<div class="pr-card' + statusCls + '" onclick="openProjectDetail(\'' + p.id + '\')">' +
                '<span class="pr-strip" style="' + projectStripStyle(p) + '"></span>' +
                '<div class="pr-card-body">' +
                    '<div class="pr-card-top">' +
                        '<span class="pr-card-emoji">' + renderStoredIcon(p.icon || p.emoji || DEFAULT_QUEST_ICON) + '</span>' +
                        '<div class="pr-card-headings">' +
                            '<div class="pr-card-name-row">' +
                                '<h3 class="pr-card-name">' + escapeHtml(p.name || 'Untitled quest') + '</h3>' +
                            '</div>' +
                            '<div class="pr-card-detailline">' + detailLine + '</div>' +
                        '</div>' +
                        '<div class="pr-card-actions">' +
                            '<button class="pr-icon-btn" onclick="event.stopPropagation();openProjectModal(\'' + p.id + '\')" title="Edit" aria-label="Edit quest">' + editSvg + '</button>' +
                            '<button class="pr-icon-btn pr-icon-danger" onclick="event.stopPropagation();deleteProject(\'' + p.id + '\')" title="Delete" aria-label="Delete quest">' + trashSvg + '</button>' +
                        '</div>' +
                    '</div>' +
                    '<div class="pr-card-progrow">' +
                        '<span class="pr-card-progcount">' + stats.done + '/' + stats.total + ' ' + unit + ' done</span>' +
                        '<span class="pr-card-progpct">' + pct + '%</span>' +
                    '</div>' +
                    '<div class="pr-prog"><div class="pr-prog-fill" style="width:' + pct + '%;"></div></div>' +
                    (chip ? '<div class="pr-card-statuschip">' + chip + '</div>' : '') +
                    (threadsHtml ? '<div class="pr-card-threads">' + threadsHtml + '</div>' : '') +
                '</div>' +
            '</div>';
        }

        // ═══ DETAIL VIEW ════════════════════════════════════════════════════
        var _prFocusNode = {};    // `${pid}:${groupId}` -> nodeId — which pipeline node the "Do now" panel targets
        var _prLeafExpanded = {}; // leafId -> bool (inline activity detail)
        var _prFlashRep = null, _prFlashStep = null; // one-shot gold flash targets
        var _prNextDone = {}, _prNextSkip = {};       // What's Next state, per project id

        window.openProjectDetail = function(id) {
            window._openProjectId = id;
            try { history.pushState({ questDetail: id }, ''); } catch (e) {}
            renderProjectDetail(id);
            try { window.scrollTo(0, 0); } catch (e) {}
        };
        window.closeProjectDetail = function(fromPop) {
            window._openProjectId = null; _prNextDone = {};
            renderProjects();
            try { window.scrollTo(0, 0); } catch (e) {}
            if (!fromPop) { try { if (history.state && history.state.questDetail) history.back(); } catch (e) {} }
        };
        if (!window._prPopBound) {
            window._prPopBound = true;
            window.addEventListener('popstate', function() {
                var dv = document.getElementById('projectsDetailView');
                if (dv && dv.style.display !== 'none' && window._openProjectId) window.closeProjectDetail(true);
            });
        }

        function renderProjectDetail(id) {
            _buildActIdx();
            var p = findProject(id);
            var lv = document.getElementById('projectsListView');
            var dv = document.getElementById('projectsDetailView');
            if (!dv) return;
            if (!p) { window._openProjectId = null; if (lv) lv.style.display = ''; dv.style.display = 'none'; dv.innerHTML = ''; renderProjects(); return; }
            if (lv) lv.style.display = 'none';
            dv.style.display = '';
            var prevScroll = window.scrollY;

            var stats = questStats(p);
            var potential = questPotentialBonus(p);
            var gritPotential = questGritBonus(p);
            var flavor = questFlavor(p);
            var pct = stats.total ? Math.round(stats.done / stats.total * 100) : 0;
            var sealed = p.status === 'completed';
            var groupCount = (p.groups || []).length;
            var dim = p.dimensionId ? (window.userData.dimensions || []).find(function(d) { return d.id === p.dimensionId; }) : null;
            var dimHex = dim ? DIM_HEX_MAP[dim.color] : null;

            // No back row: it repeated the page title one line under it, and the
            // Quests tab and the system back gesture both already return to the
            // list. Edit rides in the hero card's own top-right corner instead
            // of floating above it.
            var header =
                '<div class="pr-detail-head' + (sealed ? ' pr-detail-sealed' : '') + '">' +
                    '<span class="pr-strip" style="' + projectStripStyle(p) + '"></span>' +
                    '<button class="pr-icon-btn pr-detail-edit" onclick="openProjectModal(\'' + p.id + '\')" aria-label="Edit quest"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>' +
                    '<div class="pr-detail-top">' +
                        '<span class="pr-detail-emoji">' + renderStoredIcon(p.icon || p.emoji || DEFAULT_QUEST_ICON) + '</span>' +
                        '<div class="pr-detail-titles">' +
                            '<div class="pr-detail-name-row">' +
                                '<h1 class="pr-detail-name">' + escapeHtml(p.name || 'Untitled quest') + '</h1>' +
                                (dim ? '<span class="pr-detail-dim" style="background:' + hexA(dimHex, .16) + ';color:' + dimHex + ';">' + escapeHtml(dim.name) + '</span>' : '') +
                            '</div>' +
                            (flavor ? '<div class="pr-detail-flavor">' + escapeHtml(flavor) + '</div>' : '') +
                            (p.description ? '<div class="pr-detail-desc">' + escapeHtml(p.description) + '</div>' : '') +
                            '<div class="pr-detail-meta">' +
                                (potential > 0 ? '<span class="pr-detail-meta-g">+' + potential + ' XP</span>' + (gritPotential > 0 ? ' <span class="pr-detail-meta-grit">+' + gritPotential + ' Grit</span>' : '') + ' bonus <span class="pr-detail-meta-dot">·</span> ' : '') +
                                escapeHtml(prFreqLabel(p)) + ' <span class="pr-detail-meta-dot">·</span> ' + groupCount + ' group' + (groupCount === 1 ? '' : 's') +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                    (sealed
                        ? '<div class="pr-sealed-badge">' + prCheckSvg() + 'Quest complete — XP banked</div>'
                        : '<div class="pr-detail-prog-row"><span class="pr-detail-prog-lbl">Progress</span><span class="pr-detail-prog-num">' + pct + '%</span></div><div class="pr-prog pr-prog-lg"><div class="pr-prog-fill" style="width:' + pct + '%;"></div></div>'
                    ) +
                '</div>';

            var whatsNext = renderWhatsNext(p);
            var groupsHtml = (p.groups || []).map(renderGroupBlock.bind(null, p)).join('');
            var footer = renderProjectFooter(p);

            dv.innerHTML = header + whatsNext + '<div class="pr-groups">' + groupsHtml + '</div>' + footer;
            _prFlashRep = null; _prFlashStep = null;
            requestAnimationFrame(function() { centerPipes(dv); window.scrollTo(0, prevScroll); });
        }

        function centerPipes(root) {
            (root || document).querySelectorAll('.pr-pipe[data-scroll]').forEach(function(pipe) {
                var cur = pipe.querySelector('.pr-step-cur') || pipe.querySelector('.pr-step');
                if (cur) { try { pipe.scrollTo({ left: cur.offsetLeft - (pipe.clientWidth - cur.offsetWidth) / 2, behavior: 'auto' }); } catch (e) {} }
            });
        }

        // ── What's Next — recommends the nearest-to-done actionable leaf across
        //    every top-level group (ordered groups via their live step, unordered
        //    groups via first-incomplete), skipping unperformable items and
        //    advancing past an item after one completion. ──────────────────────
        function itemPerformable(leaf) {
            if (leafDone(leaf)) return false;
            if (leaf.type === 'task') return true;
            var act = leaf.linkedActivityId ? findActivityById(leaf.linkedActivityId) : null;
            if (!act) return true;
            if (typeof canCompleteActivity === 'function' && !canCompleteActivity(act)) return false;
            var allowMulti = act.allowMultiplePerDay && act.frequency !== 'occasional';
            if (typeof isCompletedToday === 'function' && isCompletedToday(act) && !allowMulti && (leaf.completedCount || 0) >= 1) return false;
            return true;
        }
        function firstPerformableLeaf(node, skip) {
            if (node.kind !== 'group') { if (nodeDone(node) || skip[node.id]) return null; return itemPerformable(node) ? node : null; }
            var kids = node.children || [];
            if (node.ordered) {
                var idx = currentIndex(node); if (idx < 0) return null;
                return firstPerformableLeaf(kids[idx], skip);
            }
            for (var i = 0; i < kids.length; i++) { if (nodeDone(kids[i])) continue; var r = firstPerformableLeaf(kids[i], skip); if (r) return r; }
            return null;
        }
        function computeWhatsNext(p) {
            if (!_prNextSkip[p.id]) _prNextSkip[p.id] = {};
            var skip = _prNextSkip[p.id];
            function gather(useSkip) {
                var cands = [];
                (p.groups || []).forEach(function(g) {
                    if (nodeDone(g)) return;
                    var leaf = firstPerformableLeaf(g, useSkip ? skip : {});
                    if (!leaf) return;
                    var remaining = (g.children || []).filter(function(c) { return !nodeDone(c); }).length;
                    cands.push({ group: g, leaf: leaf, remaining: remaining });
                });
                return cands;
            }
            var cands = gather(true);
            if (!cands.length) { _prNextSkip[p.id] = {}; cands = gather(false); }
            if (!cands.length) return null;
            cands.sort(function(a, b) { return a.remaining - b.remaining; });
            return cands[0];
        }
        window.tapNextUp = async function(pid, leafId) {
            var p = findProject(pid); if (!p) return;
            if (!_prNextSkip[p.id]) _prNextSkip[p.id] = {};
            _prNextSkip[p.id][leafId] = true;
            _prNextDone[p.id] = leafId;
            await window.bumpLeaf(pid, leafId);
        };
        window.undoNextUp = async function(pid, leafId) {
            var p = findProject(pid); if (!p) return;
            if (_prNextSkip[p.id]) delete _prNextSkip[p.id][leafId];
            if (_prNextDone[p.id] === leafId) _prNextDone[p.id] = null;
            await window.undoLeaf(pid, leafId);
        };
        function renderWhatsNext(p) {
            if (p.status !== 'active') return '';
            var doneHtml = '';
            var doneId = _prNextDone[p.id];
            if (doneId) {
                var di = findNode(p, doneId);
                if (di) {
                    doneHtml = '<div class="pr-next pr-next-donecard">' +
                        '<span class="pr-next-donecheck">' + prCheckSvg() + '</span>' +
                        '<div class="pr-next-main"><div class="pr-next-kicker pr-next-kicker-done">DONE</div><div class="pr-next-name pr-next-name-done">' + escapeHtml(itemName(di)) + '</div></div>' +
                        '<button class="pr-next-undo" onclick="event.stopPropagation();undoNextUp(\'' + p.id + '\',\'' + doneId + '\')">Undo</button>' +
                    '</div>';
                } else { _prNextDone[p.id] = null; }
            }
            var next = computeWhatsNext(p);
            var liveHtml;
            if (!next) {
                if (projectCycleReady(p)) {
                    var isRec = p.cadence && p.cadence.type === 'recurring';
                    liveHtml = '<div class="pr-next pr-next-ready" onclick="completeProjectCycle(\'' + p.id + '\')">' +
                        '<div class="pr-next-main"><div class="pr-next-kicker">READY</div>' +
                        '<div class="pr-next-name">' + (isRec ? 'Seal this cycle' : 'Mark this quest complete') + '</div>' +
                        '<div class="pr-next-crumb">Everything is done</div></div>' +
                        '<div class="pr-next-go">' + prArrowSvg() + '</div></div>';
                } else {
                    liveHtml = '<div class="pr-next pr-next-caught"><div class="pr-next-main"><div class="pr-next-kicker">CAUGHT UP</div>' +
                        '<div class="pr-next-name">Nothing to log right now</div>' +
                        '<div class="pr-next-crumb">Come back later, or finish the rest below</div></div></div>';
                }
            } else {
                var leaf = next.leaf;
                var crumb = crumbFor(p, next.group, leaf);
                if (next.remaining > 1) crumb += ' <span class="pr-next-left">· ' + next.remaining + ' left</span>';
                var req = itemReq(leaf), cc = Math.max(0, leaf.completedCount || 0);
                var counter = req > 1 ? '<span class="pr-next-count">' + cc + '/' + req + '</span>' : '';
                liveHtml = '<div class="pr-next pr-next-live" onclick="tapNextUp(\'' + p.id + '\',\'' + leaf.id + '\')">' +
                    '<div class="pr-next-main"><div class="pr-next-kicker">NEXT UP</div>' +
                    '<div class="pr-next-name">' + escapeHtml(itemName(leaf)) + counter + '</div>' +
                    '<div class="pr-next-crumb">' + crumb + '</div></div>' +
                    '<div class="pr-next-go">' + prCheckSvg() + '</div></div>';
            }
            return '<div class="pr-next-stack">' + doneHtml + liveHtml + '</div>';
        }

        // ── Group / pipeline / checklist rendering (recursive) ─────────────
        function renderRepDots(g) {
            var h = '<div class="pr-reps"><span class="pr-reps-label">' + escapeHtml(g.name || 'Group') + ' ' + Math.min((g.repsDone || 0) + (nodeDone(g) ? 0 : 1), g.repeat) + ' of ' + g.repeat + '</span><div class="pr-rep-dots">';
            for (var i = 0; i < g.repeat; i++) {
                var cls = i < (g.repsDone || 0) ? 'pr-rep-done' : (i === (g.repsDone || 0) && !nodeDone(g) ? 'pr-rep-cur' : '');
                var flash = (_prFlashRep === g.id && i === (g.repsDone || 0) - 1) ? ' pr-rep-flash' : '';
                h += '<span class="pr-rep-dot ' + cls + flash + '">' + (i < (g.repsDone || 0) ? prCheckSvg() : (i + 1)) + '</span>';
            }
            h += '</div></div>';
            return h;
        }
        function currentFocusIndex(p, g) {
            var key = p.id + ':' + g.id;
            var focusId = _prFocusNode[key];
            if (focusId) { var idx = (g.children || []).findIndex(function(c) { return c.id === focusId; }); if (idx >= 0) return idx; }
            return currentIndex(g);
        }
        function renderPipelineRow(p, g) {
            var cur = currentIndex(g);
            var focusIdx = currentFocusIndex(p, g);
            var kids = g.children || [];
            var h = '<div class="pr-pipe-wrap"><div class="pr-pipe"' + (kids.length > 3 ? ' data-scroll' : '') + '>';
            kids.forEach(function(c, idx) {
                var cdone = nodeDone(c);
                var cls = cdone ? 'pr-step-done' : (idx === cur ? 'pr-step-cur' : 'pr-step-future');
                if (idx === focusIdx && idx !== cur) cls += ' pr-step-focus';
                var inner, badge = '';
                if (cdone) inner = prCheckSvg();
                else if (c.kind === 'group') {
                    var d = (c.children || []).filter(nodeDone).length;
                    inner = '<span class="pr-node-frac">' + d + '/' + (c.children || []).length + '</span>';
                    badge = '<span class="pr-node-badge">' + (c.children || []).length + '</span>';
                } else if (itemReq(c) > 1) {
                    inner = '<span class="pr-node-frac">' + (c.completedCount || 0) + '/' + itemReq(c) + '</span>';
                } else {
                    inner = String(idx + 1);
                }
                var flash = (_prFlashStep === c.id) ? ' pr-step-flash' : '';
                var name = c.kind === 'group' ? (c.name || 'Group') : itemName(c);
                h += '<button type="button" class="pr-step ' + cls + flash + '" onclick="tapPipelineNode(\'' + p.id + '\',\'' + g.id + '\',\'' + c.id + '\',' + (idx === cur) + ')">' +
                    '<span class="pr-node">' + (idx === cur && !cdone ? '<span class="pr-node-glow"></span>' : '') + inner + badge + '</span>' +
                    '<span class="pr-step-name">' + escapeHtml(name) + '</span>' +
                '</button>';
            });
            h += '</div></div>';
            return h;
        }
        function renderDoNowPanel(p, g) {
            var idx = currentFocusIndex(p, g);
            var kids = g.children || [];
            if (idx < 0 || !kids[idx]) return '';
            var node = kids[idx];
            var label = '<div class="pr-now-label">' + prPlaySvg() + 'Do now' + (node.kind === 'group' ? ' · ' + escapeHtml(node.name || 'Group') : '') + '</div>';
            var body = node.kind === 'group' ? renderGroupBody(p, node) : '<div class="pr-checklist">' + renderLeafCard(p, node) + '</div>';
            return '<div class="pr-now-panel">' + label + body + '</div>';
        }
        function renderGroupBody(p, g) {
            if (g.ordered) return renderPipelineRow(p, g) + renderDoNowPanel(p, g);
            return '<div class="pr-checklist">' + renderChecklist(p, g.children || []) + '</div>';
        }
        function renderNestedGroupHeader(g) {
            var repeats = (g.repeat || 1) > 1;
            return '<div class="pr-nested-head"><span>' + escapeHtml(g.name || 'Group') + '</span>' +
                (repeats ? '<span class="pr-nested-rep">×' + g.repeat + (nodeDone(g) ? ' · done' : ' · ' + Math.min((g.repsDone || 0) + 1, g.repeat) + '/' + g.repeat) + '</span>' : '') +
                '<span class="pr-nested-mode">' + (g.ordered ? 'sequence' : 'list') + '</span>' +
            '</div>';
        }
        function renderChecklist(p, nodes) {
            var h = '';
            (nodes || []).forEach(function(c) {
                if (c.kind === 'group') { h += '<div class="pr-nested-group">' + renderNestedGroupHeader(c) + renderGroupBody(p, c) + '</div>'; }
                else { h += renderLeafCard(p, c); }
            });
            return h;
        }
        function renderGroupBlock(p, g) {
            var gd = (g.children || []).filter(nodeDone).length;
            var repeats = (g.repeat || 1) > 1;
            var h = '<div class="pr-group"><div class="pr-group-head">' +
                '<span class="pr-group-title">' + escapeHtml(g.name || 'Group') + '</span>' +
                '<span class="pr-group-mode ' + (g.ordered ? 'pr-mode-ord' : 'pr-mode-un') + '">' + (g.ordered ? 'sequence' : 'list') + '</span>' +
                '<span class="pr-group-frac">' + gd + '/' + (g.children || []).length + '</span>' +
            '</div>';
            if (repeats) h += renderRepDots(g);
            h += renderGroupBody(p, g);
            h += '</div>';
            return h;
        }

        function renderLeafDetail(meta, dimHex) {
            if (!meta) return '<div class="pr-item-detail"><div class="pr-detail-inner"><div class="pr-drow"><span class="pr-drow-v">Activity no longer exists.</span></div></div></div>';
            return '<div class="pr-item-detail"><div class="pr-detail-inner">' +
                '<div class="pr-drow"><span class="pr-drow-k">Dimension</span><span class="pr-dchip" style="background:' + hexA(dimHex, .16) + ';color:' + dimHex + ';">' + escapeHtml(meta.dimName) + '</span></div>' +
                '<div class="pr-drow"><span class="pr-drow-k">Path</span><span class="pr-drow-v">' + escapeHtml(meta.dimName + ' › ' + meta.pathName) + '</span></div>' +
                '<div class="pr-drow"><span class="pr-drow-k">Earns</span><span class="pr-drow-v pr-drow-xp">+' + (meta.baseXP || 0) + ' XP each time</span></div>' +
            '</div></div>';
        }
        function renderLeafCard(p, l) {
            var done = leafDone(l);
            var req = itemReq(l);
            var hasCounter = req > 1;
            var partial = !done && (l.completedCount || 0) > 0;
            var isAct = l.type === 'activity';
            var meta = isAct ? actMeta(l.linkedActivityId) : null;
            var dimHex = (isAct && meta && meta.dimHex) ? meta.dimHex : null;
            var name = itemName(l);
            var showUndo = hasCounter && (l.completedCount || 0) > 0;
            var expanded = !!_prLeafExpanded[l.id];
            var sealed = p.status === 'completed' || p.status === 'archived';
            var h = '<div class="pr-item' + (done ? ' pr-item-done' : '') + (expanded ? ' pr-item-expanded' : '') + (sealed ? ' pr-item-locked' : '') + '">' +
                '<div class="pr-item-row">' +
                    '<button class="pr-check' + (partial ? ' pr-check-partial' : '') + '" aria-label="Complete" onclick="bumpLeaf(\'' + p.id + '\',\'' + l.id + '\')">' + prCheckSvg() + '</button>' +
                    '<div class="pr-item-main" onclick="' + (isAct ? 'toggleLeafDetail(\'' + l.id + '\')' : 'bumpLeaf(\'' + p.id + '\',\'' + l.id + '\')') + '">' +
                        '<div class="pr-item-name-row">' +
                            (isAct ? '<span class="pr-dimdot" style="background:' + (dimHex || '#8a9099') + '"></span>' : '') +
                            '<span class="pr-item-name">' + escapeHtml(name) + '</span>' +
                        '</div>' +
                    '</div>' +
                    (showUndo ? '<button class="pr-item-undo" aria-label="Undo one" onclick="event.stopPropagation();undoLeaf(\'' + p.id + '\',\'' + l.id + '\')">' + prUndoSvg() + '</button>' : '') +
                    (hasCounter ? '<span class="pr-item-counter" onclick="bumpLeaf(\'' + p.id + '\',\'' + l.id + '\')">' + (l.completedCount || 0) + '/' + req + '</span>' : '') +
                    (isAct ? '<button class="pr-chev" aria-label="Details" onclick="toggleLeafDetail(\'' + l.id + '\')">' + prChevSvg() + '</button>' : '') +
                '</div>' +
                (isAct ? renderLeafDetail(meta, dimHex) : '') +
            '</div>';
            return h;
        }
        window.toggleLeafDetail = function(id) {
            if (_prLeafExpanded[id]) delete _prLeafExpanded[id]; else _prLeafExpanded[id] = true;
            if (window._openProjectId) renderProjectDetail(window._openProjectId);
        };
        window.tapPipelineNode = function(pid, gid, nodeId, isCurrent) {
            var p = findProject(pid); if (!p || p.status !== 'active') return;
            var g = findNode(p, gid); if (!g || g.kind !== 'group') return;
            var node = (g.children || []).find(function(c) { return c.id === nodeId; });
            if (!node) return;
            if (isCurrent && node.kind === 'leaf') { window.bumpLeaf(pid, nodeId); return; } // finishMutation -> setFocusPath keeps its card showing
            _prFocusNode[pid + ':' + gid] = nodeId;
            renderProjectDetail(pid);
        };

        // Keep every ordered ancestor's "Do now" panel pointed at the node that
        // was just acted on, instead of letting currentIndex() silently auto-
        // advance past it the instant it's marked done — so a single-tap leaf
        // (no counter, no repeat) still shows its own card after completion,
        // not just multi-count leaves that happen to stay "current" for a
        // few extra taps.
        function setFocusPath(p, leafId) {
            var path = findPath(p, leafId);
            if (!path || !path.length) return;
            for (var i = 0; i < path.length - 1; i++) {
                if (path[i].node.kind === 'group') _prFocusNode[p.id + ':' + path[i].node.id] = path[i + 1].node.id;
            }
        }

        // ── Leaf mutation — funnels through one apply step that settles reps,
        //    computes flash targets, saves, and re-renders. ─────────────────
        function finishMutation(p, beforeSnap, leafId, alreadySaved) {
            settleAll(p);
            var bankedGroupId = null;
            (p.groups || []).forEach(function(g, i) { var f = trackBank(g, beforeSnap[i]); if (f) bankedGroupId = f; });
            _prFlashRep = bankedGroupId;
            _prFlashStep = bankedGroupId ? null : leafId;
            setFocusPath(p, leafId);
            if (!alreadySaved) debouncedSaveUserData();
            if (window._openProjectId === p.id) renderProjectDetail(p.id);
            if (p.status === 'active' && projectCycleReady(p)) {
                setTimeout(function() { showToast((p.cadence && p.cadence.type === 'recurring') ? 'All done — seal the cycle below' : 'All done — mark the quest complete', 'blue', null, 'flag-checkered'); }, 280);
            }
        }
        function snapshotReps(p) { return (p.groups || []).map(repsSnapshot); }

        window.bumpLeaf = async function(pid, leafId) {
            var p = findProject(pid);
            if (!p || p.status === 'completed' || p.status === 'archived') return;
            var leaf = findNode(p, leafId);
            if (!leaf || leaf.kind !== 'leaf') return;
            var req = itemReq(leaf);

            if (leaf.type === 'task') {
                var before = snapshotReps(p);
                if ((leaf.completedCount || 0) < req) { leaf.completedCount = (leaf.completedCount || 0) + 1; }
                else { leaf.completedCount = 0; }
                finishMutation(p, before, leafId);
                return;
            }

            var act = leaf.linkedActivityId ? findActivityById(leaf.linkedActivityId) : null;
            if (!act) { var before2 = snapshotReps(p); leaf.completedCount = (leaf.completedCount || 0) < req ? req : 0; finishMutation(p, before2, leafId); return; }

            if ((leaf.completedCount || 0) < req) {
                var allowMulti = act.allowMultiplePerDay && act.frequency !== 'occasional';
                if (typeof isCompletedToday === 'function' && isCompletedToday(act) && !allowMulti) {
                    if ((leaf.completedCount || 0) === 0) {
                        var before3 = snapshotReps(p);
                        leaf.completedCount = 1;
                        finishMutation(p, before3, leafId);
                    } else {
                        showToast('“' + (act.name || 'Activity') + '” is already done for today', 'olive');
                    }
                    return;
                }
                if (typeof canCompleteActivity === 'function' && !canCompleteActivity(act)) { showToast('“' + (act.name || 'Activity') + '” isn’t available to complete right now', 'olive'); return; }
                var before4 = snapshotReps(p);
                await window.completeActivityById(leaf.linkedActivityId);
                finishMutation(p, before4, leafId, true);
            } else {
                var before5 = snapshotReps(p);
                await window.undoActivityById(leaf.linkedActivityId);
                finishMutation(p, before5, leafId, true);
            }
        };
        window.undoLeaf = async function(pid, leafId) {
            var p = findProject(pid);
            if (!p || p.status === 'completed' || p.status === 'archived') return;
            var leaf = findNode(p, leafId);
            if (!leaf || leaf.kind !== 'leaf' || (leaf.completedCount || 0) <= 0) return;
            if (leaf.type === 'task') {
                var before = snapshotReps(p);
                leaf.completedCount = Math.max(0, leaf.completedCount - 1);
                finishMutation(p, before, leafId);
                return;
            }
            var act = leaf.linkedActivityId ? findActivityById(leaf.linkedActivityId) : null;
            if (!act) { var before2 = snapshotReps(p); leaf.completedCount = Math.max(0, leaf.completedCount - 1); finishMutation(p, before2, leafId); return; }
            var before3 = snapshotReps(p);
            await window.undoActivityById(leaf.linkedActivityId);
            finishMutation(p, before3, leafId, true);
        };

        function renderProjectFooter(p) {
            var isRecurring = p.cadence && p.cadence.type === 'recurring';
            var ready = projectCycleReady(p);
            var out = '<div class="pr-footer">';
            if (p.status === 'active') {
                var cta = isRecurring ? (ready ? 'Seal Cycle ' + (p.currentCycle || 1) : 'Complete cycle') : (ready ? 'Mark quest complete' : 'Complete quest');
                out += '<button class="pr-cycle-btn' + (ready ? ' pr-cycle-ready' : '') + '" onclick="completeProjectCycle(\'' + p.id + '\')">' + prCheckSvg() + cta + '</button>';
            } else if (p.status === 'paused') {
                out += '<button class="pr-cycle-btn" onclick="resumeProject(\'' + p.id + '\')">Resume quest</button>';
            } else if (p.status === 'completed') {
                out += '<div class="pr-sealed-note pr-sealed-gold">' + phIcon('trophy', { weight: 'fill', lead: true }) + 'Quest completed' + (p.completedAt ? ' · ' + new Date(p.completedAt).toLocaleDateString() : '') + '</div>' +
                       '<button class="pr-cycle-btn" onclick="reopenProject(\'' + p.id + '\')">Reopen quest</button>';
            } else if (p.status === 'archived') {
                out += '<div class="pr-sealed-note">Archived</div><button class="pr-cycle-btn" onclick="unarchiveProject(\'' + p.id + '\')">Restore quest</button>';
            }
            var canReset = isRecurring ? (p.status === 'active' || p.status === 'paused') : (p.status === 'active' || p.status === 'paused' || p.status === 'completed');
            out += '<div class="pr-actions">';
            out += '<button class="pr-act-btn" onclick="openProjectModal(\'' + p.id + '\')">Edit</button>';
            if (p.status === 'active') out += '<button class="pr-act-btn" onclick="pauseProject(\'' + p.id + '\')">Pause</button>';
            if (canReset) out += '<button class="pr-act-btn pr-act-reset" onclick="resetProject(\'' + p.id + '\')">' + (isRecurring ? 'Reset cycle' : 'Reset') + '</button>';
            if (p.status !== 'archived') out += '<button class="pr-act-btn" onclick="archiveProject(\'' + p.id + '\')">Archive</button>';
            out += '<button class="pr-act-btn pr-act-danger" onclick="deleteProject(\'' + p.id + '\')">Delete</button>';
            out += '</div>';
            out += '<div class="pr-footer-cad">' + escapeHtml(cadenceFooterText(p)) + '</div></div>';
            return out;
        }

        // Bonus XP is a lump sum paid ONLY on a legitimate seal (every
        // per-cycle / required leaf actually done). Force-sealing early via
        // the confirm() override below pays zero bonus — the copy says so —
        // so there's no way to skip work and still collect the payout.
        window.completeProjectCycle = function(projectId) {
            var p = findProject(projectId);
            if (!p || p.status !== 'active') return;
            var ready = projectCycleReady(p);
            if (!ready) {
                var isRec = p.cadence && p.cadence.type === 'recurring';
                if (!confirm(isRec ? 'Some per-cycle items aren’t done yet. Seal this cycle early and start a fresh one? You won’t earn this cycle’s bonus XP or Grit.' : 'Some items aren’t done yet. Mark this quest complete anyway? You won’t earn the bonus XP or Grit.')) return;
            }
            // Sealing early (the confirm() override above) pays NOTHING — not
            // XP, not Grit. Both are gated on the same `ready` flag so the two
            // currencies can never disagree about whether the work was done.
            var cycleNum = p.currentCycle || 1;
            // Pay only for a settlement this quest/cycle has not already been
            // paid for. Sealing early pays nothing; sealing a second time
            // after a reopen or a reset pays nothing.
            var payable = ready && !questBonusPaid(p, cycleNum);
            var bonus = payable ? questPotentialBonus(p) : 0;
            var grit  = payable ? questGritBonus(p) : 0;
            var stats = questStats(p);
            // Persistence precedes the grant (§3.4): the history entry and the
            // marker are on the object before any currency moves, so a failure
            // between the two leaves a record of an unpaid seal rather than a
            // payment with no record of what earned it. The marker is set on
            // any ready settlement, not only a paying one — otherwise a quest
            // completed while worth nothing could be edited to add activity
            // leaves and completed again for a full payout.
            p.cycleHistory = p.cycleHistory || [];
            p.cycleHistory.push({ cycleNumber: cycleNum, startedAt: p.startedCycleAt || p.createdAt, completedAt: new Date().toISOString(), itemsCompleted: stats.done, itemsTotal: stats.total, bonusXp: bonus, bonusGrit: grit });
            if (payable) markQuestBonusPaid(p, cycleNum);
            delete _prNextSkip[p.id]; delete _prNextDone[p.id];
            payQuestBonus(p, bonus);
            var gritPaid = payQuestGrit(p, grit, cycleNum);
            var bonusMsg = bonus > 0 ? (' — +' + bonus + ' XP') : '';
            if (gritPaid > 0) bonusMsg += (bonus > 0 ? ' · +' : ' — +') + gritPaid + ' Grit';
            if (p.cadence && p.cadence.type === 'recurring') {
                clearRecurringItems(p);
                p.currentCycle = (p.currentCycle || 1) + 1; p.startedCycleAt = new Date().toISOString();
                saveUserData();
                showToast('Cycle ' + (p.currentCycle - 1) + ' shipped' + bonusMsg + ' — Cycle ' + p.currentCycle + ' begins', 'olive', null, 'trophy');
            } else {
                p.status = 'completed'; p.completedAt = new Date().toISOString(); saveUserData();
                showToast('Quest complete' + bonusMsg + ' — ' + (p.name || ''), 'olive', null, 'trophy');
            }
            renderProjectDetail(projectId);
        };
        window.pauseProject = function(id) { var p = findProject(id); if (!p) return; p.status = 'paused'; saveUserData(); showToast('Quest paused', 'olive'); renderProjectDetail(id); };
        window.resumeProject = function(id) { var p = findProject(id); if (!p) return; p.status = 'active'; saveUserData(); showToast('Quest resumed', 'green'); renderProjectDetail(id); };
        window.archiveProject = function(id) { var p = findProject(id); if (!p) return; p.status = 'archived'; saveUserData(); showToast('Quest archived', 'olive'); window.closeProjectDetail(); };
        window.unarchiveProject = function(id) { var p = findProject(id); if (!p) return; p.status = 'active'; saveUserData(); showToast('Quest restored', 'green'); renderProjectDetail(id); };
        // Reopening takes nothing back. Double payment is prevented at the
        // paying end by the bonusPaidAt / bonusPaidCycles marker, not by a
        // clawback here: reopen -> re-complete simply pays zero. Quest state
        // must never reduce a user's XP, level, or Grit (spec §24.3).
        window.reopenProject = function(id) {
            var p = findProject(id); if (!p) return;
            p.status = 'active'; p.completedAt = null;
            saveUserData();
            showToast('Quest reopened', 'green');
            renderProjectDetail(id);
        };

        function clearCycleNode(n) {
            if (n.kind === 'group') { n.repsDone = 0; (n.children || []).forEach(clearCycleNode); }
            else if (n.resetMode !== 'once') { n.completedCount = 0; }
        }
        function clearRecurringItems(p) { (p.groups || []).forEach(clearCycleNode); }

        window.resetProject = function(id) {
            var p = findProject(id); if (!p) return;
            var isRecurring = p.cadence && p.cadence.type === 'recurring';
            if (isRecurring) {
                if (p.status !== 'active' && p.status !== 'paused') return;
                if (!confirm('Reset this cycle? Progress on repeating items will clear, but nothing you’ve already earned is lost. This can’t be undone.')) return;
                clearRecurringItems(p);
                p.startedCycleAt = new Date().toISOString();
                p.resetCount = (p.resetCount || 0) + 1;
                showToast('Cycle reset', 'olive');
            } else {
                if (p.status !== 'active' && p.status !== 'paused' && p.status !== 'completed') return;
                if (!confirm('Reset this quest? Progress will clear, but nothing you’ve already earned is lost. This can’t be undone.')) return;
                (p.groups || []).forEach(resetNode);
                p.status = 'active'; p.completedAt = null;
                p.lastResetAt = new Date().toISOString();
                p.startedCycleAt = new Date().toISOString();
                p.resetCount = (p.resetCount || 0) + 1;
                showToast('Quest reset', 'olive');
            }
            delete _prNextSkip[id]; delete _prNextDone[id];
            saveUserData(); renderProjectDetail(id);
        };
        window.deleteProject = function(id) {
            var p = findProject(id); if (!p) return;
            if (!confirm('Delete “' + (p.name || 'this quest') + '” permanently? This can’t be undone.')) return;
            var arr = getProjects(); var i = arr.findIndex(function(x) { return x.id === id; });
            if (i >= 0) arr.splice(i, 1);
            saveUserData(); showToast('Quest deleted', 'red');
            if (window._openProjectId === id) window.closeProjectDetail(); else renderProjects();
        };

        function refreshProjectsView() {
            var dv = document.getElementById('projectsDetailView');
            if (dv && dv.style.display !== 'none' && window._openProjectId && findProject(window._openProjectId)) renderProjectDetail(window._openProjectId);
            else renderProjects();
        }

        window.openProjectsInfo = function() { var m = document.getElementById('projectsInfoModal'); if (m) m.classList.add('active'); };
        window.closeProjectsInfo = function() { var m = document.getElementById('projectsInfoModal'); if (m) m.classList.remove('active'); };

        // ═══ BUILDER (create / edit) ════════════════════════════════════════
        // The group/item tree is authored directly against the DOM (no parallel
        // JS draft to keep in sync) so arbitrary-depth nesting and pointer-based
        // drag reorder — which move real DOM nodes — never fight a second
        // source of truth. Only top-level quest fields (emoji/name/description/
        // cadence) are read straight from their inputs, as before.
        var _projectEditingId = null;

        window.openProjectModal = function(id) {
            _projectEditingId = (id && typeof id === 'string') ? id : null;
            var editing = _projectEditingId ? findProject(_projectEditingId) : null;
            document.getElementById('projectModalTitle').textContent = editing ? 'Edit Quest' : 'New Quest';
            document.getElementById('projectSaveBtn').textContent = editing ? 'Save changes' : 'Create quest';
            setIconPickerValue('projectIcon', 'projectIconBtn',
                editing ? (editing.icon || editing.emoji) : null, 'target');
            document.getElementById('projectName').value = editing ? (editing.name || '') : '';
            document.getElementById('projectDesc').value = editing ? (editing.description || '') : '';
            var cadType = editing && editing.cadence ? editing.cadence.type : 'oneoff';
            _applyCadenceUI(cadType);
            var helpBody = document.getElementById('builderHelpBody'), helpChev = document.getElementById('builderHelpChev');
            if (helpBody) helpBody.classList.remove('open');
            if (helpChev) helpChev.classList.remove('open');
            _buildActIdx();
            var host = document.getElementById('projectBuilder');
            host.innerHTML = '';
            if (editing && (editing.groups || []).length) {
                editing.groups.forEach(function(g) { addGroupCard(host, g); });
            } else {
                addGroupCard(host, null);
            }
            renderProjectDimReadout();
            var body = document.querySelector('#projectModal .pl-modal-body'); if (body) body.scrollTop = 0;
            document.getElementById('projectModal').classList.add('active');
        };
        window.closeProjectModal = function() { document.getElementById('projectModal').classList.remove('active'); _projectEditingId = null; };

        window.setProjectCadence = function(type) { _applyCadenceUI(type); };
        function _applyCadenceUI(type) {
            document.getElementById('projectCadenceType').value = type;
            document.querySelectorAll('#projectCadenceSeg .pr-seg-btn').forEach(function(b) { b.classList.toggle('active', b.getAttribute('data-cad') === type); });
            document.getElementById('projectCadenceHint').textContent = type === 'recurring'
                ? 'Quest restarts after completion. For routines and larger habits.'
                : 'Quest is archived after completion. For one time projects.';
        }
        window.toggleBuilderHelp = function() {
            var body = document.getElementById('builderHelpBody');
            var chev = document.getElementById('builderHelpChev');
            var toggle = document.querySelector('.pr-help-toggle');
            var open = body ? body.classList.toggle('open') : false;
            if (chev) chev.classList.toggle('open', open);
            if (toggle) toggle.setAttribute('aria-expanded', open);
        };

        function renderProjectDimReadout() {
            var wrap = document.getElementById('projectDimReadoutWrap');
            var host = document.getElementById('projectDimReadout');
            if (!wrap || !host) return;
            var groups = readTopLevelGroups();
            var result = computeProjectDimensions(groups);
            var names = result.dimensionIds.map(function(id) { var dim = (window.userData.dimensions || []).find(function(d) { return d.id === id; }); return dim ? dim.name : null; }).filter(Boolean);
            if (!names.length) { wrap.style.display = 'none'; host.innerHTML = ''; return; }
            wrap.style.display = '';
            host.innerHTML = 'Categories: <strong>' + escapeHtml(names.join(', ')) + '</strong> — set automatically from the activities in this quest.';
        }

        function wireDragHandle(el) {
            var h = el.querySelector('[data-draghandle]');
            if (h) h.addEventListener('pointerdown', function(e) { startDrag(e, el); });
        }

        function addGroupCard(hostEl, seed) {
            var gid = seed && seed.id ? seed.id : prId('grp');
            var ordered = seed ? !!seed.ordered : false;
            var repeat = seed ? Math.max(1, seed.repeat || 1) : 1;
            var repsDone = seed ? Math.max(0, seed.repsDone || 0) : 0;
            var wrap = document.createElement('div');
            wrap.className = 'pr-b-group' + (repeat > 1 ? ' pr-b-repeating' : '');
            wrap.setAttribute('data-group', gid);
            wrap.setAttribute('data-reps-done', repsDone);
            wrap.innerHTML =
                '<div class="pr-b-group-head">' +
                    '<span class="pr-b-handle" data-draghandle aria-label="Drag">' + prDragSvg() + '</span>' +
                    '<input class="pr-b-group-name" value="' + prAttr(seed ? seed.name : '') + '" placeholder="Group name — e.g. Morning routine">' +
                    '<button type="button" class="pr-b-group-x" aria-label="Remove group" onclick="removeGroupCard(\'' + gid + '\')">' + prXSvg() + '</button>' +
                '</div>' +
                '<div class="pr-b-ctrl-row">' +
                    '<div class="pr-b-ctrl-ord' + (ordered ? ' pr-b-on' : '') + '" onclick="toggleGroupOrdered(this)" role="switch" aria-checked="' + ordered + '">' +
                        '<span class="pr-b-ctrl-label">Make this a Sequence</span>' +
                        '<span class="pr-b-switch"></span>' +
                    '</div>' +
                    '<div class="pr-b-ctrl-rep">' +
                        '<span class="pr-b-ctrl-label">Repeat this entire group</span>' +
                        '<div class="pr-b-stepper"><button type="button" aria-label="Fewer" onclick="stepGroupRepeat(\'' + gid + '\',-1)">' + prMinusSvg() + '</button><span class="pr-b-stepper-val">×' + repeat + '</span><button type="button" aria-label="More" onclick="stepGroupRepeat(\'' + gid + '\',1)">' + prPlusSvg() + '</button></div>' +
                    '</div>' +
                '</div>' +
                '<div class="pr-b-zone" data-dropzone data-group="' + gid + '"></div>' +
                '<div class="pr-b-empty" data-empty>No activities, tasks, or groups yet</div>' +
                '<div class="pr-b-add-row">' +
                    '<button type="button" class="pr-b-add-activity" onclick="openActivityPicker(\'' + gid + '\')">' + prLinkSvg() + 'Add activity</button>' +
                    '<button type="button" class="pr-b-add-task" onclick="addTaskRow(\'' + gid + '\')">' + prPlusSvg() + 'Task</button>' +
                    '<button type="button" class="pr-b-add-group" onclick="addNestedGroup(\'' + gid + '\')" aria-label="Add group" title="Add a nested group">' + prGroupSvg() + '</button>' +
                '</div>';
            wireDragHandle(wrap);
            hostEl.appendChild(wrap);
            var zone = wrap.querySelector(':scope > .pr-b-zone');
            if (seed && (seed.children || []).length) {
                seed.children.forEach(function(c) {
                    if (c.kind === 'group') addGroupCard(zone, c);
                    else addLeafRow(zone, c);
                });
            }
            refreshZoneEmptyState(zone);
            return wrap;
        }
        window.addGroup = function() { addGroupCard(document.getElementById('projectBuilder'), null); };
        window.addNestedGroup = function(gid) {
            var zone = document.querySelector('.pr-b-group[data-group="' + gid + '"] > .pr-b-zone');
            if (!zone) return;
            addGroupCard(zone, null);
            refreshZoneEmptyState(zone);
        };
        window.removeGroupCard = function(gid) {
            var el = document.querySelector('.pr-b-group[data-group="' + gid + '"]');
            if (!el) return;
            var zone = el.closest('.pr-b-zone');
            el.remove();
            if (zone) refreshZoneEmptyState(zone);
            renderProjectDimReadout();
        };
        window.toggleGroupOrdered = function(el) {
            var on = el.classList.toggle('pr-b-on');
            el.setAttribute('aria-checked', on);
        };
        window.stepGroupRepeat = function(gid, delta) {
            var wrap = document.querySelector('.pr-b-group[data-group="' + gid + '"]');
            if (!wrap) return;
            var el = wrap.querySelector(':scope > .pr-b-ctrl-row .pr-b-stepper-val');
            var v = parseInt(el.textContent.replace('×', ''), 10) || 1;
            v = Math.max(1, Math.min(20, v + delta));
            el.textContent = '×' + v;
            wrap.classList.toggle('pr-b-repeating', v > 1);
        };

        function addLeafRow(zoneEl, seed) {
            var iid = seed && seed.id ? seed.id : prId('lf');
            var type = seed && seed.type === 'activity' ? 'activity' : 'task';
            var isAct = type === 'activity';
            var req = seed ? Math.max(1, seed.requiredCount || 1) : 1;
            var completedCount = seed ? Math.max(0, seed.completedCount || 0) : 0;
            var resetMode = seed && seed.resetMode === 'once' ? 'once' : 'per-cycle';
            var meta = isAct ? actMeta(seed.linkedActivityId) : null;
            var dimHex = meta ? meta.dimHex : null;
            var displayName = isAct ? (meta ? meta.name : '(activity removed)') : (seed ? (seed.name || '') : '');
            var row = document.createElement('div');
            row.className = 'pr-b-item';
            row.setAttribute('data-item', '1');
            row.setAttribute('data-id', iid);
            row.setAttribute('data-type', type);
            row.setAttribute('data-linked-id', isAct ? (seed.linkedActivityId || '') : '');
            row.setAttribute('data-completed-count', completedCount);
            row.setAttribute('data-reset-mode', resetMode);
            row.innerHTML =
                '<span class="pr-b-handle" data-draghandle aria-label="Drag">' + prDragSvg() + '</span>' +
                '<div class="pr-b-item-body">' +
                    (isAct
                        ? '<div class="pr-b-item-name pr-b-item-name-static" title="' + prAttr(displayName) + '">' + escapeHtml(displayName) + '</div>'
                        : '<input class="pr-b-item-name pr-b-item-name-inp" value="' + prAttr(displayName) + '" placeholder="Task name">') +
                    '<div class="pr-b-item-meta ' + (isAct ? 'pr-meta-act' : 'pr-meta-task') + '">' +
                        (isAct ? ('<span class="pr-b-mdot" style="background:' + (dimHex || '#8a9099') + '"></span>' + escapeHtml(meta ? meta.dimName : 'Unknown')) : 'one-off task') +
                    '</div>' +
                '</div>' +
                '<span class="pr-b-mini-step" title="Times to complete"><button type="button" aria-label="Fewer" onclick="stepLeafCount(this,-1)">' + prMinusSvg() + '</button><span class="pr-b-mini-val' + (req > 1 ? ' pr-hot' : '') + '">×' + req + '</span><button type="button" aria-label="More" onclick="stepLeafCount(this,1)">' + prPlusSvg() + '</button></span>' +
                '<button type="button" class="pr-b-item-x" aria-label="Remove" onclick="removeLeafRow(this)">' + prXSvg() + '</button>';
            wireDragHandle(row);
            zoneEl.appendChild(row);
            return row;
        }
        window.addTaskRow = function(gid) {
            var zone = document.querySelector('.pr-b-group[data-group="' + gid + '"] > .pr-b-zone');
            if (!zone) return;
            var row = addLeafRow(zone, { type: 'task', name: '', requiredCount: 1, completedCount: 0 });
            refreshZoneEmptyState(zone);
            var inp = row.querySelector('.pr-b-item-name-inp'); if (inp) inp.focus();
        };
        window.removeLeafRow = function(btn) {
            var row = btn.closest('.pr-b-item');
            var zone = row.closest('.pr-b-zone');
            row.remove();
            if (zone) refreshZoneEmptyState(zone);
            renderProjectDimReadout();
        };
        window.stepLeafCount = function(btn, delta) {
            var wrap = btn.closest('.pr-b-mini-step');
            var v = wrap.querySelector('.pr-b-mini-val');
            var n = parseInt(v.textContent.replace('×', ''), 10) || 1;
            n = Math.max(1, Math.min(99, n + delta));
            v.textContent = '×' + n;
            v.classList.toggle('pr-hot', n > 1);
        };
        function refreshZoneEmptyState(zoneEl) {
            if (!zoneEl) return;
            var empty = zoneEl.parentElement ? zoneEl.parentElement.querySelector(':scope > [data-empty]') : null;
            if (!empty) return;
            var has = zoneEl.querySelector(':scope > [data-item]') || zoneEl.querySelector(':scope > .pr-b-group');
            empty.style.display = has ? 'none' : 'block';
        }

        // ── Drag and drop — pointer-based, cross-zone at any nesting depth
        //    (drop detection is just elementFromPoint→closest([data-dropzone]),
        //    which doesn't care how deep the zone is nested). ────────────────
        var _drag = null;
        function startDrag(e, row) {
            e.preventDefault();
            var rect = row.getBoundingClientRect();
            var clone = row.cloneNode(true);
            clone.classList.add('pr-dragging-clone');
            clone.style.width = rect.width + 'px';
            clone.style.left = rect.left + 'px';
            clone.style.top = rect.top + 'px';
            document.body.appendChild(clone);
            var ph = document.createElement('div');
            ph.className = row.classList.contains('pr-b-group') ? 'pr-drop-ph pr-drop-ph-group' : 'pr-drop-ph';
            ph.style.height = rect.height + 'px';
            row.after(ph);
            row.style.display = 'none';
            _drag = { row: row, clone: clone, ph: ph, dx: e.clientX - rect.left, dy: e.clientY - rect.top };
            document.addEventListener('pointermove', onDragMove, { passive: false });
            document.addEventListener('pointerup', onDragUp, { once: true });
        }
        function onDragMove(e) {
            if (!_drag) return;
            e.preventDefault();
            _drag.clone.style.left = (e.clientX - _drag.dx) + 'px';
            _drag.clone.style.top = (e.clientY - _drag.dy) + 'px';
            var under = document.elementFromPoint(e.clientX, e.clientY);
            document.querySelectorAll('.pr-zone-hover').forEach(function(z) { z.classList.remove('pr-zone-hover'); });
            var zone = under && under.closest('[data-dropzone]');
            if (!zone || (_drag.row.contains && _drag.row.contains(zone))) return;
            zone.classList.add('pr-zone-hover');
            var over = under.closest('[data-item],.pr-b-group');
            if (over && over !== _drag.row && !over.classList.contains('pr-dragging-clone') && zone.contains(over) && !(_drag.row.contains && _drag.row.contains(over))) {
                var r = over.getBoundingClientRect();
                if (e.clientY < r.top + r.height / 2) over.before(_drag.ph); else over.after(_drag.ph);
            } else if (!zone.contains(_drag.ph)) {
                zone.appendChild(_drag.ph);
            }
        }
        function onDragUp() {
            if (!_drag) return;
            document.removeEventListener('pointermove', onDragMove);
            document.querySelectorAll('.pr-zone-hover').forEach(function(z) { z.classList.remove('pr-zone-hover'); });
            var destZone = _drag.ph.closest('[data-dropzone]');
            _drag.ph.replaceWith(_drag.row);
            _drag.row.style.display = '';
            _drag.clone.remove();
            if (destZone) refreshZoneEmptyState(destZone);
            renderProjectDimReadout();
            _drag = null;
        }

        // ── Activity picker sheet — retargeted to a builder zone (by group id)
        //    instead of pipeline/stage indices. ──────────────────────────────
        var _prPickerTargetGid = null;
        var _prPickerSelection = {};
        window.openActivityPicker = function(gid) {
            _prPickerTargetGid = gid; _prPickerSelection = {};
            var input = document.getElementById('projectActivitySearch'); if (input) input.value = '';
            renderProjectActivityPickerList('');
            document.getElementById('projectActivityPicker').classList.add('active');
        };
        window.closeProjectActivityPicker = function() { document.getElementById('projectActivityPicker').classList.remove('active'); _prPickerTargetGid = null; };
        window.renderProjectActivityPickerList = function(filter) {
            _buildActIdx();
            var host = document.getElementById('projectActivityPickerList');
            var emptyEl = document.getElementById('projectActivityPickerEmpty');
            if (!host) return;
            var zone = _prPickerTargetGid ? document.querySelector('.pr-b-group[data-group="' + _prPickerTargetGid + '"] > .pr-b-zone') : null;
            var already = {};
            if (zone) { zone.querySelectorAll(':scope > [data-item][data-type="activity"]').forEach(function(el) { already[el.getAttribute('data-linked-id')] = true; }); }
            var q = (filter || '').toLowerCase().trim();
            var list = Object.keys(window._prActIdx || {}).map(function(k) { return window._prActIdx[k]; })
                .filter(function(a) { return !q || a.name.toLowerCase().indexOf(q) !== -1 || (a.dimName + ' ' + a.pathName).toLowerCase().indexOf(q) !== -1; })
                .sort(function(a, b) { return a.name.localeCompare(b.name); });
            if (!list.length) { host.innerHTML = ''; if (emptyEl) emptyEl.style.display = 'block'; _prUpdatePickerAddBtn(); return; }
            if (emptyEl) emptyEl.style.display = 'none';
            host.innerHTML = list.map(function(a) {
                var isIn = already[a.id];
                var sel = _prPickerSelection[a.id];
                return '<div class="pr-pick-row' + (sel ? ' sel' : '') + (isIn ? ' added' : '') + '" ' + (isIn ? '' : 'onclick="toggleProjectPick(\'' + prAttr(a.id) + '\')"') + '>' +
                    '<span class="pr-pick-check">' + (isIn ? phIcon('check') : (sel ? prCheckSvg() : '')) + '</span>' +
                    '<span class="pr-pick-dot" style="background:' + (a.dimHex || '#8a9099') + '"></span>' +
                    '<span class="pr-pick-main"><span class="pr-pick-name">' + escapeHtml(a.name) + '</span>' +
                    '<span class="pr-pick-sub">' + escapeHtml(a.dimName + ' › ' + a.pathName) + ' · ' + a.baseXP + ' XP</span></span>' +
                    (isIn ? '<span class="pr-pick-added">added</span>' : '') + '</div>';
            }).join('');
            _prUpdatePickerAddBtn();
        };
        window.toggleProjectPick = function(id) { if (_prPickerSelection[id]) delete _prPickerSelection[id]; else _prPickerSelection[id] = true; renderProjectActivityPickerList(document.getElementById('projectActivitySearch').value); };
        function _prUpdatePickerAddBtn() { var n = Object.keys(_prPickerSelection).length; var btn = document.getElementById('projectActivityPickerAdd'); if (btn) { btn.textContent = n ? 'Add ' + n : 'Add'; btn.disabled = !n; } }
        window.confirmProjectActivityPicker = function() {
            if (!_prPickerTargetGid) return closeProjectActivityPicker();
            var zone = document.querySelector('.pr-b-group[data-group="' + _prPickerTargetGid + '"] > .pr-b-zone');
            if (zone) {
                Object.keys(_prPickerSelection).forEach(function(aid) { addLeafRow(zone, { type: 'activity', linkedActivityId: aid, requiredCount: 1, completedCount: 0 }); });
                refreshZoneEmptyState(zone);
            }
            closeProjectActivityPicker();
            renderProjectDimReadout();
        };

        // ── Save — recursively read the DOM tree into groups[] ─────────────
        function readLeafRow(el) {
            var type = el.getAttribute('data-type') === 'activity' ? 'activity' : 'task';
            var reqEl = el.querySelector(':scope > .pr-b-mini-step .pr-b-mini-val');
            var req = parseInt((reqEl ? reqEl.textContent : '×1').replace('×', ''), 10) || 1;
            var completedCount = Math.max(0, Math.min(req, parseInt(el.getAttribute('data-completed-count'), 10) || 0));
            var resetMode = el.getAttribute('data-reset-mode') === 'once' ? 'once' : 'per-cycle';
            if (type === 'activity') {
                var linkedId = el.getAttribute('data-linked-id');
                if (!linkedId) return null;
                return { id: el.getAttribute('data-id') || prId('lf'), kind: 'leaf', type: 'activity', linkedActivityId: linkedId, name: '', resetMode: resetMode, requiredCount: req, completedCount: completedCount };
            }
            var nameInp = el.querySelector(':scope > .pr-b-item-body > .pr-b-item-name-inp');
            var name = ((nameInp ? nameInp.value : '') || '').trim();
            if (!name) return null;
            return { id: el.getAttribute('data-id') || prId('lf'), kind: 'leaf', type: 'task', linkedActivityId: null, name: name, resetMode: resetMode, requiredCount: req, completedCount: completedCount };
        }
        function readGroupCard(el) {
            var gid = el.getAttribute('data-group');
            var nameInp = el.querySelector(':scope > .pr-b-group-head > .pr-b-group-name');
            var name = ((nameInp ? nameInp.value : '') || '').trim();
            var ordtog = el.querySelector(':scope > .pr-b-ctrl-row > .pr-b-ctrl-ord');
            var ordered = !!(ordtog && ordtog.classList.contains('pr-b-on'));
            var stepVal = el.querySelector(':scope > .pr-b-ctrl-row .pr-b-stepper-val');
            var repeat = parseInt((stepVal ? stepVal.textContent : '×1').replace('×', ''), 10) || 1;
            var repsDone = Math.min(repeat, Math.max(0, parseInt(el.getAttribute('data-reps-done'), 10) || 0));
            var zone = el.querySelector(':scope > .pr-b-zone');
            var children = readGroupTree(zone);
            return { id: gid || prId('grp'), kind: 'group', name: name, ordered: ordered, repeat: repeat, repsDone: repsDone, children: children };
        }
        function readGroupTree(zoneEl) {
            var out = [];
            if (!zoneEl) return out;
            Array.prototype.forEach.call(zoneEl.children, function(el) {
                if (el.classList.contains('pr-b-group')) {
                    var node = readGroupCard(el);
                    if (node && node.children.length) out.push(node);
                } else if (el.hasAttribute && el.hasAttribute('data-item')) {
                    var leaf = readLeafRow(el);
                    if (leaf) out.push(leaf);
                }
            });
            return out;
        }
        function readTopLevelGroups() { return readGroupTree(document.getElementById('projectBuilder')); }

        window.saveProject = function(event) {
            if (event && event.preventDefault) event.preventDefault();
            var name = (document.getElementById('projectName').value || '').trim();
            if (!name) { showToast('Give your quest a name', 'red'); return; }
            var icon = (document.getElementById('projectIcon').value || '').trim() || DEFAULT_QUEST_ICON;
            var desc = (document.getElementById('projectDesc').value || '').trim();
            var cadType = document.getElementById('projectCadenceType').value || 'oneoff';

            var groups = readTopLevelGroups();
            if (!groups.length) groups = [blankGroup()];

            var cadence = { type: cadType };
            var dims = computeProjectDimensions(groups);

            if (_projectEditingId) {
                var p = findProject(_projectEditingId);
                if (!p) { showToast('Quest not found', 'red'); return; }
                p.name = name; p.icon = icon; p.description = desc; p.dimensionIds = dims.dimensionIds; p.dimensionId = dims.dimensionId;
                p.cadence = cadence; p.groups = groups; p.schemaVersion = 2;
                var savedId = p.id;
                saveUserData(); closeProjectModal(); showToast('Quest updated', 'green', null, 'check'); openProjectDetail(savedId);
            } else {
                var proj = { id: prId('proj'), name: name, icon: icon, description: desc, dimensionIds: dims.dimensionIds, dimensionId: dims.dimensionId,
                    status: 'active', cadence: cadence, groups: groups, schemaVersion: 2, currentCycle: 1, cycleHistory: [],
                    createdAt: new Date().toISOString(), startedCycleAt: new Date().toISOString() };
                getProjects().push(proj);
                // A composed or accepted draft materializes its new-activity
                // leaves now that the builder saved.
                var _qcCtx = window._qcDraft ? qcFinishDraft(proj) : null;
                saveUserData(); closeProjectModal(); showToast('Quest created', 'green', null, 'check'); openProjectDetail(proj.id);
                // New activities were added to the tracker — show them, let the
                // user rename, reword, re-price or remove any of them.
                if (_qcCtx && _qcCtx.created && _qcCtx.created.length) {
                    setTimeout(function() { qcOpenNewActivityReview(proj.id, _qcCtx.created); }, 260);
                }
            }
        };

        // ════════════════════════════════════════════════════════════════════
        // ══ QUEST COMPOSER ══════════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // The engine that turns a validated quest spec into a prefilled entry
        // in the REAL builder. It was born inside the Tech Tree, which is why
        // the names below have tt-shaped ancestors; it is not tech-tree code
        // and must not grow any. Nothing here reads tt.nodes, and nothing here
        // may.
        //
        // Nothing is persisted until the user taps Create quest: the draft
        // lives in the builder DOM and window._qcDraft, and closing the modal
        // discards it.
        //
        //   qcWalkLeaves      was ttWalkLeaves
        //   qcDraftToBuilder  was ttAcceptQuestToBuilder (minus the tt lookup)
        //   qcFinishDraft     was ttFinishQuestAccept   (minus the node link)
        //   qcValidateGroup   was validateGroup  in the old tech-tree worker
        //   qcValidateLeaf    was validateLeaf   in the old tech-tree worker
        // ════════════════════════════════════════════════════════════════════

        // The pending draft context: { newSpecs: {leafId: spec}, nodeId? }.
        // nodeId is set only by the Tech Tree's legacy accept path and goes
        // away with it.
        window._qcDraft = window._qcDraft || null;

        function qcWalkLeaves(groups, fn) {
            (function walk(nodes) { (nodes || []).forEach(function(n) { if (n.kind === 'group') walk(n.children); else fn(n); }); })(groups);
        }

        // Opens the real builder on a validated spec. New-activity leaves ride
        // along as named TASK rows — nothing becomes an activity until the
        // user saves — and qcFinishDraft materializes the survivors.
        function qcDraftToBuilder(spec, opts) {
            opts = opts || {};
            spec = spec || {};
            var groups = JSON.parse(JSON.stringify(spec.groups || []));
            var newSpecs = {};
            qcWalkLeaves(groups, function(l) {
                if (l.type === 'activity' && !l.linkedActivityId && l.spec) {
                    newSpecs[l.id] = l.spec;
                    l.type = 'task';
                    l.name = l.spec.name || 'Practice';
                }
                delete l.spec; delete l._promotable;
            });
            window._qcDraft = { newSpecs: newSpecs };
            openProjectModal();
            document.getElementById('projectModalTitle').textContent = opts.title || 'Review your quest';
            document.getElementById('projectName').value = spec.name || opts.fallbackName || '';
            setIconPickerValue('projectIcon', 'projectIconBtn', spec.icon || spec.emoji, 'target');
            document.getElementById('projectDesc').value = spec.description || opts.fallbackDesc || '';
            try { setProjectCadence((spec.cadence && spec.cadence.type) === 'recurring' ? 'recurring' : 'oneoff'); } catch (e) {}
            var host = document.getElementById('projectBuilder');
            host.innerHTML = '';
            (groups.length ? groups : [null]).forEach(function(g) { addGroupCard(host, g); });
            renderProjectDimReadout();
            // Badge the rows that become real activities on save.
            Object.keys(newSpecs).forEach(function(leafId) {
                var row = host.querySelector('[data-id="' + leafId + '"] .pr-b-item-meta');
                if (row) row.innerHTML = '<span class="qc-newact-badge">' + phIcon('arrow-right', { lead: true }) + 'becomes an activity (' + escapeHtml(newSpecs[leafId].frequency || 'weekly') + ')</span>';
            });
            return window._qcDraft;
        }

        // Runs inside saveProject's create branch, before its save/close.
        // Returns the consumed context so a caller can act on it further.
        function qcFinishDraft(proj) {
            var ctx = window._qcDraft;
            window._qcDraft = null;
            if (!ctx || !proj) return null;
            // Every activity minted here is reported back, so the user gets to
            // see and change what was added to their tracker rather than
            // discovering it later.
            ctx.created = [];
            (function walk(nodes) {
                (nodes || []).forEach(function(l) {
                    if (l.kind === 'group') return walk(l.children);
                    if (l.type === 'task' && ctx.newSpecs[l.id]) {
                        if (!canAddActivity()) return;   // cap hit — it stays a task
                        var spec = Object.assign({}, ctx.newSpecs[l.id]);
                        if (l.name && l.name.trim()) spec.name = l.name.trim();
                        var act = createActivityFromSpec(spec, ctx.nodeId || null, null);
                        l.type = 'activity'; l.linkedActivityId = act.id; l.name = '';
                        ctx.created.push({ activityId: act.id, leafId: l.id });
                    }
                });
            })(proj.groups);
            if (ctx.created.length && typeof computeProjectDimensions === 'function') {
                var dims = computeProjectDimensions(proj.groups);
                proj.dimensionIds = dims.dimensionIds; proj.dimensionId = dims.dimensionId;
            }
            return ctx;
        }

        // Cancelling the builder discards the draft. Wrapped once, the same
        // way the Tech Tree used to wrap it.
        setTimeout(function() {
            if (typeof window.closeProjectModal === 'function' && !window._qcWrappedCloseProj) {
                window._qcWrappedCloseProj = true;
                var _closeProj = window.closeProjectModal;
                window.closeProjectModal = function() {
                    var r = _closeProj.apply(this, arguments);
                    window._qcDraft = null;
                    return r;
                };
            }
        }, 0);

        // ── The composer sheet ───────────────────────────────────────────────
        // One screen, one call, one draft. No chat. The draft opens in the real
        // builder, fully editable, and nothing is saved until Create quest.
        var QC_MIN_ACTIVITIES = 3;
        var _qcShape = 'oneoff';
        var _qcSize = null;
        var _qcBusy = false;

        // Counts what the function will count: live activities only. A courtesy
        // gate so nobody spends a wait to be told no — the function gates too,
        // and its count is the authoritative one.
        function qcLiveActivityCount() {
            var n = 0, now = Date.now();
            ((window.userData && window.userData.dimensions) || []).forEach(function(d) {
                (d.paths || []).forEach(function(pth) {
                    (pth.activities || []).forEach(function(a) {
                        if (!a || a.archived || a.deleted) return;
                        if (a.isNegative && !a.isSkipNegative) return;
                        var days = (typeof gritLookbackDays === 'function') ? gritLookbackDays(a) : 7;
                        var hist = a.completionHistory || [];
                        for (var i = hist.length - 1; i >= 0; i--) {
                            var e = hist[i];
                            if (!e || e.isPenalty || (e.xp || 0) <= 0) continue;
                            if (now - new Date(e.date).getTime() <= days * 86400000) { n++; return; }
                        }
                    });
                });
            });
            return n;
        }

        window.openQuestComposer = function() {
            if (qcLiveActivityCount() < QC_MIN_ACTIVITIES) {
                showToast('Need ' + QC_MIN_ACTIVITIES + '+ activities to plan a quest', 'olive');
                return;
            }
            _qcShape = 'oneoff'; _qcSize = null;
            var box = document.getElementById('qcRequest');
            if (box) { box.value = ''; box.oninput = qcSyncCount; }
            qcSyncCount();
            qcPickShape('oneoff');
            var sizeHost = document.getElementById('qcSize');
            if (sizeHost) sizeHost.querySelectorAll('.qc-opt').forEach(function(b) { b.classList.remove('is-on'); });
            qcSetError('');
            qcSetBusy(false);
            var m = document.getElementById('questComposerModal');
            if (m) m.classList.add('active');
            setTimeout(function() { if (box) box.focus(); }, 60);
        };

        window.closeQuestComposer = function() {
            var m = document.getElementById('questComposerModal');
            if (m) m.classList.remove('active');
            clearInterval(_qcStepTimer);
            _qcStepTimer = null;
        };

        function qcSyncCount() {
            var box = document.getElementById('qcRequest');
            var out = document.getElementById('qcCount');
            if (box && out) out.textContent = String((box.value || '').length);
        }

        window.qcPickShape = function(shape) {
            _qcShape = shape === 'recurring' ? 'recurring' : 'oneoff';
            var host = document.getElementById('qcShape');
            if (!host) return;
            host.querySelectorAll('.qc-opt').forEach(function(b) {
                b.classList.toggle('is-on', b.getAttribute('data-shape') === _qcShape);
            });
        };

        window.qcPickSize = function(size) {
            // Tapping the chosen size again clears it — omitted means the model decides.
            _qcSize = (_qcSize === size) ? null : size;
            var host = document.getElementById('qcSize');
            if (!host) return;
            host.querySelectorAll('.qc-opt').forEach(function(b) {
                b.classList.toggle('is-on', _qcSize !== null && b.getAttribute('data-size') === _qcSize);
            });
        };

        function qcSetError(msg) {
            var el = document.getElementById('qcError');
            if (!el) return;
            el.textContent = msg || '';
            el.style.display = msg ? '' : 'none';
        }

        // The wait is 5-15 seconds of someone watching a screen, so it gets a
        // real state rather than a disabled button: the form steps aside, a
        // pipeline assembles itself, and the caption moves through what is
        // actually happening. The captions are paced, not synced to real
        // progress — a streamed call has no honest percentage to report, and a
        // fake bar that stalls at 80% is worse than none.
        var QC_BUILD_STEPS = [
            'Reading your activities\u2026',
            'Working out the shape\u2026',
            'Choosing what you already do\u2026',
            'Ordering the steps\u2026',
            'Almost there\u2026'
        ];
        var _qcStepTimer = null;

        function qcSetBusy(busy) {
            _qcBusy = busy;
            var btn = document.getElementById('qcSubmit');
            var form = document.getElementById('qcForm');
            var build = document.getElementById('qcBuilding');
            var cancel = document.querySelector('#questComposerModal .pl-btn-ghost');

            if (btn) { btn.disabled = busy; btn.style.display = busy ? 'none' : ''; }
            if (cancel) cancel.textContent = busy ? 'Cancel' : 'Cancel';
            if (form) form.style.display = busy ? 'none' : '';
            if (build) build.style.display = busy ? '' : 'none';

            clearInterval(_qcStepTimer);
            _qcStepTimer = null;
            if (!busy) return;

            var i = 0;
            var step = document.getElementById('qcBuildStep');
            if (step) step.textContent = QC_BUILD_STEPS[0];
            _qcStepTimer = setInterval(function() {
                i = Math.min(i + 1, QC_BUILD_STEPS.length - 1);
                var el = document.getElementById('qcBuildStep');
                if (!el) return;
                el.classList.remove('is-in');
                // reflow, so the fade replays on a repeated class
                void el.offsetWidth;
                el.textContent = QC_BUILD_STEPS[i];
                el.classList.add('is-in');
            }, 2600);
        }

        // The client's own activity index, for re-checking linkedActivityId
        // against what exists right now.
        function qcClientCtx() {
            var ids = Object.keys(window._prActIdx || {});
            var dims = ((window.userData && window.userData.dimensions) || []).map(function(d) { return d.id; });
            return { activityIds: new Set(ids), dimIds: new Set(dims), fallbackDim: dims[0] || 'uncategorized' };
        }

        window.qcSubmit = async function() {
            if (_qcBusy) return;
            var box = document.getElementById('qcRequest');
            var text = ((box && box.value) || '').trim();
            if (!text) { qcSetError('Tell me what you are trying to get done.'); return; }
            var RETRY = 'Couldn\u2019t put a plan together. Try describing it differently?';

            qcSetError('');
            qcSetBusy(true);
            try {
                var res = await qcCallCompose({ request: text, shape: _qcShape, size: _qcSize || undefined });

                if (!res || !res.ok) {
                    var reason = res && res.reason;
                    if (reason === 'gate') qcSetError('Need ' + QC_MIN_ACTIVITIES + '+ activities to plan a quest.');
                    else if (reason === 'ratelimit') qcSetError('That is all 3 plans for this week. The manual builder is always open.');
                    else qcSetError(RETRY);
                    qcSetBusy(false);
                    return;
                }

                // Validate again on receipt: the builder assumes well-formed
                // input, and this crossed a trust boundary.
                _buildActIdx();
                var ctx = qcClientCtx();
                var counter = { newActs: 0, leaves: 0, linked: {} };
                var groups = ((res.spec && res.spec.groups) || [])
                    .map(function(g) { return qcValidateGroup(g, ctx, counter, 1); })
                    .filter(Boolean);
                if (!groups.length) { qcSetError(RETRY); qcSetBusy(false); return; }
                qcDemoteExcessNewActivities(counter);

                closeQuestComposer();
                qcSetBusy(false);
                qcDraftToBuilder({
                    name: res.spec.name, emoji: res.spec.emoji, description: res.spec.description,
                    cadence: res.spec.cadence, groups: groups
                }, { title: 'Review your quest' });
                try { window.trackEvent && window.trackEvent('quest_composed', { shape: _qcShape }); } catch (e) {}
            } catch (err) {
                qcSetBusy(false);
                qcSetError(err && err.message === 'qc_timeout' ? 'That took too long. Try again?' : RETRY);
            }
        };

        // ── New-activity review ──────────────────────────────────────────────
        // A composed quest can mint real activities, and an activity is a
        // durable commitment — it earns XP forever, keeps a streak, and counts
        // toward the weekly quota. So nothing arrives silently: whatever was
        // created is shown, editable, and removable in one pass.
        var _qcReview = null;   // { projectId, items:[{activityId, leafId}] }

        // Resolved straight off userData rather than through the shared
        // activity index: that index is memoised on a fingerprint of dimension
        // / path / activity COUNTS, so a tree that changes without changing
        // any count hands back stale objects — and an edit written to a stale
        // object goes nowhere. This walk is a few dozen items and always live.
        function qcFindActivity(activityId) {
            if (!activityId) return null;
            var dims = (window.userData && window.userData.dimensions) || [];
            for (var di = 0; di < dims.length; di++) {
                var paths = dims[di].paths || [];
                for (var pi = 0; pi < paths.length; pi++) {
                    var acts = paths[pi].activities || [];
                    for (var ai = 0; ai < acts.length; ai++) {
                        if (acts[ai] && acts[ai].id === activityId) {
                            return { activity: acts[ai], dim: dims[di], path: paths[pi], index: ai };
                        }
                    }
                }
            }
            return null;
        }

        function qcOpenNewActivityReview(projectId, created) {
            var items = (created || []).filter(function(c) { return !!qcFindActivity(c.activityId); });
            if (!items.length) return;
            _qcReview = { projectId: projectId, items: items };
            qcRenderNewActivityReview();
            var m = document.getElementById('qcReviewModal');
            if (m) m.classList.add('active');
        }

        window.qcCloseNewActivityReview = function() {
            var m = document.getElementById('qcReviewModal');
            if (m) m.classList.remove('active');
            _qcReview = null;
            saveUserData();
            if (typeof renderActivities === 'function') { try { renderActivities(); } catch (e) {} }
        };

        function qcRenderNewActivityReview() {
            var host = document.getElementById('qcReviewBody');
            if (!host || !_qcReview) return;
            var live = _qcReview.items.filter(function(it) { return !!qcFindActivity(it.activityId); });
            _qcReview.items = live;

            if (!live.length) {
                host.innerHTML = '<div class="qc-rev-empty">All removed — the quest keeps those steps as plain tasks.</div>';
                qcSyncReviewCount();
                return;
            }

            var freqs = ['daily', 'weekly', 'biweekly', 'monthly', 'occasional'];
            host.innerHTML = live.map(function(it) {
                var found = qcFindActivity(it.activityId);
                var a = found.activity, dim = found.dim || {};
                var opts = freqs.map(function(f) {
                    return '<option value="' + f + '"' + (a.frequency === f ? ' selected' : '') + '>' + f + '</option>';
                }).join('');
                return '' +
                '<div class="qc-rev-card" data-act="' + prAttr(a.id) + '">' +
                    '<div class="qc-rev-top">' +
                        '<span class="qc-rev-badge">New activity</span>' +
                        (dim.name ? '<span class="qc-rev-dim">' + escapeHtml(dim.name) + '</span>' : '') +
                        '<button class="qc-rev-remove" onclick="qcRemoveNewActivity(\'' + a.id + '\')" title="Don\u2019t add this one">Remove</button>' +
                    '</div>' +
                    '<input class="pl-input qc-rev-name" type="text" maxlength="80" value="' + prAttr(a.name || '') + '" ' +
                        'oninput="qcEditNewActivity(\'' + a.id + '\',\'name\',this.value)" placeholder="Activity name">' +
                    '<textarea class="pl-input qc-rev-desc" rows="2" maxlength="200" ' +
                        'oninput="qcEditNewActivity(\'' + a.id + '\',\'description\',this.value)" ' +
                        'placeholder="What does doing this actually involve?">' + escapeHtml(a.description || '') + '</textarea>' +
                    '<div class="qc-rev-row">' +
                        '<label class="qc-rev-field"><span>XP</span>' +
                            '<input class="pl-input" type="number" min="1" max="50" value="' + (a.baseXP || 8) + '" ' +
                                'oninput="qcEditNewActivity(\'' + a.id + '\',\'baseXP\',this.value)"></label>' +
                        '<label class="qc-rev-field qc-rev-field-wide"><span>How often</span>' +
                            '<select class="pl-input ay-select" onchange="qcEditNewActivity(\'' + a.id + '\',\'frequency\',this.value)">' + opts + '</select></label>' +
                    '</div>' +
                '</div>';
            }).join('');
            qcSyncReviewCount();
        }

        function qcSyncReviewCount() {
            var n = (_qcReview && _qcReview.items.length) || 0;
            var el = document.getElementById('qcReviewCount');
            if (el) el.textContent = n === 1 ? '1 new activity' : n + ' new activities';
            var btn = document.getElementById('qcReviewAccept');
            if (btn) btn.textContent = n ? (n === 1 ? 'Add it' : 'Add all ' + n) : 'Done';
        }

        window.qcEditNewActivity = function(activityId, field, value) {
            var found = qcFindActivity(activityId);
            if (!found) return;
            var a = found.activity;
            if (field === 'baseXP') {
                a.baseXP = Math.min(50, Math.max(1, parseInt(value, 10) || 1));
            } else if (field === 'frequency') {
                a.frequency = value;
                // The mastery target is derived from the pace, so it has to
                // move with it rather than keep the original frequency's shape.
                if (typeof ttMasteryDefaultFor === 'function') a.techTreeMastery = ttMasteryDefaultFor(value);
            } else if (field === 'name') {
                a.name = String(value || '').slice(0, 80);
            } else if (field === 'description') {
                a.description = String(value || '').slice(0, 200);
            }
            debouncedSaveUserData();
        };

        // Removing keeps the step: the leaf falls back to the plain task it was
        // before the activity was minted, so the quest never loses a step.
        window.qcRemoveNewActivity = function(activityId) {
            if (!_qcReview) return;
            var entry = _qcReview.items.find(function(it) { return it.activityId === activityId; });
            var found = qcFindActivity(activityId);
            if (!entry || !found) return;
            var name = found.activity.name || 'this activity';

            var proj = findProject(_qcReview.projectId);
            if (proj) {
                var leaf = findNode(proj, entry.leafId);
                if (leaf && leaf.kind === 'leaf') {
                    leaf.type = 'task';
                    leaf.linkedActivityId = null;
                    leaf.name = name;
                }
            }

            (window.userData.dimensions || []).forEach(function(d) {
                (d.paths || []).forEach(function(pth) {
                    var i = (pth.activities || []).findIndex(function(x) { return x.id === activityId; });
                    if (i >= 0) pth.activities.splice(i, 1);
                });
            });

            _qcReview.items = _qcReview.items.filter(function(it) { return it.activityId !== activityId; });
            if (proj && typeof computeProjectDimensions === 'function') {
                var dims = computeProjectDimensions(proj.groups);
                proj.dimensionIds = dims.dimensionIds; proj.dimensionId = dims.dimensionId;
            }
            saveUserData();
            qcRenderNewActivityReview();
            if (window._openProjectId === _qcReview.projectId) renderProjectDetail(_qcReview.projectId);
            showToast('Kept as a task — ' + name, 'olive');
        };

        // ── The callable ─────────────────────────────────────────────────────
        // The region is passed explicitly where `functions` is created
        // (asia-south1, matching the Firestore database). Leave it out and the
        // SDK calls us-central1, finds nothing, and returns an error that
        // looks like CORS but is not.
        //
        // The SDK's own timeout is well under a minute, which would abandon a
        // legitimate composition, so it is set explicitly. The 30-second guard
        // below is the one the user actually feels — nobody should be left on
        // a spinner, and the callable is expected back in 5-15 seconds.
        var QC_CALL_TIMEOUT_MS = 180000;   // SDK ceiling
        var QC_USER_TIMEOUT_MS = 30000;    // what the user waits, at most

        async function qcCallCompose(payload) {
            var call = httpsCallable(functions, 'composeQuest', { timeout: QC_CALL_TIMEOUT_MS });
            var timer = null;
            var guard = new Promise(function(_, reject) {
                timer = setTimeout(function() { reject(new Error('qc_timeout')); }, QC_USER_TIMEOUT_MS);
            });
            try {
                var res = await Promise.race([call(payload), guard]);
                return (res && res.data) || null;
            } finally {
                clearTimeout(timer);
            }
        }

        // ── Validators ───────────────────────────────────────────────────────
        // KEEP IN SYNC: a byte-identical copy of qcValidateGroup /
        // qcValidateLeaf runs server-side in the composer Cloud Function, so a
        // malformed model response never reaches the client. Edit both or
        // neither.
        //
        // Ported verbatim from validateGroup / validateLeaf in the tech-tree
        // worker this repo used to run. Their leniency is load-bearing: Haiku
        // drops the `spec` wrapper and puts leaves where groups belong, and an
        // earlier strict implementation discarded the whole quest when it did
        // — which is why quests "never generated". Repair, do not reject.
        // New practices are capped as a SHARE of the quest, not a flat count:
        // three new activities in a four-step quest is a different thing from
        // three in a twenty-step pipeline. Applied once the total is known.
        var QC_NEW_ACTIVITY_SHARE = 0.3;
        var QC_MIN_NEW_ACTIVITIES = 2;
        var QC_MAX_NEW_ACTIVITIES = 6;
        function qcNewActivityAllowance(totalLeaves) {
            return Math.max(QC_MIN_NEW_ACTIVITIES,
                Math.min(QC_MAX_NEW_ACTIVITIES, Math.round(totalLeaves * QC_NEW_ACTIVITY_SHARE)));
        }
        // The excess is DEMOTED to tasks, never dropped: the step stays in the
        // plan, it just stops being a lifelong commitment.
        function qcDemoteExcessNewActivities(counter) {
            var made = counter.newLeaves || [];
            var allowed = qcNewActivityAllowance(counter.leaves);
            if (made.length <= allowed) return 0;
            var excess = made.slice(allowed);
            excess.forEach(function(leaf) {
                leaf.type = 'task';
                leaf.name = String((leaf.spec && leaf.spec.name) || 'Step').slice(0, 80);
                leaf.linkedActivityId = null;
                delete leaf.spec;
            });
            counter.newActs -= excess.length;
            return excess.length;
        }
        var QC_MAX_LEAVES = 20;
        var QC_MAX_DEPTH = 3;
        var QC_VALID_FREQUENCIES = ['daily', 'weekly', 'biweekly', 'monthly', 'occasional'];
        function qcNewId(prefix) { return prefix + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

        // ctx: { activityIds:Set, dimIds:Set, fallbackDim:string }
        // counter: { newActs:int, leaves:int } — mutated. The caps are enforced
        // here, not merely requested in the prompt: excess new activities are
        // demoted to tasks, excess leaves truncated, excess depth flattened.
        function qcValidateGroup(g, ctx, counter, depth) {
            if (!g || typeof g !== 'object') return null;
            if (g.kind === 'leaf' || g.type) return null; // a bare leaf at group position
            depth = depth || 1;

            var raw = Array.isArray(g.children) ? g.children : [];
            var children = [];
            for (var i = 0; i < raw.length; i++) {
                if (counter.leaves >= QC_MAX_LEAVES) break;
                var c = raw[i], built;
                if (c && c.kind === 'group') {
                    // Past the ceiling a nested group is flattened into its
                    // parent rather than dropped, so its steps survive.
                    if (depth >= QC_MAX_DEPTH) {
                        var inner = qcValidateGroup(c, ctx, counter, depth);
                        if (inner) children.push.apply(children, inner.children);
                        continue;
                    }
                    built = qcValidateGroup(c, ctx, counter, depth + 1);
                } else {
                    built = qcValidateLeaf(c, ctx, counter);
                }
                if (built) children.push(built);
            }
            if (!children.length) return null;            // every group has >=1 child

            return {
                id: qcNewId('grp'),
                kind: 'group',
                name: String(g.name || '').slice(0, 60),
                ordered: !!g.ordered,
                repeat: Math.max(1, parseInt(g.repeat, 10) || 1),
                repsDone: 0,
                children: children
            };
        }

        function qcValidateLeaf(l, ctx, counter) {
            if (!l || typeof l !== 'object') return null;
            if (counter.leaves >= QC_MAX_LEAVES) return null;

            var req = Math.max(1, parseInt(l.requiredCount, 10) || 1);
            var resetMode = l.resetMode === 'once' ? 'once' : 'per-cycle';
            var type = l.type === 'activity' ? 'activity' : 'task';

            if (type === 'activity') {
                // Re-checked here in case the activity was deleted between the
                // call returning and the user saving.
                if (l.linkedActivityId && ctx.activityIds.has(l.linkedActivityId)) {
                    // One activity, one leaf. The model likes to repeat an
                    // activity in every group it feels relevant to, which shows
                    // up as duplicate cards for the same thing. A repeat is
                    // FOLDED INTO the first leaf rather than dropped, so the
                    // work it represents survives.
                    if (!counter.linked) counter.linked = {};
                    var seen = counter.linked[l.linkedActivityId];
                    if (seen) {
                        seen.requiredCount = Math.min(99, seen.requiredCount + req);
                        return null;
                    }
                    counter.leaves++;
                    var built = {
                        id: qcNewId('lf'), kind: 'leaf', type: 'activity', linkedActivityId: l.linkedActivityId,
                        name: '', resetMode: resetMode, requiredCount: req, completedCount: 0
                    };
                    counter.linked[l.linkedActivityId] = built;
                    return built;
                }
                var spec = l.spec || {};
                if (counter.newActs >= QC_MAX_NEW_ACTIVITIES) {
                    type = 'task'; // demote the excess rather than dropping it
                } else if (spec && (spec.baseXP || spec.frequency || spec.dimensionId || l.name)) {
                    counter.newActs++;
                    counter.leaves++;
                    var madeNew = {
                        id: qcNewId('lf'), kind: 'leaf', type: 'activity', linkedActivityId: null,
                        name: '', resetMode: resetMode, requiredCount: req, completedCount: 0,
                        spec: {
                            name: String(spec.name || l.name || 'Practice').slice(0, 80),
                            description: String(spec.description || '').slice(0, 200),
                            baseXP: Math.min(50, Math.max(1, parseInt(spec.baseXP, 10) || 8)),
                            frequency: QC_VALID_FREQUENCIES.indexOf(spec.frequency) !== -1 ? spec.frequency : 'weekly',
                            dimensionId: ctx.dimIds.has(spec.dimensionId) ? spec.dimensionId : ctx.fallbackDim
                        }
                    };
                    if (!counter.newLeaves) counter.newLeaves = [];
                    counter.newLeaves.push(madeNew);
                    return madeNew;
                } else {
                    type = 'task';
                }
            }
            var name = String(l.name || '').trim();
            if (!name) return null;   // a task leaf needs a name
            counter.leaves++;
            return {
                id: qcNewId('lf'), kind: 'leaf', type: 'task', linkedActivityId: null,
                name: name.slice(0, 80), resetMode: resetMode, requiredCount: req, completedCount: 0
            };
        }

        // ════════════════════════════════════════════════════════════════════
        // ── APP-WIDE BACK-BUTTON GUARD ───────────────────────────────────────
        // On Android (PWA), the hardware back button must never accidentally
        // exit the app. One guard entry sits in the history stack; pressing
        // back (1) closes whatever overlay/sheet/modal is on screen, else
        // (2) returns to the home tab, else (3) warns once — and only the
        // NEXT press actually leaves. Any tap re-arms the guard.
        // The profile overlay and quest detail view push their own history
        // entries with their own popstate handlers; those pops land back ON
        // the guard state (e.state.mkGuard), which tells us to stand down.
        // ════════════════════════════════════════════════════════════════════
        (function() {
            var HOME_TAB = 'activities';
            var armed = false;

            function arm() {
                if (armed) return;
                try { history.pushState({ mkGuard: 1 }, ''); armed = true; } catch (e) {}
            }

            // Close the top-most thing on screen. Order matters: sheets and
            // pickers sit above modals, modals above tabs.
            function closeTopOverlay() {
                var sheet = document.getElementById('ttSheet');
                if (sheet && sheet.style.display === 'flex') { try { ttCloseSheet(); } catch (e) {} return true; }
                var ov = document.getElementById('ttOverlay');
                if (ov && ov.style.display === 'flex') { try { ttCloseOverlay(); } catch (e) {} return true; }
                var menu = document.getElementById('gcActionMenu');
                if (menu && menu.style.display && menu.style.display !== 'none') {
                    if (typeof closeGridActionMenu === 'function') { try { closeGridActionMenu(); } catch (e) {} return true; }
                }
                // Known modals with dedicated close functions (they reset state).
                var closers = [
                    ['projectActivityPicker', 'closeProjectActivityPicker'],
                    ['activityModal', 'closeActivityModal'],
                    ['projectModal', 'closeProjectModal'],
                ];
                for (var i = 0; i < closers.length; i++) {
                    var el = document.getElementById(closers[i][0]);
                    if (el && el.classList.contains('active')) {
                        var fn = window[closers[i][1]];
                        if (typeof fn === 'function') { try { fn(); } catch (e) { el.classList.remove('active'); } }
                        else el.classList.remove('active');
                        return true;
                    }
                }
                // Anything else styled as an open modal (challenge, dimension,
                // path, group, info, reward…): try its conventional closer,
                // fall back to just dismissing it.
                var open = document.querySelector('.modal.active, [id$="Modal"].active');
                if (open && open.id) {
                    var conv = window['close' + open.id.charAt(0).toUpperCase() + open.id.slice(1)];
                    if (typeof conv === 'function') { try { conv(); } catch (e) { open.classList.remove('active'); } }
                    else open.classList.remove('active');
                    return true;
                }
                return false;
            }

            // Any interaction re-arms the guard, so there is always exactly
            // one buffer entry between the user and leaving the app.
            document.addEventListener('click', function() { arm(); }, true);
            arm();

            window.addEventListener('popstate', function(e) {
                if (e.state && e.state.mkGuard) {
                    // An entry ABOVE the guard was popped (profile overlay /
                    // quest detail). Its own handler closed the view — the
                    // guard is still in place.
                    armed = true;
                    return;
                }
                // The guard itself was consumed.
                armed = false;
                if (closeTopOverlay()) { arm(); return; }
                if (window.currentTab && window.currentTab !== HOME_TAB) {
                    try { switchTab(HOME_TAB); } catch (err) {}
                    arm();
                    return;
                }
                try { showToast('Press back again to exit', 'olive'); } catch (err) {}
                // Deliberately not re-armed: the next back press exits.
            });
        })();


        // ════════════════════════════════════════════════════════════════════
        // ══ GRIT CURRENCY SYSTEM ════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // Self-contained. Everything below is namespaced `grit*` and reaches
        // the rest of the app through four surgical hook points only:
        //
        //   predictCompletionXP()  — reads the armed XP boost (×2)
        //   completeActivity()     — one call to gritOnCompletion()
        //   retroactiveComplete()  — one call to gritOnRetroComplete()
        //   retroactiveDelete()    — one call to gritOnRetroDelete()
        //   processStreakPauses()  — one call to gritOnLogin()
        //
        // Balance and state live in `userData.grit` (rides the existing
        // saveUserData full-document write). The ledger lives in the
        // `users/{uid}/gritLedger` SUBCOLLECTION so saveUserData's setDoc
        // can never clobber it and it never bloats the user document.
        //
        // NOTHING here touches the tech tree's unsealing, modes, quests or
        // social features (§8.12). It reads `techTreeMasteredAt` — a value
        // the tech tree already writes — and nothing else.
        // ════════════════════════════════════════════════════════════════════

        // ── Rate card ─────────────────────────────────────────────────────
        // Single source of truth for every number in the system.
        const GRIT_SCHEMA_VERSION   = 1;
        const GRIT_DRIP             = 1;      // §4.1 per completion
        const GRIT_CADENCE_BONUS    = 5;      // §4.2 occasional on-rhythm
        const GRIT_CADENCE_MIN_PRIOR = 4;     // §4.2 prior completions required
        const GRIT_CADENCE_SAMPLE   = 6;      // §4.2 last N completions for the median
        const GRIT_CADENCE_LO       = 0.5;    // §4.2 window around the median
        const GRIT_CADENCE_HI       = 1.5;
        const GRIT_STREAK_TIERS     = [       // §4.3 [days, grit]
            [7, 10], [14, 20], [30, 40], [60, 60], [100, 100]
        ];
        const GRIT_MASTERY_FLOOR    = 40;     // §4.4 1 per required rep, clamped
        const GRIT_MASTERY_CAP      = 120;
        const GRIT_SHIELD_COST      = 40;     // §5.1 uncapped
        const GRIT_BOOST_COST       = 50;     // §5.2
        const GRIT_BOOST_PER_MONTH  = 1;      // §5.2 calendar-month cap

        // ── Gifting rate card (gifting spec §3.2) ─────────────────────────
        // A gifted item ALWAYS costs half the self-purchase price. That ratio
        // is the standing rule for every future giftable item — it exists to
        // push people toward bringing friends in rather than self-servicing,
        // so derive it, never hand-write a second number.
        const GRIT_GIFT_RATIO           = 0.5;
        const GRIT_GIFT_SHIELD_COST     = Math.round(GRIT_SHIELD_COST * GRIT_GIFT_RATIO);  // 20
        const GRIT_GIFT_BOOST_COST      = Math.round(GRIT_BOOST_COST  * GRIT_GIFT_RATIO);  // 25
        const GRIT_GIFT_BOOST_PER_MONTH = 3;  // gifted boosts, counted separately
                                              // from the 1 self-purchase

        const GRIT_RATIO_CAP        = 1.30;   // §3.5

        // §3.5 / rate card §1.2 — weekly bonus curve, [ratio, grit], linearly
        // interpolated between anchors and rounded to whole Grit.
        //
        // Below 20% the payout is a hard zero, NOT an interpolation down to
        // nothing: the rate card lists "Below 20% → 0" as its own row, so 19%
        // pays nothing and 20% pays 30. The cliff is deliberate — it is the
        // floor that makes the bonus mean "you showed up this week".
        const GRIT_WEEKLY_MIN_RATIO = 0.20;
        const GRIT_WEEKLY_CURVE = [
            [0.20,  30],
            [0.30,  36],
            [0.40,  42],
            [0.50,  48],
            [0.60,  54],
            [0.70,  60],
            [0.80,  65],
            [0.90,  70],
            [1.00,  75],
            [1.10,  83],
            [1.20,  91],
            [1.30, 100]
        ];

        // ── State access ──────────────────────────────────────────────────
        // Returns the live grit object, creating it on first touch. Never
        // returns null: callers that run before sign-in get a throwaway that
        // is discarded when userData loads.
        function gritState() {
            if (!window.userData) return null;
            var g = window.userData.grit;
            if (!g || typeof g !== 'object') {
                g = window.userData.grit = {
                    schemaVersion: GRIT_SCHEMA_VERSION,
                    balance: 0, lifetimeEarned: 0, lifetimeSpent: 0,
                    shieldPool: 0,
                    week: null,
                    awarded: {},
                    boostPurchases: [],
                    cadence: {},
                    pendingBoost: null
                };
            }
            if (g.schemaVersion !== GRIT_SCHEMA_VERSION) g.schemaVersion = GRIT_SCHEMA_VERSION;
            if (typeof g.balance !== 'number' || !isFinite(g.balance)) g.balance = 0;
            if (typeof g.lifetimeEarned !== 'number') g.lifetimeEarned = 0;
            if (typeof g.lifetimeSpent !== 'number') g.lifetimeSpent = 0;
            if (typeof g.shieldPool !== 'number') g.shieldPool = 0;
            if (!g.awarded || typeof g.awarded !== 'object') g.awarded = {};
            if (!Array.isArray(g.boostPurchases)) g.boostPurchases = [];
            if (!g.cadence || typeof g.cadence !== 'object') g.cadence = {};
            return g;
        }

        function gritBalance() { var g = gritState(); return g ? g.balance : 0; }
        window.gritBalance = gritBalance;

        // ── Ledger (users/{uid}/gritLedger) ───────────────────────────────
        // Append-only. Never mutated, never deleted. Entry ids are
        // timestamp-prefixed so the raw collection reads chronologically and
        // ids never collide; the Rewards tab pages newest-first by ordering
        // on the `at` field (see gritReadLedger for why not by id).
        let _gritLedgerBuffer = [];
        let _gritLedgerTimer  = null;
        let _gritLedgerSeq    = 0;

        function gritLedgerId(atISO) {
            // 2026-08-22T09:14:07.221Z → 20260822T091407221 + seq + rand,
            // so ids sort chronologically and never collide inside one ms.
            var stamp = String(atISO).replace(/[-:.]/g, '').replace('Z', '');
            _gritLedgerSeq = (_gritLedgerSeq + 1) % 1000;
            return stamp + '-' + String(_gritLedgerSeq).padStart(3, '0') + '-' +
                   Math.random().toString(36).slice(2, 7);
        }

        // Buffers an entry. §2.2: the per-completion drip fires constantly, so
        // we never write a document per tap — the balance in userData updates
        // immediately and the ledger catches up on a debounce, on tab blur,
        // and on unload.
        function gritLedgerWrite(delta, balanceAfter, reason, meta) {
            var at = new Date().toISOString();
            var entry = {
                at: at, delta: delta, balanceAfter: balanceAfter, reason: reason,
                meta: meta || {}
            };
            _gritLedgerBuffer.push({ id: gritLedgerId(at), data: entry });
            clearTimeout(_gritLedgerTimer);
            _gritLedgerTimer = setTimeout(function () { gritFlushLedger(); }, 5000);
            return entry;
        }

        async function gritFlushLedger() {
            clearTimeout(_gritLedgerTimer);
            _gritLedgerTimer = null;
            if (!_gritLedgerBuffer.length) return;
            if (!canPersistUserData('gritLedger')) return;   // keep buffered; retry later
            var pending = _gritLedgerBuffer;
            _gritLedgerBuffer = [];
            try {
                var uid = window.currentUser.uid;
                // Firestore caps a batch at 500 writes.
                for (var i = 0; i < pending.length; i += 400) {
                    var slice = pending.slice(i, i + 400);
                    var batch = writeBatch(db);
                    slice.forEach(function (e) {
                        batch.set(doc(db, 'users', uid, 'gritLedger', e.id), e.data);
                    });
                    await batch.commit();
                }
                _gritLogCache = null;
            } catch (err) {
                // Put them back — the ledger is append-only and must not lose
                // entries. Balance is already correct in userData either way.
                console.warn('Grit ledger flush failed, re-buffering:', err && err.message);
                _gritLedgerBuffer = pending.concat(_gritLedgerBuffer);
            }
        }

        async function gritReadLedger(max) {
            if (!canPersistUserData('gritLedgerRead')) return [];
            try {
                var col = collection(db, 'users', window.currentUser.uid, 'gritLedger');
                // Ordered by the `at` field, NOT by document id: Firestore
                // refuses a descending key scan outright
                // (failed-precondition), so orderBy(documentId(), 'desc')
                // throws on every call. `at` is an ISO-8601 UTC string, so
                // lexicographic order is chronological order, and a single
                // field plus a limit is served by the automatic single-field
                // index — still no composite index to configure.
                var snap = await getDocs(query(col, orderBy('at', 'desc'), limit(max || 20)));
                var out = [];
                snap.forEach(function (d) { out.push(d.data()); });
                return out;
            } catch (err) {
                console.warn('Grit ledger read failed:', err && err.message);
                return [];
            }
        }

        // ── Balance arithmetic ────────────────────────────────────────────
        // §8.4 the balance never goes negative; §8.6 every change writes a
        // ledger entry with an attributable reason.
        function gritApplyDelta(delta, reason, meta) {
            var g = gritState();
            if (!g) return 0;
            delta = Math.round(delta || 0);
            if (!delta) return g.balance;

            var raw = g.balance + delta;
            if (raw < 0) {
                // Should be unreachable — every spend path checks first. If we
                // get here the arithmetic is wrong somewhere, so clamp and say
                // so in the ledger rather than silently carrying a negative.
                var shortfall = -raw;
                var applied = delta + shortfall;          // what actually moved
                console.warn('Grit: clamped a negative balance (' + raw + ') from ' + reason);
                g.balance = 0;
                if (delta < 0) g.lifetimeSpent += -applied;
                gritLedgerWrite(applied, 0, reason, meta || {});
                // The correction carries delta 0 on purpose: nothing was
                // credited, so summing every delta in the ledger still lands
                // exactly on the balance. It is a note in the record of a
                // clamp that happened, with the arithmetic that caused it.
                gritLedgerWrite(0, 0, 'correction', {
                    note: 'clamped to zero', attemptedFrom: reason,
                    attemptedDelta: delta, shortfall: shortfall
                });
                gritRefreshUI();
                return 0;
            }

            g.balance = raw;
            if (delta > 0) g.lifetimeEarned += delta; else g.lifetimeSpent += -delta;
            gritLedgerWrite(delta, g.balance, reason, meta || {});
            gritRefreshUI();
            return g.balance;
        }

        // Persists userData and reports success honestly. §5.3 requires
        // persistence to precede the grant, so purchases need a save they can
        // actually check — saveUserData() swallows its error and alerts.
        async function gritPersist() {
            if (!canPersistUserData('gritPersist')) return false;
            try {
                await setDoc(doc(db, 'users', window.currentUser.uid), window.userData);
                return true;
            } catch (err) {
                console.error('Grit persist failed:', err);
                return false;
            }
        }

        // ── Dates ─────────────────────────────────────────────────────────
        // All Grit dates are local YYYY-MM-DD via the app's existing
        // toLocalDateStr(). completionHistory stores full ISO timestamps, so
        // every comparison goes through this pair.
        function gritDayOf(isoOrDate) {
            return toLocalDateStr(isoOrDate instanceof Date ? isoOrDate : new Date(isoOrDate));
        }

        // Monday 00:00 local of the week containing `d` (§3.1).
        function gritWeekAnchorOf(d) {
            var dt = d ? new Date(d.getTime()) : new Date();
            dt.setHours(0, 0, 0, 0);
            dt.setDate(dt.getDate() - ((dt.getDay() + 6) % 7));   // 0=Sun → back 6
            return dt;
        }
        function gritWeekAnchorStr(d) { return toLocalDateStr(gritWeekAnchorOf(d)); }

        function gritDaysBetween(aISO, bISO) {
            return (new Date(bISO).getTime() - new Date(aISO).getTime()) / 86400000;
        }

        // ── Activity classification ───────────────────────────────────────
        function gritAllActivities() {
            var out = [];
            ((window.userData && window.userData.dimensions) || []).forEach(function (dim) {
                (dim.paths || []).forEach(function (path) {
                    (path.activities || []).forEach(function (act) { out.push(act); });
                });
            });
            return out;
        }

        function gritFindActivity(id) {
            var hit = null;
            gritAllActivities().some(function (a) { if (a.id === id) { hit = a; return true; } return false; });
            return hit;
        }

        function gritIsOccasional(a) {
            return a.frequency === 'occasional' || a.frequency === 'one-time' || !a.frequency;
        }

        // A perform-mode negative habit costs XP when done. Putting one in the
        // denominator would pay the user to do the thing they are trying to
        // stop, so it is excluded from BOTH the quota and the drip. Skip-mode
        // negatives (isSkipNegative) pay positive XP when performed and are
        // treated as ordinary activities.
        function gritIsPunitive(a) {
            return !!(a.isNegative && !a.isSkipNegative);
        }

        function gritIsCountable(a) {
            return !!a && !a.archived && !a.deleted && !gritIsPunitive(a);
        }

        // What the "+N Grit" float will say for a completion that is about to
        // land. Read by the float BEFORE the award runs, so it goes through
        // the same countability rule the award itself uses — the two can never
        // disagree, and a punitive activity that earns nothing shows nothing.
        function gritDripPreview(activity) {
            return (gritState() && gritIsCountable(activity)) ? GRIT_DRIP : 0;
        }
        window.gritDripPreview = gritDripPreview;

        // §3.2 — lookback window for liveness, in days.
        //   daily / weekly → 7; anything longer → its own cycle length.
        function gritLookbackDays(a) {
            switch (a.frequency) {
                case 'daily':    return 7;
                case 'weekly':   return 7;
                case 'biweekly': return 14;
                case 'monthly':  return 30;
                case 'custom':
                    if (a.customSubtype === 'days') return 7;   // day-pinned: weekly window
                    return Math.max(7, a.customDays || 1);
                default:         return 7;
            }
        }

        // §3.3 — weekly quota units this activity contributes.
        //   daily 7 · weekly 1 · biweekly 0.5 · monthly 7/30
        //   custom cycle: 7 × timesPerCycle ÷ customDays
        //   custom day-pinned: 1 per required completion, NOT one per eligible
        //     day — pinning narrows WHEN, not HOW MUCH
        //   occasional / one-time / no frequency: 0, always (§8.8)
        function gritQuotaUnits(a) {
            if (!gritIsCountable(a)) return 0;
            if (gritIsOccasional(a)) return 0;
            switch (a.frequency) {
                case 'daily':    return 7;
                case 'weekly':   return 1;
                case 'biweekly': return 7 / 14;
                case 'monthly':  return 7 / 30;
                case 'custom': {
                    var n = Math.max(1, a.timesPerCycle || 1);
                    if (a.customSubtype === 'days') {
                        // No eligible day pinned → nothing is owed this week.
                        if (!a.scheduledDays || !a.scheduledDays.length) return 0;
                        return n;
                    }
                    var d = Math.max(1, a.customDays || 1);
                    return 7 * n / d;
                }
                default: return 0;
            }
        }

        // §3.2 — at least one completion inside the lookback window, counted
        // backward from the week anchor. No dormant flag, no user toggle: an
        // activity you stopped doing quietly leaves the denominator.
        function gritIsLive(a, refDate) {
            var backMs = refDate.getTime() - gritLookbackDays(a) * 86400000;
            var refMs  = refDate.getTime();
            var hist = a.completionHistory || [];
            // Scanned newest-first but WITHOUT an early exit on the first
            // too-old entry. completionHistory is kept sorted everywhere it is
            // written, but liveness decides whether an activity is in the
            // denominator at all — too load-bearing to rest on an ordering
            // invariant maintained somewhere else. 365 entries at most.
            for (var i = hist.length - 1; i >= 0; i--) {
                var e = hist[i];
                if (!e || e.isPenalty || (e.xp || 0) <= 0) continue;
                var t = new Date(e.date).getTime();
                if (t >= backMs && t < refMs) return true;
            }
            return false;
        }

        // Builds the frozen denominator for the week starting `anchorDate`.
        function gritBuildWeekQuota(anchorDate) {
            var contributors = [];
            var quota = 0;
            gritAllActivities().forEach(function (a) {
                if (!gritIsCountable(a)) return;
                var units = gritQuotaUnits(a);
                if (units <= 0) return;
                if (!gritIsLive(a, anchorDate)) return;
                quota += units;
                contributors.push({
                    activityId: a.id,
                    title: a.name || 'Activity',
                    quotaUnits: Math.round(units * 100) / 100
                });
            });
            return { quota: Math.round(quota * 100) / 100, contributors: contributors };
        }

        // ── The weekly quota engine (§3) ──────────────────────────────────

        function gritNewWeek(anchorStr) {
            // Liveness is measured backward from the moment the week actually
            // opens. On a Monday-morning open that is the anchor, exactly as
            // §3.2 describes. When the week is opened LATE — a cold start on a
            // Wednesday, a first run after deploy, a user returning mid-week —
            // the anchor is already in the past, and measuring from it would
            // ignore everything they have done since Monday and hand them an
            // empty denominator for a week they were plainly active in. The
            // reference is therefore the later of the anchor and now.
            var anchorDate = new Date(anchorStr + 'T00:00:00');
            var now = new Date();
            var built = gritBuildWeekQuota(now > anchorDate ? now : anchorDate);
            return {
                anchor: anchorStr,
                quota: built.quota,
                completions: 0,
                byActivity: {},          // numerator split, so §3.4 deletions
                                         // can be subtracted from it
                contributors: built.contributors,
                reconciledAt: null
            };
        }

        // §3.5 — payout curve, linearly interpolated between anchors and
        // rounded to whole Grit.
        function gritCurve(ratio) {
            var c = GRIT_WEEKLY_CURVE;
            if (!c.length) return 0;
            if (ratio < GRIT_WEEKLY_MIN_RATIO) return 0;   // the cliff, not a ramp
            if (ratio <= c[0][0]) return Math.round(c[0][1]);
            for (var i = 1; i < c.length; i++) {
                if (ratio <= c[i][0]) {
                    var span = c[i][0] - c[i - 1][0];
                    var f = span > 0 ? (ratio - c[i - 1][0]) / span : 0;
                    return Math.round(c[i - 1][1] + f * (c[i][1] - c[i - 1][1]));
                }
            }
            return Math.round(c[c.length - 1][1]);
        }

        // §3.5 — ratio = min(completions / quota, 1.30). A zero denominator
        // is NOT a divide-by-zero and NOT a payout: it is "nothing has a
        // frequency set", which the UI says plainly (§8.9).
        function gritWeekRatio(week) {
            if (!week || !week.quota || week.quota <= 0) return null;
            return Math.min(week.completions / week.quota, GRIT_RATIO_CAP);
        }

        function gritProjectedBonus(week) {
            var r = gritWeekRatio(week);
            return r === null ? 0 : gritCurve(r);
        }

        // §3.4 — activities deleted mid-week leave the denominator immediately
        // and take their completions out of the numerator with them. Done
        // lazily (on every week touch and every render) rather than by hooking
        // the several delete paths, so no deletion route can miss it.
        function gritReconcileContributors(g) {
            var w = g.week;
            if (!w || !Array.isArray(w.contributors)) return false;
            var changed = false;
            var kept = [];
            w.contributors.forEach(function (c) {
                if (gritFindActivity(c.activityId)) { kept.push(c); return; }
                w.quota = Math.max(0, Math.round((w.quota - c.quotaUnits) * 100) / 100);
                changed = true;
            });
            if (changed) w.contributors = kept;

            // Numerator: drop the completions of activities that no longer
            // exist. deleteOnComplete activities are excluded — they are
            // *meant* to vanish on completion and their completion was real.
            var by = w.byActivity || (w.byActivity = {});
            Object.keys(by).forEach(function (id) {
                if (by[id] && by[id].keepOnDelete) return;
                if (gritFindActivity(id)) return;
                var n = (typeof by[id] === 'number') ? by[id] : (by[id].n || 0);
                if (n > 0) { w.completions = Math.max(0, w.completions - n); changed = true; }
                delete by[id];
            });
            return changed;
        }

        function gritBumpNumerator(g, activity, delta) {
            var w = g.week;
            if (!w) return;
            w.completions = Math.max(0, w.completions + delta);
            var by = w.byActivity || (w.byActivity = {});
            var cur = by[activity.id];
            var rec = (cur && typeof cur === 'object') ? cur : { n: (typeof cur === 'number' ? cur : 0) };
            rec.n = Math.max(0, (rec.n || 0) + delta);
            // An occasional activity with deleteOnComplete removes itself the
            // instant it is completed. Mark the tally so the reconcile pass
            // above doesn't then take the completion back.
            if (activity.deleteOnComplete) rec.keepOnDelete = true;
            if (rec.n === 0 && !rec.keepOnDelete) delete by[activity.id]; else by[activity.id] = rec;
        }

        // §3.6 — rollover. Called on login and before every write that touches
        // the week. Returns true when anything changed.
        let _gritEnsuring = false;
        function gritEnsureWeek(opts) {
            var g = gritState();
            if (!g || _gritEnsuring) return false;
            _gritEnsuring = true;
            try { return gritEnsureWeekInner(g); } finally { _gritEnsuring = false; }
        }

        function gritEnsureWeekInner(g) {
            var nowAnchor = gritWeekAnchorStr(new Date());
            var changed = false;

            if (!g.week || !g.week.anchor) {
                g.week = gritNewWeek(nowAnchor);
                return true;
            }

            if (g.week.anchor === nowAnchor) {
                return gritReconcileContributors(g) || changed;
            }

            // ── A boundary has passed ─────────────────────────────────────
            // The stored week is the most recent week the app actually
            // observed. §3.6: reconcile that one and only that one. If the
            // user was away for a month, the weeks in between were never
            // observed, have no frozen denominator and no completions — they
            // pay nothing and are not reconstructed.
            var closed = g.week;
            gritReconcileContributors(g);
            var marker = 'weekly:' + closed.anchor;
            if (!g.awarded[marker]) {
                g.awarded[marker] = true;
                var ratio = gritWeekRatio(closed);
                var payout = ratio === null ? 0 : gritCurve(ratio);
                closed.reconciledAt = new Date().toISOString();
                if (payout > 0) {
                    gritApplyDelta(payout, 'weekly_bonus', {
                        ratio: Math.round(ratio * 1000) / 1000,
                        quota: closed.quota,
                        completions: closed.completions,
                        anchor: closed.anchor
                    });
                    gritBurstAdd('Weekly consistency (' + Math.round(ratio * 100) + '% of target)', payout);
                }
                g.lastClosedWeek = {
                    anchor: closed.anchor, quota: closed.quota,
                    completions: closed.completions,
                    ratio: ratio, payout: payout
                };
            }

            // §3.6.3–4 — rebuild the denominator against current activities,
            // reset the numerator, advance straight to the current Monday.
            g.week = gritNewWeek(nowAnchor);
            return true;
        }

        // ── Earn: idempotency ─────────────────────────────────────────────
        // §8.5 — every award path is idempotent by explicit marker, never by
        // assuming single execution. Mastery and streak evaluation each run on
        // login, after every completion AND on every render.
        function gritAwardOnce(marker, amount, reason, meta, toastLabel) {
            var g = gritState();
            if (!g || g.awarded[marker]) return false;
            g.awarded[marker] = true;
            gritApplyDelta(amount, reason, meta);
            if (toastLabel) gritBurstAdd(toastLabel, amount);
            return true;
        }

        // ── Earn: streak milestones (§4.3) ────────────────────────────────
        // Awards every unpaid tier at or below the current streak, so a
        // retroactive edit that jumps a streak from 5 to 31 pays 7, 14 and 30
        // once each. A rebuilt streak never re-pays: the marker lives for the
        // life of the activity (§4.3).
        function gritCheckStreakMilestones(activity) {
            if (!gritIsCountable(activity) || gritIsOccasional(activity)) return false;
            var streak = activity.streak || 0;
            if (streak <= 0) return false;
            var any = false;
            GRIT_STREAK_TIERS.forEach(function (tier) {
                if (streak < tier[0]) return;
                var paid = gritAwardOnce(
                    'streak:' + activity.id + ':' + tier[0], tier[1], 'streak_milestone',
                    { activityId: activity.id, activityTitle: activity.name, streakDays: tier[0] },
                    tier[0] + '-day streak on ' + (activity.name || 'activity')
                );
                if (paid) any = true;
            });
            return any;
        }

        // ── Earn: mastery (§4.4) ──────────────────────────────────────────
        // 1 Grit per required rep, floored at 40 and capped at 120. The
        // required rep count is techTreeMastery.count — the same figure
        // ttMasteryProgress() measures against. The tech-tree node that
        // resolves alongside mastery pays nothing extra: one event, one payout.
        function gritMasteryReps(activity) {
            var th = activity.techTreeMastery ||
                     (typeof ttMasteryDefaultFor === 'function'
                        ? ttMasteryDefaultFor(activity.frequency) : null);
            return Math.max(1, (th && th.count) || 1);
        }

        function gritCheckMastery() {
            var g = gritState();
            if (!g) return false;
            var any = false;
            gritAllActivities().forEach(function (a) {
                if (!a.techTreeMasteredAt) return;
                if (g.awarded['mastery:' + a.id]) return;
                var reps = gritMasteryReps(a);
                var pay = Math.min(GRIT_MASTERY_CAP, Math.max(GRIT_MASTERY_FLOOR, reps));
                if (gritAwardOnce('mastery:' + a.id, pay, 'mastery',
                        { activityId: a.id, activityTitle: a.name, masteryReps: reps },
                        'Mastered ' + (a.name || 'activity'))) any = true;
            });
            return any;
        }

        // ── Earn: occasional cadence bonus (§4.2) ─────────────────────────
        // +5 when an occasional activity lands inside its established rhythm.
        // Needs ≥4 PRIOR completions before it activates, so a rhythm can't be
        // faked quickly; gaps are fractional days, so completing something
        // twice in one day falls below the 50% floor and pays nothing.
        function gritMedian(nums) {
            if (!nums.length) return 0;
            var s = nums.slice().sort(function (a, b) { return a - b; });
            var m = Math.floor(s.length / 2);
            return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
        }

        function gritCheckCadence(activity, thisCompletionISO) {
            var g = gritState();
            if (!g || !gritIsOccasional(activity) || !gritIsCountable(activity)) return 0;

            // Prior completions only — this one is already in history.
            var hist = (activity.completionHistory || [])
                .filter(function (e) { return !e.isPenalty && (e.xp || 0) > 0; })
                .map(function (e) { return e.date; })
                .sort();
            var idx = hist.lastIndexOf(thisCompletionISO);
            var prior = idx === -1 ? hist.slice(0, -1) : hist.slice(0, idx);
            if (prior.length < GRIT_CADENCE_MIN_PRIOR) return 0;

            var sample = prior.slice(-GRIT_CADENCE_SAMPLE);
            var gaps = [];
            for (var i = 1; i < sample.length; i++) gaps.push(gritDaysBetween(sample[i - 1], sample[i]));
            if (!gaps.length) return 0;
            var median = gritMedian(gaps);

            var currentGap = gritDaysBetween(prior[prior.length - 1], thisCompletionISO);
            var onRhythm = median > 0 &&
                currentGap >= median * GRIT_CADENCE_LO &&
                currentGap <= median * GRIT_CADENCE_HI;

            // §4.2 — refresh the stored cadence after every completion,
            // whether or not the bonus paid.
            var allGaps = [];
            var full = prior.concat([thisCompletionISO]).slice(-(GRIT_CADENCE_SAMPLE + 1));
            for (var j = 1; j < full.length; j++) allGaps.push(gritDaysBetween(full[j - 1], full[j]));
            g.cadence[activity.id] = {
                medianGapDays: Math.round(gritMedian(allGaps) * 10) / 10,
                sampleCount: full.length
            };

            if (!onRhythm) return 0;
            gritApplyDelta(GRIT_CADENCE_BONUS, 'cadence_bonus', {
                activityId: activity.id, activityTitle: activity.name,
                medianGapDays: Math.round(median * 10) / 10,
                gapDays: Math.round(currentGap * 10) / 10
            });
            return GRIT_CADENCE_BONUS;
        }

        // ── Earn: the completion drip (§4.1) ──────────────────────────────
        // The single hook completeActivity() calls, in the same beat as XP.
        function gritOnCompletion(activity) {
            var g = gritState();
            if (!g || !activity) return;
            if (!gritIsCountable(activity)) return;   // perform-mode negatives earn nothing

            gritEnsureWeek();

            gritApplyDelta(GRIT_DRIP, 'completion',
                { activityId: activity.id, activityTitle: activity.name });
            gritBumpNumerator(g, activity, +1);
            // Floated from the card by spawnFloatingGrit(), not toasted — see
            // the `floated` flag in gritFlushBurst(). A backdated completion
            // has no card to float from, so gritOnRetroComplete() still toasts.
            gritBurstAdd(activity.name || 'Completion', GRIT_DRIP, true);

            var tail = (activity.completionHistory || [])
                .filter(function (e) { return e && !e.isPenalty && (e.xp || 0) > 0; }).slice(-1)[0];
            var cad = gritCheckCadence(activity,
                tail ? tail.date : (activity.lastCompleted || new Date().toISOString()));
            if (cad) gritBurstAdd('On rhythm — ' + (activity.name || 'activity'), cad);

            gritCheckStreakMilestones(activity);
            gritConsumeBoost(activity);
            // Deliberately NOT flushed here. Mastery is evaluated by the tech
            // tree a few milliseconds after completeActivity returns, so the
            // burst's own debounce is what lets a completion that also crosses
            // a streak threshold AND completes a mastery read as one toast
            // instead of three (§6.2).
            gritRefreshUI();
        }

        // §4.1 — a backdated completion pays its drip either way. Landing it
        // inside the CURRENT week also feeds the numerator; landing it in a
        // CLOSED week does not retroactively move that week's ratio and never
        // triggers a re-reconcile. Backdating stays free and unlimited (§8.3).
        function gritOnRetroComplete(activity, dateStr) {
            var g = gritState();
            if (!g || !activity || !gritIsCountable(activity)) return;
            gritEnsureWeek();
            gritApplyDelta(GRIT_DRIP, 'completion',
                { activityId: activity.id, activityTitle: activity.name, backdatedTo: dateStr });
            if (g.week && dateStr >= g.week.anchor) gritBumpNumerator(g, activity, +1);
            gritBurstAdd((activity.name || 'Completion') + ' (' + dateStr + ')', GRIT_DRIP);
            gritCheckStreakMilestones(activity);
            gritRefreshUI();
        }

        // Deleting a completion inside the current week takes it back out of
        // the numerator, mirroring the add. The drip already paid is NOT
        // reclaimed — no spec path claws Grit back, and doing so would make
        // history editing feel punitive.
        function gritOnRetroDelete(activity, dateStr) {
            var g = gritState();
            if (!g || !activity || !g.week) return;
            if (dateStr >= g.week.anchor) gritBumpNumerator(g, activity, -1);
            gritRefreshUI();
        }

        // ── Login pass ────────────────────────────────────────────────────
        // Rides processStreakPauses(), which has already recomputed every
        // streak from history by the time this runs. Returns true when
        // anything changed so the caller's single write picks it up.
        function gritOnLogin() {
            var g = gritState();
            if (!g) return false;
            var changed = false;
            if (gritMigrateLocalBalance()) changed = true;
            if (gritEnsureWeek()) changed = true;
            gritAllActivities().forEach(function (a) {
                if (gritCheckStreakMilestones(a)) changed = true;
            });
            if (gritCheckMastery()) changed = true;
            gritFlushBurst();
            gritRefreshUI();
            return changed;
        }

        // §1.1 — one-time migration off the placeholder's localStorage key.
        // Firestore wins if both exist; the key is dropped either way.
        function gritMigrateLocalBalance() {
            var g = gritState();
            if (!g) return false;
            var raw = null;
            try { raw = localStorage.getItem('mk_grit_balance'); } catch (e) { return false; }
            if (raw === null) return false;
            var seeded = false;
            var n = parseInt(raw, 10);
            if (!g.awarded['migration'] && !isNaN(n) && n > 0 && g.balance === 0 &&
                g.lifetimeEarned === 0 && g.lifetimeSpent === 0) {
                g.awarded['migration'] = true;
                gritApplyDelta(n, 'migration', { note: 'seeded from local placeholder balance' });
                seeded = true;
            }
            try { localStorage.removeItem('mk_grit_balance'); } catch (e) {}
            return seeded;
        }

        // ── Spend (§5) ────────────────────────────────────────────────────
        // Every purchase: check against the PERSISTED balance, refuse cleanly
        // rather than ever going negative, decrement → ledger → persist →
        // THEN grant, and roll the whole thing back if the write fails.
        // Double-tap is blocked by _gritPurchaseLock plus the caller
        // disabling the button until the write resolves.
        let _gritPurchaseLock = false;

        function gritMonthKey(d) {
            var dt = d || new Date();
            return dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0');
        }

        // §5.2 / gifting §3.2 — remaining boost allowance this calendar month.
        // `kind` was added when gifting landed; entries written before that are
        // all self-purchases, so a missing kind reads as 'self'.
        function gritBoostsUsedThisMonth(kind) {
            var g = gritState();
            if (!g) return 0;
            var mk = gritMonthKey();
            return g.boostPurchases.filter(function (p) {
                return p && p.month === mk && (p.kind || 'self') === kind;
            }).length;
        }

        function gritBoostsLeftThisMonth() {
            return Math.max(0, GRIT_BOOST_PER_MONTH - gritBoostsUsedThisMonth('self'));
        }

        function gritGiftBoostsLeftThisMonth() {
            return Math.max(0, GRIT_GIFT_BOOST_PER_MONTH - gritBoostsUsedThisMonth('gift'));
        }
        window.gritGiftBoostsLeftThisMonth = gritGiftBoostsLeftThisMonth;

        async function gritPurchase(cost, reason, grant, revert, meta) {
            var g = gritState();
            if (!g) return { ok: false, message: 'Not signed in.' };
            if (_gritPurchaseLock) return { ok: false, message: 'Hold on — a purchase is still going through.' };
            if (g.balance < cost) {
                return { ok: false, message: 'You need ' + (cost - g.balance) + ' more Grit for that.' };
            }
            _gritPurchaseLock = true;

            var before = { balance: g.balance, lifetimeSpent: g.lifetimeSpent };
            var bufferMark = _gritLedgerBuffer.length;
            try {
                gritApplyDelta(-cost, reason, meta || {});
                grant(g);
                var saved = await gritPersist();
                if (!saved) {
                    // §5.3 — persistence precedes the grant. It didn't land,
                    // so nothing happened: unwind state and the ledger entry.
                    revert(g);
                    g.balance = before.balance;
                    g.lifetimeSpent = before.lifetimeSpent;
                    _gritLedgerBuffer.length = bufferMark;
                    gritRefreshUI();
                    return { ok: false, message: 'Could not save that purchase. Nothing was spent.' };
                }
                gritFlushLedger();
                gritRefreshUI();
                return { ok: true };
            } finally {
                _gritPurchaseLock = false;
            }
        }

        // §5.1 — Streak shield, 40 Grit, uncapped. Buys into the pool.
        // Purchase and placement stay separate decisions: this only fills the
        // pool. gritApplyShield() below moves one onto an activity.
        window.gritBuyShield = async function () {
            var res = await gritPurchase(GRIT_SHIELD_COST, 'shield_purchase',
                function (g) { g.shieldPool = (g.shieldPool || 0) + 1; },
                function (g) { g.shieldPool = Math.max(0, (g.shieldPool || 0) - 1); },
                { item: 'streak_shield' });
            showToast(res.ok ? 'Shield added to your pool — 40 Grit' : res.message,
                      res.ok ? 'green' : 'red', null, res.ok ? 'shield' : null);
            gritRenderRewards();
            return res.ok;
        };

        // §5.2 — Double XP on the next completion, 50 Grit, once per calendar
        // month. Armed, not assigned: buy it, then tap whichever completion
        // you want doubled.
        window.gritBuyBoost = async function () {
            var g = gritState();
            if (!g) return false;
            if (g.pendingBoost) {
                showToast('You already have a double-XP boost armed.', 'olive');
                return false;
            }
            if (gritBoostsLeftThisMonth() <= 0) {
                showToast('Double XP is limited to once a calendar month.', 'red');
                return false;
            }
            var mk = gritMonthKey();
            var res = await gritPurchase(GRIT_BOOST_COST, 'xp_boost_purchase',
                function (gg) {
                    gg.pendingBoost = { activityId: null, purchasedAt: new Date().toISOString() };
                    gg.boostPurchases.push({ month: mk, at: new Date().toISOString(), kind: 'self' });
                    if (gg.boostPurchases.length > 24) gg.boostPurchases = gg.boostPurchases.slice(-24);
                },
                function (gg) {
                    gg.pendingBoost = null;
                    for (var i = gg.boostPurchases.length - 1; i >= 0; i--) {
                        if (gg.boostPurchases[i] && gg.boostPurchases[i].month === mk &&
                            (gg.boostPurchases[i].kind || 'self') === 'self') {
                            gg.boostPurchases.splice(i, 1); break;
                        }
                    }
                },
                { item: 'xp_boost', month: mk });
            showToast(res.ok ? 'Double XP armed — your next completion counts twice' : res.message,
                      res.ok ? 'green' : 'red', null, res.ok ? 'lightning' : null);
            gritRenderRewards();
            return res.ok;
        };

        // ── Applying a pooled shield to an activity ───────────────────────
        // The mechanism is one appended event; the two shield folds already
        // read it through shieldFloorFor(). Nothing about the existing streak
        // grant, the consumption rule, or the backdating reconciliation is
        // touched — this adds an event type and moves the cap, nothing else.
        //
        // Shields only do anything on an activity whose streak can break, so
        // occasional activities and perform-mode negatives are not offered:
        // neither accrues a streak for a shield to protect.
        function gritShieldEligible(a) {
            return !!a && !a.archived && !a.deleted &&
                   !gritIsOccasional(a) && !gritIsPunitive(a);
        }
        window.gritShieldEligible = gritShieldEligible;

        function gritShieldEventId() {
            return 'sa-' + Date.now().toString(36) + '-' +
                   Math.random().toString(36).slice(2, 9);
        }

        // The pool decrement and the event append are ONE write to
        // users/{uid} — they are both fields of the same document, so a single
        // setDoc makes "both or neither" a property of Firestore rather than a
        // sequence we have to unwind. If the write fails, the in-memory pool
        // and the event are both rolled back and nothing was spent.
        let _gritApplyLock = false;
        window.gritApplyShield = async function (activityId) {
            var g = gritState();
            if (!g) return { ok: false, message: 'Not signed in.' };
            if (_gritApplyLock) return { ok: false, message: 'Hold on — that is still going through.' };

            var a = gritFindActivity(activityId);
            if (!a) return { ok: false, message: 'That activity no longer exists.' };
            if (!gritShieldEligible(a)) {
                return { ok: false, message: (a.name || 'That activity') + ' does not keep a streak, so a shield has nothing to protect.' };
            }
            if ((g.shieldPool || 0) <= 0) {
                return { ok: false, message: 'No shields in your pool. Buy one for ' + GRIT_SHIELD_COST + ' Grit.' };
            }
            if (shieldCapNow(a) >= SHIELD_ABS_CAP) {
                return { ok: false, message: (a.name || 'That activity') + ' is already at ' + SHIELD_ABS_CAP + ' shields — the maximum.' };
            }

            _gritApplyLock = true;
            var prevPool = g.shieldPool;
            var prevCap  = a.shieldCapUsed;
            var hadArray = Array.isArray(a.shieldEvents);
            var ev = { type: 'shield_applied', id: gritShieldEventId(), at: toLocalDateStr(new Date()) };
            try {
                if (!hadArray) a.shieldEvents = [];
                a.shieldEvents.push(ev);
                g.shieldPool = prevPool - 1;
                // Refresh the stored capacity so the count is right on screen
                // immediately; the next login walk derives the same number.
                a.shieldCapUsed = shieldCapNow(a);

                var saved = await gritPersist();
                if (!saved) {
                    // Neither half happened. Put everything back exactly.
                    var at = a.shieldEvents.indexOf(ev);
                    if (at !== -1) a.shieldEvents.splice(at, 1);
                    if (!hadArray) delete a.shieldEvents;
                    g.shieldPool = prevPool;
                    a.shieldCapUsed = prevCap;
                    gritLedgerWrite(0, g.balance, 'correction', {
                        note: 'shield apply failed to persist; pool restored',
                        activityId: a.id, activityTitle: a.name
                    });
                    gritRefreshUI();
                    return { ok: false, message: 'Could not save that. Your shield is still in the pool.' };
                }
                gritFlushLedger();
                try { updateDashboard(); } catch (e) {}
                gritRefreshUI();
                return { ok: true, cap: shieldCapNow(a), title: a.name };
            } finally {
                _gritApplyLock = false;
            }
        };

        // Read by predictCompletionXP. Exactly ×2, never more, and never on a
        // perform-mode negative (doubling a penalty is not a reward).
        function gritIsBoostArmed(activity) {
            var g = window.userData && window.userData.grit;
            if (!g || !g.pendingBoost) return false;
            if (!activity || !gritIsCountable(activity)) return false;
            if (g.pendingBoost.activityId && g.pendingBoost.activityId !== activity.id) return false;
            return true;
        }
        window.gritIsBoostArmed = gritIsBoostArmed;

        function gritConsumeBoost(activity) {
            var g = gritState();
            if (!g || !gritIsBoostArmed(activity)) return false;
            g.pendingBoost = null;
            gritBurstNote('Double XP spent on ' + (activity.name || 'that completion'), 'lightning');
            return true;
        }

        // ── Award feedback (§6.2) ─────────────────────────────────────────
        // One attributed toast per beat, not one per award: a completion that
        // also crosses a streak threshold reads as a single line. Awards are
        // collected across the whole tick (completion → streak → mastery, each
        // fired from a different place) and flushed together.
        let _gritBurst = [];
        let _gritBurstNotes = [];
        let _gritBurstTimer = null;

        // `floated` marks an award the card already showed as a rising
        // "+N Grit" label. It still counts in the ledger and the week — it
        // just does not get a toast of its own, because the float said it.
        function gritBurstAdd(label, amount, floated) {
            _gritBurst.push({ label: label, amount: amount, floated: !!floated });
            clearTimeout(_gritBurstTimer);
            _gritBurstTimer = setTimeout(gritFlushBurst, 120);
        }
        function gritBurstNote(text, icon) {
            _gritBurstNotes.push({ text: text, icon: icon || null });
            clearTimeout(_gritBurstTimer);
            _gritBurstTimer = setTimeout(gritFlushBurst, 120);
        }

        function gritFlushBurst() {
            clearTimeout(_gritBurstTimer);
            _gritBurstTimer = null;
            var items = _gritBurst; _gritBurst = [];
            var notes = _gritBurstNotes; _gritBurstNotes = [];
            notes.forEach(function (n) { try { showToast(n.text, 'blue', null, n.icon); } catch (e) {} });
            // A tap that earned nothing but its drip has already said so on
            // the card. Only the beats the float cannot carry reach a toast.
            items = items.filter(function (i) { return !i.floated; });
            if (!items.length) return;
            var total = items.reduce(function (s, i) { return s + i.amount; }, 0);
            if (total <= 0) return;
            var msg;
            if (items.length === 1) {
                msg = items[0].label + ' — +' + total + ' Grit';
            } else {
                var top = items.slice().sort(function (a, b) { return b.amount - a.amount; });
                var named = top.slice(0, 3);
                var rest = top.length - named.length;
                msg = named.map(function (i) { return i.label + ' +' + i.amount; }).join(' · ') +
                      (rest > 0 ? ' · and ' + rest + ' more' : '') +
                      ' — +' + total + ' Grit';
            }
            try { showToast(msg, 'green', null, 'diamond'); } catch (e) {}
        }

        // ── UI plumbing ───────────────────────────────────────────────────
        function gritRefreshUI() {
            try { if (typeof window.mkRenderGrit === 'function') window.mkRenderGrit(); } catch (e) {}
            // The Modes page's balance chip is persistent DOM now (the nav
            // borrows it for the title row), so it is refreshed here rather
            // than only when that page re-renders.
            try { modesRenderGritChip(); } catch (e) {}
            gritRenderRewards();
        }
        window.gritRefreshUI = gritRefreshUI;

        function gritFillColor(ratio) {
            if (ratio === null) return 'var(--color-progress-track)';
            var t = Math.max(0, Math.min(1, ratio));      // 0 → target
            // Hue travels the SHORT way round the wheel — 356° up through
            // 0/amber to 96° green. Interpolating 356 → 96 directly runs
            // backwards through blue, which is not a progress colour.
            var hue = (356 + 100 * t) % 360;              // red → amber → green
            var sat = 58 + 6 * t;
            var lit = 46 + 6 * t;
            if (ratio > 1) { hue = 96; sat = 62; lit = 52; }   // overshoot: hold green
            return 'hsl(' + hue.toFixed(0) + ' ' + sat.toFixed(0) + '% ' + lit.toFixed(0) + '%)';
        }

        function gritEsc(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;');
        }

        // Human phrasing for a ledger row (§6.1 "Recent activity").
        function gritLedgerPhrase(e) {
            var m = e.meta || {};
            var title = m.activityTitle || 'an activity';
            switch (e.reason) {
                case 'completion':       return m.backdatedTo
                                            ? 'Logged ' + title + ' for ' + m.backdatedTo
                                            : 'Completed ' + title;
                case 'cadence_bonus':    return 'On rhythm — ' + title;
                case 'weekly_bonus':     return 'Weekly bonus — ' +
                                            (m.ratio != null ? Math.round(m.ratio * 100) + '% of target' : 'consistency');
                case 'streak_milestone': return m.streakDays + '-day streak on ' + title;
                case 'mastery':          return 'Mastered ' + title;
                case 'node_reveal':      return 'Revealed ' + (m.nodeTitle
                                            ? '"' + m.nodeTitle + '" on your map' : 'a node on your map');
                case 'tree_regen':       return 'Regenerated your map';
                case 'shield_purchase':  return 'Bought a streak shield';
                case 'xp_boost_purchase':return 'Bought double XP';
                case 'gift_shield':      return 'Sent a shield to ' + (m.receiverName || 'a friend');
                case 'gift_xp_boost':    return 'Sent double XP to ' + (m.receiverName || 'a friend');
                case 'leaderboard_payout': return (m.place ? gritOrdinal(m.place) + ' place' : 'Placed') +
                                            ' on your leaderboard';
                case 'migration':        return 'Balance carried over';
                case 'correction':       return 'Balance correction';
                default:                 return e.reason;
            }
        }

        function gritRelTime(iso) {
            var mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
            if (mins < 1)    return 'just now';
            if (mins < 60)   return mins + 'm ago';
            var h = Math.round(mins / 60);
            if (h < 24)      return h + 'h ago';
            var d = Math.round(h / 24);
            return d < 7 ? d + 'd ago' : gritDayOf(iso);
        }

        // ── The Rewards tab (§6) ──────────────────────────────────────────
        // Lives under More, adjacent to Analytics. The home of the whole
        // currency system: balance, the live weekly bar, the frozen breakdown,
        // the shop, the explainer and recent history.
        let _gritRewardsBusy = false;

        function gritRewardsVisible() {
            var el = document.getElementById('mkEmptyMoreRewards');
            return !!(el && el.classList.contains('active'));
        }

        let _gritRendering = false;
        function gritRenderRewards(force) {
            var host = document.getElementById('gritRewardsRoot');
            if (!host || _gritRendering) return;
            if (!force && !gritRewardsVisible()) return;
            _gritRendering = true;
            try { gritRenderRewardsInner(host, force); } finally { _gritRendering = false; }
        }

        function gritRenderRewardsInner(host, force) {
            var g = gritState();
            if (!g) { host.innerHTML = '<div class="grit-empty">Sign in to see your Grit.</div>'; return; }
            gritEnsureWeek();

            var w = g.week || gritNewWeek(gritWeekAnchorStr(new Date()));
            var ratio = gritWeekRatio(w);
            var pct = ratio === null ? 0 : Math.min(1, ratio / GRIT_RATIO_CAP);
            var projected = gritProjectedBonus(w);
            var atTarget = ratio !== null && ratio >= 1;

            var html = '';

            // ── Balance header + the live weekly bar ──────────────────────
            html += '<div class="grit-head">' +
                      '<div class="grit-bal-label">Grit balance</div>' +
                      '<div class="grit-bal-num">' + (g.balance || 0).toLocaleString() + '</div>' +
                      '<div class="grit-bal-sub">' +
                        (g.lifetimeEarned || 0).toLocaleString() + ' earned · ' +
                        (g.lifetimeSpent || 0).toLocaleString() + ' spent' +
                      '</div>' +
                    '</div>';

            html += '<button type="button" class="grit-week" id="gritWeekBar" ' +
                        'aria-expanded="false" aria-controls="gritBreakdown">';
            if (ratio === null) {
                html += '<div class="grit-week-top">' +
                          '<span class="grit-week-title">This week</span>' +
                          '<span class="grit-week-amt">No bonus</span>' +
                        '</div>' +
                        '<div class="grit-week-track"><span class="grit-week-fill" style="width:0%"></span></div>' +
                        '<div class="grit-week-note">No activity has a frequency, so there is no ' +
                          'weekly target. Set one and it counts from Monday.</div>';
            } else {
                html += '<div class="grit-week-top">' +
                          '<span class="grit-week-title">This week</span>' +
                          '<span class="grit-week-amt' + (atTarget ? ' is-target' : '') + '">+' + projected + ' Grit</span>' +
                        '</div>' +
                        '<div class="grit-week-track' + (atTarget ? ' is-target' : '') + '">' +
                          '<span class="grit-week-fill" style="width:' + (pct * 100).toFixed(1) + '%;' +
                            'background:' + gritFillColor(ratio) + '"></span>' +
                          '<span class="grit-week-target" style="left:' + (100 / GRIT_RATIO_CAP).toFixed(1) + '%"></span>' +
                        '</div>' +
                        '<div class="grit-week-note">' +
                          w.completions + ' of ' + (Math.round(w.quota * 10) / 10) + ' · ' +
                          Math.round(ratio * 100) + '% of target. Tap for the breakdown.' +
                        '</div>';
            }
            html += '</button>';

            // ── Weekly breakdown (frozen contributors) ────────────────────
            html += '<div class="grit-breakdown" id="gritBreakdown" hidden>';
            if (!w.contributors || !w.contributors.length) {
                html += '<div class="grit-empty">Nothing in this week\'s target yet. ' +
                        'Activities join on the Monday after you start them.</div>';
            } else {
                html += '<div class="grit-bd-head"><span>Activity</span><span>Done</span><span>Target</span></div>';
                w.contributors.forEach(function (c) {
                    var rec = (w.byActivity || {})[c.activityId];
                    var done = rec == null ? 0 : (typeof rec === 'number' ? rec : (rec.n || 0));
                    html += '<div class="grit-bd-row">' +
                              '<span class="grit-bd-name">' + gritEsc(c.title) + '</span>' +
                              '<span class="grit-bd-done">' + done + '</span>' +
                              '<span class="grit-bd-quota">' + (Math.round(c.quotaUnits * 10) / 10) + '</span>' +
                            '</div>';
                });
                html += '<div class="grit-bd-foot">' +
                          (ratio === null
                            ? 'No target, so no bonus this week.'
                            : 'On track for <strong>+' + projected + ' Grit</strong> when the week closes.') +
                        '</div>';
            }
            html += '</div>';

            // ── Shop ─────────────────────────────────────────────────────
            var boostsLeft = gritBoostsLeftThisMonth();
            html += '<h4 class="grit-h">Shop</h4><div class="grit-shop">';

            // A card is dimmed only when you can afford NEITHER action on it.
            // Gifting is half price, so a balance that covers only the gift
            // still leaves the card live — greying it out told people they
            // could do nothing when they could still do something.
            var pool       = g.shieldPool || 0;
            var canBuyShield  = g.balance >= GRIT_SHIELD_COST;
            var canGiftShield = g.balance >= GRIT_GIFT_SHIELD_COST;
            html += '<div class="grit-item' + (!canBuyShield && !canGiftShield ? ' is-poor' : '') + '">' +
                      '<div class="grit-item-main">' +
                        '<div class="grit-item-name">' + phIcon('shield', { weight: 'fill', lead: true }) + 'Streak shield</div>' +
                        '<div class="grit-item-sub">Absorbs one missed window. Buy into your pool, ' +
                          'then place it on an activity.' +
                          '<br><span class="grit-item-gift-note">Gift one for ' +
                            GRIT_GIFT_SHIELD_COST + '.</span></div>' +
                      '</div>' +
                      '<div class="grit-buy-pair">' +
                        '<button type="button" class="grit-buy" id="gritBuyShieldBtn"' +
                          (canBuyShield ? '' : ' disabled') + '>' +
                          GRIT_SHIELD_COST + '</button>' +
                        '<button type="button" class="grit-buy grit-gift-buy" id="gritGiftShieldBtn"' +
                          (canGiftShield ? '' : ' disabled') +
                          ' title="Gift a shield to a friend">Gift ' + GRIT_GIFT_SHIELD_COST + '</button>' +
                      '</div>' +
                    '</div>';

            // ── The pool: hold it, then place it ─────────────────────────
            html += '<div class="grit-pool' + (pool > 0 ? ' has-shields' : '') + '">' +
                      '<div class="grit-pool-row">' +
                        '<span class="grit-pool-count">' + pool + '</span>' +
                        '<span class="grit-pool-label">' +
                          (pool === 1 ? 'shield in your pool' : 'shields in your pool') +
                        '</span>' +
                        (pool > 0
                          ? '<button type="button" class="grit-pool-apply" id="gritApplyOpenBtn">Place one</button>'
                          : '') +
                      '</div>' +
                      (pool > 0 ? '<div class="grit-pool-pick" id="gritApplyPick" hidden></div>' : '') +
                    '</div>';

            var boostBlocked = g.balance < GRIT_BOOST_COST || boostsLeft <= 0 || !!g.pendingBoost;
            var giftBoostsLeft   = gritGiftBoostsLeftThisMonth();
            var giftBoostBlocked = g.balance < GRIT_GIFT_BOOST_COST || giftBoostsLeft <= 0;
            html += '<div class="grit-item' + (boostBlocked && giftBoostBlocked ? ' is-poor' : '') + '">' +
                      '<div class="grit-item-main">' +
                        '<div class="grit-item-name">' + phIcon('lightning', { weight: 'fill', lead: true }) + 'Double XP</div>' +
                        '<div class="grit-item-sub">' +
                          (g.pendingBoost
                            ? 'Armed — your next completion counts twice.'
                            : '×2 on your next completion. ' +
                              boostsLeft + ' of ' + GRIT_BOOST_PER_MONTH + ' left this month.') +
                          '<br><span class="grit-item-gift-note">Gift: ' + giftBoostsLeft + ' of ' +
                            GRIT_GIFT_BOOST_PER_MONTH + ' left this month.</span>' +
                        '</div>' +
                      '</div>' +
                      '<div class="grit-buy-pair">' +
                        '<button type="button" class="grit-buy" id="gritBuyBoostBtn"' +
                          (boostBlocked ? ' disabled' : '') + '>' +
                          GRIT_BOOST_COST + '</button>' +
                        '<button type="button" class="grit-buy grit-gift-buy" id="gritGiftBoostBtn"' +
                          (giftBoostBlocked ? ' disabled' : '') +
                          ' title="Gift double XP to a friend">Gift ' + GRIT_GIFT_BOOST_COST + '</button>' +
                      '</div>' +
                    '</div>';
            html += '</div>';

            // ── How Grit works ───────────────────────────────────────────
            // The anchor the title's "i" button scrolls to.
            html += '<h4 class="grit-h" id="gritHow">How Grit works</h4>' +
                    '<ul class="grit-explain">' +
                      '<li>1 Grit per completion.</li>' +
                      '<li>A weekly bonus, scaled by how much of your frequency target you hit.</li>' +
                      '<li>Streaks and mastery pay out as you reach them.</li>' +
                    '</ul>';

            // ── Recent activity ──────────────────────────────────────────
            // Collapsible, and paged rather than a wall: twenty rows is as far
            // as anyone reads in one go, and the rest is one tap away.
            html += '<button type="button" class="grit-h grit-h-toggle" id="gritLogToggle" ' +
                        'aria-expanded="' + _gritLogOpen + '" aria-controls="gritLogWrap">' +
                      '<span>Recent activity</span>' +
                      '<svg class="grit-h-chev' + (_gritLogOpen ? ' is-open' : '') + '" viewBox="0 0 24 24" ' +
                        'fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" ' +
                        'stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
                    '</button>' +
                    '<div class="grit-log-wrap" id="gritLogWrap"' + (_gritLogOpen ? '' : ' hidden') + '>' +
                      '<div class="grit-log" id="gritLog"><div class="grit-empty">Loading…</div></div>' +
                      '<div class="grit-log-pager" id="gritLogPager"></div>' +
                    '</div>';

            host.innerHTML = html;

            var logToggle = document.getElementById('gritLogToggle');
            if (logToggle) logToggle.addEventListener('click', function () {
                _gritLogOpen = !_gritLogOpen;
                var wrap = document.getElementById('gritLogWrap');
                var chev = logToggle.querySelector('.grit-h-chev');
                if (wrap) wrap.hidden = !_gritLogOpen;
                if (chev) chev.classList.toggle('is-open', _gritLogOpen);
                logToggle.setAttribute('aria-expanded', String(_gritLogOpen));
                if (_gritLogOpen) gritRenderLog();
            });

            var bar = document.getElementById('gritWeekBar');
            var bd  = document.getElementById('gritBreakdown');
            if (bar && bd) bar.addEventListener('click', function () {
                var open = !bd.hidden;
                bd.hidden = open;
                bar.setAttribute('aria-expanded', String(!open));
            });
            var sb = document.getElementById('gritBuyShieldBtn');
            if (sb) sb.addEventListener('click', function () {
                sb.disabled = true;                      // §5.4 — no double-tap
                window.gritBuyShield().finally(function () { gritRenderRewards(); });
            });
            var ao = document.getElementById('gritApplyOpenBtn');
            if (ao) ao.addEventListener('click', function () {
                var pick = document.getElementById('gritApplyPick');
                if (!pick) return;
                if (!pick.hidden) { pick.hidden = true; ao.textContent = 'Place one'; return; }
                gritRenderShieldPicker(pick);
                pick.hidden = false;
                ao.textContent = 'Cancel';
            });
            var bb = document.getElementById('gritBuyBoostBtn');
            if (bb) bb.addEventListener('click', function () {
                bb.disabled = true;
                window.gritBuyBoost().finally(function () { gritRenderRewards(); });
            });
            var gs = document.getElementById('gritGiftShieldBtn');
            if (gs) gs.addEventListener('click', function () { giftOpenPicker(null, 'shield'); });
            var gb = document.getElementById('gritGiftBoostBtn');
            if (gb) gb.addEventListener('click', function () { giftOpenPicker(null, 'xp_boost'); });

            if (_gritLogOpen) gritRenderLog();
        }

        let _gritLogCache = null;
        let _gritLogCacheAt = 0;
        const GRIT_LOG_CACHE_MS = 30000;

        // Recent activity: twenty rows a page, five pages deep. Reading more
        // than a hundred entries back is not what this list is for, and a
        // deeper read is a bigger query on every visit to the tab.
        const GRIT_LOG_PAGE  = 20;
        const GRIT_LOG_DEPTH = 100;
        let _gritLogOpen = false;   // collapsed by default — the page opens on what you can do, not on history
        let _gritLogPage = 0;

        // Lists every activity a shield can actually protect, with its current
        // shield count, and refuses the ones already at the cap in place
        // rather than after the tap.
        function gritRenderShieldPicker(host) {
            var eligible = gritAllActivities().filter(gritShieldEligible);
            if (!eligible.length) {
                host.innerHTML = '<div class="grit-empty">Nothing keeps a streak yet. ' +
                    'Shields protect activities with a frequency.</div>';
                return;
            }
            eligible.sort(function (a, b) { return (b.streak || 0) - (a.streak || 0); });
            host.innerHTML = eligible.map(function (a) {
                var cap  = shieldCapNow(a);
                var full = cap >= SHIELD_ABS_CAP;
                var used = getShieldsUsedDisplay(a);
                return '<button type="button" class="grit-pick-row' + (full ? ' is-full' : '') + '"' +
                         ' data-act="' + gritEsc(a.id) + '"' + (full ? ' disabled' : '') + '>' +
                         '<span class="grit-pick-name">' + gritEsc(a.name || 'Activity') + '</span>' +
                         '<span class="grit-pick-meta">' +
                           (a.streak ? (a.streak + '-day streak · ') : '') +
                           cap + '/' + SHIELD_ABS_CAP + ' shields' +
                           (used ? ' · ' + used + ' used' : '') +
                         '</span>' +
                         '<span class="grit-pick-cta">' + (full ? 'Full' : phIcon('shield', { weight: 'fill', lead: true }) + '+1') + '</span>' +
                       '</button>';
            }).join('');

            host.querySelectorAll('.grit-pick-row').forEach(function (btn) {
                btn.addEventListener('click', async function () {
                    // Disabled between click and write resolution (spec §6).
                    host.querySelectorAll('.grit-pick-row').forEach(function (b) { b.disabled = true; });
                    var res = await window.gritApplyShield(btn.getAttribute('data-act'));
                    showToast(res.ok
                        ? 'Shield placed on ' + res.title + ' — now ' + res.cap + ' of ' + SHIELD_ABS_CAP
                        : res.message, res.ok ? 'green' : 'red', null, res.ok ? 'shield' : null);
                    gritRenderRewards(true);
                });
            });
        }

        // Page changes read from the rows already in hand — the fetch is one
        // query per cache window, not one per page.
        window.gritLogGoPage = function (n) {
            _gritLogPage = Math.max(0, n);
            gritPaintLog();
        };

        function gritLogRows() {
            // Entries still sitting in the write buffer are real and already
            // reflected in the balance — show them rather than a gap.
            var pending = _gritLedgerBuffer.map(function (b) { return b.data; }).reverse();
            return pending.concat(_gritLogCache || []).slice(0, GRIT_LOG_DEPTH);
        }

        function gritPaintLog() {
            var live  = document.getElementById('gritLog');
            var pager = document.getElementById('gritLogPager');
            if (!live) return;

            var rows  = gritLogRows();
            if (!rows.length) {
                live.innerHTML = '<div class="grit-empty">Nothing yet. Complete an activity to start earning.</div>';
                if (pager) pager.innerHTML = '';
                return;
            }

            var pages = Math.ceil(rows.length / GRIT_LOG_PAGE);
            if (_gritLogPage >= pages) _gritLogPage = pages - 1;
            var from = _gritLogPage * GRIT_LOG_PAGE;
            var page = rows.slice(from, from + GRIT_LOG_PAGE);

            live.innerHTML = page.map(function (e) {
                var sign = e.delta > 0 ? '+' : '';
                return '<div class="grit-log-row">' +
                         '<span class="grit-log-what">' + gritEsc(gritLedgerPhrase(e)) + '</span>' +
                         '<span class="grit-log-when">' + gritEsc(gritRelTime(e.at)) + '</span>' +
                         '<span class="grit-log-amt ' + (e.delta > 0 ? 'is-up' : 'is-down') + '">' +
                           sign + e.delta + '</span>' +
                       '</div>';
            }).join('');

            if (!pager) return;
            if (pages <= 1) { pager.innerHTML = ''; return; }
            pager.innerHTML =
                '<button type="button" class="grit-page-btn" ' +
                  (_gritLogPage === 0 ? 'disabled ' : '') +
                  'onclick="gritLogGoPage(' + (_gritLogPage - 1) + ')" aria-label="Newer entries">' +
                  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" ' +
                  'stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>' +
                '</button>' +
                '<span class="grit-page-count">' + (from + 1) + '–' + (from + page.length) +
                  ' of ' + rows.length + '</span>' +
                '<button type="button" class="grit-page-btn" ' +
                  (_gritLogPage >= pages - 1 ? 'disabled ' : '') +
                  'onclick="gritLogGoPage(' + (_gritLogPage + 1) + ')" aria-label="Older entries">' +
                  '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" ' +
                  'stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>' +
                '</button>';
        }

        async function gritRenderLog() {
            var el = document.getElementById('gritLog');
            if (!el || _gritRewardsBusy) return;
            _gritRewardsBusy = true;
            try {
                if (!_gritLogCache || (Date.now() - _gritLogCacheAt) >= GRIT_LOG_CACHE_MS) {
                    _gritLogCache = await gritReadLedger(GRIT_LOG_DEPTH);
                    _gritLogCacheAt = Date.now();
                }
                gritPaintLog();
            } finally {
                _gritRewardsBusy = false;
            }
        }

        // The "i" beside the Rewards title. The explainer stays where it is —
        // at the bottom, out of the way of the things you came here to do —
        // and the button is the shortcut to it.
        window.gritScrollToHow = function () {
            var el = document.getElementById('gritHow');
            if (!el) return;
            el.scrollIntoView({ behavior: 'smooth', block: 'start' });
            el.classList.remove('is-flagged');
            void el.offsetWidth;
            el.classList.add('is-flagged');
        };

        // Called by the v5 nav when it activates More › Rewards.
        window.gritOpenRewards = function () {
            var host = document.getElementById('gritRewardsRoot');
            if (!host) return;
            _gritLogPage = 0;   // a fresh visit starts at the newest entries
            try { if (typeof window.mkRenderGrit === 'function') window.mkRenderGrit(); } catch (e) {}
            gritRenderRewards(true);
        };
        window.gritRenderRewards = gritRenderRewards;

        // ── Ledger durability ─────────────────────────────────────────────
        // The buffer must not die with the tab. Flush on blur and on unload;
        // `visibilitychange` is the reliable one on mobile, where `unload`
        // frequently never fires.
        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState === 'hidden') gritFlushLedger();
        });
        window.addEventListener('pagehide', function () { gritFlushLedger(); });
        window.addEventListener('blur', function () { gritFlushLedger(); });

        // ════════════════════════════════════════════════════════════════════
        // ══ END GRIT CURRENCY SYSTEM ════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════


        // ════════════════════════════════════════════════════════════════════
        // ══ TECH TREE v5 — THE REVEAL LOOP ══════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // v4 generated a map you read once. v5 makes it a place you come back
        // to, because most of it is dark and Grit is what turns the lights on.
        //
        // The whole tree is visible from the first day — every node, as a
        // silhouette. Shape, dimension colour, goal thread and position are
        // all there. Titles and descriptions are not. Revealing a node tells
        // you what it is; adopting it still requires mastering its
        // prerequisite.
        //
        //   Grit buys information.  Mastery buys access.
        //
        // Those are separate currencies for separate things, and conflating
        // them was the mistake v4 made. A user can reveal five nodes deep
        // without having mastered anything — they simply cannot adopt them
        // yet. Adoption itself is free and always has been.
        //
        // Reveal state is orthogonal to lifecycle. `lifecycle` tracks
        // progression (locked → available → active → resolved); `revealed`
        // tracks information. Neither is derived from the other, and nothing
        // here overloads one to mean the other.
        //
        // Everything below is client-written and lives inside
        // userData.techTree, which is safe under saveUserData()'s full
        // document overwrite. Any future SERVER-side reveal would have to
        // move to a subcollection instead — see §3.3.
        // ════════════════════════════════════════════════════════════════════

        const TT_REVEAL_COST  = 40;    // §5.2 flat, every node past tier 1
        const TT_REGEN_COST   = 200;   // §6
        const TT_REGEN_MASTERIES = 1;  // §6 the gate that actually matters

        // §3.1/§10.2 — which nodes are born revealed. The spec defines tier 1
        // as "empty prerequisites[]", which in this generator's output means
        // the anchors (the user's own activities) and the wildcard. The
        // roadmap's first tier hangs off an anchor via an
        // `activity_mastered` prerequisite, so it costs like everything else.
        //
        // If reveals ever feel too punishing on a fresh map, flipping this to
        // 'tier' frees the whole first roadmap rank instead. It is one
        // constant precisely so that is a one-line decision.
        const TT_FREE_TIER_RULE = 'no-prerequisites';   // | 'tier'

        function ttIsFreeTier(node, tt) {
            if (TT_FREE_TIER_RULE === 'tier') {
                if (node._tier == null && tt) ttComputeTiers((tt.nodes || []).filter(function (n) {
                    return n.lifecycle !== 'archived';
                }));
                return (node._tier || 1) <= 1;
            }
            return !(node.prerequisites || []).length;
        }

        // ── Migration (§9 step 2) ─────────────────────────────────────────
        // Runs exactly once per tree, marked by revealMigratedAt rather than
        // schemaVersion: the generation worker writes schemaVersion 3 on
        // every result, so keying off it would re-run the generous pass after
        // every generation and hand out free reveals forever.
        //
        // The one-time pass is deliberately generous — every node whose
        // prerequisites are already met is marked revealed, because the user
        // can already read those and charging retroactively for what they can
        // see would be a theft. Nodes arriving AFTER migration follow §3.1:
        // free only if they have no prerequisites at all.
        function ttEnsureRevealFields(tt) {
            if (!tt || !Array.isArray(tt.nodes)) return false;
            var changed = false;
            var firstPass = !tt.revealMigratedAt;

            if (tt.lastRegenAt === undefined)       { tt.lastRegenAt = null; changed = true; }
            if (typeof tt.masteriesSinceRegen !== 'number') { tt.masteriesSinceRegen = 0; changed = true; }

            tt.nodes.forEach(function (n) {
                if (!n) return;
                if (typeof n.revealCost !== 'number') { n.revealCost = TT_REVEAL_COST; changed = true; }
                if (n.revealedAt === undefined)       { n.revealedAt = null; changed = true; }
                if (typeof n.revealed !== 'boolean') {
                    n.revealed = firstPass ? ttNodeUnlocked(n, tt) : ttIsFreeTier(n, tt);
                    // Anything the user has already accepted or finished is
                    // theirs and is never dark, whichever pass we are in.
                    if (n.lifecycle === 'active' || n.resolvedAt || n.source === 'user') n.revealed = true;
                    if (n.revealed && !n.revealedAt) n.revealedAt = n.createdAt || new Date().toISOString();
                    changed = true;
                }
            });

            if (firstPass) { tt.revealMigratedAt = new Date().toISOString(); changed = true; }
            if (ttSyncMasteryGate(tt)) changed = true;
            return changed;
        }

        // §6's gate, DERIVED rather than counted. Mastery is declared in two
        // places — the evaluation pass, and ttFinishLink's retroactive resolve
        // when a linked activity already has the history — so an incrementing
        // counter silently misses the second one and tells a user who just
        // mastered something that they have not. Reading it off the
        // activities' own timestamps cannot drift, and self-corrects a
        // counter that already has.
        //
        // A tree that has never been regenerated counts every mastery the
        // user has ever earned: "since the last regeneration" with no last
        // regeneration means since the beginning, and they did do the work.
        function ttSyncMasteryGate(tt) {
            if (!tt) return false;
            var since = tt.lastRegenAt ? new Date(tt.lastRegenAt).getTime() : 0;
            var n = 0;
            ttAllActivities().forEach(function (e) {
                var at = e.activity.techTreeMasteredAt;
                if (at && new Date(at).getTime() > since) n++;
            });
            if (tt.masteriesSinceRegen === n) return false;
            tt.masteriesSinceRegen = n;
            return true;
        }

        // ── The three states (§4) ─────────────────────────────────────────
        // Derived, never stored twice.
        function ttRevealState(node, tt) {
            if (!node.revealed) return 'silhouette';
            return ttNodeUnlocked(node, tt || ensureTechTree()) ? 'adoptable' : 'revealed';
        }
        function ttIsSilhouette(node) { return !node.revealed; }

        // §5.1 — a silhouette is revealable only if every node it depends on
        // is already revealed. Reveal propagates along the edges outward from
        // the free tier: you cannot buy the leaf of a branch without buying
        // the branch.
        //
        // This is a LINEAGE rule, not a mastery rule. An archived ancestor is
        // transparent to it — see ttRejectNode, which re-points around the
        // rejection so a branch is never stranded behind one.
        function ttRevealBlockers(node, tt) {
            var out = [];
            var byId = {}, anchorByAct = {};
            (tt.nodes || []).forEach(function (n) {
                byId[n.id] = n;
                if (n.payload && n.payload.activityId && !anchorByAct[n.payload.activityId]) {
                    anchorByAct[n.payload.activityId] = n;
                }
            });
            (node.prerequisites || []).forEach(function (pr) {
                var src = pr.type === 'node_mastered' ? byId[pr.nodeId]
                        : pr.type === 'activity_mastered' ? anchorByAct[pr.activityId] : null;
                if (!src || src.id === node.id) return;          // dangling — never brick a branch
                if (src.lifecycle === 'archived') return;        // rejected — transparent
                if (!src.revealed) out.push(src);
            });
            return out;
        }
        function ttRevealable(node, tt) {
            return ttIsSilhouette(node) && ttRevealBlockers(node, tt).length === 0;
        }

        function ttRevealCost(node) {
            return typeof node.revealCost === 'number' ? node.revealCost : TT_REVEAL_COST;
        }

        function ttDarkCount(tt) {
            return (tt.nodes || []).filter(function (n) {
                return n.lifecycle !== 'archived' && ttIsSilhouette(n);
            }).length;
        }

        // ── Reveal purchase (§5.3) ────────────────────────────────────────

        window.ttOpenRevealSheet = function (nodeId) {
            var tt = ensureTechTree();
            var node = (tt.nodes || []).find(function (n) { return n.id === nodeId; });
            if (!node) return;
            if (!ttIsSilhouette(node)) { ttOpenNode(nodeId); return; }

            var cost = ttRevealCost(node);
            var bal  = gritBalance();
            var blockers = ttRevealBlockers(node, tt);
            var goals = ttNodeGoals(node);
            var goalChips = goals.map(function (g) {
                return '<span class="tt-mini-chip" style="--gc:' + (g.color || '#888') + '">' +
                       escapeHtml(g.shortName || 'Goal') + '</span>';
            }).join('');

            // Everything on this sheet is about the PURCHASE. Nothing about
            // the node — no title, no teaser, no partial text (§10.9). The
            // whole value of the transaction is the information.
            var body = '<div class="tt-sheet-body" id="ttRevealSheetBody">'
                + '<div class="tt-sheet-kicker tt-reveal-kicker">Unrevealed</div>'
                + '<div class="tt-reveal-mark">' + ttSilhouettePreview(node) + '</div>'
                + '<h3 class="tt-sheet-title tt-reveal-title">Something is here</h3>';

            if (blockers.length) {
                body += '<p class="tt-sheet-desc">Reveal what comes before it first — the map opens outward from what you already know.</p>'
                     +  '<div class="tt-locked-note">' + ttIcon('lock', 12) + ' '
                     +  blockers.length + ' node' + (blockers.length === 1 ? '' : 's')
                     +  ' before this one ' + (blockers.length === 1 ? 'is' : 'are') + ' still dark</div>'
                     +  '<div class="tt-sheet-actions"><button class="tt-btn tt-btn-ghost" onclick="ttCloseSheet()">Close</button></div>';
            } else {
                var short = bal < cost;
                body += '<p class="tt-sheet-desc">Spend Grit to find out what it is. Revealing tells you what a node '
                     +  'is — it does not unlock it. Adoption still costs mastery, and adoption is free.</p>'
                     +  (goalChips ? '<div class="tt-goal-feed">Feeds ' + goalChips + '</div>' : '')
                     +  '<div class="tt-reveal-price">'
                     +    '<div><span>Reveal</span><strong>' + cost + ' Grit</strong></div>'
                     +    '<div><span>Your balance</span><strong class="' + (short ? 'tt-short' : '') + '">' + bal + ' Grit</strong></div>'
                     +  '</div>'
                     +  (short
                          ? '<div class="tt-locked-note tt-short">' + ttIcon('lock', 12) + ' ' +
                            (cost - bal) + ' Grit short. Keep showing up — the map will wait.</div>'
                          : '')
                     +  '<div class="tt-sheet-actions">'
                     +    '<button class="tt-btn tt-btn-primary" id="ttRevealBtn" onclick="ttConfirmReveal(\'' + node.id + '\')"'
                     +      (short ? ' disabled' : '') + '>' + ttIcon('spark', 13) + '<span>Reveal · ' + cost + '</span></button>'
                     +    '<button class="tt-btn tt-btn-ghost" onclick="ttCloseSheet()">Not yet</button>'
                     +  '</div>';
            }
            ttShowSheet(body + '</div>');
        };

        // The glyph alone, at sheet scale — the same silhouette the map shows,
        // so the purchase is visibly about THAT node without naming it.
        function ttSilhouettePreview(node) {
            var color = ttNodeColor(node);
            var defs = [];
            var g = ttGlyph(node, 30, 30, color, defs);
            return '<svg width="60" height="60" viewBox="0 0 60 60" class="tt-sil-preview">'
                 + '<defs>' + defs.join('') + '</defs><g class="tt-silhouette">' + g + '</g></svg>';
        }

        window.ttConfirmReveal = async function (nodeId) {
            var tt = ensureTechTree();
            var node = (tt.nodes || []).find(function (n) { return n.id === nodeId; });
            if (!node || !ttIsSilhouette(node)) return;
            if (!ttRevealable(node, tt)) { showToast('Reveal what comes before it first', 'olive'); return; }

            var cost = ttRevealCost(node);
            if (gritBalance() < cost) {
                showToast('You are ' + (cost - gritBalance()) + ' Grit short of that reveal', 'red');
                return;
            }

            // Disable between tap and write resolution (§5.3) — a double tap
            // must not be able to charge twice.
            var btn = document.getElementById('ttRevealBtn');
            if (btn) { btn.disabled = true; btn.innerHTML = '<span>Revealing…</span>'; }

            // §10.4 — persistence precedes the reveal. The debit and the
            // reveal go into ONE write and the user is shown nothing until it
            // lands: charge-then-persist-then-grant would leave a window
            // where a failed second write takes the Grit and gives back
            // nothing. If the write fails, both halves roll back together.
            gritApplyDelta(-cost, 'node_reveal', { nodeId: node.id, nodeTitle: node.title });
            node.revealed   = true;
            node.revealedAt = new Date().toISOString();

            var ok = await gritPersist();
            if (!ok) {
                node.revealed   = false;
                node.revealedAt = null;
                gritApplyDelta(cost, 'correction', {
                    note: 'reveal write failed, stake returned', nodeId: node.id
                });
                showToast('Could not save that reveal — your Grit is untouched', 'red');
                if (btn) { btn.disabled = false; btn.innerHTML = '<span>Reveal · ' + cost + '</span>'; }
                return;
            }

            // §8.4 — the emotional beat. Gold flash, then the sheet turns
            // over in place. Never close and reopen.
            try { ttGoldFlash(); } catch (e) {}
            window._ttFlashNodeId = node.id;
            ttOpenNode(node.id);
            ttRenderIfVisible();
        };

        // ── Regeneration (§6) ─────────────────────────────────────────────
        // The mastery gate matters more than the price. Cost alone is the
        // wrong lever — it means the most consistent users regenerate most
        // often, and it rewards hoarding that starves every other sink.
        // Requiring a mastery means someone who has not done the work cannot
        // regenerate no matter how rich they are.
        //
        // A third gate joined them once generation became instant: ONCE A
        // MONTH. Cheap-feeling AI invites spamming it, and a web rewoven
        // weekly is a web nobody ever walks. The server owns that clock —
        // this only reads it, so the screen and the answer agree. Hand-adding
        // a node ("Add your own") stays free and unlimited; that is the
        // pressure valve.

        function ttRegenStatus() {
            var tt = ensureTechTree();
            var masteries = tt.masteriesSinceRegen || 0;
            var cooldown = ttCooldownLeft(tt.lastRegenAt);
            return {
                masteries: masteries,
                needed: TT_REGEN_MASTERIES,
                masteryMet: masteries >= TT_REGEN_MASTERIES,
                cost: TT_REGEN_COST,
                balance: gritBalance(),
                affordable: gritBalance() >= TT_REGEN_COST,
                cooldown: cooldown,
                ready: masteries >= TT_REGEN_MASTERIES && gritBalance() >= TT_REGEN_COST && !cooldown && !_ttWeaving
            };
        }

        window.ttOpenRegenSheet = function () {
            var s = ttRegenStatus();
            var tt = ensureTechTree();
            var dark = ttDarkCount(tt);
            var keep = (tt.nodes || []).filter(function (n) {
                return n.lifecycle !== 'archived' && (n.revealed || n.resolvedAt || n.lifecycle === 'active');
            }).length;

            var body = '<div class="tt-sheet-body">'
                + '<div class="tt-sheet-kicker" style="color:' + TT_GOLD + '">Regenerate</div>'
                + '<h3 class="tt-sheet-title">A new frontier</h3>'
                + '<p class="tt-sheet-desc">The tree is finite. Regenerating replaces what is still dark with a fresh '
                + 'set of branches grown from where you actually are now — not from the goal you typed months ago.</p>'
                + '<div class="tt-regen-table">'
                +   '<div><span>Kept</span><strong>' + keep + ' node' + (keep === 1 ? '' : 's') + '</strong></div>'
                +   '<div><span>Replaced</span><strong>' + dark + ' silhouette' + (dark === 1 ? '' : 's') + '</strong></div>'
                +   '<div><span>Cost</span><strong>' + s.cost + ' Grit</strong></div>'
                +   '<div><span>Your balance</span><strong class="' + (s.affordable ? '' : 'tt-short') + '">' + s.balance + ' Grit</strong></div>'
                +   '<div><span>Allowance</span><strong class="' + (s.cooldown ? 'tt-short' : '') + '">'
                +     (s.cooldown ? s.cooldown + ' day' + (s.cooldown === 1 ? '' : 's') + ' to go' : 'Once a month · ready') + '</strong></div>'
                + '</div>'
                + '<p class="tt-muted">Anything you have adopted, mastered, or paid to reveal is kept. '
                + 'Regeneration replaces the unexplored frontier, not the journey.</p>';

            if (s.cooldown) {
                body += '<div class="tt-locked-note">' + ttIcon('lock', 12) +
                        ' Once a month. Free again in ' + s.cooldown + ' day' + (s.cooldown === 1 ? '' : 's') +
                        ' — until then, add your own nodes.</div>';
            } else if (!s.masteryMet) {
                body += '<div class="tt-locked-note">' + ttIcon('lock', 12) +
                        ' Master one activity since your last regeneration first. ' +
                        'No balance unlocks this — the work does.</div>';
            } else if (!s.affordable) {
                body += '<div class="tt-locked-note tt-short">' + ttIcon('lock', 12) + ' ' +
                        (s.cost - s.balance) + ' Grit short.</div>';
            }

            body += '<div class="tt-sheet-actions">'
                 +   '<button class="tt-btn tt-btn-primary" id="ttRegenBtn" onclick="ttConfirmRegen()"'
                 +     (s.ready ? '' : ' disabled') + '>'
                 +     ttIcon('refresh', 13) + '<span>Regenerate · ' + s.cost + '</span></button>'
                 +   '<button class="tt-btn tt-btn-ghost" onclick="ttCloseSheet()">Close</button>'
                 + '</div></div>';
            ttShowSheet(body);
        };

        window.ttConfirmRegen = async function () {
            if (!ttRegenStatus().ready) return;
            var tt = ensureTechTree();
            ttCloseSheet();
            tt.loadBudget = { current: ttWeeklyLoad(), updatedAt: new Date().toISOString() };

            // The web arrives before the Grit leaves. When generation was a
            // cron the charge had to be committed with the request, because
            // nothing came back to charge against; now a failed weave simply
            // costs nothing. The server's own monthly clock — stamped only on
            // a weave that produced something — is what stops a retry loop,
            // not the price.
            var ok = await ttWeave({ mode: 'generate' });
            if (!ok) return;

            gritApplyDelta(-TT_REGEN_COST, 'tree_regen', { nodes: (tt.nodes || []).length });
            tt.masteriesSinceRegen = 0;
            await gritPersist();
            renderTechTree();
        };

        // ── Sky / Branch (§8) ─────────────────────────────────────────────
        // Sky is the label-free overview: shape, colour, thread, depth, and
        // nothing else. It is where silhouettes do their work — the contrast
        // between explored and unexplored territory is the single most
        // important thing on that screen, and text would dilute it.
        //
        // Branch is where words live: one readable column at 360px, titles
        // for revealed nodes, glyph and a lock affordance with the price for
        // the rest.

        function ttViewMode() {
            var tt = ensureTechTree();
            return tt.viewMode === 'branch' ? 'branch' : 'sky';
        }

        window.ttSetView = function (mode, focusNodeId) {
            var tt = ensureTechTree();
            tt.viewMode = (mode === 'branch') ? 'branch' : 'sky';
            if (mode === 'branch' && focusNodeId) window._ttBranchFocus = focusNodeId;
            debouncedSaveUserData();
            renderTechTree();
            // §8.3 — entering Branch from a Sky tap scrolls to that node;
            // returning to Sky preserves scroll position.
            if (tt.viewMode === 'branch' && window._ttBranchFocus) {
                var id = window._ttBranchFocus;
                window._ttBranchFocus = null;
                requestAnimationFrame(function () {
                    var el = document.getElementById('ttb-' + id);
                    if (el && el.scrollIntoView) el.scrollIntoView({ block: 'center', behavior: 'smooth' });
                });
            } else if (tt.viewMode === 'sky' && window._ttSkyScroll) {
                requestAnimationFrame(function () {
                    var sc = document.querySelector('.tt-web-scroll');
                    if (sc) sc.scrollLeft = window._ttSkyScroll;
                });
            }
        };

        function ttViewToggleHtml() {
            var m = ttViewMode();
            return '<div class="tt-viewtoggle" role="tablist">'
                 +   '<button class="tt-vt-btn' + (m === 'sky' ? ' on' : '') + '" role="tab" aria-selected="' + (m === 'sky') + '" onclick="ttSetView(\'sky\')">'
                 +     ttIcon('map', 12) + '<span>Sky</span></button>'
                 +   '<button class="tt-vt-btn' + (m === 'branch' ? ' on' : '') + '" role="tab" aria-selected="' + (m === 'branch') + '" onclick="ttSetView(\'branch\')">'
                 +     ttIcon('branch', 12) + '<span>Branch</span></button>'
                 + '</div>';
        }

        // How much of the map is still dark — the number that makes the
        // reveal economy legible at a glance, and that visibly shrinks.
        function ttDarkStripHtml(tt) {
            var alive = (tt.nodes || []).filter(function (n) { return n.lifecycle !== 'archived'; });
            if (!alive.length) return '';
            var dark = alive.filter(ttIsSilhouette).length;
            var lit  = alive.length - dark;
            var pct  = Math.round((lit / alive.length) * 100);
            var bal  = gritBalance();
            return '<div class="tt-darkstrip">'
                 +   '<div class="tt-darkbar"><div class="tt-darkbar-fill" style="width:' + pct + '%"></div></div>'
                 +   '<div class="tt-darkmeta">'
                 +     '<span><b>' + lit + '</b> revealed · <b>' + dark + '</b> still dark</span>'
                 +     '<span class="tt-darkbal">' + bal + ' Grit</span>'
                 +   '</div>'
                 + '</div>';
        }

        // ── Branch view (§8.2) ────────────────────────────────────────────
        // A single column through the lineages, ordered by tier so a chain
        // reads top to bottom.
        //
        // It opens on ONE goal, not on all of them, because that is the read
        // people actually want out of a roadmap: master this, then that, then
        // the thing after it. Filtered to a goal the column becomes a literal
        // chain — a spine down the glyphs, no tier headings interrupting it,
        // and every locked node saying in full what opens it. "All" is still
        // there, one tap away, for the cross-goal view.

        // undefined means "not chosen yet" and resolves to the first goal;
        // null is the user explicitly asking for All. They are not the same.
        window.ttBranchFilter = function (goalId) {
            window._ttBranchGoal = goalId || null;
            renderTechTree();
        };
        // Tapping the thread you are already reading opens its menu — the
        // edit-the-reading / reweave / retire actions Sky's legend carries.
        window.ttBranchGoalChip = function (goalId) {
            if (window._ttBranchGoal === goalId) { ttGoalMenu(goalId); return; }
            ttBranchFilter(goalId);
        };

        function ttBranchFilterId(goals) {
            var f = window._ttBranchGoal;
            if (f === undefined) return goals.length ? goals[0].id : null;
            if (f && !goals.some(function (g) { return g.id === f; })) return goals.length ? goals[0].id : null;
            return f;
        }

        function ttBranchHtml(tt) {
            var alive = (tt.nodes || []).filter(function (n) { return n.lifecycle !== 'archived'; });
            if (!alive.length) return '';
            ttComputeTiers(alive);

            var goals = ttActiveGoals();
            var filter = ttBranchFilterId(goals);
            window._ttBranchGoal = filter;

            var shown = filter
                ? alive.filter(function (n) { return (n.goalIds || []).indexOf(filter) !== -1; })
                : alive;

            shown = shown.slice().sort(function (a, b) {
                if (a._tier !== b._tier) return a._tier - b._tier;
                return String(a.dimensionId).localeCompare(String(b.dimensionId));
            });

            var chips = '';
            if (goals.length) {
                chips = '<div class="tt-goal-legend tt-branch-filter">'
                      + goals.map(function (g) {
                          var on = filter === g.id;
                          return '<button class="tt-goal-chip' + (on ? ' on' : '') + '" onclick="ttBranchGoalChip(\'' + g.id + '\')"'
                               + ' title="' + (on ? 'Goal options' : 'Show only this thread') + '">'
                               + '<span class="tt-goal-chip-dot" style="background:' + (g.color || '#888') + '"></span>'
                               + escapeHtml(g.shortName || 'Goal') + '</button>';
                        }).join('')
                      + '<button class="tt-goal-chip' + (!filter ? ' on' : '') + '" onclick="ttBranchFilter(null)">All</button>'
                      + '</div>';
            }

            if (!shown.length) {
                return chips + '<p class="tt-muted" style="margin:14px 2px;">Nothing on this thread yet.</p>';
            }

            // One goal = one chain, so the tier headings become noise: the
            // order IS the tiers, and the spine already says "then this".
            var linear = !!filter;
            var lastTier = null;
            var rows = shown.map(function (n) {
                var head = '';
                if (!linear && n._tier !== lastTier) {
                    lastTier = n._tier;
                    head = '<div class="tt-branch-tier">Tier ' + n._tier + '</div>';
                }
                return head + ttBranchRow(n, tt, linear);
            }).join('');

            return chips + '<div class="tt-branch' + (linear ? ' tt-branch-linear' : '') + '">' + rows + '</div>';
        }

        function ttBranchRow(node, tt, linear) {
            var color = ttNodeColor(node);
            var sil   = ttIsSilhouette(node);
            var state = ttRevealState(node, tt);
            var defs  = [];
            var glyph = '<svg width="34" height="34" viewBox="0 0 34 34" class="tt-branch-glyph' + (sil ? ' tt-silhouette' : '') + '">'
                      + '<defs>' + defs.join('') + '</defs>'
                      + ttGlyph(node, 17, 17, color, defs) + '</svg>';

            var body;
            if (sil) {
                // Glyph and a lock affordance with the cost. Nothing else —
                // no title, no teaser, no partial text (§10.9).
                var can = ttRevealable(node, tt);
                var afford = gritBalance() >= ttRevealCost(node);
                body = '<span class="tt-branch-name tt-branch-dark">Unrevealed</span>'
                     + '<span class="tt-branch-sub">' + (can
                          ? (afford ? 'Tap to reveal' : 'Not enough Grit yet')
                          : 'Reveal what comes before it') + '</span>';
                var price = '<span class="tt-branch-price' + (can && afford ? '' : ' tt-branch-price-off') + '">'
                          + ttIcon('lock', 11) + ttRevealCost(node) + '</span>';
                return '<button class="tt-branch-row tt-branch-row-dark" id="ttb-' + node.id + '"'
                     + ' style="--rc:' + color + '" onclick="ttOpenRevealSheet(\'' + node.id + '\')">'
                     + glyph + '<span class="tt-branch-col">' + body + '</span>' + price + '</button>';
            }

            // Progression state wins over reveal state here: something the
            // user has already adopted or mastered is never "open to accept",
            // however its prerequisites read.
            var badge = node.resolvedAt
                ? '<span class="tt-seg-badge tt-seg-gold">mastered</span>'
                : (node.lifecycle === 'active' ? '<span class="tt-seg-badge">doing</span>'
                : (state === 'adoptable' ? '<span class="tt-seg-badge tt-seg-open">open</span>'
                : '<span class="tt-seg-badge tt-seg-locked">' + escapeHtml(ttShort(ttLockReason(node, tt), 26)) + '</span>'));

            // In the chain read the unlock condition is the point, so it gets
            // the whole sub-line instead of a 26-character badge.
            var locked = !node.resolvedAt && node.lifecycle !== 'active' && state !== 'adoptable';
            if (linear && locked) {
                badge = '';
                body = '<span class="tt-branch-name">' + escapeHtml(node.title) + '</span>'
                     + '<span class="tt-branch-sub tt-branch-gate">' + ttIcon('lock', 10) + ' ' + escapeHtml(ttLockReason(node, tt)) + '</span>';
            } else {
                body = '<span class="tt-branch-name">' + escapeHtml(node.title) + '</span>'
                     + '<span class="tt-branch-sub">' + escapeHtml(ttShort(ttNodeSublabel(node, tt), 40)) + '</span>';
            }

            return '<button class="tt-branch-row" id="ttb-' + node.id + '" style="--rc:' + color + '"'
                 + ' onclick="ttOpenNode(\'' + node.id + '\')">'
                 + glyph + '<span class="tt-branch-col">' + body + '</span>' + badge + '</button>';
        }

        // ── Rejection fallback (§5.4) ─────────────────────────────────────
        // The piece most likely to be skipped and most likely to strand
        // users. Before v5, rejecting a node archived it and ttPrereqMet
        // returned false for archived targets forever — every child behind it
        // was permanently unreachable, and anyone who had paid to reveal one
        // had bought a dead end.
        //
        // Now the rejected node's own prerequisites are spliced into each
        // child in its place, so a child inherits the nearest non-archived
        // ancestor. A rejected tier-1 node leaves its children with no
        // prerequisite at all, which is correct: there is nothing left to
        // master before them.
        //
        // Rejection stays free, and it never refunds the reveal — the user
        // got the information, which is what they paid for.
        function ttRepointChildrenOf(node, tt) {
            var inherited = (node.prerequisites || []).slice();
            var changed = false;
            (tt.nodes || []).forEach(function (child) {
                if (!child || child.id === node.id) return;
                var prereqs = child.prerequisites || [];
                if (!prereqs.some(function (pr) { return pr.type === 'node_mastered' && pr.nodeId === node.id; })) return;

                var next = [];
                prereqs.forEach(function (pr) {
                    if (pr.type === 'node_mastered' && pr.nodeId === node.id) {
                        inherited.forEach(function (up) {
                            var dup = next.some(function (x) {
                                return x.type === up.type && x.nodeId === up.nodeId && x.activityId === up.activityId;
                            });
                            // Never inherit a prerequisite pointing back at
                            // the child — a rejection must not create a cycle.
                            if (!dup && !(up.type === 'node_mastered' && up.nodeId === child.id)) {
                                next.push(Object.assign({}, up));
                            }
                        });
                    } else {
                        next.push(pr);
                    }
                });
                child.prerequisites = next;
                changed = true;
            });
            return changed;
        }

        // ════════════════════════════════════════════════════════════════════
        // ══ VERSUS CHALLENGES ═══════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // A wagered two-player contest, and the whole of the Challenges tab.
        //
        // Placement: a TOP-LEVEL `versusChallenges` collection. Two accounts read and
        // write the same document; a document under users/{uid} could not be
        // granted to the other side without widening that user's rules far past
        // what is safe. The challenge document is the ONLY cross-account
        // surface: no participant is ever granted read access to the other's
        // user document, activity list, completion history or Grit balance.
        // Everything the opponent sees is mirrored into it by its owner, and
        // that mirror is counters and agreed names only (§2.3).
        //
        // Hooks into the rest of the app (all of them wrappers — no core
        // function is restructured):
        //   completeActivity()  → vsOnCompletion(activityId)
        //   undoActivity()      → vsOnUndo(activityId)
        //   deleteActivity()    → forfeit warning (vsGuardActivityDelete)
        //   saveActivity()      → picks up an activity created inside the
        //                         accept walkthrough (same creation path, no fork)
        //   switchSubTab()      → renders the Versus sub-tab
        //   login              → vsOnLogin()
        //
        // Grit invariant: every Grit that leaves a balance is either escrowed
        // in a challenge document's `pot` or recorded in `payout` waiting to be
        // claimed. Nothing evaporates and nothing is created. Balance moves
        // happen inside runTransaction() so a debit and the pot it funds land
        // together or not at all.
        // ════════════════════════════════════════════════════════════════════

        // A collection of its own. The previous one was written by a schema
        // that carried a hand-typed name on every requirement; rather than
        // teach every reader to cope with both shapes forever, the retirement
        // took the documents with it. Nothing here has ever seen the old one.
        const VS_COL             = 'versusChallenges';
        const VS_SCHEMA_VERSION  = 3;
        const VS_STAKE_MIN       = 25;     // §3.1, rate card reserved table
        const VS_STAKE_MAX       = 100;
        const VS_STAKE_STEP      = 25;
        const VS_INVITE_DAYS     = 7;      // §2.2 expiresAt = createdAt + 7d
        const VS_CACHE_TTL_MS    = 60000;  // §5 re-fetch if the cache is older
        const VS_MAX_REQS        = 5;
        const VS_ARCHIVE_DAYS    = 3;      // §8.7 resolved cards linger, then hide

        // §3.1 concurrency cap. There is no free/Pro tier in this codebase —
        // the only limit-shaped pattern left in the app is getActivityLimit's
        // level-based activity cap. Rather than invent a paid tier, this is a
        // single tunable constant, counted over pending + active combined.
        const VS_MAX_CONCURRENT  = 3;

        const VS_TERMINAL = ['resolved', 'expired', 'declined', 'cancelled'];
        const VS_ALL_STATUSES = ['pending', 'active'].concat(VS_TERMINAL);

        // ── In-memory read model (§5) ─────────────────────────────────────
        // One getDocs on login / tab open, cached. No listener is attached in
        // the list view; exactly one is attached while a detail view is open.
        let _vsCache      = { at: 0, list: [], uid: null };
        let _vsFetchInFlight = null;
        let _vsDetailUnsub   = null;
        let _vsDetailId      = null;
        let _vsIndexMissing  = false;   // fall back to the unfiltered query once

        function vsUid() { return (window.currentUser && window.currentUser.uid) || null; }
        function vsNow() { return Date.now(); }

        function vsOther(ch, uid) {
            var p = ch.participants || [];
            return p[0] === uid ? p[1] : p[0];
        }

        function vsName(ch, uid) {
            return (ch.names && ch.names[uid]) || 'Opponent';
        }

        function vsIsTerminal(status) { return VS_TERMINAL.indexOf(status) !== -1; }

        // A requirement's display name. There is no `name` field: a
        // requirement IS an activity, so its label is the creator's activity
        // name, read from the creator's own mapping. That mapping is written
        // once at create and frozen by the rules for the rest of the
        // challenge's life — no branch of the update rule lets either side
        // rewrite it — so this is a stable read, not a convenient guess.
        function vsReqName(ch, req) {
            var mine = (ch.mapping && ch.mapping[ch.createdBy]) || {};
            var m = mine[req.reqId];
            return (m && m.activityName) || 'Activity';
        }

        // The advanced settings that make an activity behave the way its owner
        // set it up. Snapshotted into the challenge document at authoring time
        // so the receiver's "Add to my activities" can rebuild it — they have
        // no read access to the sender's activity list, so if it is not
        // mirrored here it cannot cross.
        function vsActivitySeed(act) {
            if (!act) return null;
            return {
                baseXP: act.baseXP || 1,
                frequency: act.frequency || 'daily',
                isNegative: !!act.isNegative,
                isSkipNegative: !!act.isSkipNegative,
                negativeXpMode: act.negativeXpMode || null,
                allowMultiplePerDay: !!act.allowMultiplePerDay
            };
        }

        function vsProgressOf(ch, uid) {
            return (ch.progress && ch.progress[uid]) || {};
        }

        function vsMappingOf(ch, uid) {
            return (ch.mapping && ch.mapping[uid]) || {};
        }

        // Capped per requirement (§4.2): excess completions never inflate a
        // total. The stored counters are already capped on write; this is the
        // read-side belt to the same braces, and what resolution compares.
        function vsCappedTotal(ch, uid) {
            var prog = vsProgressOf(ch, uid);
            return (ch.requirements || []).reduce(function (s, r) {
                return s + Math.min(prog[r.reqId] || 0, r.targetCount || 0);
            }, 0);
        }

        function vsHasCompleted(ch, uid) {
            var prog = vsProgressOf(ch, uid);
            var reqs = ch.requirements || [];
            if (!reqs.length) return false;
            return reqs.every(function (r) { return (prog[r.reqId] || 0) >= (r.targetCount || 0); });
        }

        // Every activity id this user has committed to a live challenge.
        // §3.3: an activity may be mapped into at most one active challenge at
        // a time — without it, one completion feeds several wagers.
        function vsCommittedActivityIds(excludeChallengeId) {
            var uid = vsUid();
            var out = new Set();
            if (!uid) return out;
            _vsCache.list.forEach(function (ch) {
                if (ch.id === excludeChallengeId) return;
                if (ch.status !== 'active' && ch.status !== 'pending') return;
                var m = vsMappingOf(ch, uid);
                Object.keys(m).forEach(function (reqId) {
                    if (m[reqId] && m[reqId].activityId) out.add(m[reqId].activityId);
                });
            });
            return out;
        }

        // ── Fetch (§5) ────────────────────────────────────────────────────

        async function vsFetch(force) {
            var uid = vsUid();
            if (!uid || !canPersistUserData('vsFetch')) return [];
            if (_vsCache.uid !== uid) { _vsCache = { at: 0, list: [], uid: uid }; }
            if (!force && _vsCache.at && (vsNow() - _vsCache.at) < VS_CACHE_TTL_MS) {
                return _vsCache.list;
            }
            if (_vsFetchInFlight) return _vsFetchInFlight;

            _vsFetchInFlight = (async function () {
                var list = [];
                var col  = collection(db, VS_COL);
                try {
                    // participants array-contains + status in — needs the
                    // composite index declared in firestore.indexes.json.
                    //
                    // The status list is every status on purpose. A refund
                    // owed on a declined or expired invite lives in a terminal
                    // document, and the side that is owed it is not
                    // necessarily the side that made the transition — so
                    // narrowing this filter to the statuses the UI draws would
                    // leave escrowed Grit unclaimable. Nothing is filtered out
                    // that anyone could still be owed money from.
                    var q = _vsIndexMissing
                        ? query(col, where('participants', 'array-contains', uid))
                        : query(col, where('participants', 'array-contains', uid),
                                     where('status', 'in', VS_ALL_STATUSES));
                    var snap = await getDocs(q);
                    snap.forEach(function (d) { list.push(Object.assign({ id: d.id }, d.data())); });
                } catch (err) {
                    if (!_vsIndexMissing && err && (err.code === 'failed-precondition' ||
                        /index/i.test(err.message || ''))) {
                        // The composite index has not been built yet. Fall back
                        // to the single-field query and filter in memory so the
                        // feature still works, permanently for this session.
                        console.warn('Versus: composite index missing, falling back to unfiltered query.');
                        _vsIndexMissing = true;
                        _vsFetchInFlight = null;
                        return vsFetch(true);
                    }
                    console.warn('Versus fetch failed:', err && err.message);
                    return _vsCache.list;
                }
                _vsCache = { at: vsNow(), list: list, uid: uid };
                return list;
            })();

            try { return await _vsFetchInFlight; }
            finally { _vsFetchInFlight = null; }
        }

        function vsCacheReplace(ch) {
            var i = _vsCache.list.findIndex(function (c) { return c.id === ch.id; });
            if (i === -1) _vsCache.list.push(ch); else _vsCache.list[i] = ch;
        }

        function vsCacheGet(id) {
            return _vsCache.list.find(function (c) { return c.id === id; }) || null;
        }

        // ── Grit escrow (§3.1, §3.3) ──────────────────────────────────────
        // The balance lives in userData.grit.balance, which normally rides the
        // full-document setDoc in saveUserData(). A stake is not allowed to be
        // that loose: debit and pot must land together. So the debit is a
        // dotted-path transaction.update on the user document inside the same
        // runTransaction as the challenge write, and the in-memory balance is
        // mirrored from the committed value afterwards.
        //
        // Callers MUST flush pending in-memory state first (vsFlushBeforeStake)
        // so a debounced full-document save cannot land on top of the debit.

        async function vsFlushBeforeStake() {
            try { cancelPendingUserDataSave(); } catch (e) {}
            await saveUserData();
        }

        function vsMirrorBalance(newBalance, delta, reason, meta) {
            var g = gritState();
            if (!g) return;
            g.balance = newBalance;
            if (delta < 0) g.lifetimeSpent  = (g.lifetimeSpent  || 0) + (-delta);
            else           g.lifetimeEarned = (g.lifetimeEarned || 0) + delta;
            gritLedgerWrite(delta, newBalance, reason, meta || {});
            try { gritRefreshUI(); } catch (e) {}
            debouncedSaveUserData();
        }

        // Reads the authoritative balance out of the user document inside a
        // transaction. Returns { ref, balance, spent }.
        async function vsReadBalance(tx, uid) {
            var ref  = doc(db, 'users', uid);
            var snap = await tx.get(ref);
            if (!snap.exists()) throw new Error('vs/no-user-doc');
            var g = snap.data().grit || {};
            return {
                ref: ref,
                balance: (typeof g.balance === 'number' && isFinite(g.balance)) ? g.balance : 0,
                spent:   (typeof g.lifetimeSpent === 'number') ? g.lifetimeSpent : 0,
                earned:  (typeof g.lifetimeEarned === 'number') ? g.lifetimeEarned : 0
            };
        }

        // ── Create (§3.1) ─────────────────────────────────────────────────

        function vsNewId() {
            return 'vs-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
        }

        function vsCountLive() {
            var uid = vsUid();
            return _vsCache.list.filter(function (c) {
                return (c.status === 'pending' || c.status === 'active') &&
                       (c.participants || []).indexOf(uid) !== -1;
            }).length;
        }

        // opponentUid must be a friend; requirements is
        // [{ reqId, targetCount, activityId, activityName, seed }] — the
        // activity fields are the CREATOR's own mapping, filled in inline at
        // authoring time because they are mapping activities they already own.
        //
        // A requirement carries no name of its own. It is an activity and a
        // count, and its label is read back off the creator's mapping
        // (vsReqName) rather than stored a second time.
        //
        // `seed` is the sender's advanced settings for that activity, mirrored
        // into the challenge document because the receiver can never read the
        // sender's activity list. It is the only way "Add to my activities"
        // can reproduce a negative or multiple-per-day habit faithfully.
        async function vsCreateChallenge(opts) {
            var uid = vsUid();
            if (!uid) throw new Error('Not signed in.');
            if (!canPersistUserData('vsCreate')) throw new Error('Your account is not loaded yet.');

            var opponentUid = opts.opponentUid;
            if (!opponentUid || opponentUid === uid) throw new Error('Pick a friend to challenge.');
            if (((window.userData.friends) || []).indexOf(opponentUid) === -1) {
                throw new Error('You can only challenge someone on your friends list.');
            }

            var stake = Math.round(opts.stake || 0);
            if (stake < VS_STAKE_MIN || stake > VS_STAKE_MAX) {
                throw new Error('Stake must be between ' + VS_STAKE_MIN + ' and ' + VS_STAKE_MAX + ' Grit.');
            }
            var durationDays = Math.max(1, Math.round(opts.durationDays || 0));
            var reqs = (opts.requirements || []).filter(function (r) { return r && r.activityId; });
            if (!reqs.length) throw new Error('Add at least one requirement.');
            if (reqs.length > VS_MAX_REQS) throw new Error('At most ' + VS_MAX_REQS + ' requirements.');

            await vsFetch(true);
            if (vsCountLive() >= VS_MAX_CONCURRENT) {
                throw new Error('You already have ' + VS_MAX_CONCURRENT +
                                ' challenges running. Finish one first.');
            }
            var committed = vsCommittedActivityIds(null);
            var clash = reqs.find(function (r) { return committed.has(r.activityId); });
            if (clash) {
                throw new Error('"' + clash.activityName + '" is already committed to another challenge.');
            }

            var myName  = (window.userData.profile && window.userData.profile.username) ||
                          (window.currentUser && window.currentUser.displayName) || 'You';
            var oppName = opts.opponentName || 'Opponent';

            var now = vsNow();
            var id  = vsNewId();
            var chRef = doc(db, VS_COL, id);

            var mappingMine = {};
            var payload = {
                schemaVersion: VS_SCHEMA_VERSION,
                mode: 'versus',
                createdBy: uid,
                opponent: opponentUid,
                participants: [uid, opponentUid],
                status: 'pending',
                name: String(opts.name || '').slice(0, 80),
                description: String(opts.description || '').slice(0, 300),
                stake: stake,
                pot: stake,
                bonusXP: Math.max(1, Math.round(opts.bonusXP || 1)),
                durationDays: durationDays,
                createdAt: now,
                expiresAt: now + VS_INVITE_DAYS * 86400000,
                startedAt: null,
                endsAt: null,
                resolvedAt: null,
                requirements: reqs.map(function (r) {
                    mappingMine[r.reqId] = {
                        activityId: r.activityId,
                        activityName: r.activityName   // snapshot at mapping time (§2.2)
                    };
                    var req = { reqId: r.reqId,
                                targetCount: Math.max(1, Math.round(r.targetCount || 1)) };
                    if (r.seed) req.seed = r.seed;
                    return req;
                }),
                mapping:       (function () { var m = {}; m[uid] = mappingMine; m[opponentUid] = {}; return m; })(),
                progress:      (function () { var m = {}; m[uid] = {}; m[opponentUid] = {}; return m; })(),
                totals:        (function () { var m = {}; m[uid] = 0;  m[opponentUid] = 0;  return m; })(),
                winner: null,
                outcome: null,
                payout:        (function () { var m = {}; m[uid] = 0;  m[opponentUid] = 0;  return m; })(),
                payoutClaimed: (function () { var m = {}; m[uid] = false; m[opponentUid] = false; return m; })(),
                seen:          (function () { var m = {}; m[uid] = now; m[opponentUid] = 0; return m; })(),
                names:         (function () { var m = {}; m[uid] = myName; m[opponentUid] = oppName; return m; })()
            };

            await vsFlushBeforeStake();

            var committedBalance = null;
            await runTransaction(db, async function (tx) {
                var bal = await vsReadBalance(tx, uid);
                if (bal.balance < stake) {
                    throw new Error('SHORTFALL:' + (stake - bal.balance));
                }
                committedBalance = bal.balance - stake;
                tx.update(bal.ref, {
                    'grit.balance': committedBalance,
                    'grit.lifetimeSpent': bal.spent + stake
                });
                tx.set(chRef, payload);
            });

            vsMirrorBalance(committedBalance, -stake, 'challenge_stake',
                { challengeId: id, challengeName: payload.name, role: 'creator' });

            vsCacheReplace(Object.assign({ id: id }, payload));
            return id;
        }

        // ── Accept / decline / cancel / expire (§3.3, §3.4) ────────────────

        async function vsAcceptChallenge(id, mappingMine) {
            var uid = vsUid();
            if (!uid) throw new Error('Not signed in.');
            if (!canPersistUserData('vsAccept')) throw new Error('Your account is not loaded yet.');

            await vsFetch(true);
            if (vsCountLive() > VS_MAX_CONCURRENT) {
                throw new Error('You already have ' + VS_MAX_CONCURRENT +
                                ' challenges running. Finish one first.');
            }
            var committed = vsCommittedActivityIds(id);
            var clashId = Object.keys(mappingMine).find(function (k) {
                return committed.has(mappingMine[k].activityId);
            });
            if (clashId) {
                throw new Error('"' + mappingMine[clashId].activityName +
                                '" is already committed to another challenge.');
            }

            await vsFlushBeforeStake();

            var chRef = doc(db, VS_COL, id);
            var committedBalance = null, stake = 0, chName = '', started = 0, ends = 0;

            await runTransaction(db, async function (tx) {
                // Every read must precede every write in a transaction.
                var chSnap = await tx.get(chRef);
                if (!chSnap.exists()) throw new Error('This challenge no longer exists.');
                var ch = chSnap.data();
                if (ch.status !== 'pending') throw new Error('This challenge is no longer open.');
                if (ch.opponent !== uid)     throw new Error('This invite is not yours to accept.');
                if (vsNow() > ch.expiresAt)  throw new Error('This invite has expired.');
                var missing = (ch.requirements || []).some(function (r) {
                    return !mappingMine[r.reqId] || !mappingMine[r.reqId].activityId;
                });
                if (missing) throw new Error('Every requirement needs an activity before you can accept.');

                var bal = await vsReadBalance(tx, uid);
                stake = ch.stake;
                chName = ch.name;
                if (bal.balance < stake) throw new Error('SHORTFALL:' + (stake - bal.balance));

                started = vsNow();
                ends    = started + ch.durationDays * 86400000;
                committedBalance = bal.balance - stake;

                tx.update(bal.ref, {
                    'grit.balance': committedBalance,
                    'grit.lifetimeSpent': bal.spent + stake
                });
                var patch = {
                    status: 'active',
                    pot: stake * 2,
                    startedAt: started,
                    endsAt: ends
                };
                patch['mapping.' + uid] = mappingMine;
                patch['seen.' + uid]    = started;
                tx.update(chRef, patch);
            });

            vsMirrorBalance(committedBalance, -stake, 'challenge_stake',
                { challengeId: id, challengeName: chName, role: 'opponent' });

            var cached = vsCacheGet(id);
            if (cached) {
                cached.status = 'active';
                cached.pot = stake * 2;
                cached.startedAt = started;
                cached.endsAt = ends;
                cached.mapping = cached.mapping || {};
                cached.mapping[uid] = mappingMine;
            }
            return true;
        }

        // Decline, expire and cancel refund identically (§3.4): terminal
        // status, the pot recorded as owed back to whoever paid it, pot zeroed.
        // The claim path in §6.4 returns it. Guarded on status == 'pending' so
        // two clients racing cannot both refund.
        async function vsTerminatePending(id, nextStatus, outcome) {
            var uid = vsUid();
            var chRef = doc(db, VS_COL, id);
            var didRun = false;
            await runTransaction(db, async function (tx) {
                var snap = await tx.get(chRef);
                if (!snap.exists()) return;
                var ch = snap.data();
                if (ch.status !== 'pending') return;   // someone else got here first
                if ((ch.participants || []).indexOf(uid) === -1) return;
                if (nextStatus === 'declined'  && ch.opponent  !== uid) return;
                if (nextStatus === 'cancelled' && ch.createdBy !== uid) return;
                if (nextStatus === 'expired'   && vsNow() <= ch.expiresAt) return;

                var payout = {};
                (ch.participants || []).forEach(function (p) { payout[p] = 0; });
                // Only the challenger has paid while a challenge is pending —
                // escrow at invite (§3.1) means the pot is exactly one stake.
                payout[ch.createdBy] = ch.pot;

                tx.update(chRef, {
                    status: nextStatus,
                    outcome: outcome,
                    winner: null,
                    resolvedAt: vsNow(),
                    pot: 0,
                    payout: payout
                });
                didRun = true;
            });
            if (didRun) { await vsFetch(true); }
            return didRun;
        }

        window.vsDecline = async function (id) {
            if (!confirm('Decline this challenge? Their stake goes back to them.')) return;
            try {
                await vsTerminatePending(id, 'declined', 'declined_refund');
                showToast('Challenge declined.', 'olive');
                vsRenderTab();
            } catch (e) { showToast(vsErrText(e), 'red'); }
        };

        window.vsCancel = async function (id) {
            if (!confirm('Withdraw this invite? Your stake is returned.')) return;
            try {
                await vsTerminatePending(id, 'cancelled', 'cancelled_refund');
                showToast('Invite withdrawn — your stake is on its way back.', 'olive');
                await vsRunMaintenance();
                vsRenderTab();
            } catch (e) { showToast(vsErrText(e), 'red'); }
        };

        // ── Resolution (§6) ───────────────────────────────────────────────
        //
        // Resolution never moves Grit. The loser's client cannot write to the
        // winner's balance and is never granted the ability to. It records what
        // is owed in `payout` and zeroes the pot; each side then claims its own
        // (§6.4). Every resolving transaction is guarded on the status it
        // expects, so whichever client gets there first wins the race and the
        // second is a no-op — two clients resolving at once cannot double-pay.

        function vsBuildResolution(ch, winnerUid, outcome) {
            var p = ch.participants || [];
            var payout = {};
            p.forEach(function (u) { payout[u] = 0; });
            if (winnerUid) {
                payout[winnerUid] = ch.pot;
            } else {
                // Tie or refund: both stakes go home whole. No coin flip — a
                // wager where nobody lost should not manufacture a loser.
                p.forEach(function (u) { payout[u] = Math.round(ch.pot / p.length); });
            }
            return {
                status: 'resolved',
                winner: winnerUid || null,
                outcome: outcome,
                resolvedAt: vsNow(),
                pot: 0,
                payout: payout
            };
        }

        // Applies one qualifying completion AND resolves in the same
        // transaction when it crosses the final target (§6.1 rule 1, §6.3).
        // Returns 'won' | 'progressed' | null.
        async function vsCommitProgress(id, reqId, delta) {
            var uid = vsUid();
            var chRef = doc(db, VS_COL, id);
            var result = null;
            await runTransaction(db, async function (tx) {
                var snap = await tx.get(chRef);
                if (!snap.exists()) return;
                var ch = snap.data();
                if (ch.status !== 'active') return;
                var now = vsNow();
                if (now < ch.startedAt || now > ch.endsAt) return;

                var req = (ch.requirements || []).find(function (r) { return r.reqId === reqId; });
                if (!req) return;

                var prog = Object.assign({}, (ch.progress || {})[uid] || {});
                var before = prog[reqId] || 0;
                var after  = Math.max(0, Math.min(req.targetCount, before + delta));
                if (after === before) return;   // already at target, or already zero
                prog[reqId] = after;

                var total = (ch.requirements || []).reduce(function (s, r) {
                    return s + Math.min(prog[r.reqId] || 0, r.targetCount || 0);
                }, 0);

                var patch = {};
                patch['progress.' + uid + '.' + reqId] = after;
                patch['totals.' + uid] = total;

                var complete = (ch.requirements || []).every(function (r) {
                    return (prog[r.reqId] || 0) >= (r.targetCount || 0);
                });
                if (complete && delta > 0) {
                    Object.assign(patch, vsBuildResolution(ch, uid, 'completed_first'));
                    result = 'won';
                } else {
                    result = 'progressed';
                }
                tx.update(chRef, patch);
            });
            return result;
        }

        // §6.1 rules 2 and 3 — evaluated lazily on any client load of an
        // `active` challenge whose deadline has passed. Guarded on
        // status == 'active'.
        async function vsResolveDeadline(id) {
            var chRef = doc(db, VS_COL, id);
            var fired = false;
            await runTransaction(db, async function (tx) {
                var snap = await tx.get(chRef);
                if (!snap.exists()) return;
                var ch = snap.data();
                if (ch.status !== 'active') return;
                if (vsNow() <= ch.endsAt) return;

                var p = ch.participants || [];
                var a = p[0], b = p[1];
                // Re-derive both totals from the counters rather than trusting
                // the denormalised value, and re-apply the per-requirement cap.
                var ta = vsCappedTotal(ch, a), tb = vsCappedTotal(ch, b);

                // A side that quietly reached every target without the
                // resolving write landing still wins outright.
                var doneA = vsHasCompleted(ch, a), doneB = vsHasCompleted(ch, b);
                var patch;
                if (doneA && !doneB)      patch = vsBuildResolution(ch, a, 'completed_first');
                else if (doneB && !doneA) patch = vsBuildResolution(ch, b, 'completed_first');
                else if (ta > tb)         patch = vsBuildResolution(ch, a, 'deadline_lead');
                else if (tb > ta)         patch = vsBuildResolution(ch, b, 'deadline_lead');
                else                      patch = vsBuildResolution(ch, null, 'tie_refund');

                // Neither side's denormalised totals are rewritten here: a
                // participant may only ever write their own keys, and the
                // comparison above is derived from the counters regardless.
                tx.update(chRef, patch);
                fired = true;
            });
            return fired;
        }

        // §6.2 — forfeiting hands the whole pot to the opponent. Reachable by
        // deleting or unmapping an activity that is committed to a live
        // challenge, or by explicitly forfeiting.
        async function vsForfeit(id, reason) {
            var uid = vsUid();
            var chRef = doc(db, VS_COL, id);
            var done = false;
            await runTransaction(db, async function (tx) {
                var snap = await tx.get(chRef);
                if (!snap.exists()) return;
                var ch = snap.data();
                if (ch.status !== 'active') return;
                if ((ch.participants || []).indexOf(uid) === -1) return;
                var opp = vsOther(ch, uid);
                var patch = vsBuildResolution(ch, opp, 'forfeit');
                patch.forfeitedBy = uid;
                if (reason) patch.forfeitReason = String(reason).slice(0, 80);
                tx.update(chRef, patch);
                done = true;
            });
            if (done) await vsFetch(true);
            return done;
        }
        window.vsForfeit = vsForfeit;

        // ── Payout claim (§6.4) ───────────────────────────────────────────
        // Runs automatically on load — no button. `payoutClaimed[myUid]` is the
        // only key in that map this user may write, and only false → true, so
        // the claim is idempotent no matter how many times a client retries.
        async function vsClaimPayout(ch) {
            var uid = vsUid();
            if (!uid) return 0;
            var owed = (ch.payout && ch.payout[uid]) || 0;
            if (owed <= 0) return 0;
            if (ch.payoutClaimed && ch.payoutClaimed[uid]) return 0;

            await vsFlushBeforeStake();

            var chRef = doc(db, VS_COL, ch.id);
            var credited = 0, newBalance = null, reason = 'challenge_payout';

            await runTransaction(db, async function (tx) {
                var snap = await tx.get(chRef);
                if (!snap.exists()) return;
                var live = snap.data();
                var amount = (live.payout && live.payout[uid]) || 0;
                if (amount <= 0) return;
                if (live.payoutClaimed && live.payoutClaimed[uid]) return;

                var bal = await vsReadBalance(tx, uid);
                newBalance = bal.balance + amount;
                credited   = amount;
                reason = (live.winner === uid && live.outcome !== 'tie_refund')
                       ? 'challenge_payout' : 'challenge_refund';

                tx.update(bal.ref, {
                    'grit.balance': newBalance,
                    'grit.lifetimeEarned': bal.earned + amount
                });
                var patch = {};
                patch['payoutClaimed.' + uid] = true;
                tx.update(chRef, patch);
            });

            if (credited > 0) {
                vsMirrorBalance(newBalance, credited, reason,
                    { challengeId: ch.id, challengeName: ch.name });
                if (ch.payoutClaimed) ch.payoutClaimed[uid] = true;
            }
            return credited;
        }

        // ── Lazy maintenance (§3.4, §6.3, §6.4) ───────────────────────────
        // Expiry and deadline resolution are ALSO done server-side now, by the
        // resolveDueVersusChallenges scheduler — that is what makes the win/loss
        // push arrive at the deadline instead of whenever someone next opens the
        // app. This pass stays anyway, and stays first: it is what settles a
        // challenge in the seconds before the scheduler's next sweep, and payout
        // claims can only ever happen here, because nothing server-side writes a
        // user's balance. Both paths guard on the status they expect, so
        // whichever gets there first wins and the other is a no-op.
        let _vsMaintaining = false;

        async function vsRunMaintenance() {
            if (_vsMaintaining) return;
            _vsMaintaining = true;
            try {
                var uid = vsUid();
                if (!uid) return;
                var list = await vsFetch(false);
                var touched = false;

                for (var i = 0; i < list.length; i++) {
                    var ch = list[i];
                    try {
                        if (ch.status === 'pending' && vsNow() > ch.expiresAt) {
                            if (await vsTerminatePending(ch.id, 'expired', 'expired_refund')) touched = true;
                        } else if (ch.status === 'active' && vsNow() > ch.endsAt) {
                            if (await vsResolveDeadline(ch.id)) touched = true;
                        }
                    } catch (e) { console.warn('Versus maintenance step failed:', e && e.message); }
                }
                if (touched) list = await vsFetch(true);

                for (var j = 0; j < list.length; j++) {
                    var c = list[j];
                    if (!vsIsTerminal(c.status)) continue;
                    try {
                        var got = await vsClaimPayout(c);
                        if (got > 0) {
                            touched = true;
                            showToast('+' + got + ' Grit returned from "' + c.name + '"', 'olive');
                        }
                    } catch (e) { console.warn('Versus claim failed:', e && e.message); }
                }
                if (touched) await vsFetch(true);
                vsAnnounceResults();
                vsPrune();
                vsUpdateBadges();
            } finally {
                _vsMaintaining = false;
            }
        }

        // A terminal challenge that owes this user nothing, or has already paid
        // them, is dead weight in memory. It stays in Firestore — documents are
        // never deleted — but there is no reason to carry it in the cache the
        // completion path walks on every tap.
        function vsPrune() {
            var uid = vsUid();
            if (!uid) return;
            _vsCache.list = _vsCache.list.filter(function (c) {
                if (!vsIsTerminal(c.status)) return true;
                var owed    = (c.payout && c.payout[uid]) || 0;
                var claimed = !!(c.payoutClaimed && c.payoutClaimed[uid]);
                if (owed > 0 && !claimed) return true;                 // still owed
                if (c.status === 'resolved' &&
                    (vsNow() - (c.resolvedAt || 0)) < VS_ARCHIVE_DAYS * 86400000) return true;
                return false;
            });
        }

        // §6.5 — both sides get told, plainly, on next load. Seen results are
        // remembered in userData so the message fires once, not every render.
        function vsAnnounceResults() {
            var uid = vsUid();
            if (!uid || !window.userData) return;
            if (!window.userData.vsSeenResults) window.userData.vsSeenResults = {};
            var seen = window.userData.vsSeenResults;
            var changed = false;

            _vsCache.list.forEach(function (ch) {
                if (ch.status !== 'resolved') return;
                if (seen[ch.id]) return;
                seen[ch.id] = true;
                changed = true;
                var opp = vsOther(ch, uid);
                var mine = vsCappedTotal(ch, uid), theirs = vsCappedTotal(ch, opp);
                var line, lineIcon = null;
                if (ch.outcome === 'tie_refund') {
                    line = '"' + ch.name + '" ended level — ' + mine + '–' + theirs +
                           '. Both stakes returned.';
                    lineIcon = 'handshake';
                } else if (ch.winner === uid) {
                    line = 'You won "' + ch.name + '" ' + mine + '–' + theirs +
                           ' · +' + ((ch.payout && ch.payout[uid]) || 0) + ' Grit';
                    lineIcon = 'trophy';
                } else {
                    line = '"' + ch.name + '" went to ' + vsName(ch, opp) + ' — ' +
                           mine + '–' + theirs + '. Your stake is gone.';
                }
                showToast(line, ch.winner === uid ? 'olive' : 'red', null, lineIcon);
            });
            if (changed) debouncedSaveUserData();
        }

        // ── Progress accounting (§4) ──────────────────────────────────────
        //
        // A completion counts only when: the challenge is active, now is inside
        // [startedAt, endsAt], the activity is mapped to a requirement FOR THIS
        // USER, and the completion is live rather than backdated.
        //
        // The fourth rule is why this hooks completeActivity() and nothing
        // else. completeActivity is the live path; retroactiveComplete() is the
        // backdating path and is deliberately NOT hooked. Backdating stays free
        // and unlimited everywhere else — it still awards XP, still feeds
        // streaks, still counts in analytics. It simply does not move a wager.
        //
        // Cost (§4.3): one small write per qualifying completion, only while a
        // challenge is active, only for mapped activities. The mapping lookup
        // resolves against the in-memory cache — there is no read on the
        // completion hot path. A stale cache can miss a challenge accepted
        // seconds ago; that is acceptable and self-corrects on next refresh.

        function vsLiveMappingsFor(activityId) {
            var uid = vsUid();
            var out = [];
            if (!uid) return out;
            var now = vsNow();
            _vsCache.list.forEach(function (ch) {
                if (ch.status !== 'active') return;
                if (now < ch.startedAt || now > ch.endsAt) return;
                var m = vsMappingOf(ch, uid);
                Object.keys(m).forEach(function (reqId) {
                    if (m[reqId] && m[reqId].activityId === activityId) {
                        out.push({ ch: ch, reqId: reqId });
                    }
                });
            });
            return out;
        }

        async function vsOnCompletion(activityId) {
            var hits = vsLiveMappingsFor(activityId);
            if (!hits.length) return;
            var uid = vsUid();
            for (var i = 0; i < hits.length; i++) {
                var ch = hits[i].ch, reqId = hits[i].reqId;
                var req = (ch.requirements || []).find(function (r) { return r.reqId === reqId; });
                if (!req) continue;
                var cur = (vsProgressOf(ch, uid))[reqId] || 0;
                if (cur >= req.targetCount) continue;   // capped — no write at all
                try {
                    var res = await vsCommitProgress(ch.id, reqId, +1);
                    if (res) {
                        // Mirror into the cache so the next completion caps
                        // correctly without a re-read.
                        ch.progress = ch.progress || {};
                        ch.progress[uid] = ch.progress[uid] || {};
                        ch.progress[uid][reqId] = cur + 1;
                        ch.totals = ch.totals || {};
                        ch.totals[uid] = vsCappedTotal(ch, uid);
                    }
                    if (res === 'won') {
                        await vsFetch(true);
                        showToast('You finished "' + ch.name + '" first — the pot is yours.', 'olive', null, 'trophy');
                        await vsRunMaintenance();
                    }
                } catch (e) { console.warn('Versus progress write failed:', e && e.message); }
            }
            vsRenderIfVisible();
        }

        // §4.2 — undo must mirror. undoActivity only ever reverses a completion
        // made today, which is exactly the set of completions that could have
        // incremented a challenge, so the symmetry is clean. Clamped at zero.
        async function vsOnUndo(activityId) {
            var hits = vsLiveMappingsFor(activityId);
            if (!hits.length) return;
            var uid = vsUid();
            for (var i = 0; i < hits.length; i++) {
                var ch = hits[i].ch, reqId = hits[i].reqId;
                var cur = (vsProgressOf(ch, uid))[reqId] || 0;
                if (cur <= 0) continue;
                try {
                    await vsCommitProgress(ch.id, reqId, -1);
                    ch.progress[uid][reqId] = cur - 1;
                    ch.totals[uid] = vsCappedTotal(ch, uid);
                } catch (e) { console.warn('Versus undo write failed:', e && e.message); }
            }
            vsRenderIfVisible();
        }

        // ── Detail listener (§5) ──────────────────────────────────────────
        // The one place a live socket is warranted: the detail view is the one
        // place the user is actually looking at the opponent's bar. Never in
        // the list — several active challenges would otherwise hold several
        // sockets open for bars nobody is watching.
        function vsAttachDetail(id) {
            vsDetachDetail();
            _vsDetailId = id;
            try {
                _vsDetailUnsub = onSnapshot(doc(db, VS_COL, id), function (snap) {
                    if (!snap.exists()) return;
                    var ch = Object.assign({ id: snap.id }, snap.data());
                    vsCacheReplace(ch);
                    if (_vsDetailId === id) vsRenderDetail(id);
                }, function (err) { console.warn('Versus detail listener:', err && err.message); });
            } catch (e) { console.warn('Versus listener attach failed:', e && e.message); }
        }

        function vsDetachDetail() {
            if (_vsDetailUnsub) { try { _vsDetailUnsub(); } catch (e) {} }
            _vsDetailUnsub = null;
            _vsDetailId = null;
        }

        function vsErrText(e) {
            var m = (e && e.message) || String(e);
            if (m.indexOf('SHORTFALL:') === 0) {
                return 'You are ' + m.split(':')[1] + ' Grit short of this stake.';
            }
            if (/permission|insufficient/i.test(m)) {
                return 'Firestore rules rejected that write — the versus rules may not be deployed yet.';
            }
            return m;
        }
        // ── UI (§8) ───────────────────────────────────────────────────────
        // The versus board carries forward the design language of the solo
        // Challenge card that used to live one sub-tab over: a hero number, a
        // full-width track, an expandable per-activity breakdown. The delta is
        // the opponent — a second bar, deliberately subordinate, so the card
        // reads "this is mine, they are on it" rather than as two rivals of
        // equal weight.
        //
        // All of it is self-contained vs-* markup. The ch-* system it learned
        // from went away with the solo feature, so nothing here leans on it.

        function vsFmtLeft(ms) {
            if (ms <= 0) return 'ended';
            var d = Math.floor(ms / 86400000);
            if (d >= 1) return d + (d === 1 ? ' day left' : ' days left');
            var h = Math.floor(ms / 3600000);
            if (h >= 1) return h + 'h left';
            return Math.max(1, Math.floor(ms / 60000)) + 'm left';
        }

        function vsPct(cur, target) {
            return target > 0 ? Math.min(100, (cur / target) * 100) : 0;
        }

        function vsDurationText(days) {
            if (days % 7 === 0 && days >= 7) {
                var w = days / 7;
                return w + (w === 1 ? ' week' : ' weeks');
            }
            return days + (days === 1 ? ' day' : ' days');
        }

        // Everything the board and its breakdown need, derived once per paint
        // (§9). Expanding the breakdown re-reads this model rather than
        // recomputing per-activity progress on every toggle.
        function vsBoardModel(ch, uid) {
            var opp    = vsOther(ch, uid);
            var reqs   = ch.requirements || [];
            var myProg = vsProgressOf(ch, uid);
            var opProg = vsProgressOf(ch, opp);
            var myMap  = vsMappingOf(ch, uid);
            var opMap  = vsMappingOf(ch, opp);

            var target = 0, mine = 0, theirs = 0;
            var rows = reqs.map(function (r) {
                var t  = r.targetCount || 1;
                var mc = Math.min(myProg[r.reqId] || 0, t);
                var tc = Math.min(opProg[r.reqId] || 0, t);
                target += t; mine += mc; theirs += tc;
                return {
                    reqId:     r.reqId,
                    label:     vsReqName(ch, r),
                    target:    t,
                    mine:      mc,
                    theirs:    tc,
                    myAct:     (myMap[r.reqId] || {}).activityName || null,
                    theirAct:  (opMap[r.reqId] || {}).activityName || null
                };
            });

            var leadKey = mine > theirs ? 'ahead' : (mine < theirs ? 'behind' : 'level');
            return {
                opp: opp, oppName: vsName(ch, opp),
                rows: rows, target: target, mine: mine, theirs: theirs,
                myPct: vsPct(mine, target), theirPct: vsPct(theirs, target),
                leadKey: leadKey,
                leadTxt: leadKey === 'ahead' ? 'you lead' : (leadKey === 'behind' ? 'you trail' : 'level')
            };
        }

        // ── Board pieces ──────────────────────────────────────────────────

        // The hero: biggest number on the card, full-width track under it.
        function vsHero(model, done) {
            return '' +
            '<div class="vs-hero">' +
                '<div class="vs-hero-top">' +
                    '<span class="vs-count">' +
                        '<span class="vs-count-cur">' + model.mine + '</span>' +
                        '<span class="vs-count-sep">/</span>' +
                        '<span class="vs-count-tgt">' + model.target + '</span>' +
                    '</span>' +
                    '<span class="vs-hero-pct">' + Math.floor(model.myPct) + '%</span>' +
                '</div>' +
                '<div class="vs-track"><div class="vs-fill' + (done ? ' is-done' : '') +
                    '" style="width:' + model.myPct + '%;"></div></div>' +
            '</div>';
        }

        // The opponent: same shape, narrower and quieter. The hierarchy is the
        // message — you should not need to read the labels to know whose card
        // this is.
        function vsOppBar(model) {
            return '' +
            '<div class="vs-opp">' +
                '<div class="vs-opp-top">' +
                    '<span class="vs-opp-name">' + escapeHtml(model.oppName) + '</span>' +
                    '<span class="vs-opp-count">' + model.theirs + '/' + model.target + '</span>' +
                '</div>' +
                '<div class="vs-track vs-track-sm"><div class="vs-fill vs-fill-opp" style="width:' +
                    model.theirPct + '%;"></div></div>' +
            '</div>';
        }

        // The opponent's bar and whatever sits beside it. Forfeit rides this
        // row rather than the action row below: quitting is about the person
        // you are racing, so it belongs against their line, and putting it
        // there leaves the action row to the one thing you actually press.
        function vsOppRow(model, trailing) {
            return '<div class="vs-opp-row">' + vsOppBar(model) + (trailing || '') + '</div>';
        }

        // The header's facts as chips. Dots between four different kinds of
        // number made them read as one run-on line; a chip each gives the pot,
        // the bonus, the clock and the standing their own edges.
        function vsChips(cells) {
            return '<div class="vs-chips">' + cells.filter(Boolean).map(function (c) {
                var tone = c.tone || 'plain';
                // The semantic classes the card has always carried — gold is
                // money, green is XP, the lead is the standing — ride along, so
                // the tone is still readable from the markup alone.
                var extra = tone === 'gold' ? ' vs-gold'
                          : tone === 'xp'   ? ' vs-xp'
                          : tone.indexOf('lead-') === 0 ? ' vs-lead vs-' + tone
                          : '';
                return '<span class="vs-chip vs-chip-' + tone + extra + '">' +
                       escapeHtml(String(c.text)) + '</span>';
            }).join('') + '</div>';
        }

        // One activity inside the breakdown.
        function vsSubBar(label, cur, target, quiet) {
            var done = cur >= target;
            return '' +
            '<div class="vs-sub' + (quiet ? ' vs-sub-quiet' : '') + '">' +
                '<div class="vs-sub-top">' +
                    '<span class="vs-sub-name' + (done ? ' is-done' : '') + '">' + escapeHtml(label) + '</span>' +
                    '<span class="vs-sub-count">' + cur + '/' + target + '</span>' +
                '</div>' +
                '<div class="vs-track vs-track-xs"><div class="vs-fill' + (done ? ' is-done' : '') +
                    (quiet ? ' vs-fill-opp' : '') + '" style="width:' + vsPct(cur, target) + '%;"></div></div>' +
            '</div>';
        }

        function vsChevron(open) {
            return '<svg class="vs-chev' + (open ? ' is-open' : '') + '" viewBox="0 0 24 24" fill="none" ' +
                   'stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">' +
                   '<polyline points="6 9 12 15 18 9"/></svg>';
        }

        // Three numbers, sized like they matter. Gold is money on the line,
        // green is XP, neutral is what you hold — and red when you are short.
        function vsStakes(cells) {
            return '<div class="vs-stakes">' + cells.map(function (c) {
                return '<div class="vs-stake-cell vs-tone-' + c.tone + '">' +
                       '<div class="vs-stake-val">' + escapeHtml(String(c.value)) + '</div>' +
                       '<div class="vs-stake-lbl">' + escapeHtml(c.label) + '</div>' +
                       '</div>';
            }).join('') + '</div>';
        }

        // ── Cards ─────────────────────────────────────────────────────────

        function vsPendingCard(ch, uid) {
            var mine = ch.createdBy === uid;
            var opp  = vsOther(ch, uid);
            var reqLine = (ch.requirements || []).map(function (r) {
                return escapeHtml(vsReqName(ch, r)) + ' ×' + r.targetCount;
            }).join(' · ');

            var actions = mine
                ? '<button class="vs-btn vs-btn-ghost" onclick="vsCancel(\'' + ch.id + '\')">Withdraw</button>'
                : '<button class="vs-btn vs-btn-primary" onclick="vsOpenAccept(\'' + ch.id + '\')">Accept</button>' +
                  '<button class="vs-btn vs-btn-ghost" onclick="vsDecline(\'' + ch.id + '\')">Decline</button>';

            return '' +
            '<div class="vs-board" data-state="pending">' +
                '<div class="vs-board-head">' +
                    '<div class="vs-ribbon">' + (mine ? 'Sent' : 'Received') + '</div>' +
                    '<h3 class="vs-board-title">' + escapeHtml(ch.name) + '</h3>' +
                    '<div class="vs-board-sub">' + (mine ? 'To ' : 'From ') +
                        escapeHtml(vsName(ch, opp)) + '</div>' +
                    vsChips([
                        { text: ch.stake + ' Grit each', tone: 'gold' },
                        { text: vsDurationText(ch.durationDays), tone: 'plain' },
                        { text: 'Answer in ' + vsFmtLeft(ch.expiresAt - vsNow()).replace(/ left$/, ''), tone: 'plain' }
                    ]) +
                '</div>' +
                '<div class="vs-rule"></div>' +
                '<div class="vs-reqline">' + reqLine + '</div>' +
                '<div class="vs-actions">' + actions + '</div>' +
            '</div>';
        }

        function vsActiveCard(ch, uid) {
            var m    = vsBoardModel(ch, uid);
            var open = _vsDetailId === ch.id;
            var done = m.target > 0 && m.mine >= m.target;

            var breakdown = '';
            if (open) {
                breakdown =
                    '<div class="vs-breakdown">' +
                        '<div class="vs-bd-group">' +
                            '<div class="vs-bd-head">You</div>' +
                            m.rows.map(function (r) {
                                return vsSubBar(r.myAct || r.label, r.mine, r.target, false);
                            }).join('') +
                        '</div>' +
                        '<div class="vs-bd-group">' +
                            '<div class="vs-bd-head">' + escapeHtml(m.oppName) + '</div>' +
                            '<div class="vs-track vs-track-sm vs-bd-total">' +
                                '<div class="vs-fill vs-fill-opp" style="width:' + m.theirPct + '%;"></div>' +
                            '</div>' +
                            m.rows.map(function (r) {
                                return vsSubBar(r.theirAct || r.label, r.theirs, r.target, true);
                            }).join('') +
                        '</div>' +
                    '</div>';
            }

            var forfeit =
                '<button type="button" class="vs-btn vs-btn-danger vs-forfeit" ' +
                    'onclick="vsConfirmForfeit(\'' + ch.id + '\')">' +
                    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" ' +
                    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
                    '<line x1="4" y1="22" x2="4" y2="3"/>' +
                    '<path d="M4 4h11l-1.6 3.5L15 11H4z"/></svg>' +
                    '<span>Forfeit</span>' +
                '</button>';

            return '' +
            '<div class="vs-board" data-state="' + (done ? 'won' : 'active') + '">' +
                '<div class="vs-board-head">' +
                    '<h3 class="vs-board-title">' + escapeHtml(ch.name) + '</h3>' +
                    vsChips([
                        { text: ch.pot + ' Grit pot', tone: 'gold' },
                        { text: '+' + ch.bonusXP + ' XP', tone: 'xp' },
                        { text: vsFmtLeft(ch.endsAt - vsNow()), tone: 'plain' },
                        { text: m.leadTxt, tone: 'lead-' + m.leadKey }
                    ]) +
                '</div>' +
                '<div class="vs-rule"></div>' +
                vsHero(m, done) +
                vsOppRow(m, forfeit) +
                '<div class="vs-board-actions">' +
                    '<button class="vs-expand" type="button" aria-expanded="' + open + '" ' +
                        'onclick="vsToggleDetail(\'' + ch.id + '\')">' +
                        '<span>' + (open ? 'Hide breakdown' : 'Breakdown') + '</span>' + vsChevron(open) +
                    '</button>' +
                '</div>' +
                breakdown +
            '</div>';
        }

        function vsResolvedCard(ch, uid) {
            var m       = vsBoardModel(ch, uid);
            var won     = ch.winner === uid;
            var tie     = !ch.winner;
            var owed    = (ch.payout && ch.payout[uid]) || 0;
            var claimed = !!(ch.payoutClaimed && ch.payoutClaimed[uid]);
            var oppName = escapeHtml(m.oppName);

            var verdict, state;
            if (tie) {
                verdict = 'Level at the deadline.'; state = 'tie';
            } else if (won) {
                verdict = ch.outcome === 'forfeit' ? oppName + ' forfeited.'
                        : (ch.outcome === 'completed_first' ? 'You finished first.'
                                                           : 'You were ahead at the deadline.');
                state = 'won';
            } else {
                verdict = ch.outcome === 'forfeit' ? 'You forfeited.'
                        : (ch.outcome === 'completed_first' ? oppName + ' finished first.'
                                                           : oppName + ' was ahead at the deadline.');
                state = 'lost';
            }

            var gritLine = owed > 0
                ? '<span class="vs-xp">+' + owed + ' Grit' + (claimed ? '' : ' incoming') + '</span>'
                : '<span class="vs-loss">−' + ch.stake + ' Grit</span>';

            return '' +
            '<div class="vs-board" data-state="' + state + '">' +
                '<div class="vs-board-head">' +
                    '<div class="vs-ribbon vs-ribbon-' + state + '">' +
                        (tie ? 'Draw' : (won ? 'Won' : 'Lost')) + '</div>' +
                    '<h3 class="vs-board-title">' + escapeHtml(ch.name) + '</h3>' +
                    '<div class="vs-board-meta">' +
                        '<span>' + verdict + '</span>' +
                        '<span class="vs-dot">·</span>' + gritLine +
                    '</div>' +
                '</div>' +
                '<div class="vs-rule"></div>' +
                vsHero(m, won) +
                vsOppRow(m) +
            '</div>';
        }

        // ── Tab render ────────────────────────────────────────────────────

        window.vsRenderTab = async function () {
            var host = document.getElementById('versusContent');
            if (!host) return;
            var uid = vsUid();
            if (!uid) { host.innerHTML = ''; return; }

            if (!_vsCache.at) {
                host.innerHTML = '<div class="vs-loading">Loading…</div>';
            }
            await vsFetch(false);
            await vsRunMaintenance();
            vsPaint();
        };

        function vsPaint() {
            var host = document.getElementById('versusContent');
            if (!host) return;
            var uid = vsUid();
            if (!uid) return;

            var list = _vsCache.list.slice();
            var pending  = list.filter(function (c) { return c.status === 'pending'; });
            var active   = list.filter(function (c) { return c.status === 'active'; });
            var resolved = list.filter(function (c) {
                return c.status === 'resolved' &&
                       (vsNow() - (c.resolvedAt || 0)) < VS_ARCHIVE_DAYS * 86400000;
            });
            pending.sort(function (a, b) { return a.expiresAt - b.expiresAt; });
            active.sort(function (a, b) { return a.endsAt - b.endsAt; });
            resolved.sort(function (a, b) { return (b.resolvedAt || 0) - (a.resolvedAt || 0); });

            var live = pending.length + active.length;
            var html = '' +
                '<div class="act-toolbar vs-toolbar">' +
                    '<div class="tool-cluster">' +
                        '<span class="vs-cap">' + live + ' / ' + VS_MAX_CONCURRENT + ' running</span>' +
                    '</div>' +
                    '<button class="act-tb-add-main"' +
                        (live >= VS_MAX_CONCURRENT ? ' disabled title="You are at the limit"' : '') +
                        ' onclick="vsOpenCreate()">' +
                        '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>' +
                        'Challenge a friend' +
                    '</button>' +
                '</div>';

            if (!live && !resolved.length) {
                html += '<div class="vs-empty">' +
                            '<div class="vs-empty-icon"><i class="ph-fill ph-sword mk-ico-block"></i></div>' +
                            '<div class="vs-empty-text">Stake Grit against a friend. ' +
                            'First to finish takes the pot.</div>' +
                        '</div>';
                host.innerHTML = html;
                return;
            }

            function section(title, count, body) {
                return '<div class="vs-section"><h3 class="vs-section-title">' + title + '</h3>' +
                       '<span class="vs-section-count">' + count + '</span></div>' + body;
            }
            if (pending.length) {
                html += section('Invites', pending.length,
                    pending.map(function (c) { return vsPendingCard(c, uid); }).join(''));
            }
            if (active.length) {
                html += section('Live', active.length,
                    active.map(function (c) { return vsActiveCard(c, uid); }).join(''));
            }
            if (resolved.length) {
                html += section('Finished', resolved.length,
                    resolved.map(function (c) { return vsResolvedCard(c, uid); }).join(''));
            }
            host.innerHTML = html;
            vsMarkSeen(pending.concat(active));
        }

        function vsRenderIfVisible() {
            if (window.currentTab === 'challenges') vsPaint();
            vsUpdateBadges();
        }

        function vsRenderDetail(id) {
            // The open card is re-rendered in place by repainting the list;
            // the listener keeps the opponent's bar live while it is open.
            vsPaint();
        }

        window.vsToggleDetail = function (id) {
            if (_vsDetailId === id) { vsDetachDetail(); }
            else { vsAttachDetail(id); }
            vsPaint();
        };

        // §2.2 `seen` — drives the invite badge. Written at most once per
        // challenge per session, own key only.
        let _vsSeenWritten = {};
        function vsMarkSeen(list) {
            var uid = vsUid();
            if (!uid) return;
            list.forEach(function (ch) {
                if (_vsSeenWritten[ch.id]) return;
                if (ch.createdBy === uid && ch.status === 'pending') return;  // nothing new to see
                _vsSeenWritten[ch.id] = true;
                var patch = {};
                patch['seen.' + uid] = vsNow();
                updateDoc(doc(db, VS_COL, ch.id), patch).catch(function () {});
                if (ch.seen) ch.seen[uid] = vsNow();
            });
            vsUpdateBadges();
        }

        // ── Badges (§3.2) ─────────────────────────────────────────────────
        function vsPendingForMe() {
            var uid = vsUid();
            return _vsCache.list.filter(function (c) {
                return c.status === 'pending' && c.opponent === uid && vsNow() < c.expiresAt;
            }).length;
        }

        function vsUpdateBadges() {
            var n = vsPendingForMe();
            // Challenges nav tab
            document.querySelectorAll('.nav-tab').forEach(function (tab) {
                var oc = tab.getAttribute('onclick') || '';
                if (oc.indexOf("switchTab('challenges')") === -1) return;
                var d = tab.querySelector('.vs-nav-dot');
                if (n > 0) {
                    if (!d) { d = document.createElement('span'); d.className = 'vs-nav-dot'; tab.appendChild(d); }
                } else if (d) { d.remove(); }
            });
        }

        // ── Sheet primitive ───────────────────────────────────────────────
        // One reusable overlay, created on demand, styled with the app's
        // existing modal tokens.

        // ── Why sheets used to "refresh" on every tap ─────────────────────
        // On phones the app animates `.modal-overlay.active > .modal` with
        // mkSheetRise: the panel slides up from off-screen when it opens. Every
        // sheet in the app used to show a new state by building a NEW .modal
        // element — so the browser saw a fresh node matching that selector and
        // replayed the OPEN animation. Tap "+ Add requirement", or open the
        // activity picker, and the whole card dropped to the bottom of the
        // screen and slid back up. That is the flash, and it was never a
        // re-fetch: it was the entry animation, once per click.
        //
        // The fix is to keep the .modal node and swap what is inside it. The
        // animation runs once, when the sheet genuinely opens.
        function mkSwapSheetContents(overlay, innerHtml) {
            var modal = overlay && overlay.querySelector('.modal');
            if (!modal) return false;
            var oldBody = modal.querySelector('.modal-body');
            var top = oldBody ? oldBody.scrollTop : 0;
            modal.innerHTML = innerHtml;
            var newBody = modal.querySelector('.modal-body');
            if (newBody && top) newBody.scrollTop = top;
            return true;
        }
        window.mkSwapSheetContents = mkSwapSheetContents;

        function vsSheet(innerHtml) {
            var el = document.getElementById('vsSheet');
            // Already open: this is a state change, not an open.
            if (el && el.classList.contains('active') && mkSwapSheetContents(el, innerHtml)) return;
            if (!el) {
                el = document.createElement('div');
                el.id = 'vsSheet';
                el.className = 'modal-overlay vs-sheet-scrim';
                el.addEventListener('click', function (ev) { if (ev.target === el) vsCloseSheet(); });
                document.body.appendChild(el);
            }
            el.innerHTML = '<div class="modal pl-modal vs-sheet">' + innerHtml + '</div>';
            el.classList.add('active');
            el.style.display = 'flex';
        }

        window.vsCloseSheet = function () {
            var el = document.getElementById('vsSheet');
            if (el) { el.classList.remove('active'); el.style.display = 'none'; el.innerHTML = ''; }
        };

        function vsSheetHead(eyebrow, title) {
            return '<div class="modal-header pl-modal-header">' +
                     '<div><div class="pl-modal-eyebrow">' + escapeHtml(eyebrow) + '</div>' +
                     '<h3 class="modal-title">' + escapeHtml(title) + '</h3></div>' +
                     '<button class="pl-modal-close" type="button" onclick="vsCloseSheet()" aria-label="Close">' +
                     '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                     '</button></div>';
        }

        // An initial badge in the app's friend-row idiom.
        function vsAvatar(name, photoURL, size) {
            var px = size || 40;
            if (photoURL) {
                return '<img class="vs-avatar" src="' + escapeHtml(photoURL) + '" alt="" ' +
                       'style="width:' + px + 'px;height:' + px + 'px;">';
            }
            var initial = (String(name || '?').trim()[0] || '?').toUpperCase();
            return '<div class="vs-avatar vs-avatar-initial" style="width:' + px + 'px;height:' + px +
                   'px;font-size:' + Math.round(px * 0.38) + 'px;">' + escapeHtml(initial) + '</div>';
        }

        // ── Create flow (§3, §4, §5) ──────────────────────────────────────
        // Opponent picker → terms → send. The creator maps their own
        // activities inline, because they already own them.

        let _vsDraft = null;
        let _vsFriendRows = [];

        window.vsOpenCreate = async function () {
            await vsFetch(false);
            if (vsCountLive() >= VS_MAX_CONCURRENT) {
                showToast('You already have ' + VS_MAX_CONCURRENT + ' challenges running.', 'red');
                return;
            }
            var friends = (window.userData.friends || []);
            var head = vsSheetHead('New challenge', 'Choose an opponent');

            if (!friends.length) {
                vsSheet(head + '<div class="modal-body pl-modal-body">' +
                    '<p class="vs-note">No friends yet. Add one from the Friends tab first.</p></div>');
                return;
            }
            vsSheet(head + '<div class="modal-body pl-modal-body"><div class="vs-loading">Loading…</div></div>');

            var rows = await Promise.all(friends.map(async function (uid) {
                try {
                    var s = await getDoc(doc(db, 'publicProfiles', uid));
                    var d = s.exists() ? s.data() : {};
                    return { uid: uid, name: d.displayName || 'Adventurer',
                             level: d.level || null, photoURL: d.photoURL || null,
                             title: d.characterTitle || '' };
                } catch (e) { return { uid: uid, name: 'Adventurer', level: null, photoURL: null, title: '' }; }
            }));
            rows.sort(function (a, b) { return a.name.localeCompare(b.name); });
            // Held in memory and addressed by index — a display name is never
            // interpolated into an onclick attribute, where an apostrophe
            // would break out of the handler.
            _vsFriendRows = rows;

            var body = rows.map(function (r, i) {
                var meta = [];
                if (r.level) meta.push('Lv ' + r.level);
                if (r.title) meta.push(r.title);
                return '<button class="vs-opprow" onclick="vsPickOpponent(' + i + ')">' +
                       vsAvatar(r.name, r.photoURL, 40) +
                       '<span class="vs-opprow-info">' +
                           '<span class="vs-opprow-name">' + escapeHtml(r.name) + '</span>' +
                           (meta.length ? '<span class="vs-opprow-meta">' + escapeHtml(meta.join(' · ')) + '</span>' : '') +
                       '</span>' +
                       '<svg class="vs-opprow-go" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>' +
                       '</button>';
            }).join('');

            vsSheet(head + '<div class="modal-body pl-modal-body vs-opplist">' + body + '</div>');
        };

        window.vsPickOpponent = function (i) {
            var r = _vsFriendRows[i];
            if (!r) return;
            _vsDraft = {
                opponentUid: r.uid,
                opponentName: r.name || 'Opponent',
                rows: [],
                durationDays: 14,
                stake: VS_STAKE_MIN,
                pickerRow: -1
            };
            vsDraftAddRow();
            vsRenderCreateForm();
        };

        function vsDraftAddRow() {
            if (_vsDraft.rows.length >= VS_MAX_REQS) return;
            _vsDraft.rows.push({ reqId: 'r' + Math.random().toString(36).slice(2, 8),
                                 activityId: '', targetCount: 5 });
        }

        window.vsAddRow = function () { vsReadCreateForm(); vsDraftAddRow(); vsUpdateCreateForm(); };
        window.vsDelRow = function (i) {
            vsReadCreateForm();
            if (_vsDraft.rows.length > 1) _vsDraft.rows.splice(i, 1);
            _vsDraft.pickerRow = -1;
            vsUpdateCreateForm();
        };
        window.vsTermsChanged = function () { vsReadCreateForm(); vsUpdateCreateForm(); };

        function vsReadCreateForm() {
            if (!_vsDraft) return;
            var g = function (id) { var e = document.getElementById(id); return e ? e.value : null; };
            var nm = g('vsName');       if (nm !== null) _vsDraft.name = nm;
            var ds = g('vsDesc');       if (ds !== null) _vsDraft.description = ds;
            var du = g('vsDuration');   if (du !== null) _vsDraft.durationDays = Math.max(1, parseInt(du, 10) || 14);
            var st = g('vsStake');      if (st !== null) _vsDraft.stake = parseInt(st, 10) || VS_STAKE_MIN;
            _vsDraft.rows.forEach(function (r, i) {
                var t = document.getElementById('vsRowTarget' + i);
                if (t) r.targetCount = Math.max(1, parseInt(t.value, 10) || 1);
            });
        }

        // Existing bonus-XP behaviour, unchanged (§9.12): 20% of the base XP
        // the requirements are worth at their targets, floored at 1.
        function vsDraftBonusXP() {
            var total = 0;
            _vsDraft.rows.forEach(function (r) {
                var a = gritFindActivity(r.activityId);
                if (a) total += (a.baseXP || 0) * (r.targetCount || 1);
            });
            return Math.max(1, Math.round(total * 0.2));
        }

        // ── The activity picker (§4) ──────────────────────────────────────
        // A native <select> renders differently on every platform and badly on
        // desktop, so this is an in-sheet searchable list instead: one row per
        // activity, filtered live. Filtering rewrites only the list container,
        // so the search field keeps focus between keystrokes.

        function vsPickableActivities(rowIndex) {
            var committed = vsCommittedActivityIds(null);
            var usedHere  = _vsDraft.rows.map(function (r, i) {
                return i === rowIndex ? null : r.activityId;
            }).filter(Boolean);
            return gritAllActivities().map(function (a) {
                var lock = committed.has(a.id) ? 'In another challenge'
                         : (usedHere.indexOf(a.id) !== -1 ? 'Used above' : null);
                return { id: a.id, name: a.name, xp: a.baseXP || 0, lock: lock };
            });
        }

        function vsActListHtml(rowIndex, query) {
            var q = String(query || '').trim().toLowerCase();
            var items = vsPickableActivities(rowIndex).filter(function (a) {
                return !q || a.name.toLowerCase().indexOf(q) !== -1;
            });
            if (!items.length) {
                return '<div class="vs-pick-none">' +
                       (q ? 'Nothing matches.' : 'No activities yet.') + '</div>';
            }
            var chosen = _vsDraft.rows[rowIndex].activityId;
            return items.map(function (a) {
                if (a.lock) {
                    return '<div class="vs-pickrow is-locked">' +
                           '<span class="vs-pickrow-name">' + escapeHtml(a.name) + '</span>' +
                           '<span class="vs-pickrow-why">' + escapeHtml(a.lock) + '</span></div>';
                }
                return '<button type="button" class="vs-pickrow' + (chosen === a.id ? ' is-on' : '') +
                       '" onclick="vsPickAct(' + rowIndex + ',\'' + a.id + '\')">' +
                       '<span class="vs-pickrow-name">' + escapeHtml(a.name) + '</span>' +
                       '<span class="vs-pickrow-xp">' + a.xp + ' XP</span></button>';
            }).join('');
        }

        window.vsOpenPicker = function (i) {
            vsReadCreateForm();
            _vsDraft.pickerRow = (_vsDraft.pickerRow === i) ? -1 : i;
            _vsDraft.pickerQuery = '';
            vsUpdateCreateForm();
            if (_vsDraft.pickerRow === i) {
                var el = document.getElementById('vsActSearch');
                if (el) setTimeout(function () { el.focus(); }, 40);
            }
        };

        window.vsFilterActs = function (value) {
            var host = document.getElementById('vsActList');
            if (!host || !_vsDraft || _vsDraft.pickerRow < 0) return;
            _vsDraft.pickerQuery = value;
            host.innerHTML = vsActListHtml(_vsDraft.pickerRow, value);
        };

        window.vsPickAct = function (i, activityId) {
            vsReadCreateForm();
            _vsDraft.rows[i].activityId = activityId;
            _vsDraft.pickerRow = -1;
            vsUpdateCreateForm();
        };

        // ── The terms form ────────────────────────────────────────────────
        // Split in two on purpose. vsRenderCreateForm() mounts the screen
        // once; every later interaction goes through vsUpdateCreateForm(),
        // which rewrites only the three regions that can actually change —
        // the requirement rows, the add button and the stake summary. The name
        // field, the description and the duration input are never re-created,
        // so a half-typed name keeps its caret when you add a requirement.

        function vsReqRowsHtml() {
            return _vsDraft.rows.map(function (r, i) {
                var act  = gritFindActivity(r.activityId);
                var open = _vsDraft.pickerRow === i;
                return '' +
                '<div class="vs-req' + (open ? ' is-picking' : '') + '">' +
                    '<div class="vs-req-head">' +
                        '<span class="vs-req-idx">' + (i + 1) + '</span>' +
                        (_vsDraft.rows.length > 1
                            ? '<button type="button" class="vs-req-del" onclick="vsDelRow(' + i +
                              ')" aria-label="Remove">×</button>'
                            : '') +
                    '</div>' +
                    '<div class="vs-req-body">' +
                        '<button type="button" class="vs-actbtn' + (act ? ' has-value' : '') +
                            '" onclick="vsOpenPicker(' + i + ')">' +
                            '<span class="vs-actbtn-label">' +
                                (act ? escapeHtml(act.name) : 'Choose activity') + '</span>' +
                            vsChevron(open) +
                        '</button>' +
                        '<div class="vs-req-target">' +
                            '<input class="pl-input" id="vsRowTarget' + i + '" type="number" min="1" max="999" ' +
                                'inputmode="numeric" value="' + r.targetCount + '" aria-label="Times" ' +
                                'onchange="vsTermsChanged()">' +
                            '<span class="vs-req-times">×</span>' +
                        '</div>' +
                    '</div>' +
                    (open
                        ? '<div class="vs-picker">' +
                              '<input class="pl-input vs-picker-search" id="vsActSearch" type="search" ' +
                                  'placeholder="Search activities" oninput="vsFilterActs(this.value)">' +
                              '<div class="vs-picker-list" id="vsActList">' +
                                  vsActListHtml(i, _vsDraft.pickerQuery) +
                              '</div>' +
                          '</div>'
                        : '') +
                '</div>';
            }).join('');
        }

        function vsAddReqBtnHtml() {
            return _vsDraft.rows.length < VS_MAX_REQS
                ? '<button type="button" class="vs-addreq" onclick="vsAddRow()">+ Add requirement</button>'
                : '';
        }

        function vsStakesHtml() {
            var bal = gritBalance();
            return vsStakes([
                { label: 'Pot',     value: (_vsDraft.stake * 2) + ' Grit', tone: 'gold' },
                { label: 'Bonus',   value: '+' + vsDraftBonusXP() + ' XP', tone: 'xp' },
                { label: 'Balance', value: bal + ' Grit', tone: bal < _vsDraft.stake ? 'short' : 'neutral' }
            ]);
        }

        // Rewrite only what changed. Falls back to a full mount if the form is
        // not on screen (the first render of the step, or after a close).
        function vsUpdateCreateForm() {
            var list = document.getElementById('vsReqList');
            if (!list) { vsRenderCreateForm(); return; }
            list.innerHTML = vsReqRowsHtml();
            var addWrap = document.getElementById('vsAddReqWrap');
            if (addWrap) addWrap.innerHTML = vsAddReqBtnHtml();
            var stakesHost = document.getElementById('vsStakesHost');
            if (stakesHost) stakesHost.innerHTML = vsStakesHtml();
            var send = document.getElementById('vsSendBtn');
            if (send) {
                var short = gritBalance() < _vsDraft.stake;
                send.disabled = short;
                if (short) send.title = 'Not enough Grit'; else send.removeAttribute('title');
            }
        }

        function vsRenderCreateForm() {
            var stakeOpts = '';
            for (var st = VS_STAKE_MIN; st <= VS_STAKE_MAX; st += VS_STAKE_STEP) {
                stakeOpts += '<option value="' + st + '"' + (_vsDraft.stake === st ? ' selected' : '') +
                             '>' + st + ' Grit</option>';
            }
            var short = gritBalance() < _vsDraft.stake;

            vsSheet(
                vsSheetHead('Challenge · ' + _vsDraft.opponentName, 'Set the terms') +
                '<div class="modal-body pl-modal-body ay-modal-body">' +
                    '<div class="ay-field"><label class="pl-field-label" for="vsName">Name</label>' +
                        '<input class="pl-input" id="vsName" placeholder="Two weeks of mornings" value="' +
                        escapeHtml(_vsDraft.name || '') + '"></div>' +
                    '<div class="ay-field"><label class="pl-field-label" for="vsDesc">Description</label>' +
                        '<textarea class="pl-input ay-textarea" rows="2" id="vsDesc" placeholder="Optional">' +
                        escapeHtml(_vsDraft.description || '') + '</textarea></div>' +

                    '<div class="ay-field"><label class="pl-field-label">Requirements</label>' +
                        '<div id="vsReqList">' + vsReqRowsHtml() + '</div>' +
                        '<div id="vsAddReqWrap">' + vsAddReqBtnHtml() + '</div>' +
                    '</div>' +

                    '<div class="vs-two">' +
                        '<div class="ay-field"><label class="pl-field-label" for="vsDuration">Days</label>' +
                            '<input class="pl-input" id="vsDuration" type="number" min="1" max="90" ' +
                            'inputmode="numeric" value="' + _vsDraft.durationDays + '"></div>' +
                        '<div class="ay-field"><label class="pl-field-label" for="vsStake">Stake each</label>' +
                            '<select class="pl-input" id="vsStake" onchange="vsTermsChanged()">' + stakeOpts +
                            '</select></div>' +
                    '</div>' +

                    '<div id="vsStakesHost">' + vsStakesHtml() + '</div>' +
                    '<p class="vs-note">Your stake is locked in when you send, and returned if they ' +
                    'decline or it expires. Only same-day completions count.</p>' +
                '</div>' +
                '<div class="modal-footer pl-modal-footer">' +
                    '<button class="vs-btn vs-btn-ghost" onclick="vsCloseSheet()">Cancel</button>' +
                    '<button class="vs-btn vs-btn-primary" id="vsSendBtn" onclick="vsSubmitCreate()"' +
                        (short ? ' disabled title="Not enough Grit"' : '') + '>Send</button>' +
                '</div>'
            );
        }

        window.vsSubmitCreate = async function () {
            vsReadCreateForm();
            var d = _vsDraft;
            if (!d) return;
            if (!d.name || !d.name.trim()) { showToast('Give the challenge a name.', 'red'); return; }
            var reqs = [];
            for (var i = 0; i < d.rows.length; i++) {
                var r = d.rows[i];
                if (!r.activityId) { showToast('Pick an activity for requirement ' + (i + 1) + '.', 'red'); return; }
                var act = gritFindActivity(r.activityId);
                if (!act) { showToast('That activity no longer exists.', 'red'); return; }
                reqs.push({
                    reqId: r.reqId,
                    targetCount: r.targetCount,
                    activityId: act.id,
                    activityName: act.name,
                    seed: vsActivitySeed(act)
                });
            }
            var btn = document.getElementById('vsSendBtn');
            if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
            try {
                await vsCreateChallenge({
                    opponentUid: d.opponentUid,
                    opponentName: d.opponentName,
                    name: d.name.trim(),
                    description: (d.description || '').trim(),
                    stake: d.stake,
                    durationDays: d.durationDays,
                    bonusXP: vsDraftBonusXP(),
                    requirements: reqs
                });
                vsCloseSheet();
                _vsDraft = null;
                showToast('Challenge sent — ' + d.stake + ' Grit escrowed.', 'blue');
                await vsFetch(true);
                vsPaint();
            } catch (e) {
                showToast(vsErrText(e), 'red');
                if (btn) { btn.disabled = false; btn.textContent = 'Send'; }
            }
        };

        // ── Accept walkthrough (§6, §7) ───────────────────────────────────
        // One requirement per screen: the ask in a sentence, then two ways to
        // answer it. There is no reject option on a requirement — rejecting one
        // is declining the challenge. Mapping work is kept in memory and in
        // userData, so it survives a reload and a shortfall does not throw it
        // away.

        let _vsAccept = null;

        window.vsOpenAccept = async function (id) {
            await vsFetch(false);
            var ch = vsCacheGet(id);
            if (!ch) { showToast('That challenge is gone.', 'red'); return; }
            if (ch.status !== 'pending') { showToast('That invite is no longer open.', 'red'); vsPaint(); return; }
            // A saved draft can outlive the activities it points at.
            var saved = ((window.userData && window.userData.vsDraftMappings) || {})[id] || {};
            var mapping = {};
            Object.keys(saved).forEach(function (reqId) {
                var a = gritFindActivity(saved[reqId] && saved[reqId].activityId);
                if (a) mapping[reqId] = { activityId: a.id, activityName: a.name };
            });
            _vsAccept = { id: id, step: 0, mapping: mapping, picking: false };
            vsRenderAcceptStep();
        };

        function vsPersistAcceptDraft() {
            if (!_vsAccept || !window.userData) return;
            if (!window.userData.vsDraftMappings) window.userData.vsDraftMappings = {};
            window.userData.vsDraftMappings[_vsAccept.id] = _vsAccept.mapping;
            debouncedSaveUserData();
        }

        function vsAcceptStepDots(reqs, i) {
            return '<div class="vs-stepdots">' + reqs.map(function (r, k) {
                return '<span class="vs-stepdot' + (k === i ? ' on' : '') +
                       (_vsAccept.mapping[r.reqId] ? ' done' : '') + '"></span>';
            }).join('') + '</div>';
        }

        // §7 — the receiver's mirror of the sender's stakes screen.
        function vsRenderAcceptReview(ch, reqs, uid) {
            var allMapped = reqs.every(function (r) { return _vsAccept.mapping[r.reqId]; });
            var bal   = gritBalance();
            var short = bal < ch.stake;
            var rows  = reqs.map(function (r, idx) {
                var m = _vsAccept.mapping[r.reqId];
                return '<div class="vs-review-row">' +
                    '<span class="vs-review-req">' + escapeHtml(vsReqName(ch, r)) + ' ×' + r.targetCount + '</span>' +
                    '<span class="vs-review-act">' + (m ? escapeHtml(m.activityName) : '—') + '</span>' +
                    '<button class="vs-review-edit" onclick="vsAcceptGoto(' + idx + ')">change</button>' +
                    '</div>';
            }).join('');

            vsSheet(
                vsSheetHead('Accepting · ' + vsName(ch, vsOther(ch, uid)), ch.name) +
                '<div class="modal-body pl-modal-body">' +
                    vsStakes([
                        { label: 'Your stake', value: ch.stake + ' Grit', tone: 'gold' },
                        { label: 'Bonus',      value: '+' + (ch.bonusXP || 1) + ' XP', tone: 'xp' },
                        { label: 'Balance',    value: bal + ' Grit', tone: short ? 'short' : 'neutral' }
                    ]) +
                    '<div class="vs-review-head">' + vsDurationText(ch.durationDays) +
                        ' · winner takes ' + (ch.stake * 2) + ' Grit</div>' +
                    '<div class="vs-review">' + rows + '</div>' +
                    (short
                        ? '<p class="vs-note vs-short">You are ' + (ch.stake - bal) +
                          ' Grit short. Your choices are saved.</p>'
                        : '<p class="vs-note">Only same-day completions count.</p>') +
                '</div>' +
                '<div class="modal-footer pl-modal-footer">' +
                    '<button class="vs-btn vs-btn-ghost" onclick="vsAcceptGoto(' + (reqs.length - 1) +
                        ')">Back</button>' +
                    '<button class="vs-btn vs-btn-primary" id="vsAcceptBtn" onclick="vsSubmitAccept()"' +
                        ((!allMapped || short) ? ' disabled' : '') + '>Accept · ' + ch.stake + ' Grit</button>' +
                '</div>'
            );
        }

        function vsRenderAcceptStep() {
            var ch = vsCacheGet(_vsAccept.id);
            if (!ch) { vsCloseSheet(); return; }
            var reqs = ch.requirements || [];
            var i = Math.min(_vsAccept.step, reqs.length);
            var uid = vsUid();

            if (i >= reqs.length) { vsRenderAcceptReview(ch, reqs, uid); return; }

            var req      = reqs[i];
            var reqLabel = vsReqName(ch, req);
            var chosen   = _vsAccept.mapping[req.reqId];
            var senderNm = vsName(ch, vsOther(ch, uid));

            var footer =
                '<div class="modal-footer pl-modal-footer">' +
                    (i > 0
                        ? '<button class="vs-btn vs-btn-ghost" onclick="vsAcceptGoto(' + (i - 1) + ')">Back</button>'
                        : '<button class="vs-btn vs-btn-ghost" onclick="vsCloseSheet()">Cancel</button>') +
                    '<button class="vs-btn vs-btn-primary" onclick="vsAcceptGoto(' + (i + 1) + ')"' +
                        (chosen ? '' : ' disabled') + '>' +
                        (i + 1 >= reqs.length ? 'Review' : 'Next') + '</button>' +
                '</div>';

            // Second state of the same step: the receiver's own activity list.
            if (_vsAccept.picking) {
                var committed = vsCommittedActivityIds(ch.id);
                var takenHere = Object.keys(_vsAccept.mapping)
                    .filter(function (k) { return k !== req.reqId; })
                    .map(function (k) { return _vsAccept.mapping[k].activityId; });
                var acts = gritAllActivities();
                var list = acts.map(function (a) {
                    var lock = committed.has(a.id) ? 'In another challenge'
                             : (takenHere.indexOf(a.id) !== -1 ? 'Used for another requirement' : null);
                    if (lock) {
                        return '<div class="vs-pickrow is-locked">' +
                               '<span class="vs-pickrow-name">' + escapeHtml(a.name) + '</span>' +
                               '<span class="vs-pickrow-why">' + escapeHtml(lock) + '</span></div>';
                    }
                    return '<button type="button" class="vs-pickrow' +
                           (chosen && chosen.activityId === a.id ? ' is-on' : '') +
                           '" onclick="vsMapExisting(\'' + a.id + '\')">' +
                           '<span class="vs-pickrow-name">' + escapeHtml(a.name) + '</span>' +
                           '<span class="vs-pickrow-xp">' + (a.baseXP || 0) + ' XP</span></button>';
                }).join('');

                vsSheet(
                    vsSheetHead('Requirement ' + (i + 1) + ' of ' + reqs.length, reqLabel) +
                    '<div class="modal-body pl-modal-body">' +
                        (acts.length
                            ? '<div class="vs-picker-list vs-picker-tall">' + list + '</div>'
                            : '<p class="vs-note">You have no activities yet.</p>') +
                    '</div>' +
                    '<div class="modal-footer pl-modal-footer">' +
                        '<button class="vs-btn vs-btn-ghost" onclick="vsClosePick()">Back</button>' +
                    '</div>'
                );
                return;
            }

            vsSheet(
                vsSheetHead('Requirement ' + (i + 1) + ' of ' + reqs.length, reqLabel) +
                '<div class="modal-body pl-modal-body">' +
                    vsAcceptStepDots(reqs, i) +
                    '<p class="vs-ask">' + escapeHtml(senderNm) + ' challenged you to perform <strong>' +
                        escapeHtml(reqLabel) + '</strong> <strong>' + req.targetCount + ' times</strong> in ' +
                        vsDurationText(ch.durationDays) + '.</p>' +
                    (chosen
                        ? '<div class="vs-chosen">Using <strong>' + escapeHtml(chosen.activityName) +
                          '</strong></div>'
                        : '') +
                    '<button class="vs-choice vs-choice-primary" onclick="vsCreateActivityFor()">' +
                        'Add to my activities</button>' +
                    '<button class="vs-choice" onclick="vsOpenPick()">' +
                        'Use one of my activities</button>' +
                '</div>' +
                footer
            );
        }

        window.vsAcceptGoto = function (step) {
            if (!_vsAccept) return;
            _vsAccept.step = Math.max(0, step);
            _vsAccept.picking = false;
            vsRenderAcceptStep();
        };

        window.vsOpenPick  = function () { if (_vsAccept) { _vsAccept.picking = true;  vsRenderAcceptStep(); } };
        window.vsClosePick = function () { if (_vsAccept) { _vsAccept.picking = false; vsRenderAcceptStep(); } };

        window.vsMapExisting = function (activityId) {
            var ch = vsCacheGet(_vsAccept.id);
            var req = (ch.requirements || [])[_vsAccept.step];
            var act = gritFindActivity(activityId);
            if (!req || !act) return;
            // An activity the receiver already owns keeps its own settings —
            // there is nothing to carry forward onto a configured activity.
            _vsAccept.mapping[req.reqId] = { activityId: act.id, activityName: act.name };
            vsPersistAcceptDraft();
            _vsAccept.picking = false;
            vsAcceptGoto(_vsAccept.step + 1);
        };

        // "Add to my activities" reuses the existing activity-creation path
        // exactly — same modal, same validation, same dimension/path prompts.
        // Nothing is forked. What is new is the seed (§6): the sender's
        // advanced settings, mirrored through the challenge document, are
        // pre-filled so a negative or repeatable habit crosses intact. The
        // receiver can still change anything before saving.
        window.vsCreateActivityFor = function () {
            var ch = vsCacheGet(_vsAccept.id);
            var req = (ch.requirements || [])[_vsAccept.step];
            if (!req) return;
            window._vsPendingCreate = {
                reqId: req.reqId,
                before: new Set(gritAllActivities().map(function (a) { return a.id; }))
            };
            vsCloseSheet();
            openActivityModal(null, null);
            vsSeedActivityModal(vsReqName(ch, req), req.seed);
        };

        // Pre-fills the activity modal from the seed the sender mirrored in.
        // Every write is guarded: an older challenge document has no seed, and
        // the modal must still open cleanly on its own defaults.
        function vsSeedActivityModal(name, seed) {
            var set = function (id, value) {
                var el = document.getElementById(id);
                if (el) el.value = value;
                return el;
            };
            set('activityName', name || '');
            if (!seed) return;
            try {
                if (seed.baseXP) { set('activityXP', seed.baseXP); syncActivityXPPreset(); }
                if (seed.frequency) { set('activityFrequency', seed.frequency); toggleCustomDays(); }

                var negOn = !!(seed.isNegative || seed.isSkipNegative);
                var negEl = document.getElementById('activityNegativeEnabled');
                if (negEl) negEl.checked = negOn;
                var negSec = document.getElementById('negativeXpSection');
                if (negSec) negSec.style.display = negOn ? 'flex' : 'none';
                if (negOn) {
                    var mode = seed.negativeXpMode || (seed.isNegative ? 'perform' : 'skip');
                    var modeEl = document.querySelector('input[name="negativeXpMode"][value="' + mode + '"]');
                    if (modeEl) modeEl.checked = true;
                }

                var multiEl = document.getElementById('activityAllowMultiple');
                if (multiEl) multiEl.checked = !!seed.allowMultiplePerDay;

                // Anything carried forward is an advanced setting by
                // definition — open the section so it is not a surprise.
                if ((negOn || seed.allowMultiplePerDay) && typeof setAdvancedSectionOpen === 'function') {
                    setAdvancedSectionOpen(true);
                }
            } catch (e) { console.warn('Versus: seeding the activity modal failed', e && e.message); }
        }

        window.vsSubmitAccept = async function () {
            var btn = document.getElementById('vsAcceptBtn');
            var label = btn ? btn.textContent : 'Accept';
            if (btn) { btn.disabled = true; btn.textContent = 'Staking…'; }
            try {
                await vsAcceptChallenge(_vsAccept.id, _vsAccept.mapping);
                if (window.userData && window.userData.vsDraftMappings) {
                    delete window.userData.vsDraftMappings[_vsAccept.id];
                    debouncedSaveUserData();
                }
                vsCloseSheet();
                _vsAccept = null;
                showToast('Challenge accepted — the pot is live.', 'blue');
                await vsFetch(true);
                vsPaint();
            } catch (e) {
                showToast(vsErrText(e), 'red');
                if (btn) { btn.disabled = false; btn.textContent = label; }
            }
        };

        // ── Forfeit confirmation (§6.2) ───────────────────────────────────
        window.vsConfirmForfeit = async function (id) {
            var ch = vsCacheGet(id);
            if (!ch) return;
            var uid = vsUid();
            if (!confirm('Forfeit "' + ch.name + '"? ' + vsName(ch, vsOther(ch, uid)) +
                         ' takes the whole ' + ch.pot + ' Grit pot. This cannot be undone.')) return;
            try {
                await vsForfeit(id, 'manual');
                showToast('Forfeited. The pot went to your opponent.', 'red');
                await vsRunMaintenance();
                vsPaint();
            } catch (e) { showToast(vsErrText(e), 'red'); }
        };

        // ── Hooks into existing flows ─────────────────────────────────────
        // Every one of these is a wrapper. No existing function is
        // restructured.

        // Completion → challenge progress. completeActivity is the LIVE path;
        // retroactiveComplete is deliberately not wrapped (§4.1 rule 4).
        (function () {
            var _orig = window.completeActivity;
            if (typeof _orig === 'function') {
                window.completeActivity = async function () {
                    var before = arguments;
                    var act = null;
                    try {
                        act = window.userData.dimensions[arguments[0]]
                                  .paths[arguments[1]].activities[arguments[2]];
                    } catch (e) {}
                    var countBefore = act ? (act.completionCount || 0) : null;
                    await _orig.apply(this, before);
                    // Only fire when a completion actually landed —
                    // completeActivity returns early on a blocked tap.
                    if (act && (act.completionCount || 0) > countBefore) {
                        vsOnCompletion(act.id).catch(function () {});
                    }
                };
            }
        })();

        (function () {
            var _orig = window.undoActivity;
            if (typeof _orig === 'function') {
                window.undoActivity = async function () {
                    var act = null;
                    try {
                        act = window.userData.dimensions[arguments[0]]
                                  .paths[arguments[1]].activities[arguments[2]];
                    } catch (e) {}
                    var countBefore = act ? (act.completionCount || 0) : null;
                    await _orig.apply(this, arguments);
                    if (act && (act.completionCount || 0) < countBefore) {
                        vsOnUndo(act.id).catch(function () {});
                    }
                };
            }
        })();

        // §6.2 — deleting an activity that is committed to a live wager
        // forfeits it. Say what it will cost BEFORE it happens, and only
        // actually forfeit once the activity is really gone: deleteActivity
        // runs its own confirm, and backing out there must not cost a pot.
        (function () {
            var _orig = window.deleteActivity;
            if (typeof _orig !== 'function') return;
            window.deleteActivity = async function (di, pi, ai) {
                var act = null;
                try { act = window.userData.dimensions[di].paths[pi].activities[ai]; } catch (e) {}
                var uid = vsUid();
                var hits = act ? _vsCache.list.filter(function (ch) {
                    if (ch.status !== 'active') return false;
                    var m = vsMappingOf(ch, uid);
                    return Object.keys(m).some(function (k) { return m[k].activityId === act.id; });
                }) : [];

                if (hits.length) {
                    var ch = hits[0];
                    if (!confirm('"' + act.name + '" is committed to the live challenge "' + ch.name +
                                 '". Deleting it forfeits the challenge — ' +
                                 vsName(ch, vsOther(ch, uid)) + ' takes the ' + ch.pot +
                                 ' Grit pot. Delete anyway?')) return;
                }

                var r = await _orig.call(this, di, pi, ai);

                if (!hits.length) return r;
                // The original asks for its own confirmation. If the activity
                // is still there, the user backed out — nothing is forfeited.
                if (gritFindActivity(act.id)) return r;
                for (var i = 0; i < hits.length; i++) {
                    try { await vsForfeit(hits[i].id, 'activity deleted'); } catch (e) {}
                }
                await vsRunMaintenance();
                vsRenderIfVisible();
                return r;
            };
        })();

        // The accept walkthrough's "add this to my activities" hands off to the
        // real activity modal. When it saves, pick up whichever activity is
        // new and map it to the requirement that asked for it.
        (function () {
            var _orig = window.saveActivity;
            if (typeof _orig !== 'function') return;
            window.saveActivity = async function (event) {
                // Claimed before the await: saveActivity closes the modal
                // itself, and the close wrapper must not read this as the user
                // backing out.
                var pending = window._vsPendingCreate;
                window._vsPendingCreate = null;
                await _orig.call(this, event);
                if (!pending) return;
                if (!_vsAccept) return;
                var fresh = gritAllActivities().filter(function (a) { return !pending.before.has(a.id); });
                if (!fresh.length) {
                    // Nothing was created (limit reached, or the form errored).
                    // Put the walkthrough back rather than leaving them nowhere.
                    vsRenderAcceptStep();
                    return;
                }
                var act = fresh[fresh.length - 1];
                _vsAccept.mapping[pending.reqId] = { activityId: act.id, activityName: act.name };
                vsPersistAcceptDraft();
                vsAcceptGoto(_vsAccept.step + 1);
            };
        })();

        // Backing out of the activity modal mid-walkthrough must not strand
        // the user: bring the accept sheet back where they left it.
        (function () {
            var _orig = window.closeActivityModal;
            if (typeof _orig !== 'function') return;
            window.closeActivityModal = function () {
                var wasPending = window._vsPendingCreate;
                var r = _orig.apply(this, arguments);
                if (wasPending && window._vsPendingCreate && _vsAccept) {
                    window._vsPendingCreate = null;
                    vsRenderAcceptStep();
                }
                return r;
            };
        })();

        // Versus is now the whole Challenges tab — there are no sub-tabs left
        // to switch between, so the tab itself is the render trigger. Leaving
        // it drops the detail listener (§5).
        (function () {
            var _orig = window.switchTab;
            if (typeof _orig !== 'function') return;
            window.switchTab = function (tabName) {
                if (tabName !== 'challenges') vsDetachDetail();
                var r = _orig.apply(this, arguments);
                if (tabName === 'challenges') { vsFetch(false).then(vsUpdateBadges).catch(function () {}); }
                return r;
            };
        })();

        // §3.2 / §3.4 / §6.3 — one fetch on login and on app foreground, which
        // drives the invite badge and the lazy expiry, resolution and payout
        // evaluation. The challenger's own client evaluates expiry here too, so
        // a refund is never gated on the opponent ever logging in again.
        function vsOnLogin() {
            _vsCache = { at: 0, list: [], uid: vsUid() };
            _vsSeenWritten = {};
            vsRunMaintenance().catch(function (e) {
                console.warn('Versus login pass failed:', e && e.message);
            });
        }
        window.vsOnLogin = vsOnLogin;

        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState !== 'visible') return;
            if (!vsUid()) return;
            if (vsNow() - _vsCache.at < VS_CACHE_TTL_MS) return;
            vsRunMaintenance().catch(function () {});
        });

        // ════════════════════════════════════════════════════════════════════
        // ══ END VERSUS CHALLENGES ═══════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════

        // ════════════════════════════════════════════════════════════════════
        // ══ SOCIAL GIFTING ══════════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // Peer-to-peer shields and double-XP. Self-contained: it reaches the
        // rest of the app through three hook points and nothing else.
        //
        //   predictCompletionXP()  — giftPeekFor(), side-effect free
        //   completeActivity()     — one call to giftOnCompletion()
        //   the login pass         — one call to giftOnLogin()
        //
        // Gifts live on the RECEIVER, because the receiver's device is what
        // consumes them:
        //
        //   users/{receiverUid}/gifts/{giftId}        the gift itself
        //   users/{senderUid}/giftsSent/{giftId}      the sender's mirror
        //
        // Both display names are denormalized at write time (invariant 4). No
        // read path anywhere below looks up a name — which keeps the
        // notification path free of cross-user reads, and keeps a name stable
        // if either side renames later.
        // ════════════════════════════════════════════════════════════════════

        const GIFT_TYPES = ['shield', 'xp_boost'];

        function giftUid() {
            return (window.currentUser && window.currentUser.uid) || null;
        }

        function giftMyName() {
            var p = (window.userData && window.userData.profile) || {};
            return p.username || (window.currentUser && window.currentUser.displayName) || 'A friend';
        }

        // Client-generated and stable across retries (invariant 3): a replayed
        // write lands on the same document id and can never make two gifts.
        function giftNewId() {
            return 'gf-' + Date.now().toString(36) + '-' +
                   Math.random().toString(36).slice(2, 10);
        }

        function giftCost(type) {
            return type === 'shield' ? GRIT_GIFT_SHIELD_COST : GRIT_GIFT_BOOST_COST;
        }

        function giftEsc(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        }

        // ── In-memory state ───────────────────────────────────────────────
        // _giftQueue is the receiver's pending xp_boost gifts, oldest first.
        // It exists only in memory and is NEVER rendered: an XP boost gift
        // produces no signal of any kind until it is consumed (invariant 5).
        let _giftQueue     = [];
        let _giftSentCache = [];
        let _giftSending   = false;
        let _giftInflight  = {};     // {type|receiverUid: giftId} — retry-stable
        let _giftInboxAt   = 0;      // last inbox drain, for the foreground throttle

        // ══════════════════════════════════════════════════════════════════
        //  SENDING (§3)
        // ══════════════════════════════════════════════════════════════════

        // The whole send, in the order §3.3 requires: refuse before spending,
        // spend and persist, and only then write the pair of documents. If the
        // pair fails, refund with a `correction` entry — Grit is never left
        // spent with no gift written (invariant 2).
        async function giftSend(type, receiverUid, receiverName) {
            var g = gritState();
            var me = giftUid();
            if (!g || !me) return { ok: false, message: 'Not signed in.' };
            if (GIFT_TYPES.indexOf(type) === -1) return { ok: false, message: 'Unknown gift.' };
            if (!receiverUid || receiverUid === me) return { ok: false, message: 'Pick a friend to send to.' };
            if (((window.userData.friends) || []).indexOf(receiverUid) === -1) {
                return { ok: false, message: 'You can only send gifts to someone on your friends list.' };
            }
            if (_giftSending) return { ok: false, message: 'Hold on — that gift is still going through.' };
            if (!canPersistUserData('giftSend')) return { ok: false, message: 'Not signed in.' };

            var cost = giftCost(type);
            if (g.balance < cost) {
                return { ok: false, message: 'You need ' + (cost - g.balance) + ' more Grit for that.' };
            }
            if (type === 'xp_boost' && gritGiftBoostsLeftThisMonth() <= 0) {
                return { ok: false, message: 'You have used all ' + GRIT_GIFT_BOOST_PER_MONTH +
                                             ' gifted double-XPs this month.' };
            }

            // One id per (type, receiver) attempt, reused until it succeeds.
            var key = type + '|' + receiverUid;
            var giftId = _giftInflight[key] || (_giftInflight[key] = giftNewId());

            var mk     = gritMonthKey();
            var reason = type === 'shield' ? 'gift_shield' : 'gift_xp_boost';
            var before = { balance: g.balance, lifetimeSpent: g.lifetimeSpent };
            var bufferMark = _gritLedgerBuffer.length;

            _giftSending = true;
            try {
                // 1–2. Spend, ledger, persist.
                gritApplyDelta(-cost, reason, {
                    item: type, receiverUid: receiverUid,
                    receiverName: receiverName || '', giftId: giftId
                });
                if (type === 'xp_boost') {
                    g.boostPurchases.push({ month: mk, at: new Date().toISOString(), kind: 'gift' });
                    if (g.boostPurchases.length > 24) g.boostPurchases = g.boostPurchases.slice(-24);
                }
                var saved = await gritPersist();
                if (!saved) {
                    // Nothing landed. Unwind the balance and the ledger entry
                    // so the record matches what actually happened: nothing.
                    if (type === 'xp_boost') giftDropBoostRecord(g, mk);
                    g.balance = before.balance;
                    g.lifetimeSpent = before.lifetimeSpent;
                    _gritLedgerBuffer.length = bufferMark;
                    gritRefreshUI();
                    return { ok: false, message: 'Could not save that. Nothing was spent.' };
                }

                // 3. Both documents, one batch. Never one without the other.
                var gift = {
                    id:                    giftId,
                    type:                  type,
                    senderUid:             me,
                    senderName:            giftMyName(),
                    receiverUid:           receiverUid,
                    receiverName:          receiverName || 'A friend',
                    sentAt:                new Date().toISOString(),
                    status:                'pending',
                    consumedAt:            null,
                    consumedActivityId:    null,
                    consumedActivityTitle: null,
                    baseXP:                null,
                    awardedXP:             null,
                    thanked:               false,
                    thankedAt:             null
                };
                try {
                    var batch = writeBatch(db);
                    batch.set(doc(db, 'users', receiverUid, 'gifts', giftId), gift);
                    batch.set(doc(db, 'users', me, 'giftsSent', giftId), gift);
                    await batch.commit();
                } catch (err) {
                    // 4. Refund. The spend is real and already persisted, so
                    // this is a correction in the record, not an unwind.
                    console.error('Gift write failed, refunding:', err);
                    gritApplyDelta(cost, 'correction', {
                        note: 'gift write failed; refunded', item: type,
                        receiverUid: receiverUid, giftId: giftId
                    });
                    if (type === 'xp_boost') giftDropBoostRecord(g, mk);
                    await gritPersist();
                    gritFlushLedger();
                    gritRefreshUI();
                    return { ok: false, message: 'That gift could not be delivered. Your Grit is back.' };
                }

                delete _giftInflight[key];
                _giftSentCache = [gift].concat(_giftSentCache);
                gritFlushLedger();
                gritRefreshUI();
                return { ok: true, gift: gift };
            } finally {
                _giftSending = false;
            }
        }
        window.giftSend = giftSend;

        // Removes the most recent gifted-boost record for this month — the
        // cap must not be spent by a purchase that did not happen.
        function giftDropBoostRecord(g, mk) {
            for (var i = g.boostPurchases.length - 1; i >= 0; i--) {
                var p = g.boostPurchases[i];
                if (p && p.month === mk && p.kind === 'gift') { g.boostPurchases.splice(i, 1); return; }
            }
        }

        // ══════════════════════════════════════════════════════════════════
        //  THE PICKER (§3.1)
        // ══════════════════════════════════════════════════════════════════
        // Two entry points, one flow: the Rewards shop opens it with a type
        // and no friend, a friend row opens it with a friend and no type.

        function giftCloseSheet() {
            var el = document.getElementById('giftSheet');
            if (el) el.remove();
        }
        window.giftCloseSheet = giftCloseSheet;

        function giftSheet(innerHtml) {
            // Same rule as vsSheet: moving between the gift picker's steps is a
            // state change, so it swaps contents rather than rebuilding the
            // .modal and replaying the slide-up.
            var open = document.getElementById('giftSheet');
            if (open && mkSwapSheetContents(open, innerHtml)) return open;
            giftCloseSheet();
            var el = document.createElement('div');
            el.id = 'giftSheet';
            el.className = 'modal-overlay gift-sheet-scrim active';
            el.addEventListener('click', function (e) { if (e.target === el) giftCloseSheet(); });
            el.innerHTML = '<div class="modal pl-modal gift-sheet">' + innerHtml + '</div>';
            document.body.appendChild(el);
            return el;
        }

        // Same head as the versus sheet, so the two bottom sheets in the app
        // are visibly the same component rather than two near-misses.
        function giftHeader(title, eyebrow) {
            return '<div class="modal-header pl-modal-header">' +
                     '<div>' +
                       (eyebrow ? '<div class="pl-modal-eyebrow">' + giftEsc(eyebrow) + '</div>' : '') +
                       '<h3 class="modal-title">' + giftEsc(title) + '</h3></div>' +
                     '<button class="pl-modal-close" type="button" onclick="giftCloseSheet()" aria-label="Close">' +
                     '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                     '</button></div>';
        }

        // The name written onto both gift documents comes from this cache, so
        // it has to be filled before a send — the Rewards shop can open the
        // picker in a session where the Friends tab was never rendered, and a
        // gift stamped "Adventurer" would be wrong forever (invariant 4).
        async function giftEnsureFriendNames() {
            var friends = (window.userData.friends || []);
            var cache = window._friendProfileCache || (window._friendProfileCache = {});
            var missing = friends.filter(function (u) { return !cache[u]; });
            if (!missing.length) return;
            await Promise.all(missing.map(async function (u) {
                try {
                    var snap = await getDoc(doc(db, 'publicProfiles', u));
                    if (snap.exists()) cache[u] = Object.assign({ uid: u }, snap.data());
                } catch (e) { /* an unreadable profile just stays unnamed */ }
            }));
        }

        // uid may be null (chose an item first), type may be null (chose a
        // friend first). Whichever is missing is asked for here.
        window.giftOpenPicker = async function (uid, type) {
            if (!giftUid()) return;
            var friends = (window.userData.friends || []);
            if (!friends.length) {
                showToast('Add a friend first — gifts go to people on your friends list.', 'olive');
                return;
            }
            await giftEnsureFriendNames();
            if (!uid) { giftRenderFriendStep(type); return; }
            giftRenderTypeStep(uid, type);
        };

        function giftRenderFriendStep(type) {
            var friends = (window.userData.friends || []);
            var rows = friends.map(function (u) {
                var p = (window._friendProfileCache || {})[u] || {};
                var name = p.displayName || 'Adventurer';
                return '<button type="button" class="gift-friend-row" ' +
                         'onclick="giftPickFriend(\'' + giftEsc(u) + '\',' +
                         (type ? '\'' + giftEsc(type) + '\'' : 'null') + ')">' +
                         '<span class="gift-friend-name">' + giftEsc(name) + '</span>' +
                         (p.level ? '<span class="gift-friend-lvl">Lv ' + p.level + '</span>' : '') +
                       '</button>';
            }).join('');
            giftSheet(giftHeader('Send to', 'A gift') +
                '<div class="modal-body pl-modal-body">' +
                  '<p class="gift-note">Gifts cost half what the same thing costs you.</p>' +
                  rows +
                '</div>');
        }

        window.giftPickFriend = function (uid, type) {
            giftRenderTypeStep(uid, type);
        };

        function giftFriendName(uid) {
            var p = (window._friendProfileCache || {})[uid] || {};
            return p.displayName || 'Adventurer';
        }

        function giftRenderTypeStep(uid, type) {
            var g = gritState();
            var bal = g ? g.balance : 0;
            var name = giftFriendName(uid);
            var giftBoostsLeft = gritGiftBoostsLeftThisMonth();

            function card(t, icon, title, sub, cost, blockedMsg) {
                var blocked = !!blockedMsg;
                return '<button type="button" class="gift-item' + (blocked ? ' is-blocked' : '') + '"' +
                         (blocked ? ' disabled' : '') +
                         ' onclick="giftConfirm(\'' + giftEsc(uid) + '\',\'' + t + '\')">' +
                         '<span class="gift-item-emoji">' + icon + '</span>' +
                         '<span class="gift-item-main">' +
                           '<span class="gift-item-name">' + giftEsc(title) + '</span>' +
                           '<span class="gift-item-sub">' + (blocked ? giftEsc(blockedMsg) : giftEsc(sub)) + '</span>' +
                         '</span>' +
                         '<span class="gift-item-cost">' + cost + '</span>' +
                       '</button>';
            }

            var shieldBlocked = bal < GRIT_GIFT_SHIELD_COST
                ? 'You need ' + (GRIT_GIFT_SHIELD_COST - bal) + ' more Grit.' : null;
            var boostBlocked  = giftBoostsLeft <= 0
                ? 'No gifted double-XP left this month.'
                : (bal < GRIT_GIFT_BOOST_COST
                    ? 'You need ' + (GRIT_GIFT_BOOST_COST - bal) + ' more Grit.' : null);

            var body =
                '<p class="gift-note">Sending to <strong>' + giftEsc(name) + '</strong> · ' +
                  'you have ' + bal.toLocaleString() + ' Grit</p>' +
                card('shield', phIcon('shield', { weight: 'fill' }), 'Streak shield',
                     'Drops straight into their pool. They are told you sent it.',
                     GRIT_GIFT_SHIELD_COST, shieldBlocked) +
                card('xp_boost', phIcon('lightning', { weight: 'fill' }), 'Double XP',
                     'A surprise. They find out when it lands on a completion. ' +
                     giftBoostsLeft + ' of ' + GRIT_GIFT_BOOST_PER_MONTH + ' left this month.',
                     GRIT_GIFT_BOOST_COST, boostBlocked);

            if (type === 'shield' || type === 'xp_boost') {
                // Came in from the shop with the item already chosen — confirm
                // straight away rather than asking twice.
                giftConfirm(uid, type);
                return;
            }
            giftSheet(giftHeader('Send a gift', 'Half price for a friend') +
                      '<div class="modal-body pl-modal-body">' + body + '</div>');
        }

        window.giftConfirm = function (uid, type) {
            var name = giftFriendName(uid);
            var cost = giftCost(type);
            var label = type === 'shield' ? 'a streak shield' : 'double XP';
            var self  = type === 'shield' ? GRIT_SHIELD_COST : GRIT_BOOST_COST;
            giftSheet(giftHeader('Confirm', 'A gift') +
                '<div class="modal-body pl-modal-body">' +
                  '<p class="gift-confirm-line">Send <strong>' + giftEsc(label) + '</strong> to ' +
                    '<strong>' + giftEsc(name) + '</strong> for <strong>' + cost + ' Grit</strong>?</p>' +
                  '<p class="gift-note">Half of the ' + self + ' it would cost you.' +
                    (type === 'xp_boost'
                      ? ' They get no notification — it reveals itself on their next completion.'
                      : '') + '</p>' +
                '</div>' +
                '<div class="modal-footer pl-modal-footer">' +
                  '<button type="button" class="pl-btn-ghost" onclick="giftCloseSheet()">Cancel</button>' +
                  '<button type="button" class="pl-btn-primary" id="giftSendBtn">Send</button>' +
                '</div>');
            var btn = document.getElementById('giftSendBtn');
            if (!btn) return;
            btn.addEventListener('click', async function () {
                // §3.3 — disabled between tap and resolution, so a double-tap
                // cannot start a second send.
                btn.disabled = true;
                btn.textContent = 'Sending…';
                var res = await giftSend(type, uid, name);
                giftCloseSheet();
                showToast(res.ok
                    ? (type === 'shield'
                        ? 'Shield sent to ' + name
                        : 'Double XP sent to ' + name + ' — they will not see it coming')
                    : res.message, res.ok ? 'green' : 'red',
                    null, res.ok ? (type === 'shield' ? 'shield' : 'lightning') : null);
                try { gritRenderRewards(); } catch (e) {}
                try { giftRenderSentList(); } catch (e) {}
            });
        };

        // ══════════════════════════════════════════════════════════════════
        //  RECEIVING (§4, §5.1)
        // ══════════════════════════════════════════════════════════════════

        async function giftFetchPending() {
            var me = giftUid();
            if (!me || !canPersistUserData('giftFetch')) return [];
            try {
                // One equality filter, no orderBy — served by the automatic
                // single-field index, so there is no composite index to deploy.
                // Ordering is done here; the volume is bounded by the friend cap.
                var snap = await getDocs(query(
                    collection(db, 'users', me, 'gifts'), where('status', '==', 'pending')));
                var out = [];
                snap.forEach(function (d) { out.push(d.data()); });
                out.sort(function (a, b) { return String(a.sentAt).localeCompare(String(b.sentAt)); });
                return out;
            } catch (e) {
                console.warn('Gift inbox read failed:', e && e.message);
                return [];
            }
        }

        // §4 — a gifted shield resolves immediately into the pool, exactly as a
        // self-purchased one does. Nothing distinguishes it once it is there.
        //
        // The gift is marked consumed BEFORE the pool is credited. That order
        // makes a mid-flight failure lose a shield rather than mint one: the
        // pool lives in userData, which the next save carries anyway, while a
        // gift left pending would be redeemed again on the next login.
        async function giftResolveShield(gift) {
            var me = giftUid();
            var g  = gritState();
            if (!me || !g) return false;
            var at = new Date().toISOString();
            try {
                await updateDoc(doc(db, 'users', me, 'gifts', gift.id), {
                    status: 'consumed', consumedAt: at
                });
            } catch (e) {
                console.warn('Could not claim gifted shield:', e && e.message);
                return false;
            }
            gift.consumedAt = at;
            g.shieldPool = (g.shieldPool || 0) + 1;
            gritLedgerWrite(0, g.balance, 'gift_received', {
                item: 'shield', giftId: gift.id,
                senderUid: gift.senderUid, senderName: gift.senderName
            });
            await gritPersist();
            gritFlushLedger();
            gritRefreshUI();
            showToast((gift.senderName || 'A friend') + ' sent you a shield.', 'green', null, 'shield');
            giftSyncMirror(gift, { thanked: false, thankedAt: null });
            return true;
        }

        // Reports the oldest pending xp_boost gift for this completion, or
        // null. Pure: it never mutates the queue, so the two calls a single
        // completion makes (preview, then award) always agree.
        function giftPeekFor(activity) {
            if (!_giftQueue.length) return null;
            if (!activity || typeof gritIsCountable !== 'function') return null;
            // Doubling a perform-mode negative would double a penalty.
            if (!gritIsCountable(activity)) return null;
            return _giftQueue[0];
        }
        window.giftPeekFor = giftPeekFor;

        // §5.1 — take exactly one gift, stamp it, and queue the reveal. The XP
        // has already been awarded by the caller; nothing here can change it.
        function giftOnCompletion(gift, activity, baseXP, awardedXP) {
            if (!gift || _giftQueue[0] !== gift) return;
            _giftQueue.shift();                       // gifts queue, never stack

            var me = giftUid();
            var at = new Date().toISOString();
            var patch = {
                status:                'consumed',
                consumedAt:            at,
                consumedActivityId:    activity.id || null,
                consumedActivityTitle: activity.name || null,
                baseXP:                baseXP,
                awardedXP:             awardedXP
            };
            Object.assign(gift, patch);

            if (me) {
                updateDoc(doc(db, 'users', me, 'gifts', gift.id), patch)
                    .catch(function (e) { console.warn('Gift consume write failed:', e && e.message); });
            }
            giftQueueReveal(gift);
        }
        window.giftOnCompletion = giftOnCompletion;

        // ══════════════════════════════════════════════════════════════════
        //  THE REVEAL (§5.2) AND THANKS (§5.3)
        // ══════════════════════════════════════════════════════════════════

        // If the same completion also levelled the user up, the level-up shows
        // first and the gift waits for it (§5.2). Polls rather than hooking the
        // level-up card's teardown, so no level-up path can forget to call us.
        function giftQueueReveal(gift, waited) {
            waited = waited || 0;
            var levelUpOpen = !!document.getElementById('levelUpToast');
            var rewardEl    = document.getElementById('rewardUnlockOverlay');
            var rewardOpen  = !!(rewardEl && rewardEl.style.display !== 'none' &&
                                 rewardEl.offsetParent !== null);
            if ((levelUpOpen || rewardOpen) && waited < 24000) {
                setTimeout(function () { giftQueueReveal(gift, waited + 400); }, 400);
                return;
            }
            giftShowReveal(gift);
        }

        function giftShowReveal(gift) {
            var existing = document.getElementById('giftRevealOverlay');
            if (existing) existing.remove();

            var overlay = document.createElement('div');
            overlay.id = 'giftRevealOverlay';
            overlay.className = 'level-up-overlay gift-reveal-overlay';
            overlay.setAttribute('role', 'dialog');
            overlay.setAttribute('aria-modal', 'true');

            var card = document.createElement('div');
            card.className = 'level-up-card gift-reveal-card';
            card.innerHTML =
                '<button type="button" class="level-up-close" aria-label="Dismiss" id="giftRevealClose">' +
                  '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
                  'stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">' +
                  '<line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                '</button>' +
                '<div class="level-up-eyebrow">A GIFT</div>' +
                '<div class="level-up-emoji">' + phIcon('lightning', { weight: 'fill', block: true }) + '</div>' +
                '<div class="gift-reveal-head">' + giftEsc(gift.senderName || 'A friend') +
                  ' sent you double XP</div>' +
                '<div class="gift-reveal-act">on ' +
                  giftEsc(gift.consumedActivityTitle || 'that completion') + '</div>' +
                '<div class="gift-reveal-xp">' +
                  '<span class="gift-reveal-base">' + (gift.baseXP || 0) + ' XP</span>' +
                  '<span class="gift-reveal-awarded">' + (gift.awardedXP || 0) + ' XP</span>' +
                '</div>' +
                '<div class="gift-reveal-actions">' +
                  '<button type="button" class="gift-thank-btn" id="giftThankBtn">Say thanks</button>' +
                  '<button type="button" class="gift-back-btn" id="giftBackBtn">Send one back</button>' +
                '</div>';

            overlay.appendChild(card);
            document.body.appendChild(overlay);

            // Dismissal is what settles the mirror — see giftSyncMirror. Every
            // exit path routes through here so the sender is told exactly once.
            var settled = false;
            function close(thanked) {
                if (settled) return;
                settled = true;
                giftSyncMirror(gift, thanked
                    ? { thanked: true, thankedAt: new Date().toISOString() }
                    : { thanked: false, thankedAt: null });
                overlay.classList.add('level-up-leaving');
                setTimeout(function () { overlay.remove(); }, 280);
            }

            document.getElementById('giftRevealClose').onclick = function () { close(false); };
            overlay.onclick = function (e) { if (e.target === overlay) close(false); };

            var thankBtn = document.getElementById('giftThankBtn');
            thankBtn.onclick = function () {
                // §5.3 — fixed shape, no text field, ever. The button disables
                // after the tap and does not come back.
                thankBtn.disabled = true;
                thankBtn.textContent = 'Thanks sent';
                thankBtn.classList.add('is-sent');
                close(true);
            };
            document.getElementById('giftBackBtn').onclick = function () {
                close(false);
                setTimeout(function () { giftOpenPicker(gift.senderUid); }, 200);
            };
        }

        // Writes the four fields the receiver is allowed to touch on the
        // sender's mirror, and marks our own copy synced so a session that
        // died before this point catches up on the next login. This single
        // write is what fires the sender's notification (§6), which is why
        // `thanked` is settled before it goes out — one write, one
        // notification, correct copy.
        async function giftSyncMirror(gift, thanks) {
            var me = giftUid();
            if (!me || !gift || !gift.senderUid) return;
            var patch = {
                status:     'consumed',
                consumedAt: gift.consumedAt || new Date().toISOString(),
                thanked:    !!thanks.thanked,
                thankedAt:  thanks.thankedAt || null
            };
            Object.assign(gift, { thanked: patch.thanked, thankedAt: patch.thankedAt });

            // Two writes, not one batch, and in this order on purpose. What the
            // user did is recorded on their OWN copy whatever happens to the
            // sender's tree — a mirror that has gone away (a deleted account, a
            // refused write) must not swallow the thanks as well. Only once the
            // mirror actually lands is the gift marked synced, so the login
            // catch-up knows what is still owed.
            try {
                await updateDoc(doc(db, 'users', me, 'gifts', gift.id), {
                    status: 'consumed', consumedAt: patch.consumedAt,
                    thanked: patch.thanked, thankedAt: patch.thankedAt
                });
            } catch (e) {
                console.warn('Gift thanks write failed:', e && e.message);
            }
            try {
                await updateDoc(doc(db, 'users', gift.senderUid, 'giftsSent', gift.id), patch);
                await updateDoc(doc(db, 'users', me, 'gifts', gift.id), { mirrorSynced: true });
            } catch (e) {
                console.warn('Gift mirror sync failed (will retry next login):', e && e.message);
            }
        }

        // Catch-up for a session that consumed a gift and then closed before
        // the reveal was dismissed. Without it the sender is never told.
        async function giftSyncOrphanedMirrors() {
            var me = giftUid();
            if (!me || !canPersistUserData('giftMirrorCatchup')) return;
            try {
                var snap = await getDocs(query(
                    collection(db, 'users', me, 'gifts'), where('status', '==', 'consumed')));
                var pending = [];
                snap.forEach(function (d) {
                    var v = d.data();
                    if (!v.mirrorSynced && v.type === 'xp_boost') pending.push(v);
                });
                for (var i = 0; i < pending.length; i++) {
                    await giftSyncMirror(pending[i], {
                        thanked: !!pending[i].thanked, thankedAt: pending[i].thankedAt || null
                    });
                }
            } catch (e) {
                console.warn('Gift mirror catch-up failed:', e && e.message);
            }
        }

        // ══════════════════════════════════════════════════════════════════
        //  THE SENDER'S OWN SENT LIST (§6)
        // ══════════════════════════════════════════════════════════════════
        // The only place a pending gift is ever visible, and only to the person
        // who sent it. Receivers see nothing here.

        async function giftFetchSent(max) {
            var me = giftUid();
            if (!me || !canPersistUserData('giftSentRead')) return [];
            try {
                var snap = await getDocs(query(
                    collection(db, 'users', me, 'giftsSent'),
                    orderBy('sentAt', 'desc'), limit(max || 15)));
                var out = [];
                snap.forEach(function (d) { out.push(d.data()); });
                return out;
            } catch (e) {
                console.warn('Sent-gift read failed:', e && e.message);
                return [];
            }
        }

        // The Friends tab shows the last five and nothing more. The list is a
        // reassurance that a gift landed, not a ledger — the full history is
        // not something anyone scrolls, and a long one pushed the invite box
        // off the bottom of the page.
        const GIFT_SENT_SHOWN = 5;

        async function giftRenderSentList() {
            var host = document.getElementById('friendsGiftsSent');
            if (!host) return;
            var list = await giftFetchSent(GIFT_SENT_SHOWN);
            _giftSentCache = list;
            if (!list.length) { host.innerHTML = ''; return; }
            host.innerHTML =
                '<div class="fr-section-kicker">Gifts sent</div>' +
                list.slice(0, GIFT_SENT_SHOWN).map(function (gf) {
                    var what = gf.type === 'shield'
                        ? phIcon('shield', { weight: 'fill', lead: true }) + 'Shield'
                        : phIcon('lightning', { weight: 'fill', lead: true }) + 'Double XP';
                    var state = gf.status === 'consumed'
                        ? (gf.type === 'shield' ? 'Received' :
                            (gf.thanked ? 'Used — they said thanks' : 'Used'))
                        : (gf.type === 'shield' ? 'On its way' : 'Waiting to land');
                    return '<div class="gift-sent-row">' +
                             '<span class="gift-sent-what">' + what + '</span>' +
                             '<span class="gift-sent-to">' + giftEsc(gf.receiverName || 'A friend') + '</span>' +
                             '<span class="gift-sent-state' +
                               (gf.status === 'consumed' ? ' is-done' : '') + '">' + state + '</span>' +
                           '</div>';
                }).join('');
        }
        window.giftRenderSentList = giftRenderSentList;

        // ══════════════════════════════════════════════════════════════════
        //  LOGIN PASS
        // ══════════════════════════════════════════════════════════════════

        async function giftRunInbox() {
            var pending = await giftFetchPending();
            var shields = pending.filter(function (gf) { return gf.type === 'shield'; });
            // §5.1 — oldest first, and only xp_boost gifts queue. The queue is
            // never rendered anywhere: no badge, no count, no hint (§3.4).
            _giftQueue = pending.filter(function (gf) { return gf.type === 'xp_boost'; });
            for (var i = 0; i < shields.length; i++) {
                await giftResolveShield(shields[i]);
            }
        }

        function giftOnLogin() {
            _giftQueue = [];
            _giftInflight = {};
            _giftInboxAt = Date.now();
            if (!giftUid()) return;
            giftRunInbox()
                .then(giftSyncOrphanedMirrors)
                .catch(function (e) { console.warn('Gift login pass failed:', e && e.message); });
        }
        window.giftOnLogin = giftOnLogin;

        // Foregrounding re-drains the inbox so a shield gifted while the app
        // was backgrounded lands without waiting for a fresh login. Throttled:
        // this is a Firestore read on every tab switch otherwise.
        const GIFT_INBOX_TTL_MS = 2 * 60 * 1000;
        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState !== 'visible') return;
            if (!giftUid()) return;
            if (Date.now() - _giftInboxAt < GIFT_INBOX_TTL_MS) return;
            _giftInboxAt = Date.now();
            giftRunInbox().catch(function () {});
        });

        // ════════════════════════════════════════════════════════════════════
        // ══ END SOCIAL GIFTING ══════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════

        // ════════════════════════════════════════════════════════════════════
        // ══ LEADERBOARD PAYOUTS ═════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // Leaderboards pay Grit weekly. No entry fee — charging admission
        // excludes exactly the people a leaderboard exists to re-engage.
        //
        // Every user curates their own board, so board size is under the
        // user's control and a naive "payout scales with size" rule is
        // trivially farmed. Two rules close that, and both are required:
        //
        //   ACTIVE   — a member counts only if they logged a completion during
        //              the scored week. Twenty dormant friends inflate nothing.
        //   MUTUAL   — a member counts only if you are on THEIR board too.
        //              One-sided stacking pays nothing.
        //
        // `scoredSize` is the count of members who are both, including the user
        // themselves. Every payout keys off it, never off raw membership
        // (invariant 12).
        //
        // Mutuality needs one user to be able to see another's board. That is
        // what `leaderboardBoards/{uid}` is for, and its read rule is the
        // mutuality test itself: you may read someone's board document only if
        // you appear on it. A denied read IS the "not mutual" answer, and
        // nothing about anyone's social graph leaks beyond that.
        //
        //   leaderboardBoards/{uid} = {
        //     uid, optIn, optInFrom,        // §8.7 — opt-in, effective Monday
        //     members: [uid],               // the live board
        //     scored:  [uid], scoredFrom,   // frozen at this week's Monday
        //     week: { anchor, xp, completions },   // the open week
        //     prev: { anchor, xp, completions },   // the last closed week
        //     displayName, photoURL, level, updatedAt }
        //
        // `prev` is what makes the payout race-free: a friend who opens the app
        // on Monday morning rolls their own week over, and the closed week's
        // figures have to survive that or nobody could ever score them.
        // ════════════════════════════════════════════════════════════════════

        const LB_PAY_MULT       = [3, 2, 1];   // §8.3 — 1st / 2nd / 3rd × scoredSize
        const LB_MIN_SIZE       = 3;           // §8.3 — below this, nothing pays
        const LB_THIRD_MIN_SIZE = 8;           // §8.3 — third of five is not an achievement
        const LB_PUBLISH_MS     = 5 * 60 * 1000;

        let _lbPublishedAt = 0;
        let _lbSettling    = false;

        function lbUid() { return (window.currentUser && window.currentUser.uid) || null; }

        function lbState() {
            if (!window.userData) return null;
            var lb = window.userData.leaderboard;
            if (!lb || typeof lb !== 'object') {
                lb = window.userData.leaderboard = { optIn: false, optInFrom: null, lastWeek: null, pub: null };
            }
            if (typeof lb.optIn !== 'boolean') lb.optIn = false;
            return lb;
        }

        function lbShiftAnchor(anchorStr, days) {
            var d = new Date(anchorStr + 'T00:00:00');
            d.setDate(d.getDate() + days);
            return toLocalDateStr(d);
        }

        // The Monday that opens the week AFTER this one. §8.7 — opting in
        // mid-week takes effect here, so nobody joins after seeing they'd win.
        function lbNextAnchorStr() {
            return lbShiftAnchor(getLeaderboardWeekStartStr(), 7);
        }

        // The most recent CLOSED week. §8.5 — only ever this one is paid, the
        // same rule the weekly completion bonus follows.
        function lbClosedAnchorStr() {
            return lbShiftAnchor(getLeaderboardWeekStartStr(), -7);
        }

        function lbOrdinal(n) {
            return n === 1 ? '1st' : n === 2 ? '2nd' : n === 3 ? '3rd' : n + 'th';
        }
        function gritOrdinal(n) { return lbOrdinal(n); }
        window.gritOrdinal = gritOrdinal;

        // The live board: every friend not explicitly taken off it.
        function lbBoardMembers() {
            var hidden = window.userData.leaderboardHidden || [];
            return (window.userData.friends || []).filter(function (u) { return hidden.indexOf(u) === -1; });
        }
        window.lbBoardMembers = lbBoardMembers;

        // Exact figures for any week, straight from this user's own history.
        // Only other people's numbers need the published snapshot.
        function lbMyWeek(anchor) {
            var end = lbShiftAnchor(anchor, 7);
            var xp = 0, n = 0;
            (window.userData.dimensions || []).forEach(function (dim) {
                (dim.paths || []).forEach(function (path) {
                    (path.activities || []).forEach(function (act) {
                        (act.completionHistory || []).forEach(function (e) {
                            if (e.isPenalty || !e.date) return;
                            var d = toLocalDateStr(new Date(e.date));
                            if (d >= anchor && d < end) { xp += (e.xp || 0); n++; }
                        });
                    });
                });
            });
            return { anchor: anchor, xp: xp, completions: n };
        }

        // ── Publishing (§8.1, §8.7) ───────────────────────────────────────
        // Written only while opted in. A user who has not opted in publishes
        // nothing, appears in nobody's scoredSize and cannot place — their
        // ranking display is untouched, they are simply outside the payouts.
        async function lbPublishBoard(force) {
            var me = lbUid();
            var st = lbState();
            if (!me || !st || !canPersistUserData('lbPublish')) return;
            if (!st.optIn) return;
            var now = Date.now();
            if (!force && now - _lbPublishedAt < LB_PUBLISH_MS) return;

            var anchor  = getLeaderboardWeekStartStr();
            var members = lbBoardMembers();
            var pub     = st.pub && typeof st.pub === 'object' ? st.pub : {};

            // Roll the open week into `prev` the first time we touch a new one,
            // so last week's figures survive for anyone still scoring them.
            if (pub.week && pub.week.anchor && pub.week.anchor !== anchor) pub.prev = pub.week;
            pub.week = lbMyWeek(anchor);

            // §8.1 / open question 7 — the SCORED roster is frozen at the
            // week's Monday. Adding or removing someone mid-week changes the
            // live board immediately but cannot change who is being scored, so
            // nobody trims their board after seeing who is ahead.
            if (pub.scoredFrom !== anchor) {
                // The roster that was frozen for the week just closed has to
                // survive this roll — it is what settlement scores against,
                // and what everyone else's settlement tests mutuality against.
                if (pub.scored) { pub.prevScored = pub.scored; pub.prevScoredFrom = pub.scoredFrom || null; }
                pub.scored = members.slice();
                pub.scoredFrom = anchor;
            }

            st.pub = pub;
            var profile = (window.userData.profile) || {};
            var payload = {
                uid:         me,
                optIn:       true,
                optInFrom:   st.optInFrom || null,
                members:     members,
                scored:      pub.scored || [],
                scoredFrom:  pub.scoredFrom || anchor,
                prevScored:  pub.prevScored || [],
                prevScoredFrom: pub.prevScoredFrom || null,
                week:        pub.week,
                prev:        pub.prev || null,
                displayName: profile.username || (window.currentUser && window.currentUser.displayName) || 'Adventurer',
                photoURL:    (window.currentUser && window.currentUser.photoURL) || null,
                level:       window.userData.level || 1,
                updatedAt:   new Date().toISOString()
            };
            try {
                await setDoc(doc(db, 'leaderboardBoards', me), payload);
                _lbPublishedAt = now;
            } catch (e) {
                console.warn('Leaderboard board publish failed:', e && e.message);
            }
        }
        window.lbPublishBoard = lbPublishBoard;

        // A denied read is not an error here — it is the answer "you are not on
        // their board", which is exactly what mutuality asks.
        async function lbReadBoard(uid) {
            try {
                var snap = await getDoc(doc(db, 'leaderboardBoards', uid));
                return snap.exists() ? snap.data() : null;
            } catch (e) {
                return null;
            }
        }

        // The board roster as it stood at the START of `anchor`. Works on
        // either shape — this user's own `pub` or a published board document —
        // because they carry the same three fields. Falls back to the live
        // members list only when neither snapshot covers the week asked for.
        function lbRosterFor(board, anchor) {
            if (!board) return [];
            if (board.prevScoredFrom === anchor && board.prevScored) return board.prevScored.slice();
            if (board.scoredFrom === anchor && board.scored) return board.scored.slice();
            return (board.members || board.scored || []).slice();
        }

        // ── Payout arithmetic (§8.3) ──────────────────────────────────────
        function lbPayForPosition(pos, scoredSize) {
            if (scoredSize < LB_MIN_SIZE) return 0;
            if (pos === 3 && scoredSize < LB_THIRD_MIN_SIZE) return 0;
            var mult = LB_PAY_MULT[pos - 1];
            return mult ? mult * scoredSize : 0;
        }

        // Rows in, ranked rows out. Ties split the combined payout of the
        // positions they occupy, rounded down, remainder discarded (§8.2).
        function lbRank(rows, scoredSize) {
            var sorted = rows.slice().sort(function (a, b) { return b.xp - a.xp; });
            var out = [], i = 0;
            while (i < sorted.length) {
                var j = i;
                while (j + 1 < sorted.length && sorted[j + 1].xp === sorted[i].xp) j++;
                var tiedCount = j - i + 1;
                var pot = 0;
                for (var p = i + 1; p <= j + 1; p++) pot += lbPayForPosition(p, scoredSize);
                var each = Math.floor(pot / tiedCount);
                for (var k = i; k <= j; k++) {
                    out.push(Object.assign({}, sorted[k], { place: i + 1, grit: each }));
                }
                i = j + 1;
            }
            return out;
        }
        window.lbRank = lbRank;

        // ── Settlement (§8.5) ─────────────────────────────────────────────
        // Runs on the same Monday rollover that reconciles the weekly
        // completion bonus. Ranking happens on the client, so the idempotency
        // marker is the ONLY thing standing between one payout and one payout
        // per device. It is load-bearing: set it before the award, always.
        async function lbSettleClosedWeek() {
            var g  = gritState();
            var st = lbState();
            var me = lbUid();
            if (!g || !st || !me || _lbSettling) return;
            if (!canPersistUserData('lbSettle')) return;

            var closed = lbClosedAnchorStr();
            var marker = 'leaderboard:' + closed;
            if (g.awarded[marker]) return;

            // Not opted in for that week — nothing to settle, and nothing to
            // mark: eligibility for a week already closed can never change.
            if (!st.optIn || !st.optInFrom || st.optInFrom > closed) return;

            _lbSettling = true;
            try {
                var mine   = lbMyWeek(closed);
                var roster = lbRosterFor(st.pub, closed);
                var rows   = [];

                for (var i = 0; i < roster.length; i++) {
                    var b = await lbReadBoard(roster[i]);
                    if (!b) continue;                                        // not mutual, or not opted in
                    if (b.optIn !== true) continue;
                    if (!b.optInFrom || b.optInFrom > closed) continue;      // outside the payout system
                    if (lbRosterFor(b, closed).indexOf(me) === -1) continue; // one-sided — pays nothing
                    var w = (b.prev && b.prev.anchor === closed) ? b.prev
                          : (b.week && b.week.anchor === closed) ? b.week : null;
                    if (!w || !(w.completions > 0)) continue;                // dormant — inflates nothing
                    rows.push({ uid: roster[i], name: b.displayName || 'Adventurer', xp: w.xp || 0 });
                }
                if (mine.completions > 0) {
                    rows.push({ uid: me, name: giftMyName(), xp: mine.xp, isMe: true });
                }

                var scoredSize = rows.length;
                var ranked     = lbRank(rows, scoredSize);
                var mineRow    = ranked.filter(function (r) { return r.uid === me; })[0] || null;
                var grit       = mineRow ? mineRow.grit : 0;

                g.awarded[marker] = true;
                st.lastWeek = {
                    anchor: closed, scoredSize: scoredSize,
                    place: mineRow ? mineRow.place : null, grit: grit,
                    rows: ranked.slice(0, 10).map(function (r) {
                        return { uid: r.uid, name: r.name, xp: r.xp, place: r.place, grit: r.grit };
                    })
                };

                if (grit > 0) {
                    gritApplyDelta(grit, 'leaderboard_payout', {
                        anchor: closed, place: mineRow.place, scoredSize: scoredSize
                    });
                    gritFlushLedger();
                }
                await saveUserData();
                gritRefreshUI();

                if (grit > 0) {
                    showToast(lbOrdinal(mineRow.place) + ' place this week — ' + grit + ' Grit',
                              'green', function () { lbShowStandings(); });
                }
            } catch (e) {
                console.warn('Leaderboard settlement failed:', e && e.message);
            } finally {
                _lbSettling = false;
            }
        }

        // ── Final standings (§8.6) ────────────────────────────────────────
        window.lbShowStandings = function () {
            var st = lbState();
            var lw = st && st.lastWeek;
            if (!lw) return;
            var body = !lw.rows.length
                ? '<p class="gift-note">Nobody on your board logged anything that week.</p>'
                : lw.rows.map(function (r) {
                    return '<div class="lb-standing-row' + (r.uid === lbUid() ? ' is-me' : '') + '">' +
                             '<span class="lb-standing-place">' + lbOrdinal(r.place) + '</span>' +
                             '<span class="lb-standing-name">' + giftEsc(r.name) + '</span>' +
                             '<span class="lb-standing-xp">' + (r.xp || 0).toLocaleString() + ' XP</span>' +
                             '<span class="lb-standing-grit">' + (r.grit ? '+' + r.grit : '—') + '</span>' +
                           '</div>';
                  }).join('');
            giftSheet(giftHeader('Week of ' + lw.anchor, 'Final standings') +
                '<div class="modal-body pl-modal-body">' +
                  '<p class="gift-note">' + lw.scoredSize + ' scored ' +
                    (lw.scoredSize === 1 ? 'member' : 'members') +
                    ' — mutual and active. Payouts key off that number, not board size.</p>' +
                  body +
                '</div>');
        };

        // ── Opt-in (§8.7) ─────────────────────────────────────────────────
        window.lbToggleOptIn = async function () {
            var st = lbState();
            if (!st) return;
            if (st.optIn) {
                st.optIn = false;
                st.optInFrom = null;
                showToast('You are out of leaderboard payouts.', 'olive');
                try { await deleteDoc(doc(db, 'leaderboardBoards', lbUid())); } catch (e) {}
            } else {
                st.optIn = true;
                // Effective from the FOLLOWING Monday — a user cannot join
                // after seeing they would have won this week.
                st.optInFrom = lbNextAnchorStr();
                showToast('You are in — payouts start Monday ' + st.optInFrom + '.', 'green');
            }
            await saveUserData();
            await lbPublishBoard(true);
            try { lbRenderPayoutSection(); } catch (e) {}
        };

        // ── The Leaderboards tab panel (§8.6, §8.7) ───────────────────────
        // The Leaderboards tab is where a board is EDITED. The Friends tab
        // shows people and sends them things; it carries no board control at
        // all, so there is exactly one place a roster can change and no way to
        // reshape your own ranking by accident while browsing.
        //
        // No projected payout mid-week: scoredSize moves as members become
        // active, and a number that drops on Sunday reads as the app taking
        // something away.

        // The opt-in explainer is collapsed by default — the card only needs
        // to say whether you are in and let you change it. Kept in memory, not
        // in userData: it is a reading position, not a preference.
        let _lbOptInOpen = false;
        window.lbToggleOptInInfo = function () {
            _lbOptInOpen = !_lbOptInOpen;
            var card = document.getElementById('lbOptInCard');
            var body = document.getElementById('lbOptInBody');
            var chev = document.getElementById('lbOptInChev');
            if (body) body.hidden = !_lbOptInOpen;
            if (card) card.classList.toggle('is-open', _lbOptInOpen);
            if (chev) {
                chev.classList.toggle('is-open', _lbOptInOpen);
                chev.setAttribute('aria-expanded', String(_lbOptInOpen));
            }
        };

        function lbBoardCountText() {
            var friends = (window.userData.friends || []);
            var hidden  = (window.userData.leaderboardHidden || []);
            var on = friends.filter(function (u) { return hidden.indexOf(u) === -1; }).length;
            return on + ' of ' + friends.length + ' on your board';
        }

        // One roster row, rendered from the same helper the repaint uses, so a
        // toggle can rewrite a single row rather than the whole panel.
        function lbRosterRowHtml(uid, entry) {
            var on = (window.userData.leaderboardHidden || []).indexOf(uid) === -1;
            var e  = entry || {};
            var meta = 'Lv ' + (e.level || 1) + (e.characterTitle ? ' · ' + e.characterTitle : '');
            return '<button type="button" class="lb-roster-row' + (on ? ' is-on' : '') + '" ' +
                     'data-uid="' + giftEsc(uid) + '" role="switch" aria-checked="' + on + '" ' +
                     'aria-label="' + (on ? 'Remove ' : 'Add ') + giftEsc(e.displayName || 'this friend') +
                       (on ? ' from' : ' to') + ' your leaderboard" ' +
                     'onclick="toggleLeaderboardVisibility(\'' + giftEsc(uid) + '\')">' +
                     lbRosterAvatar(e) +
                     '<span class="lb-roster-info">' +
                       '<span class="lb-roster-name">' + giftEsc(e.displayName || 'Adventurer') + '</span>' +
                       '<span class="lb-roster-meta">' + giftEsc(meta) + '</span>' +
                     '</span>' +
                     '<span class="lb-roster-switch"><span class="lb-roster-knob"></span></span>' +
                   '</button>';
        }

        function lbRosterAvatar(e) {
            if (e && e.photoURL) {
                return '<img class="lb-roster-av" src="' + giftEsc(e.photoURL) + '" alt="">';
            }
            var initial = String((e && e.displayName) || '?').trim().charAt(0).toUpperCase() || '?';
            return '<span class="lb-roster-av lb-roster-av-initial">' + giftEsc(initial) + '</span>';
        }

        // Repaint exactly what a board toggle changes: the one row in the
        // editor and its count. The ranking behind the sheet is repainted by
        // the caller. Rebuilding the sheet would scroll it back to the top.
        window.lbSyncRosterRow = function (uid) {
            var sel = '.lb-roster-row[data-uid="' + (window.CSS && CSS.escape ? CSS.escape(uid) : uid) + '"]';
            var row = document.querySelector(sel);
            if (row) {
                var entry = (window._frEntries || []).filter(function (x) { return x.uid === uid; })[0];
                row.outerHTML = lbRosterRowHtml(uid, entry);
            }
            var count = document.getElementById('lbBoardCount');
            if (count) count.textContent = lbBoardCountText();
        };

        // ── The board editor (the pencil beside the metric tabs) ──────────
        // Everyone you add is on your board from the moment you add them, so
        // this is a correction, not a setup step: it opens on demand and it
        // does not sit under the ranking as a second list of the same names.
        window.lbCloseBoardEditor = function () {
            var el = document.getElementById('lbBoardSheet');
            if (el) el.remove();
        };

        window.lbOpenBoardEditor = function () {
            if (!window.userData) return;
            var friends = (window.userData.friends || []);
            var entries = window._frEntries || [];
            var body;
            if (!friends.length) {
                body = '<div class="lb-board-empty">' +
                         '<p>Your board is built from your friends. Add someone and they join it automatically.</p>' +
                         '<button type="button" class="lb-board-cta" ' +
                           'onclick="lbCloseBoardEditor();switchTab(\'people\')">Go to Friends</button>' +
                       '</div>';
            } else {
                body = '<div class="lb-roster" id="lbRoster">' +
                         friends.map(function (u) {
                             var e = entries.filter(function (x) { return x.uid === u; })[0];
                             return lbRosterRowHtml(u, e);
                         }).join('') +
                       '</div>' +
                       '<p class="lb-board-note">Taking someone off hides them from your ranking. ' +
                         'It reaches the scored roster next Monday.</p>';
            }

            lbCloseBoardEditor();
            var el = document.createElement('div');
            el.id = 'lbBoardSheet';
            el.className = 'modal-overlay gift-sheet-scrim active';
            el.addEventListener('click', function (ev) { if (ev.target === el) lbCloseBoardEditor(); });
            el.innerHTML =
                '<div class="modal pl-modal gift-sheet">' +
                  '<div class="modal-header pl-modal-header">' +
                    '<div><div class="pl-modal-eyebrow">Leaderboard</div>' +
                    '<h3 class="modal-title">Your board</h3></div>' +
                    '<button class="pl-modal-close" type="button" onclick="lbCloseBoardEditor()" aria-label="Close">' +
                    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                    '</button>' +
                  '</div>' +
                  '<div class="modal-body pl-modal-body">' +
                    '<div class="lb-board-count-row"><span class="lb-board-count" id="lbBoardCount">' +
                      lbBoardCountText() + '</span></div>' +
                    body +
                  '</div>' +
                '</div>';
            document.body.appendChild(el);
        };

        function lbRenderPayoutSection() {
            var host = document.getElementById('lbPayoutSection');
            if (!host) return;
            var st = lbState();
            if (!st) { host.innerHTML = ''; return; }

            var anchor  = getLeaderboardWeekStartStr();
            var pending = st.optIn && st.optInFrom && st.optInFrom > anchor;
            var html = '';

            // §8.6 — say plainly that the standings above are not settled.
            if (st.optIn && !pending) {
                html += '<p class="lb-provisional">Standings for the week of ' + giftEsc(anchor) +
                        ' are provisional until Monday.</p>';
            }

            if (st.lastWeek) {
                var lw = st.lastWeek;
                var line = lw.place
                    ? lbOrdinal(lw.place) + ' place · ' + (lw.grit ? '+' + lw.grit + ' Grit' : 'no payout')
                    : 'You were not scored';
                html += '<button type="button" class="lb-last-card" onclick="lbShowStandings()">' +
                          '<span class="lb-last-kicker">Week of ' + giftEsc(lw.anchor) + '</span>' +
                          '<span class="lb-last-line">' + giftEsc(line) + '</span>' +
                          '<span class="lb-last-sub">' + lw.scoredSize + ' scored ' +
                            (lw.scoredSize === 1 ? 'member' : 'members') + ' — tap for the standings</span>' +
                        '</button>';
            }

            // ── Opt-in: one line and a button, with the rules behind a chevron ──
            var oneLiner = st.optIn
                ? (pending ? 'In from Monday ' + giftEsc(st.optInFrom) + '.'
                           : 'You are in. Top three paid every Monday.')
                : 'Not enrolled. Opt in to be paid for placing.';
            html += '<div class="lb-optin-card' + (_lbOptInOpen ? ' is-open' : '') + '" id="lbOptInCard">' +
                      '<div class="lb-optin-head">' +
                        '<div class="lb-optin-main">' +
                          '<div class="lb-optin-title">Weekly payouts</div>' +
                          '<div class="lb-optin-line">' + oneLiner + '</div>' +
                        '</div>' +
                        '<button type="button" class="lb-optin-btn' + (st.optIn ? ' is-on' : '') + '" ' +
                          'onclick="lbToggleOptIn()">' + (st.optIn ? 'Opt out' : 'Opt in') + '</button>' +
                        '<button type="button" class="lb-optin-chev' + (_lbOptInOpen ? ' is-open' : '') + '" ' +
                          'id="lbOptInChev" aria-expanded="' + _lbOptInOpen + '" aria-controls="lbOptInBody" ' +
                          'aria-label="How weekly payouts work" onclick="lbToggleOptInInfo()">' +
                          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" ' +
                          'stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
                        '</button>' +
                      '</div>' +
                      '<div class="lb-optin-body" id="lbOptInBody"' + (_lbOptInOpen ? '' : ' hidden') + '>' +
                        '<ul class="lb-optin-rules">' +
                          '<li>Nobody is enrolled by default, and joining takes effect the following Monday — so you cannot join after seeing you would have won.</li>' +
                          '<li>First, second and third are paid. The amount scales with how many of your board were <strong>mutual</strong> (they have you on theirs) and <strong>active</strong> (they logged something that week).</li>' +
                          '<li>Below three scored members, nothing pays.</li>' +
                          '<li>Standings during the week are provisional. They settle on Monday.</li>' +
                        '</ul>' +
                      '</div>' +
                    '</div>';

            host.innerHTML = html;
        }
        window.lbRenderPayoutSection = lbRenderPayoutSection;

        function lbOnLogin() {
            if (!lbUid()) return;
            lbPublishBoard(true)
                .then(lbSettleClosedWeek)
                .catch(function (e) { console.warn('Leaderboard login pass failed:', e && e.message); });
        }
        window.lbOnLogin = lbOnLogin;

        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState !== 'visible') return;
            if (!lbUid()) return;
            lbPublishBoard(false).then(lbSettleClosedWeek).catch(function () {});
        });

        // ════════════════════════════════════════════════════════════════════
        // ══ END LEADERBOARD PAYOUTS ═════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════

        // ════════════════════════════════════════════════════════════════════
        // ══ MODES ═══════════════════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
        //
        // Seven opt-in modes, living on Pursuits › Modes. Exactly ONE may be
        // active per user at a time (multi-mode is deferred), so `modes.active`
        // is a single object rather than a list. The shape is still keyed by
        // `kind` throughout, which is what a future concurrency change would
        // need — nothing below assumes there can only ever be one beyond the
        // single activation guard in modesActivate().
        //
        // STATE
        //   window.userData.modes = {
        //     schemaVersion, active, pending[], history[],
        //     suspendedHabit, streakOffsets{}, seenHabitOverlay
        //   }
        //   It rides saveUserData()'s full-document write like every other
        //   field on the user doc. Pact is the one exception: two accounts
        //   have to read the same record, so it lives in a top-level `pacts`
        //   collection, exactly as Versus Challenges does.
        //
        // HOOKS INTO THE REST OF THE APP — all of them wrappers or single
        // calls; no core function is restructured:
        //   processStreakPauses()  → modesBeforeStreakWalk() / modesAfterStreakWalk()
        //   completeActivity()     → modesOnCompletion(activity)
        //   undoActivity()         → modesOnUndo(activity)
        //   login                  → modesOnLogin()
        //   nav (index.html)       → modesOpenPage()
        //
        // THE STREAK CONSTRAINT (Recovery + Insurance)
        //   processStreakSystem() is the single authoritative writer for
        //   streak/shield state and it RE-DERIVES both from completionHistory
        //   on every login. Nothing below branches into it, adds a condition
        //   to it, or reads its internals. Both modes that touch streaks work
        //   the same additive way: the walk runs untouched and produces a base
        //   figure, and then a separate pass adds a stored, mode-owned offset
        //   on top. The offsets live in `modes`, never on the activity — so a
        //   mode being deleted, expired or migrated away can never leave a
        //   number behind on an activity that nothing owns.
        // ════════════════════════════════════════════════════════════════════

        const MODES_SCHEMA_VERSION = 1;
        const MODE_KINDS = ['habit', 'berserk', 'recovery', 'insurance', 'stake', 'pact', 'focus'];

        // ── Rate card ─────────────────────────────────────────────────────
        // Entry costs are one-way: activating spends, and nothing in a mode's
        // lifecycle refunds an entry cost. Stake and Pact are different — what
        // they take is a WAGER, escrowed and returned with a bonus on success.
        const MODE_COST = {
            habit:     30,
            berserk:   40,
            insurance: 20,
            recovery:  15,
            focus:     25
        };
        const MODE_WAGER_MIN   = 25;    // Stake mode, in steps of 25
        const MODE_WAGER_MAX   = 100;
        const MODE_WAGER_STEP  = 25;
        const MODE_WAGER_RETURN = 0.30; // Stake + Pact: stake back, plus 30%
        const PACT_WAGER       = 40;    // fixed per person

        const BERSERK_MIN_HOURS   = 1;
        const BERSERK_MAX_HOURS   = 5;
        const BERSERK_SWING       = 0.30;  // ±30% on the session's XP
        const BERSERK_DAMPENER    = 0.22;  // fraction of the above-baseline part that counts
        const BERSERK_FLOOR_PER_H = 40;    // so a brand-new account still gets a real target

        const HABIT_DEFAULT_DAYS  = 33;
        const HABIT_MIN_DAYS      = 7;
        const HABIT_MAX_DAYS      = 120;
        const HABIT_MAX_ACTS      = 3;
        const HABIT_RESUME_DAYS   = 7;     // off longer than this and it starts fresh
        const HABIT_OVERLAY_LEAD  = 30;    // minutes either side of the window
        const HABIT_PRE_LEAD      = 60;    // reminder, minutes before the window opens
        const HABIT_POST_LAG      = 30;    // nudge, minutes after it closes

        const RECOVERY_MAX_ACTS   = 3;
        const INSURANCE_MAX_ACTS  = 3;
        const INSURANCE_CHECKIN_DAYS = 30;

        const STAKE_MAX_ACTS      = 3;
        const STAKE_MIN_DAYS      = 5;
        const STAKE_MIN_TOTAL     = 5;     // combined completions across all picks

        const FOCUS_MULTIPLIER    = 0.10;  // deliberately well under Berserk's 30%
        const FOCUS_MIN_DAYS      = 3;
        const FOCUS_MAX_DAYS      = 90;

        const PACT_MIN_DAYS       = 5;
        // A floor on the COMBINED completions one side commits to, not on each
        // activity — the same shape as STAKE_MIN_TOTAL. Each individual target
        // still cannot go below 1; what this stops is a pact whose whole
        // commitment is one tap.
        const PACT_MIN_TARGET     = 3;
        // Both sides may name several activities. Three matches Stake Mode's
        // ceiling and the picker it borrows: past that the two-column panel
        // stops being a comparison and starts being a list.
        const PACT_MAX_ACTS       = 3;
        const PACT_INVITE_DAYS    = 7;

        // Hand-written, never generated (spec §0). Shown at habit milestones.
        const MODE_MILESTONE_QUOTES = [
            'Ordinary things, done consistently, produce extraordinary results.',
            'You are not what you intend. You are what you repeat.',
            'The work of a hundred days is a hundred days of work. Nothing else.',
            'Discipline is choosing what you want most over what you want now.',
            'Every rep is a vote for the person you are becoming.',
            'Momentum is built, not found.',
            'Small, boring, daily. That is the whole secret.',
            'The gap between who you are and who you want to be is the habit you keep.',
            'Nobody sees the practice. Everybody sees the result.',
            'You have already done the hard part — you started, and you kept going.'
        ];

        // Blurbs are deliberately one line each. The card is a decision, not a
        // manual — the detail belongs in the setup sheet, where it is being
        // acted on rather than read.
        const MODE_META = {
            habit:     { name: 'Habit Mode',    icon: 'plant', tag: 'Build',
                         blurb: 'Up to three activities, a daily window each. Counts days achieved.' },
            berserk:   { name: 'Berserk Mode',  icon: 'fire', tag: 'Extreme',
                         blurb: 'An XP target inside a 1–5 hour window. Clear it for +30%, miss it for −30%.' },
            recovery:  { name: 'Recovery Mode', icon: 'bandaids', tag: 'Return',
                         blurb: 'Up to three streaks climb twice as fast, until each is back at its own peak.' },
            insurance: { name: 'Insurance Mode',icon: 'shield', tag: 'Shield',
                         blurb: 'Up to three activities stop losing streak when you miss.' },
            stake:     { name: 'Stake Mode',    icon: 'dice-five', tag: 'Wager',
                         blurb: 'Bet Grit on completion targets. Every one lands, or the stake is gone.' },
            pact:      { name: 'Pact Mode',     icon: 'handshake', tag: 'Together',
                         blurb: 'Two people, two targets, one shared outcome.' },
            focus:     { name: 'Focus Window',  icon: 'target', tag: 'Rhythm',
                         blurb: 'One daily window. Everything logged inside it earns +10% XP.' }
        };

        function modeCostLabel(kind) {
            if (kind === 'stake') return MODE_WAGER_MIN + '–' + MODE_WAGER_MAX + ' wager';
            if (kind === 'pact')  return PACT_WAGER + ' wager';
            return MODE_COST[kind] + ' Grit';
        }

        // ── State ─────────────────────────────────────────────────────────
        function modesState() {
            if (!window.userData) return null;
            var m = window.userData.modes;
            if (!m || typeof m !== 'object') {
                m = window.userData.modes = {
                    schemaVersion: MODES_SCHEMA_VERSION,
                    active: null, pending: [], history: [],
                    suspendedHabit: null, streakOffsets: {}
                };
            }
            if (m.schemaVersion !== MODES_SCHEMA_VERSION) m.schemaVersion = MODES_SCHEMA_VERSION;
            if (!Array.isArray(m.pending)) m.pending = [];
            if (!Array.isArray(m.history)) m.history = [];
            if (!m.streakOffsets || typeof m.streakOffsets !== 'object') m.streakOffsets = {};
            if (m.active && MODE_KINDS.indexOf(m.active.kind) === -1) m.active = null;
            return m;
        }

        function modesActive() { var m = modesState(); return m ? m.active : null; }
        function modesActiveKind() { var a = modesActive(); return a ? a.kind : null; }
        window.modesActiveKind = modesActiveKind;

        function modesUid() { return (window.currentUser && window.currentUser.uid) || null; }
        function modesNow() { return Date.now(); }
        function modesToday() { return toLocalDateStr(new Date()); }
        function modeEsc(s) { return giftEsc(s); }

        function modesNewId(prefix) {
            return (prefix || 'md') + '-' + Date.now().toString(36) + '-' +
                   Math.random().toString(36).slice(2, 9);
        }

        // Whole local days between two YYYY-MM-DD strings (b − a).
        function modeDayDiff(aStr, bStr) {
            if (!aStr || !bStr) return 0;
            var a = new Date(aStr + 'T00:00:00'), b = new Date(bStr + 'T00:00:00');
            return Math.round((b - a) / 86400000);
        }
        function modeAddDays(dateStr, n) {
            var d = new Date(dateStr + 'T00:00:00');
            d.setDate(d.getDate() + n);
            return toLocalDateStr(d);
        }

        // "HH:mm" → minutes since local midnight, and back.
        function modeMins(hhmm) {
            var m = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(String(hhmm || ''));
            if (!m) return null;
            return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
        }
        function modeHHMM(mins) {
            mins = ((Math.round(mins) % 1440) + 1440) % 1440;
            return String(Math.floor(mins / 60)).padStart(2, '0') + ':' +
                   String(mins % 60).padStart(2, '0');
        }
        function modeTimeLabel(hhmm) {
            var mins = modeMins(hhmm);
            if (mins === null) return '--:--';
            var h = Math.floor(mins / 60), mm = String(mins % 60).padStart(2, '0');
            var ap = h < 12 ? 'AM' : 'PM';
            var h12 = h % 12 === 0 ? 12 : h % 12;
            return h12 + ':' + mm + ' ' + ap;
        }
        function modeMinutesNow() {
            var d = new Date();
            return d.getHours() * 60 + d.getMinutes();
        }

        // True when `nowMins` sits inside [start, end], with windows that cross
        // midnight handled by splitting into two ranges rather than by
        // pretending the day is longer than it is.
        function modeInWindow(startMins, endMins, nowMins, padBefore, padAfter) {
            padBefore = padBefore || 0; padAfter = padAfter || 0;
            var s = startMins - padBefore, e = endMins + padAfter;
            if (e < s) e += 1440;                       // end <= start: crosses midnight
            var n = nowMins;
            if (n < s) n += 1440;
            return n >= s && n <= e;
        }

        // Activities that can carry a mode: real, live, and countable. Negative
        // "perform" activities are excluded everywhere — they have no streak to
        // recover or insure, and rewarding their completion is not the point.
        function modeEligibleActivities(opts) {
            opts = opts || {};
            var out = [];
            try {
                (window.userData.dimensions || []).forEach(function (dim) {
                    (dim.paths || []).forEach(function (path) {
                        (path.activities || []).forEach(function (act) {
                            if (!act || act.archived || act.deleted) return;
                            if (act.isNegative && !act.isSkipNegative) return;
                            if (opts.streakOnly && act.frequency === 'occasional') return;
                            out.push({ id: String(act.id), name: act.name || 'Activity',
                                       dimName: dim.name || '', frequency: act.frequency || 'daily',
                                       streak: act.streak || 0, bestStreak: act.bestStreak || 0 });
                        });
                    });
                });
            } catch (e) {}
            return out;
        }

        // ══════════════════════════════════════════════════════════════════
        //  LIFECYCLE — activation, ending, resolution
        // ══════════════════════════════════════════════════════════════════

        let _modeActivating = false;

        // Activation is one Grit spend plus one write. gritPurchase() already
        // owns the whole "refuse before spending, persist before granting,
        // unwind on a failed save" sequence (§5.3 of the Grit spec), so this
        // hands it a grant/revert pair rather than re-implementing any of it.
        //
        // `payload` is the mode object minus the bookkeeping this function adds.
        async function modesActivate(kind, payload, cost, reason) {
            if (MODE_KINDS.indexOf(kind) === -1) return { ok: false, message: 'Unknown mode.' };
            var m = modesState();
            if (!m) return { ok: false, message: 'Not signed in.' };
            if (_modeActivating) return { ok: false, message: 'Hold on — that is still going through.' };
            if (m.active) {
                return { ok: false, message: 'You already have ' + MODE_META[m.active.kind].name +
                                             ' running. Only one mode at a time for now.' };
            }
            // A Pact invite that has not been answered yet is a mode in
            // waiting: its stake is already escrowed, and the moment it is
            // accepted it becomes the active mode. Starting something else on
            // top of it would be two modes at once a day later.
            var pending = (_pactCache.list || []).filter(function (p) {
                return p.status === 'pending' && (p.participants || []).indexOf(modesUid()) !== -1;
            });
            if (pending.length) {
                return { ok: false, message: 'You have a Pact waiting on an answer. ' +
                                             'Withdraw it, or wait for them, before starting another mode.' };
            }
            if (!canPersistUserData('modesActivate')) return { ok: false, message: 'Your account is not loaded yet.' };

            var full = Object.assign({
                kind: kind,
                id: modesNewId('md'),
                startedAt: new Date().toISOString(),
                startedDay: modesToday(),
                cost: cost
            }, payload);

            _modeActivating = true;
            try {
                var res = await gritPurchase(cost, reason || ('mode_' + kind),
                    function () { m.active = full; },
                    function () { m.active = null; },
                    { mode: kind, modeId: full.id });
                if (!res.ok) return res;
            } finally {
                _modeActivating = false;
            }

            try { await modesSyncNotifications(); } catch (e) { console.warn('Mode notification sync failed', e); }
            modesApplyTheme();
            modesRefreshBanner();
            try { window.trackEvent && window.trackEvent('mode_activated', { mode: kind }); } catch (e) {}
            return { ok: true, mode: full };
        }

        // Ending is always explicit: either the user turns it off, or the mode
        // reaches a terminal state and resolves itself. Both land here, and
        // both write exactly one archive record.
        //
        // `outcome` is one of: completed | failed | ended | expired.
        async function modesEnd(outcome, summary, opts) {
            opts = opts || {};
            var m = modesState();
            if (!m || !m.active) return false;
            var a = m.active;

            // Habit is the only mode that can be paused and resumed — its day
            // count stops while it is off, and picking it back up within a week
            // continues the same run rather than starting a new one.
            if (a.kind === 'habit' && outcome === 'ended') {
                m.suspendedHabit = { payload: a, offAt: new Date().toISOString(), offDay: modesToday() };
            } else if (a.kind === 'habit') {
                m.suspendedHabit = null;
            }

            // Insurance stops here, but what it already did stands: stamp
            // today as the day its credit was last earned, so the misses it
            // covered can never be counted against the streak afterwards. From
            // tomorrow the activity breaks like any other.
            if (a.kind === 'insurance') {
                if (!m.offsetFrom || typeof m.offsetFrom !== 'object') m.offsetFrom = {};
                (a.activities || []).forEach(function (x) {
                    var id = String(x.activityId);
                    if (m.streakOffsets[id]) m.offsetFrom[id] = modesToday();
                });
            }

            // Note what is deliberately NOT done here: the streak offsets in
            // modes.streakOffsets are left alone. A day that was genuinely
            // insured, or a step that recovery genuinely granted, stays earned
            // after the mode ends — retiring the offset would take back
            // protection that already applied. They stop GROWING, and they are
            // dropped the moment the walk says the streak actually broke
            // (see modesAfterStreakWalk).

            m.active = null;
            m.history.unshift({
                id: a.id, kind: a.kind, outcome: outcome,
                startedAt: a.startedAt, endedAt: new Date().toISOString(),
                summary: summary || ''
            });
            if (m.history.length > 30) m.history = m.history.slice(0, 30);

            if (opts.resolution) modesQueueResolution(opts.resolution);

            modesApplyTheme();
            modesRefreshBanner();
            try { await modesSyncNotifications(); } catch (e) {}
            if (!opts.skipSave) { try { await saveUserData(); } catch (e) { console.warn('Mode end save failed', e); } }
            try { modesRenderPage(); } catch (e) {}
            try { window.trackEvent && window.trackEvent('mode_ended', { mode: a.kind, outcome: outcome }); } catch (e) {}
            return true;
        }

        // ── Resolution (shared pattern, spec §0) ──────────────────────────
        // A terminal state reached while the user is looking at the app pops
        // immediately. One reached in the background (a timer expiring, a
        // window closing overnight) queues here and is shown the next time
        // they open the app. Same card either way.
        function modesQueueResolution(res) {
            var m = modesState();
            if (!m) return;
            res.id = res.id || modesNewId('mr');
            res.at = res.at || new Date().toISOString();
            m.pending.push(res);
            if (m.pending.length > 10) m.pending = m.pending.slice(-10);
        }

        function modesResolveNow(res) {
            // Live and in the app — show it straight away and don't queue it.
            if (document.visibilityState === 'visible' && document.getElementById('appContainer')) {
                modesShowResolution(res);
                return;
            }
            modesQueueResolution(res);
        }

        function modesDrainPending() {
            var m = modesState();
            if (!m || !m.pending.length) return;
            var next = m.pending.shift();
            saveUserData().catch(function () {});
            modesShowResolution(next, function () {
                // One at a time, so a night of two resolutions doesn't stack
                // two full-screen cards on top of each other.
                if (m.pending.length) setTimeout(modesDrainPending, 400);
            });
        }

        // ── Theme (spec §2) ───────────────────────────────────────────────
        // Berserk repaints the whole app, not just its own page. The theme
        // system writes inline custom properties onto <html>; this sets the
        // same properties on <body> instead, which wins for everything inside
        // it without touching, reading or fighting the theme code. Removing
        // the class restores the user's theme exactly, because nothing of
        // theirs was ever overwritten.
        function modesApplyTheme() {
            var body = document.body;
            if (!body) return;
            var on = modesActiveKind() === 'berserk' && !modeBerserkExpired(modesActive());
            body.classList.toggle('mk-mode-berserk', !!on);
        }
        window.modesApplyTheme = modesApplyTheme;

        // ── Notifications ─────────────────────────────────────────────────
        // Mode notifications ride the existing reminder infrastructure:
        // documents under users/{uid}/reminders with a nextSendAt the
        // onReminderWrite trigger fills in, sent by the sendDueReminders
        // scheduler. Nothing new is scheduled client-side, so they arrive with
        // the app closed like every other reminder.
        //
        // Every mode document id starts with `mode-`, which is how the sync
        // below knows which reminders are its own to remove.
        //
        // The full set of reminder documents the active mode wants to exist.
        function modesDesiredReminders() {
            var a = modesActive();
            var out = [];
            if (!a) return out;
            var tz = (typeof mkDetectTimezone === 'function' ? mkDetectTimezone() : null) || null;

            if (a.kind === 'habit') {
                (a.habits || []).forEach(function (h) {
                    var s = modeMins(h.windowStart), e = modeMins(h.windowEnd);
                    if (s === null || e === null) return;
                    out.push({
                        id: 'mode-habit-' + a.id + '-' + h.activityId + '-pre',
                        type: 'mode', modeKind: 'habit', modeId: a.id,
                        activityId: String(h.activityId),
                        activityName: h.activityName || 'your habit',
                        localTime: modeHHMM(s - HABIT_PRE_LEAD),
                        timezone: tz, active: true,
                        // Read by the sender, verbatim, never rewritten (§0).
                        why: String(h.why || ''),
                        anchor: String(h.anchor || ''),
                        windowStart: h.windowStart, windowEnd: h.windowEnd,
                        phase: 'pre'
                    });
                    out.push({
                        id: 'mode-habit-' + a.id + '-' + h.activityId + '-post',
                        type: 'mode', modeKind: 'habit', modeId: a.id,
                        activityId: String(h.activityId),
                        activityName: h.activityName || 'your habit',
                        localTime: modeHHMM(e + HABIT_POST_LAG),
                        timezone: tz, active: true,
                        why: String(h.why || ''),
                        anchor: String(h.anchor || ''),
                        windowStart: h.windowStart, windowEnd: h.windowEnd,
                        phase: 'post'
                    });
                });
            }

            if (a.kind === 'focus') {
                var fs = modeMins(a.windowStart);
                if (fs !== null) {
                    out.push({
                        id: 'mode-focus-' + a.id + '-pre',
                        type: 'mode', modeKind: 'focus', modeId: a.id,
                        activityId: null, activityName: null,
                        localTime: modeHHMM(fs - 15),
                        timezone: tz, active: true,
                        why: '', anchor: '',
                        windowStart: a.windowStart, windowEnd: a.windowEnd,
                        phase: 'pre'
                    });
                }
            }
            return out;
        }

        // Reconciles the reminder collection against modesDesiredReminders():
        // writes the ones that should exist, deletes every other `mode-`
        // document. Never touches a general or activity reminder.
        async function modesSyncNotifications() {
            var uid = modesUid();
            if (!uid || !canPersistUserData('modesSyncNotifications')) return;
            // Push is opt-in and permission-gated. If the user has no
            // subscription we still write the documents — they cost nothing,
            // and the moment push is enabled the reminders start arriving
            // without needing a mode to be re-created.
            var desired = modesDesiredReminders();
            var wanted = {};
            desired.forEach(function (d) { wanted[d.id] = d; });

            var existing = [];
            try {
                var snap = await getDocs(collection(db, 'users', uid, 'reminders'));
                snap.forEach(function (d) { if (d.id.indexOf('mode-') === 0) existing.push(d.id); });
            } catch (err) {
                console.warn('Mode reminder read failed:', err && err.message);
                return;
            }

            var batch = writeBatch(db);
            var writes = 0;
            existing.forEach(function (id) {
                if (!wanted[id]) { batch.delete(doc(db, 'users', uid, 'reminders', id)); writes++; }
            });
            Object.keys(wanted).forEach(function (id) {
                var d = wanted[id];
                batch.set(doc(db, 'users', uid, 'reminders', id), {
                    type: 'mode',
                    modeKind: d.modeKind,
                    modeId: d.modeId,
                    phase: d.phase,
                    activityId: d.activityId,
                    activityName: d.activityName,
                    localTime: d.localTime,
                    timezone: d.timezone,
                    windowStart: d.windowStart,
                    windowEnd: d.windowEnd,
                    why: d.why,
                    anchor: d.anchor,
                    active: true,
                    // Left null on purpose: onReminderWrite computes it with a
                    // real timezone library. Same contract as every other
                    // reminder the client creates.
                    nextSendAt: null,
                    lastSentDate: null,
                    updatedAt: new Date()
                });
                writes++;
            });
            if (!writes) return;
            try { await batch.commit(); }
            catch (err) { console.warn('Mode reminder sync failed:', err && err.message); }
        }

        // A local notification, for the things only the client can know about
        // (a recovery ceiling reached mid-session, a mode auto-resolving while
        // the tab is open). Silent if permission was never granted.
        function modesLocalNotify(title, body) {
            try {
                if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
                new Notification(title, { body: body, icon: './icon-192.svg', tag: 'mindkraft-mode' });
            } catch (e) {}
        }

        // ══════════════════════════════════════════════════════════════════
        //  XP MOVEMENT
        // ══════════════════════════════════════════════════════════════════
        //
        // Berserk's swing and Focus's multiplier are lump sums against the
        // user's own XP ledger — the same one payQuestBonus() moves, with the
        // same level-up loop. Deliberately NOT a second XP store: a berserk
        // win raises the averages that set tomorrow's berserk target, and the
        // spec says that is intended (§2).
        //
        // The bonus is also recorded in xpTodayGhost so "XP today" and the
        // leaderboard see it. Without that, XP that isn't attached to a
        // completionHistory row is invisible to every read that walks history.
        function modesAwardXP(amount, label, icon) {
            amount = Math.round(amount || 0);
            if (!amount || !window.userData) return 0;
            if (amount > 0) {
                if (typeof payQuestBonus === 'function') { payQuestBonus(null, amount); }
                var todayKey = localToday();
                if (!window.userData.xpTodayGhost) window.userData.xpTodayGhost = {};
                window.userData.xpTodayGhost[todayKey] =
                    (window.userData.xpTodayGhost[todayKey] || 0) + amount;
            } else {
                var loss = -amount;
                window.userData.currentXP = (window.userData.currentXP || 0) - loss;
                window.userData.totalXP   = (window.userData.totalXP || 0) - loss;
                while (window.userData.currentXP < 0 && window.userData.level > 1) {
                    window.userData.level -= 1;
                    window.userData.currentXP += calculateXPForLevel(window.userData.level);
                }
                if (window.userData.currentXP < 0) window.userData.currentXP = 0;
                var tk = localToday();
                if (!window.userData.xpTodayGhost) window.userData.xpTodayGhost = {};
                window.userData.xpTodayGhost[tk] =
                    (window.userData.xpTodayGhost[tk] || 0) - loss;
                try { if (typeof updateDashboard === 'function') updateDashboard(); } catch (e) {}
            }
            if (label) { try { showToast(label, amount > 0 ? 'green' : 'red', null, icon || null); } catch (e) {} }
            return amount;
        }

        // XP actually earned across every activity in a time range. Walks
        // completionHistory rather than diffing totalXP, so a penalty landing
        // mid-session or an undo elsewhere cannot be mistaken for progress.
        function modesXPBetween(fromMs, toMs) {
            var xp = 0;
            try {
                (window.userData.dimensions || []).forEach(function (dim) {
                    (dim.paths || []).forEach(function (path) {
                        (path.activities || []).forEach(function (act) {
                            (act.completionHistory || []).forEach(function (e) {
                                if (!e || e.isPenalty || !e.date) return;
                                var v = e.xp || 0;
                                if (v <= 0) return;
                                var t = new Date(e.date).getTime();
                                if (t >= fromMs && t <= toMs) xp += v;
                            });
                        });
                    });
                });
            } catch (e) {}
            return xp;
        }

        // ══════════════════════════════════════════════════════════════════
        //  BERSERK
        // ══════════════════════════════════════════════════════════════════
        //
        // TARGET (spec §2). The trailing 7-day average XP-per-hour is the
        // spine. A run of exceptional days would otherwise ratchet the target
        // straight out of reach, so only a fraction of however far that
        // average sits ABOVE the user's longer baseline is carried into the
        // target. A personal best makes tomorrow harder — a little.
        //
        //   effective/hr = baseline + BERSERK_DAMPENER × (avg7 − baseline)
        //                  when avg7 > baseline
        //   effective/hr = avg7     otherwise (a slump does not inflate it)
        //
        // "Hour" here is the app's own convention: computeXPPerHour() divides
        // a day's XP by 12 waking hours, and this uses the same divisor so the
        // number on the Berserk screen means the same thing as the one on the
        // Analytics tab.
        const MODE_WAKING_HOURS = 12;

        function modeDailyXPMap(days) {
            var out = {};
            var today = new Date(); today.setHours(0, 0, 0, 0);
            // `days` whole days BEFORE today. Today is excluded from the
            // averages (a half-finished day would drag them down), so the
            // floor is today − days, not today − (days − 1): the latter drops
            // the oldest day the caller then asks for and quietly averages
            // N days of XP over N+1 days.
            var floor = today.getTime() - days * 86400000;
            try {
                (window.userData.dimensions || []).forEach(function (dim) {
                    (dim.paths || []).forEach(function (path) {
                        (path.activities || []).forEach(function (act) {
                            (act.completionHistory || []).forEach(function (e) {
                                if (!e || e.isPenalty || !e.date) return;
                                var v = e.xp || 0;
                                if (v <= 0) return;
                                var d = new Date(e.date);
                                if (d.getTime() < floor) return;
                                var k = toLocalDateStr(d);
                                out[k] = (out[k] || 0) + v;
                            });
                        });
                    });
                });
            } catch (e) {}
            return out;
        }

        function modeAvgPerHour(days) {
            var map = modeDailyXPMap(days);
            var total = 0;
            var today = new Date(); today.setHours(0, 0, 0, 0);
            // Yesterday backwards, `days` of them. Today is excluded: a
            // half-finished day would drag the average down for no reason.
            for (var i = 1; i <= days; i++) {
                var d = new Date(today.getTime() - i * 86400000);
                total += map[toLocalDateStr(d)] || 0;
            }
            return total / days / MODE_WAKING_HOURS;
        }

        function berserkPerHourTarget() {
            var avg7 = modeAvgPerHour(7);
            var base = modeAvgPerHour(28);          // the longer, calmer baseline
            var eff  = avg7 > base ? base + BERSERK_DAMPENER * (avg7 - base) : avg7;
            return Math.max(BERSERK_FLOOR_PER_H, Math.round(eff));
        }

        function berserkTargetFor(hours) {
            return Math.max(1, Math.round(berserkPerHourTarget() * hours));
        }

        function modeBerserkExpired(a) {
            return !!(a && a.kind === 'berserk' && modesNow() >= a.endsAt);
        }

        function berserkEarned(a) {
            if (!a || a.kind !== 'berserk') return 0;
            return modesXPBetween(a.startedAtMs, Math.min(modesNow(), a.endsAt));
        }

        // Resolution. Called from three places — the completion hook (a live
        // win pops immediately), the login/foreground pass (the window closed
        // while they were away), and the Modes page render. Guarded on
        // `resolved` so whichever gets there first is the only one that pays.
        async function berserkMaybeResolve(force) {
            var a = modesActive();
            if (!a || a.kind !== 'berserk' || a.resolved) return false;
            var earned = berserkEarned(a);
            var expired = modeBerserkExpired(a);
            var won = earned >= a.targetXP;
            // `force` is the deliberate early end. Nothing else gets past
            // here: an unfinished window that nobody ended just keeps running.
            if (!won && !expired && !force) return false;

            a.resolved = true;
            var delta = won ? Math.round(earned * BERSERK_SWING)
                            : -Math.round(earned * BERSERK_SWING);
            // A failure with nothing logged still has to sting, or the mode is
            // free to enter and free to abandon. Charge the swing against what
            // the target was worth instead of against zero.
            if (!won && earned <= 0) delta = -Math.round(a.targetXP * BERSERK_SWING);
            modesAwardXP(delta, null);

            var res = {
                kind: 'berserk', outcome: won ? 'won' : 'lost',
                title: won ? 'Berserk cleared' : 'Berserk fell short',
                headline: won ? '+' + Math.abs(delta) + ' XP' : '−' + Math.abs(delta) + ' XP',
                lines: [
                    a.hours + '-hour window',
                    'Target ' + a.targetXP.toLocaleString() + ' XP',
                    'Earned ' + earned.toLocaleString() + ' XP'
                ],
                note: won
                    ? 'You beat your own trailing average with hours to spare. The bonus is already in your total.'
                    : 'The window closed short of the target. Thirty percent is the price you agreed to — it has been taken.'
            };
            await modesEnd(won ? 'completed' : 'failed',
                           (won ? 'Cleared ' : 'Missed ') + a.targetXP + ' XP in ' + a.hours + 'h',
                           { resolution: null });
            modesResolveNow(res);
            try { await saveUserData(); } catch (e) {}
            return true;
        }

        // ══════════════════════════════════════════════════════════════════
        //  FOCUS WINDOW
        // ══════════════════════════════════════════════════════════════════
        //
        // STACKING (spec §7): when several multipliers could apply to one
        // completion, only the largest one does — they never compound. Today
        // exactly one mode can be active so this can only ever pick one, but
        // the rule is written here rather than assumed, because the multi-mode
        // version of this function is meant to be this function.
        function modeBestMultiplierFor(activity, whenMs) {
            var a = modesActive();
            var best = 0;
            if (!a) return best;
            // A perform-negative completion earns negative XP. Ten percent of a
            // penalty is not a bonus, so nothing multiplies it — same rule the
            // Grit boost already follows.
            if (activity && activity.isNegative && !activity.isSkipNegative) return best;
            if (a.kind === 'focus' && !modeFocusFinished(a)) {
                var d = new Date(whenMs || Date.now());
                var nowMins = d.getHours() * 60 + d.getMinutes();
                var s = modeMins(a.windowStart), e = modeMins(a.windowEnd);
                if (s !== null && e !== null && modeInWindow(s, e, nowMins, 0, 0)) {
                    best = Math.max(best, FOCUS_MULTIPLIER);
                }
            }
            return best;
        }

        function modeFocusFinished(a) {
            if (!a || a.kind !== 'focus') return true;
            return (a.daysElapsed || 0) >= a.targetDays;
        }

        // ══════════════════════════════════════════════════════════════════
        //  HABIT
        // ══════════════════════════════════════════════════════════════════
        //
        // The only number a habit shows is "N of M days achieved". No streak,
        // no second counter (spec §1). `daysElapsed` is the denominator and it
        // only advances while the mode is ON — turning habit mode off freezes
        // it rather than letting it tick in the background.
        function habitAdvanceDays(a) {
            if (!a || a.kind !== 'habit') return false;
            var today = modesToday();
            if (a.lastCountedDay === today) return false;
            var gap = a.lastCountedDay ? modeDayDiff(a.lastCountedDay, today) : 0;
            if (gap <= 0) { a.lastCountedDay = today; return false; }
            a.daysElapsed = (a.daysElapsed || 0) + gap;
            a.lastCountedDay = today;
            return true;
        }

        function habitOf(a, activityId) {
            return (a.habits || []).filter(function (h) {
                return String(h.activityId) === String(activityId);
            })[0] || null;
        }

        // Which habit, if any, wants the screen right now: from 30 minutes
        // before its window opens to 30 minutes after it closes (spec §1).
        function habitOverlayDue() {
            var a = modesActive();
            if (!a || a.kind !== 'habit') return null;
            if ((a.daysElapsed || 0) >= a.targetDays) return null;
            var nowMins = modeMinutesNow(), today = modesToday();
            var hit = null;
            (a.habits || []).forEach(function (h) {
                if (hit) return;
                if (h.lastCompletedDay === today) return;   // already done — no nagging
                var s = modeMins(h.windowStart), e = modeMins(h.windowEnd);
                if (s === null || e === null) return;
                if (modeInWindow(s, e, nowMins, HABIT_OVERLAY_LEAD, HABIT_OVERLAY_LEAD)) hit = h;
            });
            if (!hit) return null;
            // Dismissing it is per habit, per day — it is a moment of friction,
            // not a wall (spec §1).
            if (hit.overlayDismissedDay === today) return null;
            return hit;
        }

        // Milestone fractions on the way to the target. 25/50/75 are named in
        // the spec; 10 exists because the first stretch is where people quit.
        const HABIT_MILESTONES = [0.10, 0.25, 0.50, 0.75];

        function habitCheckMilestone(a, h) {
            if (!a.targetDays) return null;
            var frac = (h.completions || 0) / a.targetDays;
            h.milestonesShown = h.milestonesShown || [];
            var hitOne = null;
            HABIT_MILESTONES.forEach(function (mfrac) {
                if (hitOne) return;
                if (frac >= mfrac && h.milestonesShown.indexOf(mfrac) === -1) {
                    h.milestonesShown.push(mfrac);
                    hitOne = mfrac;
                }
            });
            return hitOne;
        }

        function habitQuote(seed) {
            var i = Math.abs(Math.floor(seed || 0)) % MODE_MILESTONE_QUOTES.length;
            return MODE_MILESTONE_QUOTES[i];
        }

        // ══════════════════════════════════════════════════════════════════
        //  STAKE
        // ══════════════════════════════════════════════════════════════════

        function stakeEndDay(a) { return modeAddDays(a.startedDay, a.days); }
        function stakeDaysLeft(a) { return modeDayDiff(modesToday(), stakeEndDay(a)); }
        function stakeAllHit(a) {
            return (a.items || []).every(function (it) { return (it.count || 0) >= it.target; });
        }
        function stakeTotalTarget(a) {
            return (a.items || []).reduce(function (s, it) { return s + (it.target || 0); }, 0);
        }
        function stakeTotalCount(a) {
            return (a.items || []).reduce(function (s, it) {
                return s + Math.min(it.count || 0, it.target || 0);
            }, 0);
        }

        async function stakeMaybeResolve(force) {
            var a = modesActive();
            if (!a || a.kind !== 'stake' || a.resolved) return false;
            var won = stakeAllHit(a);
            var over = stakeDaysLeft(a) <= 0;
            // `force` is the deliberate early end, which forfeits — a stake
            // walked away from is a stake lost, and the copy says so.
            if (!won && !over && !force) return false;

            a.resolved = true;
            var bonus = Math.round(a.wager * MODE_WAGER_RETURN);
            var res;
            if (won) {
                gritApplyDelta(a.wager + bonus, 'mode_stake_win',
                    { mode: 'stake', modeId: a.id, wager: a.wager, bonus: bonus });
                res = {
                    kind: 'stake', outcome: 'won', title: 'Stake paid out',
                    headline: '+' + (a.wager + bonus) + ' Grit',
                    lines: (a.items || []).map(function (it) {
                        return it.activityName + ' — ' + Math.min(it.count, it.target) + '/' + it.target;
                    }),
                    note: 'Every target, inside the window. Your ' + a.wager +
                          ' Grit is back with ' + bonus + ' on top.'
                };
            } else {
                res = {
                    kind: 'stake', outcome: 'lost', title: 'Stake forfeited',
                    headline: '−' + a.wager + ' Grit',
                    lines: (a.items || []).map(function (it) {
                        var done = (it.count || 0) >= it.target;
                        return (done ? phIcon('check', { lead: true }) : phIcon('x', { lead: true })) + it.activityName + ' — ' +
                               Math.min(it.count || 0, it.target) + '/' + it.target;
                    }),
                    note: 'Stake mode is all or nothing. One target short is the same as none.'
                };
            }
            await modesEnd(won ? 'completed' : 'failed',
                           stakeTotalCount(a) + '/' + stakeTotalTarget(a) + ' completions');
            modesResolveNow(res);
            try { await saveUserData(); } catch (e) {}
            return true;
        }

        // ══════════════════════════════════════════════════════════════════
        //  RECOVERY  (strictly additive — see the header note)
        // ══════════════════════════════════════════════════════════════════
        //
        // The ceiling is read once, at activation, from bestStreak — existing
        // historical data, no new field on the activity. It has to be captured
        // then rather than read live, because the moment recovery starts
        // lifting the streak, bestStreak follows it upward and would chase its
        // own tail forever.
        //
        // `bonus[activityId]` is how many extra increments recovery has
        // granted. The login pass re-adds it after processStreakSystem has
        // re-derived the base figure, which is what makes the boost survive a
        // walk that knows nothing about it.
        function recoveryCeilingFor(act) {
            return Math.max(1, act.bestStreak || act.streak || 0);
        }

        function recoveryEntry(a, activityId) {
            return (a.activities || []).filter(function (x) {
                return String(x.activityId) === String(activityId);
            })[0] || null;
        }

        function recoveryAllAtCeiling(a) {
            return (a.activities || []).every(function (x) {
                var act = gritFindActivity(x.activityId);
                if (!act) return true;            // gone — it can't be recovered
                return (act.streak || 0) >= x.ceiling;
            });
        }

        // ══════════════════════════════════════════════════════════════════
        //  INSURANCE  (strictly additive — see the header note)
        // ══════════════════════════════════════════════════════════════════
        //
        // The rule is one line: while insurance is on an activity, its
        // displayed streak never goes DOWN. So after every authoritative walk,
        //
        //     offset = max(0, previousDisplayed − freshlyWalkedBase)
        //     displayed = base + offset  =  max(previousDisplayed, base)
        //
        // Missing a day leaves the streak where it was; logging still moves it
        // up through the normal path, because completeActivity increments the
        // displayed value. The offset melts back to zero on its own once real
        // history catches up, which is exactly what should happen.
        //
        // Shields are handled the same way: whatever the walk consumed on an
        // insured activity is put back, so "shield state" is undamaged too.
        function insuranceDaysOn(a) { return modeDayDiff(a.startedDay, modesToday()); }

        // ══════════════════════════════════════════════════════════════════
        //  THE STREAK PASSES
        // ══════════════════════════════════════════════════════════════════
        //
        // Two calls, both inside processStreakPauses() — the ORCHESTRATOR,
        // never processStreakSystem() itself. One snapshots before the
        // authoritative walk, one adds mode-owned offsets after it has
        // finished. processStreakSystem is not read, not wrapped, and not
        // aware any of this exists (spec §3).
        //
        // `modes.streakOffsets[activityId]` is a single integer per activity:
        // how many days of streak the modes have granted or protected on top
        // of what the user's own completion history supports. It survives the
        // mode that created it, because a day that was genuinely insured or
        // genuinely recovered stays earned. It is dropped the moment the walk
        // says the streak actually broke with no insurance in force.
        //
        // The whole pass is guarded per activity per day, so a second call in
        // the same session cannot add the offset twice.

        let _modeStreakSnapshot = null;

        // How many of an activity's own cycle windows, ending with the most
        // recently CLOSED one, have gone by with nothing logged — counting no
        // further back than `sinceDay`, the last day a mode's credit was
        // earned. Strictly read-only: it uses the same two window helpers the
        // walk does and writes nothing, so it is a measurement of the streak
        // system, not a participant in it.
        function modeMissedWindowsSince(act, sinceDay) {
            if (!act) return 0;
            var todayMid = new Date(); todayMid.setHours(0, 0, 0, 0);
            var todayWin = getCycleWindowStart(act, todayMid);
            if (!todayWin) return 0;

            var floorWin = null;
            if (sinceDay) floorWin = getCycleWindowStart(act, new Date(sinceDay + 'T00:00:00'));

            var hist = (act.completionHistory || []).filter(function (e) {
                return e && !e.isPenalty && (e.xp || 0) > 0 && e.date;
            });

            var cur = getCycleWindowStart(act, new Date(todayWin.getTime() - 1));
            var missed = 0;
            for (var i = 0; i < 400 && cur; i++) {
                if (floorWin && cur.getTime() <= floorWin.getTime()) break;
                var next = getNextCycleWindowStart(act, cur);
                if (!next) break;
                var cs = cur.getTime(), ce = next.getTime();
                var hit = hist.some(function (e) {
                    var t = new Date(e.date).getTime();
                    return t >= cs && t < ce;
                });
                if (hit) break;
                missed++;
                var prev = getCycleWindowStart(act, new Date(cur.getTime() - 1));
                if (!prev) break;
                cur = prev;
            }
            return missed;
        }

        function modesTrackedActivityIds() {
            var m = modesState();
            var ids = new Set();
            if (!m) return ids;
            Object.keys(m.streakOffsets || {}).forEach(function (k) { ids.add(k); });
            var a = m.active;
            if (a && (a.kind === 'insurance' || a.kind === 'recovery')) {
                (a.activities || []).forEach(function (x) { ids.add(String(x.activityId)); });
            }
            return ids;
        }

        function modesBeforeStreakWalk() {
            _modeStreakSnapshot = null;
            var ids = modesTrackedActivityIds();
            if (!ids.size) return;
            var snap = {};
            ids.forEach(function (id) {
                var act = gritFindActivity(id);
                if (!act) return;
                snap[id] = {
                    streak: act.streak || 0,
                    shieldsConsumed: act.shieldsConsumed || 0,
                    shieldCapUsed: act.shieldCapUsed || 0,
                    streakStartWindow: act.streakStartWindow || null
                };
            });
            _modeStreakSnapshot = snap;
        }

        function modesAfterStreakWalk() {
            var snap = _modeStreakSnapshot;
            _modeStreakSnapshot = null;
            var m = modesState();
            if (!m || !snap) return false;

            var a = m.active;
            var insured = new Set();
            if (a && a.kind === 'insurance') {
                (a.activities || []).forEach(function (x) { insured.add(String(x.activityId)); });
            }
            if (!m.offsetDay || typeof m.offsetDay !== 'object') m.offsetDay = {};
            if (!m.offsetFrom || typeof m.offsetFrom !== 'object') m.offsetFrom = {};
            var today = modesToday();
            var changed = false;

            Object.keys(snap).forEach(function (id) {
                if (m.offsetDay[id] === today) return;      // already applied today
                var act = gritFindActivity(id);
                if (!act) { delete m.streakOffsets[id]; delete m.offsetDay[id]; changed = true; return; }

                var prev = snap[id];
                var base = act.streak || 0;
                var n = m.streakOffsets[id] || 0;
                var isInsured = insured.has(id);

                // Insurance: whatever the walk took away, hand straight back.
                if (isInsured) {
                    n = Math.max(n, prev.streak - base);
                    // The credit is re-earned every day the cover is on. This
                    // stamp is what stops the misses it covered from counting
                    // against the user later, once it is off.
                    m.offsetFrom[id] = today;
                    // …and the shields it spent covering those misses.
                    if ((act.shieldsConsumed || 0) > prev.shieldsConsumed) {
                        act.shieldsConsumed = prev.shieldsConsumed;
                        changed = true;
                    }
                    if (prev.shieldCapUsed && (act.shieldCapUsed || 0) < prev.shieldCapUsed) {
                        act.shieldCapUsed = prev.shieldCapUsed;
                        changed = true;
                    }
                    if (!act.streakStartWindow && prev.streakStartWindow) {
                        act.streakStartWindow = prev.streakStartWindow;
                        changed = true;
                    }
                } else if (n > 0) {
                    // No cover in force. The credit stands until the activity
                    // genuinely breaks — which it has not done just because the
                    // walk reports a base of zero: the walk derives its figure
                    // from history alone, and the history has a hole in it
                    // precisely because those days were insured.
                    //
                    // So ask the only question that actually matters: how many
                    // windows in a row have gone unlogged SINCE the cover
                    // stopped? Once that run outlasts the shields the activity
                    // has, the streak is over and the credit goes with it.
                    if (modeMissedWindowsSince(act, m.offsetFrom[id]) > shieldFloorFor(act)) {
                        n = 0;
                    }
                }

                if (n > 0) {
                    act.streak = base + n;
                    act.bestStreak = Math.max(act.bestStreak || 0, act.streak);
                    m.streakOffsets[id] = n;
                    if (!m.offsetFrom[id]) m.offsetFrom[id] = today;
                    changed = true;
                } else if (m.streakOffsets[id]) {
                    delete m.streakOffsets[id];
                    delete m.offsetFrom[id];
                    changed = true;
                }
                m.offsetDay[id] = today;
            });

            // Housekeeping: markers for activities nothing tracks any more.
            Object.keys(m.offsetDay).forEach(function (id) {
                if (!snap[id] && !m.streakOffsets[id]) delete m.offsetDay[id];
            });
            Object.keys(m.offsetFrom).forEach(function (id) {
                if (!m.streakOffsets[id]) delete m.offsetFrom[id];
            });

            if (a && a.kind === 'recovery' && recoveryAllAtCeiling(a)) {
                modesRecoveryConclude(a);
                changed = true;
            }
            return changed;
        }

        function modesRecoveryConclude(a) {
            var names = (a.activities || []).map(function (x) { return x.activityName; }).join(', ');
            modesLocalNotify('Recovery complete',
                'Every activity is back at its old peak. Recovery Mode has switched itself off.');
            modesEnd('completed', names + ' back at peak', {
                resolution: {
                    kind: 'recovery', outcome: 'won', title: 'Back to your peak',
                    headline: (a.activities || []).length + ' recovered',
                    lines: (a.activities || []).map(function (x) {
                        return x.activityName + ' — reached ' + x.ceiling;
                    }),
                    note: 'Every one is back at its own peak, so the mode has ended itself. Normal rate from here.'
                }
            }).catch(function () {});
        }

        // ══════════════════════════════════════════════════════════════════
        //  COMPLETION / UNDO HOOKS
        // ══════════════════════════════════════════════════════════════════
        //
        // Everything a mode does when an activity is logged happens here, on
        // the way out of completeActivity() — never inside it.
        function modesOnCompletion(activity) {
            var m = modesState();
            if (!m || !m.active || !activity) return;
            var a = m.active;
            var id = String(activity.id);
            var today = modesToday();
            var dirty = false;

            // ── Focus Window: the multiplier (spec §7) ────────────────────
            var mult = modeBestMultiplierFor(activity, Date.now());
            if (mult > 0) {
                var hist = activity.completionHistory || [];
                var last = hist.length ? hist[hist.length - 1] : null;
                var basis = last && !last.isPenalty ? Math.abs(last.xp || 0) : 0;
                var bonus = Math.round(basis * mult);
                if (bonus > 0) {
                    modesAwardXP(bonus, 'Inside your focus window — +' + bonus + ' XP', 'target');
                    a.bonusXP = (a.bonusXP || 0) + bonus;
                    a.bonusCount = (a.bonusCount || 0) + 1;
                    dirty = true;
                }
            }

            // ── Habit: one completion per day counts (spec §1) ────────────
            if (a.kind === 'habit') {
                var h = habitOf(a, id);
                if (h && h.lastCompletedDay !== today) {
                    h.lastCompletedDay = today;
                    h.completions = (h.completions || 0) + 1;
                    dirty = true;
                    var done = (a.daysElapsed || 0) + 1 >= a.targetDays &&
                               (a.habits || []).every(function (x) { return x.lastCompletedDay === today; });
                    var ms = habitCheckMilestone(a, h);
                    if (done) {
                        habitFinish(a);
                    } else if (ms !== null) {
                        modesShowMilestone(h, ms, a.targetDays);
                    }
                }
            }

            // ── Recovery: one bonus increment per completion ──────────────
            if (a.kind === 'recovery') {
                var entry = recoveryEntry(a, id);
                if (entry && entry.lastBonusDay !== today) {
                    var streakNow = activity.streak || 0;
                    if (streakNow < entry.ceiling) {
                        activity.streak = streakNow + 1;
                        activity.bestStreak = Math.max(activity.bestStreak || 0, activity.streak);
                        m.streakOffsets[id] = (m.streakOffsets[id] || 0) + 1;
                        if (!m.offsetFrom || typeof m.offsetFrom !== 'object') m.offsetFrom = {};
                        m.offsetFrom[id] = today;
                        entry.lastBonusDay = today;
                        entry.granted = (entry.granted || 0) + 1;
                        dirty = true;
                        try {
                            showToast('Recovery — ' + (activity.name || 'streak') + ' jumps to ' +
                                      activity.streak + ' of ' + entry.ceiling, 'blue', null, 'bandaids');
                        } catch (e) {}
                    }
                    if ((activity.streak || 0) >= entry.ceiling && recoveryAllAtCeiling(a)) {
                        modesRecoveryConclude(a);
                        return;
                    }
                }
            }

            // ── Stake: count toward the wager ─────────────────────────────
            if (a.kind === 'stake' && !a.resolved) {
                var item = (a.items || []).filter(function (x) { return String(x.activityId) === id; })[0];
                if (item && stakeDaysLeft(a) > 0) {
                    item.count = (item.count || 0) + 1;
                    dirty = true;
                    if (stakeAllHit(a)) { stakeMaybeResolve().catch(function () {}); return; }
                }
            }

            // ── Berserk: progress is XP, so nothing to count — just check ──
            if (a.kind === 'berserk' && !a.resolved) {
                berserkMaybeResolve().catch(function () {});
                return;
            }

            // ── Pact: mirrored into the shared document ───────────────────
            if (a.kind === 'pact' && a.pactId && modePactHasActivity(a, id)) {
                pactCommitProgress(a.pactId, id, 1).catch(function () {});
            }

            if (dirty) {
                // completeActivity's own debounced save is already in flight
                // and would carry these fields with it, but relying on that
                // ordering would be a silent data loss the day it changes.
                try { debouncedSaveUserData(); } catch (e) {}
                try { modesRenderPage(); } catch (e) {}
                try { modesRefreshBanner(); } catch (e) {}
            }
        }

        function modesOnUndo(activity) {
            var m = modesState();
            if (!m || !m.active || !activity) return;
            var a = m.active;
            var id = String(activity.id);
            var today = modesToday();

            if (a.kind === 'habit') {
                var h = habitOf(a, id);
                if (h && h.lastCompletedDay === today) {
                    h.lastCompletedDay = null;
                    h.completions = Math.max(0, (h.completions || 0) - 1);
                }
            }
            if (a.kind === 'stake' && !a.resolved) {
                var item = (a.items || []).filter(function (x) { return String(x.activityId) === id; })[0];
                if (item) item.count = Math.max(0, (item.count || 0) - 1);
            }
            if (a.kind === 'recovery') {
                var entry = recoveryEntry(a, id);
                if (entry && entry.lastBonusDay === today) {
                    entry.lastBonusDay = null;
                    entry.granted = Math.max(0, (entry.granted || 0) - 1);
                    m.streakOffsets[id] = Math.max(0, (m.streakOffsets[id] || 0) - 1);
                    if (!m.streakOffsets[id]) delete m.streakOffsets[id];
                    activity.streak = Math.max(0, (activity.streak || 0) - 1);
                }
            }
            if (a.kind === 'pact' && a.pactId && modePactHasActivity(a, id)) {
                pactCommitProgress(a.pactId, id, -1).catch(function () {});
            }
            try { debouncedSaveUserData(); } catch (e) {}
            try { modesRenderPage(); } catch (e) {}
            try { modesRefreshBanner(); } catch (e) {}
        }

        function habitFinish(a) {
            var total = (a.habits || []).reduce(function (s, h) { return s + (h.completions || 0); }, 0);
            modesEnd('completed', total + ' completions over ' + a.targetDays + ' days', {
                resolution: {
                    kind: 'habit', outcome: 'won', title: 'Habit complete',
                    headline: a.targetDays + ' days',
                    lines: (a.habits || []).map(function (h) {
                        return h.activityName + ' — ' + h.completions + ' of ' + a.targetDays;
                    }),
                    note: 'You set out to do this for ' + a.targetDays + ' days, and you did. ' +
                          'It is a habit now — keep it without the scaffolding.'
                }
            }).catch(function () {});
        }

        // ══════════════════════════════════════════════════════════════════
        //  LOGIN / FOREGROUND PASS
        // ══════════════════════════════════════════════════════════════════
        //
        // Everything that can fall due while the app is closed is settled
        // here: the day counters advance, expired windows resolve, and any
        // resolution that happened in the background is shown (spec §0).
        let _modesPassAt = 0;

        async function modesRunPass(force) {
            var m = modesState();
            if (!m) return;
            if (!force && modesNow() - _modesPassAt < 30000) return;
            _modesPassAt = modesNow();

            var dirty = false;
            var a = m.active;

            if (a) {
                if (a.kind === 'habit') {
                    if (habitAdvanceDays(a)) dirty = true;
                    if ((a.daysElapsed || 0) >= a.targetDays) { habitFinish(a); return; }
                }
                if (a.kind === 'focus') {
                    var today = modesToday();
                    if (a.lastCountedDay !== today) {
                        var gap = a.lastCountedDay ? modeDayDiff(a.lastCountedDay, today) : 0;
                        if (gap > 0) a.daysElapsed = (a.daysElapsed || 0) + gap;
                        a.lastCountedDay = today;
                        dirty = true;
                    }
                    if (modeFocusFinished(a)) { await focusFinish(a); return; }
                }
                if (a.kind === 'berserk') {
                    if (await berserkMaybeResolve()) return;
                }
                if (a.kind === 'stake') {
                    if (await stakeMaybeResolve()) return;
                }
                if (a.kind === 'insurance') {
                    var days = insuranceDaysOn(a);
                    if (days >= INSURANCE_CHECKIN_DAYS &&
                        modeDayDiff(a.lastCheckInDay || a.startedDay, modesToday()) >= INSURANCE_CHECKIN_DAYS) {
                        a.lastCheckInDay = modesToday();
                        dirty = true;
                        modesShowInsuranceCheckIn(a, days);
                    }
                }
                if (a.kind === 'pact') {
                    await pactRunMaintenance();
                }
            }

            // An expired suspended habit stops being resumable (spec §1).
            if (m.suspendedHabit && m.suspendedHabit.offAt) {
                var off = new Date(m.suspendedHabit.offAt).getTime();
                if (modesNow() - off > HABIT_RESUME_DAYS * 86400000) { m.suspendedHabit = null; dirty = true; }
            }

            modesApplyTheme();
            modesRefreshBanner();
            if (dirty) { try { await saveUserData(); } catch (e) {} }
            modesDrainPending();
            if (!a || a.kind !== 'pact') { pactCheckInvites().catch(function () {}); }
            habitMaybeShowOverlay();
        }

        async function focusFinish(a) {
            await modesEnd('completed', (a.bonusCount || 0) + ' boosted completions', {
                resolution: {
                    kind: 'focus', outcome: 'won', title: 'Focus Window closed',
                    headline: '+' + (a.bonusXP || 0) + ' XP',
                    lines: [
                        modeTimeLabel(a.windowStart) + ' – ' + modeTimeLabel(a.windowEnd),
                        a.targetDays + ' days',
                        (a.bonusCount || 0) + ' completions inside the window'
                    ],
                    note: 'A fixed slot in the day, kept for ' + a.targetDays +
                          ' days. That is the part that carries over.'
                }
            });
        }

        function modesOnLogin() {
            if (!modesUid()) return;
            _modesPassAt = 0;
            modesRunPass(true).catch(function (e) {
                console.warn('Modes login pass failed:', e && e.message);
            });
        }
        window.modesOnLogin = modesOnLogin;

        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState !== 'visible') return;
            if (!modesUid()) return;
            modesRunPass(false).catch(function () {});
        });

        // ══════════════════════════════════════════════════════════════════
        //  PACT  —  the only mode two accounts can see
        // ══════════════════════════════════════════════════════════════════
        //
        // Placement mirrors Versus Challenges exactly, and for the same
        // reason: a document under users/{uid} could not be granted to the
        // other side without widening that user's rules far past what is safe.
        // So a pact lives in a TOP-LEVEL `pacts` collection, and it is the
        // only cross-account surface. Neither partner is ever granted read
        // access to the other's user document, activities, history or balance
        // — everything they see about each other is mirrored onto the pact by
        // its owner, and that mirror is a counter, a target and an agreed name.
        //
        // NOT a competition and NOT a wager against each other. Each person
        // sets their own activity and their own target; the stake is
        // individual. What is shared is the outcome: either both hit their own
        // targets, or the pact breaks for both (spec §6).
        //
        // Grit invariant, same as Versus: every Grit that leaves a balance is
        // either escrowed in the pact's `pot` or recorded in `payout` waiting
        // to be claimed. A broken pact is the one place Grit genuinely leaves
        // the system — that is the point of it, and it is stated up front.
        const PACT_COL = 'pacts';
        const PACT_SCHEMA_VERSION = 1;
        const PACT_TERMINAL = ['resolved', 'declined', 'cancelled', 'expired'];
        const PACT_ALL_STATUSES = ['pending', 'active'].concat(PACT_TERMINAL);
        const PACT_CACHE_TTL_MS = 60000;

        let _pactCache = { at: 0, list: [], uid: null };
        let _pactFetchInFlight = null;
        let _pactIndexMissing = false;
        let _pactMaintaining = false;

        function pactMyName() {
            var p = (window.userData && window.userData.profile) || {};
            return p.username || (window.currentUser && window.currentUser.displayName) || 'A friend';
        }
        function pactIsTerminal(s) { return PACT_TERMINAL.indexOf(s) !== -1; }
        function pactOther(p, uid) {
            var ps = p.participants || [];
            return ps[0] === uid ? ps[1] : ps[0];
        }
        function pactName(p, uid) { return (p.names && p.names[uid]) || 'Your partner'; }
        function pactTerm(p, uid) { return (p.terms && p.terms[uid]) || null; }

        // ── The two shapes, and the seam between them ─────────────────────
        //
        // A pact used to hold ONE activity per side:
        //
        //     terms[uid]    = { activityId, activityName, target }
        //     progress[uid] = <number>
        //
        // It now holds as many as each side wants, each with its own target:
        //
        //     terms[uid]    = { items: [{ activityId, activityName, target }] }
        //     progress[uid] = { <activityId>: <count> }
        //
        // Read tolerance, not migration — the same call the Quest simplification
        // made. A pact that is already running finishes out under the old shape
        // rather than being rewritten underneath two people who agreed to it;
        // everything below reads either shape and nothing ever writes the old
        // one back. Every read of a term or a counter goes through pactItems()
        // and pactCount() for exactly that reason — nothing else touches
        // terms[uid] or progress[uid] directly.
        //
        // The item shape is Stake Mode's, deliberately: {activityId,
        // activityName, target} is already what a multi-activity commitment
        // looks like in this app, and its picker and stepper rows are reused
        // wholesale by the Pact setup sheet below.
        //
        // Keeping the per-activity counters INSIDE progress[uid] rather than in
        // a new top-level field is what lets the security rules stand unchanged:
        // the progress branch allows `changed().hasOnly(['progress'])` and pins
        // the other participant's value by equality, which holds whether that
        // value is a number or a map.
        function pactItems(p, uid) {
            var t = pactTerm(p, uid);
            if (!t) return [];
            if (Array.isArray(t.items)) {
                return t.items.filter(function (it) { return it && it.activityId; });
            }
            if (t.activityId) return [t];          // the single-activity shape
            return [];
        }

        function pactCount(p, uid, activityId) {
            var pr = (p.progress && p.progress[uid]);
            if (typeof pr === 'number') return pr;  // the single-activity shape
            return (pr && pr[String(activityId)]) || 0;
        }

        // One party's side of the pact, capped per activity so an over-logged
        // item can never carry an under-logged one. This is the single
        // computation resolution, the panel, the percentage and the server's
        // nudges all read — nothing recomputes it a second way.
        function pactStats(p, uid) {
            var items = pactItems(p, uid);
            var done = 0, total = 0, hit = items.length > 0;
            items.forEach(function (it) {
                var target = Math.max(1, it.target || 1);
                var count = Math.min(pactCount(p, uid, it.activityId), target);
                done += count;
                total += target;
                if (count < target) hit = false;
            });
            return { done: done, total: total, hit: hit,
                     pct: total > 0 ? Math.round((done / total) * 100) : 0 };
        }

        // "Read × 20", or "Read × 20, Walk × 12" — the whole of one side's
        // commitment in one line, for the invite card and the accept sheet.
        // Both surfaces have to render the OTHER person's term, so neither can
        // assume how many activities it holds.
        function pactTermSummary(p, uid) {
            var items = pactItems(p, uid);
            if (!items.length) return 'an activity';
            return items.map(function (it) {
                return (it.activityName || 'an activity') + ' × ' + Math.max(1, it.target || 1);
            }).join(', ');
        }

        function pactHit(p, uid) { return pactStats(p, uid).hit; }

        // Mathematically out of reach: the days remaining cannot carry the
        // shortfall even at one completion a day. The spec asks for this
        // explicitly — a pact that cannot be saved should break now, not sit
        // there pretending (spec §6).
        //
        // Judged PER ACTIVITY, not on the totals. Several activities can be
        // logged on the same day, so a combined shortfall of ten across five
        // items is not out of reach with two days left — but a single item
        // needing three more with two days left is. Anything coarser would
        // break pacts that are still winnable.
        function pactImpossible(p, uid) {
            if (p.status !== 'active') return false;
            var items = pactItems(p, uid);
            if (!items.length) return false;
            var daysLeft = Math.ceil((p.endsAt - modesNow()) / 86400000);
            return items.some(function (it) {
                var short = Math.max(1, it.target || 1) - pactCount(p, uid, it.activityId);
                return short > 0 && daysLeft < short;
            });
        }

        async function pactFetch(force) {
            var uid = modesUid();
            if (!uid || !canPersistUserData('pactFetch')) return [];
            if (_pactCache.uid !== uid) _pactCache = { at: 0, list: [], uid: uid };
            if (!force && _pactCache.at && (modesNow() - _pactCache.at) < PACT_CACHE_TTL_MS) {
                return _pactCache.list;
            }
            if (_pactFetchInFlight) return _pactFetchInFlight;

            _pactFetchInFlight = (async function () {
                var list = [];
                var col = collection(db, PACT_COL);
                try {
                    // Same composite index shape as challenges. Every status is
                    // included on purpose: a refund owed on a declined or
                    // expired invite lives in a terminal document, so narrowing
                    // this would strand escrowed Grit.
                    var q = _pactIndexMissing
                        ? query(col, where('participants', 'array-contains', uid))
                        : query(col, where('participants', 'array-contains', uid),
                                     where('status', 'in', PACT_ALL_STATUSES));
                    var snap = await getDocs(q);
                    snap.forEach(function (d) { list.push(Object.assign({ id: d.id }, d.data())); });
                } catch (err) {
                    if (!_pactIndexMissing && err && (err.code === 'failed-precondition' ||
                        /index/i.test(err.message || ''))) {
                        console.warn('Pacts: composite index missing, falling back to unfiltered query.');
                        _pactIndexMissing = true;
                        _pactFetchInFlight = null;
                        return pactFetch(true);
                    }
                    console.warn('Pact fetch failed:', err && err.message);
                    return _pactCache.list;
                }
                _pactCache = { at: modesNow(), list: list, uid: uid };
                return list;
            })();

            try { return await _pactFetchInFlight; }
            finally { _pactFetchInFlight = null; }
        }

        function pactGet(id) {
            return _pactCache.list.filter(function (p) { return p.id === id; })[0] || null;
        }

        // ── Create (the initiator escrows immediately) ────────────────────
        async function pactCreate(partnerUid, partnerName, term, days) {
            var uid = modesUid();
            if (!uid) throw new Error('Not signed in.');
            if (!canPersistUserData('pactCreate')) throw new Error('Your account is not loaded yet.');
            if (((window.userData.friends) || []).indexOf(partnerUid) === -1) {
                throw new Error('You can only start a Pact with someone on your friends list.');
            }
            if (modesActive()) throw new Error('You already have a mode running. Only one at a time for now.');

            await pactFetch(true);
            var live = _pactCache.list.filter(function (p) {
                return p.status === 'pending' || p.status === 'active';
            });
            if (live.length) throw new Error('You already have a Pact open. Finish or withdraw it first.');

            try { cancelPendingUserDataSave(); } catch (e) {}
            await saveUserData();

            var id = modesNewId('pc');
            var now = modesNow();
            var payload = {
                id: id,
                schemaVersion: PACT_SCHEMA_VERSION,
                participants: [uid, partnerUid],
                createdBy: uid,
                partner: partnerUid,
                names: {},
                status: 'pending',
                stake: PACT_WAGER,
                pot: PACT_WAGER,
                durationDays: days,
                createdAt: now,
                expiresAt: now + PACT_INVITE_DAYS * 86400000,
                startedAt: null,
                endsAt: null,
                terms: {},
                progress: {},
                outcome: null,
                failedBy: null,
                resolvedAt: null,
                payout: {},
                payoutClaimed: {},
                seen: {}
            };
            payload.names[uid] = pactMyName();
            payload.names[partnerUid] = partnerName || 'A friend';
            payload.terms[uid] = term;
            // Per-activity counters from the start. The partner's map stays
            // empty until they accept and name their own activities.
            payload.progress[uid] = {};
            payload.progress[partnerUid] = {};
            payload.payout[uid] = 0;
            payload.payout[partnerUid] = 0;

            var newBalance = null;
            await runTransaction(db, async function (tx) {
                var bal = await vsReadBalance(tx, uid);
                if (bal.balance < PACT_WAGER) throw new Error('SHORTFALL:' + (PACT_WAGER - bal.balance));
                newBalance = bal.balance - PACT_WAGER;
                tx.update(bal.ref, {
                    'grit.balance': newBalance,
                    'grit.lifetimeSpent': bal.spent + PACT_WAGER
                });
                tx.set(doc(db, PACT_COL, id), payload);
            });

            vsMirrorBalance(newBalance, -PACT_WAGER, 'mode_pact_stake',
                { pactId: id, role: 'initiator', partnerUid: partnerUid });
            _pactCache.list.push(payload);
            return payload;
        }

        // ── Accept (the partner sets their OWN activity and target) ───────
        async function pactAccept(id, term) {
            var uid = modesUid();
            if (!uid) throw new Error('Not signed in.');
            if (modesActive()) throw new Error('You already have a mode running. Only one at a time for now.');
            try { cancelPendingUserDataSave(); } catch (e) {}
            await saveUserData();

            var ref = doc(db, PACT_COL, id);
            var newBalance = null, started = 0, ends = 0, partnerName = '';

            await runTransaction(db, async function (tx) {
                var snap = await tx.get(ref);
                if (!snap.exists()) throw new Error('This Pact no longer exists.');
                var p = snap.data();
                if (p.status !== 'pending') throw new Error('This Pact is no longer open.');
                if (p.partner !== uid) throw new Error('This invite is not yours to accept.');
                if (modesNow() > p.expiresAt) throw new Error('This invite has expired.');

                var bal = await vsReadBalance(tx, uid);
                if (bal.balance < p.stake) throw new Error('SHORTFALL:' + (p.stake - bal.balance));

                // "the pact becomes active for both starting the next day"
                // (spec §6). Tomorrow's local midnight is the start, so neither
                // side gets a half-day of window the other didn't.
                var tomorrow = new Date(); tomorrow.setHours(0, 0, 0, 0);
                tomorrow.setDate(tomorrow.getDate() + 1);
                started = tomorrow.getTime();
                ends = started + p.durationDays * 86400000;
                newBalance = bal.balance - p.stake;
                partnerName = pactName(p, p.createdBy);

                tx.update(bal.ref, {
                    'grit.balance': newBalance,
                    'grit.lifetimeSpent': bal.spent + p.stake
                });
                var patch = {
                    status: 'active',
                    pot: p.stake * 2,
                    startedAt: started,
                    endsAt: ends
                };
                patch['terms.' + uid] = term;
                patch['names.' + uid] = pactMyName();
                // Not seeding progress here on purpose: the accept rule's
                // hasOnly() list does not include it, and the first completion's
                // dotted write creates the map anyway.
                tx.update(ref, patch);
            });

            vsMirrorBalance(newBalance, -PACT_WAGER, 'mode_pact_stake',
                { pactId: id, role: 'partner' });

            await pactFetch(true);
            var live = pactGet(id);
            await modesAdoptPact(live || { id: id, startedAt: started, endsAt: ends, durationDays: 0 }, term);
            return { startedAt: started, endsAt: ends, partnerName: partnerName };
        }

        // The local mode object's own read-tolerance seam, mirroring the shared
        // document's. A pact adopted before multi-activity shipped stored
        // activityId/activityName/target directly on m.active; one adopted
        // since stores `items`. Nothing outside these two functions looks.
        function modePactItems(a) {
            if (!a) return [];
            if (Array.isArray(a.items)) {
                return a.items.filter(function (it) { return it && it.activityId; });
            }
            if (a.activityId) {
                return [{ activityId: String(a.activityId),
                          activityName: a.activityName,
                          target: Math.max(1, a.target || 1) }];
            }
            return [];
        }

        function modePactHasActivity(a, activityId) {
            var key = String(activityId);
            return modePactItems(a).some(function (it) { return String(it.activityId) === key; });
        }

        // The local half of a pact. The mode object is what the Modes page
        // draws and what the completion hook counts against; the shared
        // document is the record both accounts agree on.
        async function modesAdoptPact(p, term) {
            var m = modesState();
            if (!m) return;
            var uid = modesUid();
            // `items` mirrors the shared document's term so the panel and the
            // completion hook never have to reach for the pact to know which
            // activities count. A pact adopted before multi-activity shipped
            // carries the single-activity fields instead, which is why every
            // read of them goes through modePactItems().
            m.active = {
                kind: 'pact',
                id: modesNewId('md'),
                pactId: p.id,
                startedAt: new Date().toISOString(),
                startedDay: modesToday(),
                cost: PACT_WAGER,
                items: (term.items || [term]).map(function (it) {
                    return { activityId: String(it.activityId),
                             activityName: it.activityName,
                             target: Math.max(1, it.target || 1) };
                }),
                partnerUid: pactOther(p, uid),
                partnerName: pactName(p, pactOther(p, uid)),
                endsAt: p.endsAt,
                windowStartsAt: p.startedAt
            };
            modesApplyTheme();
            try { await saveUserData(); } catch (e) {}
            try { modesRenderPage(); } catch (e) {}
        }

        // ── Progress ──────────────────────────────────────────────────────
        // One completion of ONE of my activities, mirrored. Guarded on status
        // and on the window, so a completion logged before the pact starts or
        // after it ends counts for nothing — which is what "within the shared
        // window" means.
        //
        // The write shape follows the document's shape, and that is not
        // cosmetic: a pact created under the single-activity schema stores
        // progress[uid] as a NUMBER, and writing progress.<uid>.<activityId>
        // into it would replace that number with a map and silently zero
        // everything the user had already done. So an old pact keeps being
        // written the old way — it has exactly one activity, so there is
        // nothing the new shape would buy it.
        async function pactCommitProgress(id, activityId, delta) {
            var uid = modesUid();
            if (!uid) return null;
            var key = String(activityId);
            var ref = doc(db, PACT_COL, id);
            var result = null;
            try {
                await runTransaction(db, async function (tx) {
                    var snap = await tx.get(ref);
                    if (!snap.exists()) return;
                    var p = Object.assign({ id: id }, snap.data());
                    if (p.status !== 'active') return;
                    var now = modesNow();
                    if (now < p.startedAt || now > p.endsAt) return;

                    var item = pactItems(p, uid).filter(function (it) {
                        return String(it.activityId) === key;
                    })[0];
                    if (!item) return;
                    var target = Math.max(1, item.target || 1);

                    var before = pactCount(p, uid, key);
                    var after = Math.max(0, Math.min(target, before + delta));
                    if (after === before) return;

                    var legacy = typeof (p.progress || {})[uid] === 'number';
                    var patch = {};
                    patch[legacy ? 'progress.' + uid : 'progress.' + uid + '.' + key] = after;
                    tx.update(ref, patch);
                    result = { activityId: key, mine: after, target: target, legacy: legacy };
                });
            } catch (e) { console.warn('Pact progress failed:', e && e.message); }
            if (result) {
                var cached = pactGet(id);
                if (cached) {
                    cached.progress = cached.progress || {};
                    if (result.legacy) cached.progress[uid] = result.mine;
                    else {
                        if (typeof cached.progress[uid] !== 'object' || cached.progress[uid] === null) {
                            cached.progress[uid] = {};
                        }
                        cached.progress[uid][result.activityId] = result.mine;
                    }
                }
                await pactMaybeResolve(id);
            }
            return result;
        }

        // ── Resolution ────────────────────────────────────────────────────
        // Both hit → both get their stake back plus 30%. Either falls short,
        // or runs out of reachable days → the pact breaks for BOTH and both
        // stakes are gone. `failedBy` names who fell short, deliberately: the
        // spec asks for that transparency rather than a softened message.
        function pactBuildResolution(p) {
            var ps = p.participants || [];
            var a = ps[0], b = ps[1];
            var aHit = pactHit(p, a), bHit = pactHit(p, b);
            var payout = {};
            payout[a] = 0; payout[b] = 0;
            if (aHit && bHit) {
                var back = p.stake + Math.round(p.stake * MODE_WAGER_RETURN);
                payout[a] = back; payout[b] = back;
                return { status: 'resolved', outcome: 'kept', failedBy: null,
                         resolvedAt: modesNow(), pot: 0, payout: payout };
            }
            var failed = !aHit && !bHit ? 'both' : (aHit ? b : a);
            return { status: 'resolved', outcome: 'broken', failedBy: failed,
                     resolvedAt: modesNow(), pot: 0, payout: payout };
        }

        async function pactMaybeResolve(id) {
            var uid = modesUid();
            var ref = doc(db, PACT_COL, id);
            var resolved = null;
            try {
                await runTransaction(db, async function (tx) {
                    var snap = await tx.get(ref);
                    if (!snap.exists()) return;
                    var p = snap.data();
                    if (p.status !== 'active') return;
                    var ps = p.participants || [];
                    var bothHit = ps.every(function (u) { return pactHit(p, u); });
                    var over = modesNow() > p.endsAt;
                    var doomed = ps.some(function (u) { return pactImpossible(p, u); });
                    if (!bothHit && !over && !doomed) return;
                    var patch = pactBuildResolution(p);
                    tx.update(ref, patch);
                    resolved = Object.assign({}, p, patch);
                });
            } catch (e) { console.warn('Pact resolve failed:', e && e.message); }
            if (resolved) {
                await pactFetch(true);
                await pactSettleLocal(resolved);
            }
            return !!resolved;
        }

        // Ends the local mode and shows the card. Runs on whichever client
        // notices first; the other picks it up from the document on its own
        // next pass, because the mode object carries the pactId.
        async function pactSettleLocal(p) {
            var uid = modesUid();
            var m = modesState();
            if (!m) return;
            var them = pactOther(p, uid);
            var themName = pactName(p, them);
            var kept = p.outcome === 'kept';
            var iFailed = p.failedBy === uid || p.failedBy === 'both';
            var theyFailed = p.failedBy === them || p.failedBy === 'both';

            // One line per activity per side, so a broken pact shows exactly
            // which commitment fell short rather than a total that hides it.
            function sideLines(who, label) {
                return pactItems(p, who).map(function (it) {
                    var target = Math.max(1, it.target || 1);
                    return label + ' — ' + (it.activityName || 'Activity') + ' ' +
                           Math.min(pactCount(p, who, it.activityId), target) + '/' + target;
                });
            }
            var lines = sideLines(uid, 'You').concat(sideLines(them, themName));

            var note;
            if (kept) {
                note = 'Both of you held it. Your ' + p.stake + ' Grit is back with ' +
                       Math.round(p.stake * MODE_WAGER_RETURN) + ' on top.';
            } else if (iFailed && theyFailed) {
                note = 'Neither of you got there. Both stakes are gone — that was the deal.';
            } else if (iFailed) {
                note = 'You fell short, so the pact broke for both of you. ' + themName +
                       ' lost their stake too. They already know.';
            } else {
                note = themName + ' fell short, so the pact broke for both of you. ' +
                       'You hit everything you set yourself — that part still happened.';
            }

            var res = {
                kind: 'pact', outcome: kept ? 'won' : 'lost',
                title: kept ? 'Pact kept' : 'Pact broken',
                headline: kept ? '+' + (p.stake + Math.round(p.stake * MODE_WAGER_RETURN)) + ' Grit'
                               : '−' + p.stake + ' Grit',
                lines: lines, note: note
            };

            if (m.active && m.active.kind === 'pact' && m.active.pactId === p.id) {
                await modesEnd(kept ? 'completed' : 'failed',
                               (kept ? 'Kept with ' : 'Broken with ') + themName);
            }
            modesResolveNow(res);
            try { await saveUserData(); } catch (e) {}
        }

        // ── Terminate a pending invite (decline / withdraw / expire) ───────
        async function pactTerminatePending(id, nextStatus) {
            var uid = modesUid();
            var ref = doc(db, PACT_COL, id);
            var didRun = false;
            await runTransaction(db, async function (tx) {
                var snap = await tx.get(ref);
                if (!snap.exists()) return;
                var p = snap.data();
                if (p.status !== 'pending') return;
                if ((p.participants || []).indexOf(uid) === -1) return;
                if (nextStatus === 'declined' && p.partner !== uid) return;
                if (nextStatus === 'cancelled' && p.createdBy !== uid) return;
                if (nextStatus === 'expired' && modesNow() <= p.expiresAt) return;

                var payout = {};
                (p.participants || []).forEach(function (u) { payout[u] = 0; });
                // Only the initiator has paid while a pact is pending.
                payout[p.createdBy] = p.pot;
                tx.update(ref, {
                    status: nextStatus, outcome: nextStatus, failedBy: null,
                    resolvedAt: modesNow(), pot: 0, payout: payout
                });
                didRun = true;
            });
            if (didRun) await pactFetch(true);
            return didRun;
        }

        // ── Payout claim ──────────────────────────────────────────────────
        // Automatic, no button, idempotent — `payoutClaimed[myUid]` is the
        // only key this user may write and only false → true.
        async function pactClaimPayout(p) {
            var uid = modesUid();
            if (!uid) return 0;
            var owed = (p.payout && p.payout[uid]) || 0;
            if (owed <= 0) return 0;
            if (p.payoutClaimed && p.payoutClaimed[uid]) return 0;

            try { cancelPendingUserDataSave(); } catch (e) {}
            await saveUserData();

            var ref = doc(db, PACT_COL, p.id);
            var credited = 0, newBalance = null;
            await runTransaction(db, async function (tx) {
                var snap = await tx.get(ref);
                if (!snap.exists()) return;
                var live = snap.data();
                var amount = (live.payout && live.payout[uid]) || 0;
                if (amount <= 0) return;
                if (live.payoutClaimed && live.payoutClaimed[uid]) return;
                var bal = await vsReadBalance(tx, uid);
                newBalance = bal.balance + amount;
                credited = amount;
                tx.update(bal.ref, {
                    'grit.balance': newBalance,
                    'grit.lifetimeEarned': bal.earned + amount
                });
                var patch = {};
                patch['payoutClaimed.' + uid] = true;
                tx.update(ref, patch);
            });
            if (credited > 0) {
                vsMirrorBalance(newBalance, credited,
                    p.outcome === 'kept' ? 'mode_pact_payout' : 'mode_pact_refund',
                    { pactId: p.id });
                if (p.payoutClaimed) p.payoutClaimed[uid] = true;
            }
            return credited;
        }

        // ── Lazy maintenance ──────────────────────────────────────────────
        async function pactRunMaintenance() {
            if (_pactMaintaining) return;
            _pactMaintaining = true;
            try {
                var uid = modesUid();
                if (!uid) return;
                var list = await pactFetch(false);
                var touched = false;
                for (var i = 0; i < list.length; i++) {
                    var p = list[i];
                    try {
                        if (p.status === 'pending' && modesNow() > p.expiresAt) {
                            if (await pactTerminatePending(p.id, 'expired')) touched = true;
                        } else if (p.status === 'active') {
                            if (await pactMaybeResolve(p.id)) touched = true;
                        }
                    } catch (e) { console.warn('Pact maintenance step failed:', e && e.message); }
                }
                if (touched) list = await pactFetch(true);

                for (var j = 0; j < list.length; j++) {
                    var q = list[j];
                    if (!pactIsTerminal(q.status)) continue;
                    try {
                        var got = await pactClaimPayout(q);
                        if (got > 0) showToast('+' + got + ' Grit returned from your Pact', 'olive');
                    } catch (e) { console.warn('Pact claim failed:', e && e.message); }
                }

                // A resolved pact the local mode never noticed (the partner's
                // client resolved it while this one was closed).
                var m = modesState();
                if (m && m.active && m.active.kind === 'pact') {
                    var mine = pactGet(m.active.pactId);
                    if (mine && mine.status === 'resolved') await pactSettleLocal(mine);
                    else if (mine && pactIsTerminal(mine.status)) {
                        await modesEnd('ended', 'Pact ended before it started');
                    }
                }

                // The INITIATOR's side of acceptance. Their stake was escrowed
                // when they sent the request, but the accept happens on the
                // other person's device — so this is the only place their
                // client learns the pact is live and adopts it as their mode.
                if (m && !m.active) {
                    for (var k = 0; k < list.length; k++) {
                        var live = list[k];
                        if (live.status !== 'active') continue;
                        var term = pactTerm(live, uid);
                        if (!term) continue;
                        await modesAdoptPact(live, term);
                        showToast(pactName(live, pactOther(live, uid)) +
                                  ' accepted your Pact — it is live.', 'green', null, 'handshake');
                        break;
                    }
                }
            } finally {
                _pactMaintaining = false;
            }
        }

        // Pending invites addressed to this user, for the badge and the card.
        async function pactCheckInvites() {
            var uid = modesUid();
            if (!uid) return [];
            var list = await pactFetch(false);
            var mine = list.filter(function (p) {
                return p.status === 'pending' && p.partner === uid && modesNow() <= p.expiresAt;
            });
            if (mine.length) modesRefreshBanner();
            return mine;
        }
        window.pactCheckInvites = pactCheckInvites;

        // ══════════════════════════════════════════════════════════════════
        //  THE MODES PAGE  (Pursuits › Modes)
        // ══════════════════════════════════════════════════════════════════

        function modesRoot() { return document.getElementById('modesRoot'); }
        function modesPageVisible() {
            var el = document.getElementById('mkEmptyPursuitsModes');
            return !!(el && el.classList.contains('active'));
        }

        window.modesOpenPage = function () {
            modesRenderPage();
            modesRunPass(false).catch(function () {});
            pactCheckInvites().then(function () { modesRenderPage(); }).catch(function () {});
        };

        // ── Locating an activity by id ────────────────────────────────────
        // Modes store activity ids; completing one needs the three indices the
        // app's own completeActivity() takes. One lookup, used by the habit
        // panel, the habit overlay and the "take me to it" fallback.
        function modeActivityPos(activityId) {
            var dims = (window.userData && window.userData.dimensions) || [];
            for (var di = 0; di < dims.length; di++) {
                var paths = dims[di].paths || [];
                for (var pi = 0; pi < paths.length; pi++) {
                    var acts = paths[pi].activities || [];
                    for (var ai = 0; ai < acts.length; ai++) {
                        if (String(acts[ai].id) === String(activityId)) {
                            return { di: di, pi: pi, ai: ai, act: acts[ai] };
                        }
                    }
                }
            }
            return null;
        }

        // Can this activity be marked right now? Mirrors the app's own gate so
        // a mode never offers a button that would silently do nothing.
        function modeCanMark(activityId) {
            var pos = modeActivityPos(activityId);
            if (!pos) return false;
            var act = pos.act;
            if (typeof canCompleteActivity === 'function' && !canCompleteActivity(act)) return false;
            var allowMulti = act.allowMultiplePerDay && act.frequency !== 'occasional';
            if (!allowMulti && isCompletedToday(act)) return false;
            return true;
        }

        // Mark an activity straight from a mode surface. The mode's own
        // completion hook is already wired into completeActivity, so counts,
        // milestones and resolutions all happen exactly as they would from the
        // Activities tab — this is the same action, reached from here.
        let _modeMarking = false;
        window.modeMark = async function (activityId) {
            if (_modeMarking) return false;
            var pos = modeActivityPos(activityId);
            if (!pos) { showToast('That activity no longer exists.', 'red'); return false; }
            if (!modeCanMark(activityId)) {
                showToast('Already marked today.', 'olive');
                return false;
            }
            _modeMarking = true;
            try {
                await window.completeActivity(pos.di, pos.pi, pos.ai);
            } catch (e) {
                console.warn('Mode mark failed', e && e.message);
                showToast('That did not go through — try again.', 'red');
                return false;
            } finally {
                _modeMarking = false;
            }
            // No confirmation of our own: completeActivity already fires the
            // app's XP toast, which says more than "done" would.
            try { modesRenderPage(); } catch (e) {}
            try { modesRefreshBanner(); } catch (e) {}
            return true;
        };

        // The fallback route to an activity. It goes through the v5 nav rather
        // than switchSubTab alone, so the section strip, the page title and the
        // nav rings all agree with where you actually landed — reaching in past
        // the nav was what left the header naming the page you had just left.
        window.modeGoToActivity = function (activityId) {
            var pos = modeActivityPos(activityId);
            if (!pos) {
                if (window.mkGoSub) window.mkGoSub(2, 0);
                return;
            }
            if (window.mkGoSub) window.mkGoSub(2, 1);        // Activities › Categories
            setTimeout(function () {
                try { window.categoriesGoToActivity(pos.di, pos.pi, pos.ai); } catch (e) {}
            }, 60);
        };

        // The balance chip lives in a fixed host outside #modesRoot: the nav
        // borrows that node for the page title row, and #modesRoot is rewritten
        // wholesale on every render — writing the chip into it would either
        // destroy the borrowed node or leave a second copy behind. Only the
        // number is rewritten here.
        function modesRenderGritChip() {
            var n = document.getElementById('modesGritVal');
            if (n) n.textContent = (gritBalance() || 0).toLocaleString();
        }

        function modesRenderPage() {
            var host = modesRoot();
            if (!host) return;
            if (!window.userData) { host.innerHTML = ''; return; }
            var m = modesState();
            var a = m ? m.active : null;

            var html = '';
            // No title and no blurb of its own. The v5 nav renders every page's
            // name as .mk-page-heading above the content, and the balance chip
            // is lifted onto that same line, so "Modes" and the counter share a
            // row. The line of explanation that used to sit under them is gone
            // — each card already says what its mode does, and the page reads
            // quieter without a paragraph repeating it. The chip's markup lives
            // in index.html; only its number is written here.
            modesRenderGritChip();

            html += modesInviteCardsHtml();

            if (a) {
                html += modesActiveCardHtml(a);
                // Said once, under the mode it is about — not repeated on every
                // card it disables.
                html += '<div class="md-locked-note">One at a time. End ' +
                        modeEsc(MODE_META[a.kind].name) + ' to pick another.</div>';
            }

            html += '<div class="md-grid">';
            MODE_KINDS.forEach(function (k) {
                html += modesCatalogCardHtml(k, a);
            });
            html += '</div>';

            if (m && m.history && m.history.length) {
                html += '<div class="md-hist">' +
                          '<div class="md-hist-kicker">Past runs</div>' +
                          m.history.slice(0, 6).map(function (h) {
                              var meta = MODE_META[h.kind] || { name: h.kind };
                              return '<div class="md-hist-row md-hist-' + modeEsc(h.outcome) + '">' +
                                       '<span class="md-hist-name">' + modeEsc(meta.name) + '</span>' +
                                       '<span class="md-hist-sum">' + modeEsc(h.summary || '') + '</span>' +
                                       '<span class="md-hist-out">' + modeEsc(modeOutcomeWord(h.outcome)) + '</span>' +
                                     '</div>';
                          }).join('') +
                        '</div>';
            }

            host.innerHTML = html;
        }
        window.modesRenderPage = modesRenderPage;

        function modeOutcomeWord(o) {
            if (o === 'completed') return 'Completed';
            if (o === 'failed')    return 'Lost';
            if (o === 'expired')   return 'Expired';
            return 'Ended';
        }

        function modesCatalogCardHtml(kind, active) {
            var meta = MODE_META[kind];
            var isActive = active && active.kind === kind;
            var blocked = !!active && !isActive;
            var m = modesState();
            var resumable = kind === 'habit' && m && m.suspendedHabit && !active;

            return '<div class="md-card' + (isActive ? ' is-live' : '') + (blocked ? ' is-blocked' : '') +
                        ' md-card-' + kind + '">' +
                     // Icon, then the name beside it, then the tag at the end
                     // of the same line — one row instead of two.
                     '<div class="md-card-top">' +
                       '<span class="md-card-icon">' + phIcon(meta.icon) + '</span>' +
                       '<span class="md-card-name">' + modeEsc(meta.name) + '</span>' +
                       '<span class="md-card-tag">' + modeEsc(meta.tag) + '</span>' +
                     '</div>' +
                     '<p class="md-card-blurb">' + modeEsc(meta.blurb) + '</p>' +
                     '<div class="md-card-foot">' +
                       '<span class="md-card-cost">' + phIcon('diamond', { weight: 'fill', lead: true }) + modeEsc(modeCostLabel(kind)) + '</span>' +
                       (isActive
                         ? '<span class="md-card-live">Running</span>'
                         : '<button type="button" class="md-card-btn' + (blocked ? ' is-off' : '') + '" ' +
                            (blocked ? 'disabled ' : '') +
                            'onclick="modesOpenSetup(\'' + kind + '\')">' +
                            (resumable ? 'Resume' : 'Activate') + '</button>') +
                     '</div>' +
                   '</div>';
        }

        // ── The active-mode card ──────────────────────────────────────────
        function modesActiveCardHtml(a) {
            var meta = MODE_META[a.kind];
            var body = '';
            if (a.kind === 'habit')     body = habitPanelHtml(a);
            if (a.kind === 'berserk')   body = berserkPanelHtml(a);
            if (a.kind === 'recovery')  body = recoveryPanelHtml(a);
            if (a.kind === 'insurance') body = insurancePanelHtml(a);
            if (a.kind === 'stake')     body = stakePanelHtml(a);
            if (a.kind === 'pact')      body = pactPanelHtml(a);
            if (a.kind === 'focus')     body = focusPanelHtml(a);

            return '<div class="md-live md-live-' + a.kind + '">' +
                     '<div class="md-live-head">' +
                       '<span class="md-live-pulse" aria-hidden="true"></span>' +
                       '<div class="md-live-titles">' +
                         '<div class="md-live-eyebrow">Running now</div>' +
                         '<div class="md-live-name">' + modeEsc(meta.name) + '</div>' +
                       '</div>' +
                       '<button type="button" class="md-live-end" onclick="modesConfirmEnd()">End</button>' +
                     '</div>' +
                     '<div class="md-live-body">' + body + '</div>' +
                   '</div>';
        }

        function modeBarHtml(done, total, cls) {
            var pct = total > 0 ? Math.max(0, Math.min(100, (done / total) * 100)) : 0;
            return '<div class="md-bar ' + (cls || '') + '" role="progressbar" aria-valuemin="0" ' +
                     'aria-valuemax="' + (total || 0) + '" aria-valuenow="' + (done || 0) + '">' +
                     '<span class="md-bar-fill" style="width:' + pct.toFixed(1) + '%"></span>' +
                   '</div>';
        }

        // "in 12 days · 10 Sep" — a day count on its own is hard to picture.
        function modeDateLabel(dateStr) {
            try {
                var d = new Date(dateStr + 'T00:00:00');
                return d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
            } catch (e) { return dateStr; }
        }

        // The one action a mode panel can offer for an activity: mark it, right
        // here. Navigation is the fallback, not the first move.
        function modeMarkBtnHtml(activityId, doneToday) {
            if (doneToday) return '<span class="md-chip md-chip-done">Done today</span>';
            if (!modeCanMark(activityId)) {
                return '<button type="button" class="md-mark md-mark-ghost" ' +
                       'onclick="modeGoToActivity(\'' + modeEsc(activityId) + '\')">Open</button>';
            }
            return '<button type="button" class="md-mark" ' +
                   'onclick="modeMark(\'' + modeEsc(activityId) + '\')">Mark done</button>';
        }

        function habitPanelHtml(a) {
            var today = modesToday();
            var html = '<div class="md-metric">' +
                         '<span class="md-metric-n">' + (a.daysElapsed || 0) + '</span>' +
                         '<span class="md-metric-of">of ' + a.targetDays + ' days</span>' +
                       '</div>' +
                       modeBarHtml(a.daysElapsed || 0, a.targetDays, 'md-bar-blue');
            html += (a.habits || []).map(function (h) {
                var doneToday = h.lastCompletedDay === today;
                return '<div class="md-hrow' + (doneToday ? ' is-done' : '') + '">' +
                         '<div class="md-hrow-top">' +
                           '<span class="md-hrow-name">' + modeEsc(h.activityName) + '</span>' +
                           '<span class="md-hrow-count">' + (h.completions || 0) + ' / ' + (a.daysElapsed || 0) + '</span>' +
                         '</div>' +
                         modeBarHtml(h.completions || 0, a.targetDays, 'md-bar-green') +
                         '<div class="md-hrow-meta">' +
                           '<span class="md-chip">' + modeTimeLabel(h.windowStart) + ' – ' + modeTimeLabel(h.windowEnd) + '</span>' +
                           (h.anchor ? '<span class="md-chip md-chip-soft">' + modeEsc(h.anchor) + '</span>' : '') +
                           modeMarkBtnHtml(h.activityId, doneToday) +
                         '</div>' +
                       '</div>';
            }).join('');
            return html;
        }

        function berserkPanelHtml(a) {
            var earned = berserkEarned(a);
            return '<div class="md-metric md-metric-hot">' +
                     '<span class="md-metric-n">' + earned.toLocaleString() + '</span>' +
                     '<span class="md-metric-of">of ' + a.targetXP.toLocaleString() + ' XP</span>' +
                   '</div>' +
                   modeBarHtml(earned, a.targetXP, 'md-bar-hot') +
                   '<div class="md-hrow-meta">' +
                     '<span class="md-chip md-chip-hot" data-md-clock="berserk">' + modeCountdownLabel(a.endsAt) + '</span>' +
                     '<span class="md-chip">' + a.hours + '-hour window</span>' +
                     '<span class="md-chip">Win +30% · Miss −30%</span>' +
                   '</div>' +
                   '<p class="md-note">Log anywhere in the app — the target fills either way.</p>';
        }

        function recoveryPanelHtml(a) {
            return (a.activities || []).map(function (x) {
                var act = gritFindActivity(x.activityId);
                var cur = act ? (act.streak || 0) : 0;
                var atCeiling = cur >= x.ceiling;
                var doneToday = !modeCanMark(x.activityId);
                return '<div class="md-hrow' + (atCeiling ? ' is-done' : '') + '">' +
                         '<div class="md-hrow-top">' +
                           '<span class="md-hrow-name">' + modeEsc(x.activityName) + '</span>' +
                           '<span class="md-hrow-count">' + cur + ' / ' + x.ceiling + '</span>' +
                         '</div>' +
                         modeBarHtml(cur, x.ceiling, 'md-bar-blue') +
                         '<div class="md-hrow-meta">' +
                           '<span class="md-chip">Peak ' + x.ceiling + '</span>' +
                           (atCeiling
                             ? '<span class="md-chip md-chip-done">At peak</span>'
                             : '<span class="md-chip md-chip-soft">+1 per completion</span>') +
                           (atCeiling ? '' : modeMarkBtnHtml(x.activityId, doneToday)) +
                         '</div>' +
                       '</div>';
            }).join('') +
            '<p class="md-note">Ends itself once every activity here is back at its own peak.</p>';
        }

        function insurancePanelHtml(a) {
            var m = modesState();
            var days = insuranceDaysOn(a);
            return '<div class="md-metric">' +
                     '<span class="md-metric-n">' + days + '</span>' +
                     '<span class="md-metric-of">days insured</span>' +
                   '</div>' +
                   (a.activities || []).map(function (x) {
                       var act = gritFindActivity(x.activityId);
                       var held = (m && m.streakOffsets[String(x.activityId)]) || 0;
                       return '<div class="md-hrow">' +
                                '<div class="md-hrow-top">' +
                                  '<span class="md-hrow-name">' + modeEsc(x.activityName) + '</span>' +
                                  '<span class="md-hrow-count">Streak ' + (act ? (act.streak || 0) : 0) + '</span>' +
                                '</div>' +
                                '<div class="md-hrow-meta">' +
                                  '<span class="md-chip md-chip-soft">Downside suspended</span>' +
                                  (held > 0 ? '<span class="md-chip md-chip-done">' + held + ' day' +
                                              (held === 1 ? '' : 's') + ' held</span>' : '') +
                                  modeMarkBtnHtml(x.activityId, !modeCanMark(x.activityId)) +
                                '</div>' +
                              '</div>';
                   }).join('') +
                   '<p class="md-note">Missing costs nothing. Logging still counts as it always did.</p>';
        }

        function stakePanelHtml(a) {
            var left = stakeDaysLeft(a);
            return '<div class="md-metric">' +
                     '<span class="md-metric-n">' + stakeTotalCount(a) + '</span>' +
                     '<span class="md-metric-of">of ' + stakeTotalTarget(a) + ' completions</span>' +
                   '</div>' +
                   (a.items || []).map(function (it) {
                       var done = (it.count || 0) >= it.target;
                       return '<div class="md-hrow' + (done ? ' is-done' : '') + '">' +
                                '<div class="md-hrow-top">' +
                                  '<span class="md-hrow-name">' + modeEsc(it.activityName) + '</span>' +
                                  '<span class="md-hrow-count">' + Math.min(it.count || 0, it.target) +
                                    ' / ' + it.target + '</span>' +
                                '</div>' +
                                modeBarHtml(it.count || 0, it.target, done ? 'md-bar-green' : 'md-bar-blue') +
                                (done ? '' : '<div class="md-hrow-meta">' +
                                   modeMarkBtnHtml(it.activityId, !modeCanMark(it.activityId)) + '</div>') +
                              '</div>';
                   }).join('') +
                   '<div class="md-hrow-meta">' +
                     '<span class="md-chip' + (left <= 1 ? ' md-chip-hot' : '') + '">' +
                       (left > 0 ? left + ' day' + (left === 1 ? '' : 's') + ' left · ' +
                                   modeDateLabel(stakeEndDay(a))
                                 : 'Window closed') + '</span>' +
                     '<span class="md-chip">' + phIcon('diamond', { weight: 'fill', lead: true }) + a.wager + ' staked</span>' +
                     '<span class="md-chip">Win ' + phIcon('diamond', { weight: 'fill', lead: true }) + (a.wager + Math.round(a.wager * MODE_WAGER_RETURN)) + '</span>' +
                   '</div>' +
                   '<p class="md-note">All or nothing. One target short is the same as none.</p>';
        }

        function focusPanelHtml(a) {
            var nowMins = modeMinutesNow();
            var s = modeMins(a.windowStart), e = modeMins(a.windowEnd);
            var open = s !== null && e !== null && modeInWindow(s, e, nowMins, 0, 0);
            return '<div class="md-metric">' +
                     '<span class="md-metric-n">' + (a.daysElapsed || 0) + '</span>' +
                     '<span class="md-metric-of">of ' + a.targetDays + ' days</span>' +
                   '</div>' +
                   modeBarHtml(a.daysElapsed || 0, a.targetDays, 'md-bar-blue') +
                   '<div class="md-hrow-meta">' +
                     '<span class="md-chip' + (open ? ' md-chip-done' : '') + '">' +
                       modeTimeLabel(a.windowStart) + ' – ' + modeTimeLabel(a.windowEnd) +
                       (open ? ' · open now' : '') + '</span>' +
                     '<span class="md-chip">+' + Math.round(FOCUS_MULTIPLIER * 100) + '% XP inside</span>' +
                     '<span class="md-chip">' + (a.bonusCount || 0) + ' boosted · +' + (a.bonusXP || 0) + ' XP</span>' +
                   '</div>' +
                   '<p class="md-note">Anything logged inside the window earns it — not tied to one activity.</p>';
        }

        // The two-column head stays the headline — one bar a side, so the
        // comparison the mode is built on survives however many activities
        // each person picked. The breakdown rows below it are Stake Mode's,
        // reused rather than re-invented, and they carry the mark buttons:
        // with several activities in play, one button at the bottom would have
        // no way to say which one it marks.
        function pactPanelHtml(a) {
            var p = pactGet(a.pactId);
            var uid = modesUid();
            var mine = p ? pactStats(p, uid) : { done: 0, total: 1, pct: 0 };
            var theirs = p ? pactStats(p, a.partnerUid) : { done: 0, total: 1, pct: 0 };
            var myItems = p ? pactItems(p, uid) : modePactItems(a);
            var theirItems = p ? pactItems(p, a.partnerUid) : [];
            var notStarted = a.windowStartsAt && modesNow() < a.windowStartsAt;
            var left = a.endsAt ? Math.max(0, Math.ceil((a.endsAt - modesNow()) / 86400000)) : 0;

            function sideLabel(items) {
                if (!items.length) return '—';
                if (items.length === 1) return items[0].activityName || 'Activity';
                return items.length + ' activities';
            }

            return '<div class="md-pact">' +
                     '<div class="md-pact-side">' +
                       '<div class="md-pact-who">You</div>' +
                       '<div class="md-pact-act">' + modeEsc(sideLabel(myItems)) + '</div>' +
                       '<div class="md-pact-n">' + mine.done + ' / ' + mine.total + '</div>' +
                       modeBarHtml(mine.done, mine.total, 'md-bar-blue') +
                     '</div>' +
                     '<div class="md-pact-link" aria-hidden="true"></div>' +
                     '<div class="md-pact-side">' +
                       '<div class="md-pact-who">' + modeEsc(a.partnerName) + '</div>' +
                       '<div class="md-pact-act">' + modeEsc(sideLabel(theirItems)) + '</div>' +
                       '<div class="md-pact-n">' + (theirItems.length ? theirs.done + ' / ' + theirs.total : '—') + '</div>' +
                       modeBarHtml(theirs.done, theirs.total || 1, 'md-bar-green') +
                     '</div>' +
                   '</div>' +
                   myItems.map(function (it) {
                       var target = Math.max(1, it.target || 1);
                       var count = p ? Math.min(pactCount(p, uid, it.activityId), target) : 0;
                       var done = count >= target;
                       return '<div class="md-hrow' + (done ? ' is-done' : '') + '">' +
                                '<div class="md-hrow-top">' +
                                  '<span class="md-hrow-name">' + modeEsc(it.activityName || 'Activity') + '</span>' +
                                  '<span class="md-hrow-count">' + count + ' / ' + target + '</span>' +
                                '</div>' +
                                modeBarHtml(count, target, done ? 'md-bar-green' : 'md-bar-blue') +
                                (done || notStarted ? '' : '<div class="md-hrow-meta">' +
                                   modeMarkBtnHtml(it.activityId, !modeCanMark(it.activityId)) + '</div>') +
                              '</div>';
                   }).join('') +
                   '<div class="md-hrow-meta">' +
                     '<span class="md-chip">' + (notStarted ? 'Starts tomorrow' : left + ' day' + (left === 1 ? '' : 's') + ' left') + '</span>' +
                     '<span class="md-chip">' + phIcon('diamond', { weight: 'fill', lead: true }) + PACT_WAGER + ' each</span>' +
                   '</div>' +
                   '<p class="md-note">If either of you falls short, it breaks for both.</p>';
        }

        // ── Pending pact invites ──────────────────────────────────────────
        function modesInviteCardsHtml() {
            var uid = modesUid();
            if (!uid) return '';
            var invites = (_pactCache.list || []).filter(function (p) {
                return p.status === 'pending' && p.partner === uid && modesNow() <= p.expiresAt;
            });
            var mineOut = (_pactCache.list || []).filter(function (p) {
                return p.status === 'pending' && p.createdBy === uid && modesNow() <= p.expiresAt;
            });
            var html = '';
            invites.forEach(function (p) {
                var from = pactName(p, p.createdBy);
                html += '<div class="md-invite">' +
                          '<div class="md-invite-top"><strong>' + modeEsc(from) + '</strong> wants a Pact with you</div>' +
                          '<div class="md-invite-body">' +
                            'They are committing to <strong>' + modeEsc(pactTermSummary(p, p.createdBy)) +
                            '</strong> over ' + p.durationDays + ' days. ' +
                            'Pick your own, and stake ' + phIcon('diamond', { weight: 'fill', lead: true }) + p.stake + '. One short and both stakes go.' +
                          '</div>' +
                          '<div class="md-invite-btns">' +
                            '<button type="button" class="md-btn md-btn-primary" onclick="pactOpenAccept(\'' + modeEsc(p.id) + '\')">Accept</button>' +
                            '<button type="button" class="md-btn" onclick="pactDecline(\'' + modeEsc(p.id) + '\')">Decline</button>' +
                          '</div>' +
                        '</div>';
            });
            mineOut.forEach(function (p) {
                html += '<div class="md-invite md-invite-out">' +
                          '<div class="md-invite-top">Waiting on <strong>' + modeEsc(pactName(p, p.partner)) + '</strong></div>' +
                          '<div class="md-invite-body">Your ' + phIcon('diamond', { weight: 'fill', lead: true }) + p.stake + ' is held until they answer. ' +
                            'It starts the day after they accept.</div>' +
                          '<div class="md-invite-btns">' +
                            '<button type="button" class="md-btn" onclick="pactWithdraw(\'' + modeEsc(p.id) + '\')">Withdraw</button>' +
                          '</div>' +
                        '</div>';
            });
            return html;
        }

        window.modesConfirmEnd = function () {
            var a = modesActive();
            if (!a) return;
            var meta = MODE_META[a.kind];
            var msg;
            if (a.kind === 'stake') {
                msg = 'End Stake Mode now? Your ' + a.wager + ' Grit stake is forfeited — the wager only pays if every target lands.';
            } else if (a.kind === 'pact') {
                msg = 'Break the pact now? Your ' + PACT_WAGER + ' Grit is gone, and so is ' +
                      a.partnerName + '’s. They will be told you ended it.';
            } else if (a.kind === 'berserk') {
                msg = 'End Berserk Mode now? Ending early counts as a miss — the 30% XP penalty applies.';
            } else if (a.kind === 'habit') {
                msg = 'Turn Habit Mode off? Your day count pauses right here. Turn it back on within ' +
                      HABIT_RESUME_DAYS + ' days and you carry on from where you left off; after that it starts fresh.';
            } else if (a.kind === 'insurance') {
                msg = 'Turn Insurance off? The days it already protected stay protected — ' +
                      'they were insured, and that does not get taken back. From tomorrow, ' +
                      'missing costs you the streak like any other activity.';
            } else {
                msg = 'End ' + meta.name + ' now? The Grit you spent to start it is not refunded.';
            }
            if (!confirm(msg)) return;
            modesEndByUser();
        };

        async function modesEndByUser() {
            var a = modesActive();
            if (!a) return;
            if (a.kind === 'berserk') { await berserkMaybeResolve(true); return; }
            if (a.kind === 'stake')   { await stakeMaybeResolve(true); return; }
            if (a.kind === 'pact') {
                // Breaking a pact deliberately is a forfeit for both. Resolve
                // the shared document so the partner learns it from the record,
                // not from a message this client sends.
                try {
                    var p = pactGet(a.pactId);
                    if (p && p.status === 'pending') { await pactTerminatePending(a.pactId, 'cancelled'); }
                    else if (p) {
                        var ref = doc(db, PACT_COL, a.pactId);
                        var uid = modesUid();
                        await runTransaction(db, async function (tx) {
                            var snap = await tx.get(ref);
                            if (!snap.exists()) return;
                            var live = snap.data();
                            if (live.status !== 'active') return;
                            var payout = {};
                            (live.participants || []).forEach(function (u) { payout[u] = 0; });
                            tx.update(ref, { status: 'resolved', outcome: 'broken', failedBy: uid,
                                             resolvedAt: modesNow(), pot: 0, payout: payout });
                        });
                    }
                    await pactFetch(true);
                } catch (e) { console.warn('Pact break failed:', e && e.message); }
                await modesEnd('failed', 'Ended early');
                return;
            }
            if (a.kind === 'insurance') {
                // The protection already granted is kept: those days genuinely
                // were insured. The offsets simply stop growing (see the
                // streak-pass header).
                await modesEnd('ended', insuranceDaysOn(a) + ' days insured');
                return;
            }
            if (a.kind === 'habit') {
                await modesEnd('ended', (a.daysElapsed || 0) + ' of ' + a.targetDays + ' days');
                return;
            }
            await modesEnd('ended', '');
        }

        window.pactDecline = async function (id) {
            if (!confirm('Decline this Pact? Their stake goes straight back to them.')) return;
            try {
                await pactTerminatePending(id, 'declined');
                showToast('Pact declined.', 'olive');
                modesRenderPage();
            } catch (e) { showToast(modeErrText(e), 'red'); }
        };

        window.pactWithdraw = async function (id) {
            if (!confirm('Withdraw this Pact invite? Your stake comes back.')) return;
            try {
                await pactTerminatePending(id, 'cancelled');
                await pactRunMaintenance();
                showToast('Invite withdrawn — your Grit is on its way back.', 'olive');
                modesRenderPage();
            } catch (e) { showToast(modeErrText(e), 'red'); }
        };

        function modeErrText(e) {
            var msg = (e && e.message) ? String(e.message) : 'Something went wrong.';
            var m = /^SHORTFALL:(\d+)$/.exec(msg);
            if (m) return 'You need ' + m[1] + ' more Grit for that.';
            return msg;
        }

        // ── The running-mode banner ───────────────────────────────────────
        // This is the one thing outside the Modes page that says a mode is on,
        // so it reads as a live status strip — an indicator that breathes, the
        // mode's name, what it is doing right now, and a way in — rather than
        // a system notice. Colour comes from the interactive blue; gold stays
        // reserved for milestones.

        function modeCountdownLabel(endsAt) {
            var left = Math.max(0, (endsAt || 0) - modesNow());
            if (left <= 0) return 'Window closed';
            var mins = Math.floor(left / 60000);
            var hh = Math.floor(mins / 60), mm = mins % 60;
            return (hh > 0 ? hh + 'h ' + mm + 'm' : mm + 'm') + ' left';
        }

        // What the mode is doing right now, in one short line.
        function modeBannerStatus(a) {
            var today = modesToday();
            if (a.kind === 'habit') {
                var left = (a.habits || []).filter(function (h) { return h.lastCompletedDay !== today; }).length;
                return 'Day ' + (a.daysElapsed || 0) + ' of ' + a.targetDays +
                       (left ? ' · ' + left + ' left today' : ' · done today');
            }
            if (a.kind === 'berserk') {
                return berserkEarned(a).toLocaleString() + ' of ' + a.targetXP.toLocaleString() +
                       ' XP · ' + modeCountdownLabel(a.endsAt);
            }
            if (a.kind === 'recovery') {
                var climbing = (a.activities || []).filter(function (x) {
                    var act = gritFindActivity(x.activityId);
                    return !act || (act.streak || 0) < x.ceiling;
                }).length;
                return climbing + ' still climbing';
            }
            if (a.kind === 'insurance') {
                var n = (a.activities || []).length;
                return n + ' activit' + (n === 1 ? 'y' : 'ies') + ' covered';
            }
            if (a.kind === 'stake') {
                var d = stakeDaysLeft(a);
                return stakeTotalCount(a) + ' of ' + stakeTotalTarget(a) + ' · ' +
                       (d > 0 ? d + ' day' + (d === 1 ? '' : 's') + ' left' : 'window closed');
            }
            if (a.kind === 'focus') {
                var s = modeMins(a.windowStart), e = modeMins(a.windowEnd);
                var open = s !== null && e !== null && modeInWindow(s, e, modeMinutesNow(), 0, 0);
                return open ? 'Window open until ' + modeTimeLabel(a.windowEnd)
                            : 'Opens ' + modeTimeLabel(a.windowStart);
            }
            if (a.kind === 'pact') {
                var p = pactGet(a.pactId);
                var mine = p ? pactStats(p, modesUid())
                             : { done: 0, total: modePactItems(a).reduce(function (n, it) {
                                   return n + Math.max(1, it.target || 1); }, 0) };
                return 'With ' + a.partnerName + ' · ' + mine.done + ' of ' + mine.total;
            }
            return '';
        }

        var MODE_CHEVRON =
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" ' +
            'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
            '<polyline points="9 18 15 12 9 6"/></svg>';

        // Berserk is the only mode measured in minutes, so it is the only one
        // that needs a clock. This replaces the manual "Refresh" button the
        // panel used to carry: a countdown you have to press to update is not
        // a countdown. The ticker exists only while Berserk is running and
        // stops itself the moment it is not — nothing left behind.
        var _modeClock = null;
        function modeClockSync(a) {
            var wants = !!(a && a.kind === 'berserk');
            if (wants && !_modeClock) {
                _modeClock = setInterval(function () {
                    var live = modesActive();
                    if (!live || live.kind !== 'berserk') { modeClockSync(null); return; }
                    modesRefreshBanner();
                    // The panel's own numbers only when someone is looking at
                    // them; the banner is cheap, a full page render is not.
                    if (modesPageVisible()) modesRenderPage();
                    else {
                        var chip = document.querySelector('[data-md-clock="berserk"]');
                        if (chip) chip.textContent = modeCountdownLabel(live.endsAt);
                    }
                }, 30000);
            } else if (!wants && _modeClock) {
                clearInterval(_modeClock);
                _modeClock = null;
            }
        }

        function modesRefreshBanner() {
            var el = document.getElementById('modesBanner');
            if (!el) return;
            var a = modesActive();
            var uid = modesUid();
            var invites = (_pactCache.list || []).filter(function (p) {
                return p.status === 'pending' && p.partner === uid && modesNow() <= p.expiresAt;
            }).length;
            modeClockSync(a);
            if (!a && !invites) { el.style.display = 'none'; el.innerHTML = ''; el.removeAttribute('role'); return; }
            el.style.display = '';
            el.setAttribute('role', 'button');
            el.setAttribute('tabindex', '0');
            if (a) {
                var meta = MODE_META[a.kind];
                el.className = 'md-banner md-banner-' + a.kind;
                el.setAttribute('aria-label', meta.name + ' is running — open Modes');
                el.innerHTML =
                    '<span class="md-banner-pulse" aria-hidden="true"></span>' +
                    '<span class="md-banner-main">' +
                      '<span class="md-banner-name">' + modeEsc(meta.name) + '</span>' +
                      '<span class="md-banner-stat">' + modeEsc(modeBannerStatus(a)) + '</span>' +
                    '</span>' +
                    '<span class="md-banner-go">' + MODE_CHEVRON + '</span>';
            } else {
                el.className = 'md-banner md-banner-invite';
                el.setAttribute('aria-label', invites + ' pact invites waiting — open Modes');
                el.innerHTML =
                    '<span class="md-banner-pulse" aria-hidden="true"></span>' +
                    '<span class="md-banner-main">' +
                      '<span class="md-banner-name">Pact invite' + (invites === 1 ? '' : 's') + '</span>' +
                      '<span class="md-banner-stat">' + invites + ' waiting on your answer</span>' +
                    '</span>' +
                    '<span class="md-banner-go">' + MODE_CHEVRON + '</span>';
            }
        }
        window.modesRefreshBanner = modesRefreshBanner;

        // ══════════════════════════════════════════════════════════════════
        //  SETUP SHEETS
        // ══════════════════════════════════════════════════════════════════
        //
        // One bottom sheet, reused by every mode, so the seven setups read as
        // one component rather than seven near-misses. It is the same shell the
        // gifting and versus sheets use.

        let _modeSetup = null;

        function modeCloseSheet() {
            var el = document.getElementById('modeSheet');
            if (el) el.remove();
            _modeSetup = null;
        }
        window.modeCloseSheet = modeCloseSheet;

        // The sheet element and its .modal child are created ONCE and then
        // reused. Re-rendering rewrites the modal's children, never the modal
        // itself: the phone sheet animation is bound to
        // `.modal-overlay.active > .modal`, so replacing that node replayed the
        // rise animation on every pick, keystroke and slider step — the sheet
        // appeared to close and pop up again on every single touch. Keeping the
        // node alive also keeps scroll position and lets focus be restored.
        function modeSheet(inner) {
            var el = document.getElementById('modeSheet');
            var sheet;
            if (!el) {
                el = document.createElement('div');
                el.id = 'modeSheet';
                el.className = 'modal-overlay gift-sheet-scrim md-sheet-scrim active';
                el.addEventListener('click', function (e) { if (e.target === el) modeCloseSheet(); });
                // Presentational only: a range's filled track follows its value
                // without any render, so dragging one stays smooth.
                el.addEventListener('input', function (e) {
                    var t = e.target;
                    if (t && t.classList && t.classList.contains('md-range')) modeRangeFill(t);
                });
                sheet = document.createElement('div');
                sheet.className = 'modal pl-modal gift-sheet md-sheet';
                el.appendChild(sheet);
                document.body.appendChild(el);
                try { window.mkBindSheet && window.mkBindSheet(el); } catch (e) {}
            } else {
                sheet = el.querySelector('.md-sheet');
            }
            if (!sheet) { modeCloseSheet(); return modeSheet(inner); }

            // Carry scroll and focus across the repaint.
            var oldBody = sheet.querySelector('.md-body');
            var keepScroll = oldBody ? oldBody.scrollTop : 0;
            var focused = document.activeElement;
            var focusKey = (focused && sheet.contains(focused)) ? focused.getAttribute('data-md-focus') : null;
            var caret = null;
            if (focusKey) {
                try { caret = { s: focused.selectionStart, e: focused.selectionEnd }; } catch (e) {}
            }

            sheet.innerHTML = inner;

            var body = sheet.querySelector('.md-body');
            if (body && keepScroll) body.scrollTop = keepScroll;
            if (focusKey) {
                var again = sheet.querySelector('[data-md-focus="' + focusKey + '"]');
                if (again) {
                    again.focus();
                    if (caret) { try { again.setSelectionRange(caret.s, caret.e); } catch (e) {} }
                }
            }
            sheet.querySelectorAll('.md-range').forEach(modeRangeFill);
            return el;
        }

        function modeSheetHead(title, eyebrow) {
            return '<div class="modal-header pl-modal-header">' +
                     '<div>' +
                       (eyebrow ? '<div class="pl-modal-eyebrow">' + modeEsc(eyebrow) + '</div>' : '') +
                       '<h3 class="modal-title">' + modeEsc(title) + '</h3></div>' +
                     '<button class="pl-modal-close" type="button" onclick="modeCloseSheet()" aria-label="Close">' +
                       '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                     '</button></div>';
        }

        // `note` is the reason the commitment is unavailable. It rides the
        // footer rather than the body, because a disabled button whose reason
        // is three screens up is a dead end.
        function modeSheetFoot(label, onclick, disabled, sub, note) {
            return '<div class="md-sheet-foot">' +
                     (note !== undefined
                       ? '<div class="md-foot-note" data-md-region="warn">' + note + '</div>'
                       : '') +
                     (sub ? '<div class="md-sheet-cost">' + sub + '</div>' : '') +
                     '<button type="button" class="md-btn md-btn-primary md-btn-wide"' +
                       (disabled ? ' disabled' : '') + ' onclick="' + onclick + '">' +
                       modeEsc(label) + '</button>' +
                   '</div>';
        }

        function modeAffordable(cost) { return (gritBalance() || 0) >= cost; }

        function modeCostLine(cost) {
            var bal = gritBalance() || 0;
            return '<span class="md-cost-n">' + phIcon('diamond', { weight: 'fill', lead: true }) + cost + '</span>' +
                   '<span class="md-cost-bal">' + (bal >= cost
                     ? 'you have ' + bal
                     : bal + ' — ' + (cost - bal) + ' short') + '</span>';
        }

        window.modesOpenSetup = function (kind) {
            if (modesActive()) {
                showToast('Only one mode at a time for now — end the running one first.', 'olive');
                return;
            }
            var m = modesState();
            if (kind === 'habit' && m && m.suspendedHabit) { habitOpenResume(); return; }
            _modeSetup = { kind: kind, step: 0, picks: [], detailIndex: 0, query: '' };
            if (kind === 'habit')     { _modeSetup.targetDays = HABIT_DEFAULT_DAYS; habitRenderSetup(); }
            if (kind === 'berserk')   { _modeSetup.hours = 2; berserkRenderSetup(); }
            if (kind === 'recovery')  { recoveryRenderSetup(); }
            if (kind === 'insurance') { insuranceRenderSetup(); }
            if (kind === 'stake')     { _modeSetup.days = STAKE_MIN_DAYS; _modeSetup.wager = MODE_WAGER_MIN; stakeRenderSetup(); }
            if (kind === 'focus')     { _modeSetup.windowStart = '18:00'; _modeSetup.windowEnd = '20:00';
                                        _modeSetup.days = 14; focusRenderSetup(); }
            if (kind === 'pact')      { _modeSetup.days = 7; _modeSetup.targets = {}; pactRenderSetup(); }
        };

        // ── Shared controls ───────────────────────────────────────────────

        // A range whose track shows how far along it is. The value writes
        // through on input and the sheet is rebuilt only on release, because
        // rebuilding the input mid-drag ends the drag on its first step — which
        // is why these never felt like sliders before.
        function modeRangeFill(input) {
            var lo = parseFloat(input.min || 0), hi = parseFloat(input.max || 100);
            var v = parseFloat(input.value || 0);
            var pct = hi > lo ? ((v - lo) / (hi - lo)) * 100 : 0;
            input.style.setProperty('--md-fill', Math.max(0, Math.min(100, pct)).toFixed(2) + '%');
        }

        function modeSliderHtml(field, lo, hi, value, opts) {
            opts = opts || {};
            return '<div class="md-slider' + (opts.hot ? ' is-hot' : '') + '">' +
                     '<div class="md-slider-read">' +
                       '<span class="md-slider-n" data-md-live="' + field + '">' + value + '</span>' +
                       '<span class="md-slider-unit">' + modeEsc(opts.unit || '') + '</span>' +
                       (opts.side ? '<span class="md-slider-side" data-md-live="' + opts.side + '"></span>' : '') +
                     '</div>' +
                     '<input type="range" class="md-range' + (opts.hot ? ' md-range-hot' : '') + '" ' +
                       'min="' + lo + '" max="' + hi + '" step="1" value="' + value + '" ' +
                       'aria-label="' + modeEsc(opts.label || field) + '" ' +
                       'data-md-focus="range-' + field + '" ' +
                       'oninput="modeSlide(\'' + field + '\',this.value,' + lo + ',' + hi + ')" ' +
                       'onchange="modeSlideEnd()">' +
                     '<div class="md-slider-ends">' +
                       '<span>' + modeEsc(opts.loLabel || String(lo)) + '</span>' +
                       '<span>' + modeEsc(opts.hiLabel || String(hi)) + '</span>' +
                     '</div>' +
                   '</div>';
        }

        function modeStepperHtml(minus, value, plus, opts) {
            opts = opts || {};
            return '<div class="md-stepper">' +
                     '<button type="button" class="md-stepper-btn" aria-label="Less"' +
                       (opts.atMin ? ' disabled' : '') + ' onclick="' + minus + '">−</button>' +
                     '<span class="md-stepper-n">' + value + '</span>' +
                     '<button type="button" class="md-stepper-btn" aria-label="More"' +
                       (opts.atMax ? ' disabled' : '') + ' onclick="' + plus + '">+</button>' +
                   '</div>';
        }

        // ── The activity picker ───────────────────────────────────────────
        // A real control rather than a native <select>: a trigger that names
        // what is chosen, a chevron that says it opens, and a search field, so
        // a library of fifty activities is a typed word rather than a scroll.
        // Filtering rewrites only the list, so the search box keeps its caret.

        function modeFilterActs(acts, query) {
            var q = String(query || '').trim().toLowerCase();
            if (!q) return acts;
            return acts.filter(function (a) {
                return (a.name || '').toLowerCase().indexOf(q) !== -1 ||
                       (a.dimName || '').toLowerCase().indexOf(q) !== -1;
            });
        }

        function modeSearchHtml(count) {
            if (count < 6) return '';
            return '<input type="search" class="md-input md-dd-search" data-md-focus="dd-search" ' +
                   'placeholder="Search activities" value="' + modeEsc(_modeSetup.query || '') + '" ' +
                   'oninput="modeSearchActs(this.value)">';
        }

        window.modeSearchActs = function (value) {
            if (!_modeSetup) return;
            _modeSetup.query = value;
            var host = document.getElementById('mdActList');
            if (host) host.innerHTML = modePickListHtml();
        };

        // Multi-select: up to `max` activities, each a row that toggles.
        function modePickListHtml() {
            var s = _modeSetup;
            var opts = s.pickOpts || {};
            var all = modeEligibleActivities({ streakOnly: !!opts.streakOnly });
            var acts = modeFilterActs(all, s.query);
            if (!acts.length) {
                return '<div class="md-dd-none">' +
                       (s.query ? 'Nothing matches “' + modeEsc(s.query) + '”.' : 'No activities yet.') +
                       '</div>';
            }
            var picked = s.picks || [];
            return acts.map(function (a) {
                var on = picked.indexOf(a.id) !== -1;
                var meta = opts.showPeak ? 'peak ' + Math.max(a.bestStreak, a.streak) : (a.dimName || '');
                var blocked = opts.needPeak && Math.max(a.bestStreak, a.streak) < 1;
                return '<button type="button" class="md-pick' + (on ? ' is-on' : '') +
                         (blocked ? ' is-off' : '') + '"' + (blocked ? ' disabled' : '') +
                         ' aria-pressed="' + (on ? 'true' : 'false') + '"' +
                         ' onclick="modeTogglePick(\'' + modeEsc(a.id) + '\',' + (opts.max || 1) + ')">' +
                         '<span class="md-pick-box" aria-hidden="true"></span>' +
                         '<span class="md-pick-name">' + modeEsc(a.name) + '</span>' +
                         '<span class="md-pick-meta">' + modeEsc(meta) + '</span>' +
                       '</button>';
            }).join('');
        }

        function modePickerHtml(max, opts) {
            opts = opts || {};
            var s = _modeSetup;
            s.pickOpts = { max: max, streakOnly: !!opts.streakOnly, showPeak: !!opts.showPeak,
                           needPeak: !!opts.needPeak };
            var all = modeEligibleActivities({ streakOnly: !!opts.streakOnly });
            if (!all.length) {
                return '<p class="md-empty">No activities can carry this mode yet. Create one on the Activities tab first.</p>';
            }
            return '<div class="md-dd is-open">' +
                     '<div class="md-dd-bar">' +
                       '<span class="md-dd-count" data-md-live="pickCount">' +
                         (s.picks || []).length + ' of ' + max + ' chosen</span>' +
                     '</div>' +
                     modeSearchHtml(all.length) +
                     '<div class="md-dd-list" id="mdActList">' + modePickListHtml() + '</div>' +
                   '</div>';
        }


        window.modeTogglePick = function (id, max) {
            if (!_modeSetup) return;
            var i = _modeSetup.picks.indexOf(id);
            if (i !== -1) _modeSetup.picks.splice(i, 1);
            else {
                if (_modeSetup.picks.length >= max) {
                    showToast('That is the maximum for this mode — ' + max + '.', 'olive');
                    return;
                }
                _modeSetup.picks.push(id);
            }
            modeRerenderSetup();
        };

        function modeRerenderSetup() {
            if (!_modeSetup) return;
            var k = _modeSetup.kind;
            if (k === 'habit')      habitRenderSetup();
            if (k === 'berserk')    berserkRenderSetup();
            if (k === 'recovery')   recoveryRenderSetup();
            if (k === 'insurance')  insuranceRenderSetup();
            if (k === 'stake')      stakeRenderSetup();
            if (k === 'focus')      focusRenderSetup();
            if (k === 'pact')       pactRenderSetup();
            if (k === 'pactAccept') pactRenderAccept();
        }

        window.modeSetField = function (field, value) {
            if (!_modeSetup) return;
            _modeSetup[field] = value;
            modeRerenderSetup();
        };
        window.modeSetNum = function (field, value, lo, hi) {
            if (!_modeSetup) return;
            var n = parseInt(value, 10);
            if (isNaN(n)) return;
            _modeSetup[field] = Math.max(lo, Math.min(hi, n));
            modeRerenderSetup();
        };
        // Sliders: the value writes through and only the readouts that depend
        // on it are patched. The sheet is rebuilt once, on release.
        window.modeSlide = function (field, value, lo, hi) {
            if (!_modeSetup) return;
            var n = parseInt(value, 10);
            if (isNaN(n)) return;
            _modeSetup[field] = Math.max(lo, Math.min(hi, n));
            modeSyncLive();
        };
        window.modeSlideEnd = function () { if (_modeSetup) modeRerenderSetup(); };

        // Free-text inputs must not re-render on every keystroke — that would
        // blow away the caret. They write straight through.
        window.modeWriteDetail = function (idx, field, value) {
            if (!_modeSetup || !_modeSetup.details) return;
            if (!_modeSetup.details[idx]) _modeSetup.details[idx] = {};
            _modeSetup.details[idx][field] = value;
        };

        // Everything a slider can change without a rebuild: the numbers that
        // read out from it, the warning line, and whether the sheet's one
        // commitment button is allowed to be pressed.
        function modeLiveMap() {
            var s = _modeSetup;
            if (!s) return {};
            var out = {};
            Object.keys(s).forEach(function (k) {
                var v = s[k];
                if (typeof v === 'number' || typeof v === 'string') out[k] = v;
            });
            out.pickCount = (s.picks || []).length + ' of ' + ((s.pickOpts && s.pickOpts.max) || 1) + ' chosen';
            if (s.kind === 'habit') {
                out.habitEnds = 'ends ' + modeDateLabel(modeAddDays(modesToday(), s.targetDays));
            }
            if (s.kind === 'berserk') {
                var t = berserkTargetFor(s.hours);
                out.berserkTarget = t.toLocaleString() + ' XP';
                out.berserkWin    = '+' + Math.round(t * BERSERK_SWING).toLocaleString() + ' XP';
                out.berserkEnds   = 'until ' + modeHourLabel(s.hours);
            }
            if (s.kind === 'stake') {
                out.stakePayout = String(s.wager + Math.round(s.wager * MODE_WAGER_RETURN));
                out.stakeEnds   = 'ends ' + modeDateLabel(modeAddDays(modesToday(), s.days));
            }
            if (s.kind === 'focus') {
                out.focusEnds = 'ends ' + modeDateLabel(modeAddDays(modesToday(), s.days));
            }
            if (s.kind === 'pact') {
                out.pactEnds = 'ends ' + modeDateLabel(modeAddDays(modesToday(), s.days + 1));
            }
            return out;
        }

        function modeHourLabel(hours) {
            var d = new Date(modesNow() + hours * 3600000);
            return modeTimeLabel(String(d.getHours()).padStart(2, '0') + ':' +
                                 String(d.getMinutes()).padStart(2, '0'));
        }

        // Is the sheet's commitment button blocked right now?
        function modeStartBlocked() {
            var s = _modeSetup;
            if (!s) return true;
            if (s.kind === 'habit')     return s.step === 0 ? s.picks.length === 0 : !modeAffordable(MODE_COST.habit);
            if (s.kind === 'berserk')   return !modeAffordable(MODE_COST.berserk);
            if (s.kind === 'recovery')  return !s.picks.length || !modeAffordable(MODE_COST.recovery);
            if (s.kind === 'insurance') return !s.picks.length || !modeAffordable(MODE_COST.insurance);
            if (s.kind === 'focus')     return !modeAffordable(MODE_COST.focus);
            if (s.kind === 'stake') {
                var total = s.picks.reduce(function (n, id) { return n + ((s.targets || {})[id] || 1); }, 0);
                return !s.picks.length || s.days < STAKE_MIN_DAYS || total < STAKE_MIN_TOTAL ||
                       !modeAffordable(s.wager);
            }
            if (s.kind === 'pact') {
                return !s.partnerUid || !s.picks.length ||
                       pactTotalTarget() < PACT_MIN_TARGET || !modeAffordable(PACT_WAGER);
            }
            if (s.kind === 'pactAccept') {
                var p = pactGet(s.pactId);
                return !s.picks.length || pactTotalTarget() < PACT_MIN_TARGET ||
                       !modeAffordable(p ? p.stake : PACT_WAGER);
            }
            return false;
        }

        function modeWarnHtml() {
            var s = _modeSetup;
            // Both Pact sheets carry their own warning, and modeSyncLive rewrites
            // this region on every slider drag — so they have to be routed here
            // or a drag would blank the reason the button is dead.
            if (s && (s.kind === 'pact' || s.kind === 'pactAccept')) return pactWarnHtml();
            if (!s || s.kind !== 'stake') return '';
            var total = s.picks.reduce(function (n, id) { return n + ((s.targets || {})[id] || 1); }, 0);
            if (s.days >= STAKE_MIN_DAYS && total >= STAKE_MIN_TOTAL) return '';
            return '<p class="md-warn">A stake needs ' + STAKE_MIN_DAYS + '+ days and ' +
                   STAKE_MIN_TOTAL + '+ completions. You have ' + s.days + ' and ' + total + '.</p>';
        }

        function modeSyncLive() {
            var sheet = document.getElementById('modeSheet');
            if (!sheet || !_modeSetup) return;
            var map = modeLiveMap();
            sheet.querySelectorAll('[data-md-live]').forEach(function (el) {
                var k = el.getAttribute('data-md-live');
                if (Object.prototype.hasOwnProperty.call(map, k)) el.textContent = map[k];
            });
            var warn = sheet.querySelector('[data-md-region="warn"]');
            if (warn) warn.innerHTML = modeWarnHtml();
            var btn = sheet.querySelector('.md-sheet-foot .md-btn-primary');
            if (btn) btn.disabled = modeStartBlocked();
        }

        // ══ HABIT ═════════════════════════════════════════════════════════
        function habitRenderSetup() {
            var s = _modeSetup;
            var cost = MODE_COST.habit;
            var html = modeSheetHead('Habit Mode', 'Build');

            if (s.step === 0) {
                html += '<div class="modal-body md-body">' +
                          '<p class="md-lede">Pick up to three activities to turn into habits.</p>' +
                          modePickerHtml(HABIT_MAX_ACTS, {}) +
                        '</div>' +
                        modeSheetFoot('Next', 'habitSetupNext()', s.picks.length === 0, modeCostLine(cost));
            } else if (s.step === 1) {
                var i = s.detailIndex;
                var act = modeEligibleActivities().filter(function (a) { return a.id === s.picks[i]; })[0] || { name: 'Activity' };
                var d = (s.details && s.details[i]) || {};
                html += '<div class="modal-body md-body">' +
                          '<div class="md-step">Habit ' + (i + 1) + ' of ' + s.picks.length + '</div>' +
                          '<div class="md-step-name">' + modeEsc(act.name) + '</div>' +

                          '<label class="md-label">Every day, between</label>' +
                          '<div class="md-time-row">' +
                            '<input type="time" class="md-input md-time" data-md-focus="ws" value="' + modeEsc(d.windowStart || '22:00') + '" ' +
                              'onchange="modeWriteDetail(' + i + ',\'windowStart\',this.value)">' +
                            '<span class="md-time-and">and</span>' +
                            '<input type="time" class="md-input md-time" data-md-focus="we" value="' + modeEsc(d.windowEnd || '23:00') + '" ' +
                              'onchange="modeWriteDetail(' + i + ',\'windowEnd\',this.value)">' +
                          '</div>' +
                          '<p class="md-hint">Nudged an hour before it opens, and again after it closes.</p>' +

                          '<label class="md-label">Anchor <span class="md-label-opt">optional</span></label>' +
                          '<input type="text" class="md-input" maxlength="80" data-md-focus="anchor" ' +
                            'placeholder="right after brushing my teeth" ' +
                            'value="' + modeEsc(d.anchor || '') + '" ' +
                            'oninput="modeWriteDetail(' + i + ',\'anchor\',this.value)">' +

                          '<label class="md-label">Why does this matter?</label>' +
                          '<textarea class="md-input md-textarea" maxlength="240" rows="3" data-md-focus="why" ' +
                            'placeholder="In your own words." ' +
                            'oninput="modeWriteDetail(' + i + ',\'why\',this.value)">' + modeEsc(d.why || '') + '</textarea>' +
                          '<p class="md-hint">Comes back to you word for word on a day you miss.</p>' +
                        '</div>' +
                        modeSheetFoot(i + 1 < s.picks.length ? 'Next habit' : 'Set the length',
                                      'habitDetailNext()', false, '');
            } else {
                html += '<div class="modal-body md-body">' +
                          '<label class="md-label">How long for?</label>' +
                          modeSliderHtml('targetDays', HABIT_MIN_DAYS, HABIT_MAX_DAYS, s.targetDays, {
                              unit: 'days', side: 'habitEnds', label: 'Days',
                              loLabel: HABIT_MIN_DAYS + ' days', hiLabel: HABIT_MAX_DAYS + ' days' }) +
                          '<div class="md-summary">' +
                            s.picks.map(function (id, i) {
                                var a = modeEligibleActivities().filter(function (x) { return x.id === id; })[0] || {};
                                var d = (s.details && s.details[i]) || {};
                                return '<div class="md-summary-row"><strong>' + modeEsc(a.name || '') + '</strong> — ' +
                                       modeTimeLabel(d.windowStart || '22:00') + ' to ' + modeTimeLabel(d.windowEnd || '23:00') +
                                       (d.anchor ? ', ' + modeEsc(d.anchor) : '') + '</div>';
                            }).join('') +
                          '</div>' +
                        '</div>' +
                        modeSheetFoot('Start Habit Mode', 'habitStart()', !modeAffordable(cost), modeCostLine(cost));
            }
            modeSheet(html);
            modeSyncLive();
        }

        window.habitSetupNext = function () {
            if (!_modeSetup || !_modeSetup.picks.length) return;
            _modeSetup.details = _modeSetup.picks.map(function () {
                return { windowStart: '22:00', windowEnd: '23:00', anchor: '', why: '' };
            });
            _modeSetup.step = 1;
            _modeSetup.detailIndex = 0;
            habitRenderSetup();
        };

        window.habitDetailNext = function () {
            var s = _modeSetup;
            if (!s) return;
            var d = s.details[s.detailIndex] || {};
            if (modeMins(d.windowStart) === null || modeMins(d.windowEnd) === null) {
                showToast('Pick a start and an end time for the window.', 'red'); return;
            }
            if (!String(d.why || '').trim()) {
                showToast('Write why this one matters — it is the part that brings you back.', 'red'); return;
            }
            if (s.detailIndex + 1 < s.picks.length) { s.detailIndex++; }
            else { s.step = 2; }
            habitRenderSetup();
        };

        window.habitStart = async function () {
            var s = _modeSetup;
            if (!s) return;
            var acts = modeEligibleActivities();
            var habits = s.picks.map(function (id, i) {
                var a = acts.filter(function (x) { return x.id === id; })[0] || {};
                var d = s.details[i] || {};
                return {
                    activityId: id, activityName: a.name || 'Activity',
                    windowStart: d.windowStart, windowEnd: d.windowEnd,
                    anchor: String(d.anchor || '').trim(),
                    why: String(d.why || '').trim(),
                    completions: 0, lastCompletedDay: null,
                    milestonesShown: [], overlayDismissedDay: null
                };
            });
            var res = await modesActivate('habit', {
                habits: habits, targetDays: s.targetDays,
                daysElapsed: 0, lastCountedDay: modesToday()
            }, MODE_COST.habit, 'mode_habit');
            if (!res.ok) { showToast(res.message, 'red'); return; }
            modeCloseSheet();
            showToast('Habit Mode is on — ' + habits.length + ' habit' + (habits.length === 1 ? '' : 's') +
                      ' for ' + s.targetDays + ' days', 'green');
            modesRenderPage();
        };

        function habitOpenResume() {
            var m = modesState();
            var sus = m && m.suspendedHabit;
            if (!sus) { return; }
            var p = sus.payload;
            var offDays = Math.floor((modesNow() - new Date(sus.offAt).getTime()) / 86400000);
            _modeSetup = { kind: 'habit', step: 0, picks: [], detailIndex: 0,
                           targetDays: HABIT_DEFAULT_DAYS, query: '', resume: true };
            var html = modeSheetHead('Habit Mode', 'Resume');
            html += '<div class="modal-body md-body">' +
                      '<p class="md-lede">Paused ' + (offDays === 0 ? 'today' : offDays + ' day' + (offDays === 1 ? '' : 's') + ' ago') +
                        '. Pick it up where you left it, or start over.</p>' +
                      '<div class="md-summary">' +
                        '<div class="md-summary-row"><strong>' + (p.daysElapsed || 0) + ' of ' + p.targetDays + ' days</strong> elapsed</div>' +
                        (p.habits || []).map(function (h) {
                            return '<div class="md-summary-row">' + modeEsc(h.activityName) + ' — ' +
                                   (h.completions || 0) + ' achieved</div>';
                        }).join('') +
                      '</div>' +
                      '<p class="md-hint">Resuming is free. Starting fresh archives this run and costs ' + phIcon('diamond', { weight: 'fill', lead: true }) +
                        MODE_COST.habit + '.</p>' +
                    '</div>' +
                    '<div class="md-sheet-foot md-sheet-foot-2">' +
                      '<button type="button" class="md-btn" onclick="habitStartFresh()">Start fresh</button>' +
                      '<button type="button" class="md-btn md-btn-primary" onclick="habitResume()">Resume</button>' +
                    '</div>';
            modeSheet(html);
        }

        window.habitResume = async function () {
            var m = modesState();
            if (!m || !m.suspendedHabit) return;
            if (m.active) { showToast('End the running mode first.', 'olive'); return; }
            var p = m.suspendedHabit.payload;
            // The day count picks up from where it stopped: time spent with the
            // mode off never counted, so it is not counted now either (spec §1).
            p.lastCountedDay = modesToday();
            m.active = p;
            m.suspendedHabit = null;
            try { await saveUserData(); } catch (e) {}
            try { await modesSyncNotifications(); } catch (e) {}
            modeCloseSheet();
            showToast('Habit Mode resumed at day ' + (p.daysElapsed || 0), 'green');
            modesRenderPage();
            modesRefreshBanner();
        };

        window.habitStartFresh = function () {
            var m = modesState();
            if (m) {
                if (m.suspendedHabit) {
                    m.history.unshift({ id: m.suspendedHabit.payload.id, kind: 'habit', outcome: 'ended',
                        startedAt: m.suspendedHabit.payload.startedAt, endedAt: m.suspendedHabit.offAt,
                        summary: (m.suspendedHabit.payload.daysElapsed || 0) + ' of ' +
                                 m.suspendedHabit.payload.targetDays + ' days (archived)' });
                }
                m.suspendedHabit = null;
            }
            saveUserData().catch(function () {});
            _modeSetup = { kind: 'habit', step: 0, picks: [], detailIndex: 0,
                           targetDays: HABIT_DEFAULT_DAYS, query: '' };
            habitRenderSetup();
        };

        // ══ BERSERK ═══════════════════════════════════════════════════════
        function berserkRenderSetup() {
            var s = _modeSetup;
            var cost = MODE_COST.berserk;
            var target = berserkTargetFor(s.hours);
            var swing = Math.round(target * BERSERK_SWING);

            var html = modeSheetHead('Berserk Mode', 'Extreme');
            html += '<div class="modal-body md-body md-body-hot">' +
                      '<p class="md-lede">Hit the target inside the window for +30% XP. Miss and 30% comes off.</p>' +
                      modeSliderHtml('hours', BERSERK_MIN_HOURS, BERSERK_MAX_HOURS, s.hours, {
                          unit: 'hours', side: 'berserkEnds', hot: true, label: 'Hours',
                          loLabel: BERSERK_MIN_HOURS + ' hour', hiLabel: BERSERK_MAX_HOURS + ' hours' }) +
                      '<div class="md-stakes">' +
                        '<div class="md-stake"><span class="md-stake-k">Target</span>' +
                          '<span class="md-stake-v" data-md-live="berserkTarget">' + target.toLocaleString() + ' XP</span></div>' +
                        '<div class="md-stake md-stake-win"><span class="md-stake-k">Clear it</span>' +
                          '<span class="md-stake-v" data-md-live="berserkWin">+' + swing.toLocaleString() + ' XP</span></div>' +
                        '<div class="md-stake md-stake-lose"><span class="md-stake-k">Miss it</span>' +
                          '<span class="md-stake-v">−30% of what you earned</span></div>' +
                      '</div>' +
                      '<p class="md-hint md-hint-hot">The whole app turns red. It keeps running with the app closed.</p>' +
                    '</div>' +
                    modeSheetFoot('Go berserk', 'berserkStart()', !modeAffordable(cost), modeCostLine(cost));
            modeSheet(html);
            modeSyncLive();
        }

        window.berserkStart = async function () {
            var s = _modeSetup;
            if (!s) return;
            var now = modesNow();
            var target = berserkTargetFor(s.hours);
            var res = await modesActivate('berserk', {
                hours: s.hours,
                startedAtMs: now,
                endsAt: now + s.hours * 3600000,
                targetXP: target,
                perHourTarget: berserkPerHourTarget(),
                resolved: false
            }, MODE_COST.berserk, 'mode_berserk');
            if (!res.ok) { showToast(res.message, 'red'); return; }
            modeCloseSheet();
            showToast('Berserk — ' + target.toLocaleString() + ' XP in ' + s.hours + 'h', 'red');
            modesRenderPage();
        };

        // ══ RECOVERY ══════════════════════════════════════════════════════
        function recoveryRenderSetup() {
            var s = _modeSetup;
            var cost = MODE_COST.recovery;
            var acts = modeEligibleActivities({ streakOnly: true });
            var picked = s.picks.filter(function (id) {
                return acts.some(function (a) { return a.id === id; });
            });
            var html = modeSheetHead('Recovery Mode', 'Return');
            html += '<div class="modal-body md-body">' +
                      '<p class="md-lede">Each pick climbs an extra step per completion until it is back at its own peak.</p>' +
                      modePickerHtml(RECOVERY_MAX_ACTS, { streakOnly: true, showPeak: true, needPeak: true }) +
                      (picked.length ? '<div class="md-summary">' + picked.map(function (id) {
                          var a = acts.filter(function (x) { return x.id === id; })[0] || {};
                          var ceiling = Math.max(a.bestStreak || 0, a.streak || 0, 1);
                          return '<div class="md-summary-row">' + modeEsc(a.name) + ' — now ' + (a.streak || 0) +
                                 ', peak <strong>' + ceiling + '</strong></div>';
                      }).join('') + '</div>' : '') +
                    '</div>' +
                    modeSheetFoot('Start recovering', 'recoveryStart()',
                                  !picked.length || !modeAffordable(cost), modeCostLine(cost));
            modeSheet(html);
            modeSyncLive();
        }

        window.recoveryStart = async function () {
            var s = _modeSetup;
            if (!s || !s.picks.length) return;
            var list = [];
            s.picks.forEach(function (id) {
                var act = gritFindActivity(id);
                if (!act) return;
                list.push({
                    activityId: String(id), activityName: act.name || 'Activity',
                    ceiling: recoveryCeilingFor(act),
                    startStreak: act.streak || 0,
                    granted: 0, lastBonusDay: null
                });
            });
            if (!list.length) { showToast('Those activities are no longer available.', 'red'); return; }
            var res = await modesActivate('recovery', { activities: list }, MODE_COST.recovery, 'mode_recovery');
            if (!res.ok) { showToast(res.message, 'red'); return; }
            modeCloseSheet();
            showToast('Recovery Mode is on — chasing your own peak', 'green');
            modesRenderPage();
        };

        // ══ INSURANCE ═════════════════════════════════════════════════════
        function insuranceRenderSetup() {
            var s = _modeSetup;
            var cost = MODE_COST.insurance;
            var html = modeSheetHead('Insurance Mode', 'Shield');
            html += '<div class="modal-body md-body">' +
                      '<p class="md-lede">While it runs, missing a day costs these nothing. Logging still counts.</p>' +
                      modePickerHtml(INSURANCE_MAX_ACTS, { streakOnly: true }) +
                      '<p class="md-hint">No end date — it runs until you turn it off, and checks in after ' +
                        INSURANCE_CHECKIN_DAYS + ' days.</p>' +
                    '</div>' +
                    modeSheetFoot('Insure them', 'insuranceStart()',
                                  !s.picks.length || !modeAffordable(cost), modeCostLine(cost));
            modeSheet(html);
            modeSyncLive();
        }

        window.insuranceStart = async function () {
            var s = _modeSetup;
            if (!s || !s.picks.length) return;
            var list = [];
            s.picks.forEach(function (id) {
                var act = gritFindActivity(id);
                if (!act) return;
                list.push({ activityId: String(id), activityName: act.name || 'Activity' });
            });
            if (!list.length) { showToast('Those activities are no longer available.', 'red'); return; }
            var res = await modesActivate('insurance', {
                activities: list, lastCheckInDay: null
            }, MODE_COST.insurance, 'mode_insurance');
            if (!res.ok) { showToast(res.message, 'red'); return; }
            modeCloseSheet();
            showToast('Insurance is on — ' + list.length + ' activity' + (list.length === 1 ? '' : 's') + ' covered', 'green');
            modesRenderPage();
        };

        // ══ STAKE ═════════════════════════════════════════════════════════
        function stakeRenderSetup() {
            var s = _modeSetup;
            if (!s.targets) s.targets = {};
            var acts = modeEligibleActivities();
            var payout = s.wager + Math.round(s.wager * MODE_WAGER_RETURN);

            var html = modeSheetHead('Stake Mode', 'Wager');
            html += '<div class="modal-body md-body">' +
                      '<p class="md-lede">Hit every target inside the window and the stake comes back with 30% on top.</p>' +
                      modePickerHtml(STAKE_MAX_ACTS, {}) +
                      (s.picks.length ? '<div class="md-targets">' + s.picks.map(function (id) {
                          var a = acts.filter(function (x) { return x.id === id; })[0] || {};
                          var v = s.targets[id] || 1;
                          return '<div class="md-target-row">' +
                                   '<span class="md-target-name">' + modeEsc(a.name || '') + '</span>' +
                                   modeStepperHtml('stakeBump(\'' + modeEsc(id) + '\',-1)', v,
                                                   'stakeBump(\'' + modeEsc(id) + '\',1)',
                                                   { atMin: v <= 1, atMax: v >= 200 }) +
                                 '</div>';
                      }).join('') + '</div>' : '') +

                      '<label class="md-label">Window</label>' +
                      modeSliderHtml('days', STAKE_MIN_DAYS, 60, s.days, {
                          unit: 'days', side: 'stakeEnds', label: 'Days',
                          loLabel: STAKE_MIN_DAYS + ' days', hiLabel: '60 days' }) +

                      '<label class="md-label">Stake</label>' +
                      '<div class="md-wager">' +
                        [25, 50, 75, 100].map(function (w) {
                            return '<button type="button" class="md-wager-btn' + (s.wager === w ? ' is-on' : '') + '" ' +
                                   'aria-pressed="' + (s.wager === w ? 'true' : 'false') + '" ' +
                                   'onclick="modeSetNum(\'wager\',' + w + ',' + MODE_WAGER_MIN + ',' + MODE_WAGER_MAX + ')">' + phIcon('diamond', { weight: 'fill', lead: true }) + w + '</button>';
                        }).join('') +
                      '</div>' +
                      '<div class="md-stakes">' +
                        '<div class="md-stake md-stake-win"><span class="md-stake-k">All targets hit</span>' +
                          '<span class="md-stake-v">' + phIcon('diamond', { weight: 'fill', lead: true }) +
                            '<span data-md-live="stakePayout">' + payout + '</span></span></div>' +
                        '<div class="md-stake md-stake-lose"><span class="md-stake-k">One short</span><span class="md-stake-v">' + phIcon('diamond', { weight: 'fill', lead: true }) + '0</span></div>' +
                      '</div>' +
                    '</div>' +
                    modeSheetFoot('Place the stake', 'stakeStart()', modeStartBlocked(),
                                  modeCostLine(s.wager), modeWarnHtml());
            modeSheet(html);
            modeSyncLive();
        }

        window.stakeBump = function (id, delta) {
            if (!_modeSetup) return;
            if (!_modeSetup.targets) _modeSetup.targets = {};
            var v = (_modeSetup.targets[id] || 1) + delta;
            _modeSetup.targets[id] = Math.max(1, Math.min(200, v));
            stakeRenderSetup();
        };

        window.stakeStart = async function () {
            var s = _modeSetup;
            if (!s || !s.picks.length) return;
            var items = [];
            s.picks.forEach(function (id) {
                var act = gritFindActivity(id);
                if (!act) return;
                items.push({ activityId: String(id), activityName: act.name || 'Activity',
                             target: s.targets[id] || 1, count: 0 });
            });
            var total = items.reduce(function (n, it) { return n + it.target; }, 0);
            if (total < STAKE_MIN_TOTAL || s.days < STAKE_MIN_DAYS) {
                showToast('A stake needs at least ' + STAKE_MIN_DAYS + ' days and ' +
                          STAKE_MIN_TOTAL + ' completions.', 'red');
                return;
            }
            var res = await modesActivate('stake', {
                items: items, days: s.days, wager: s.wager, resolved: false
            }, s.wager, 'mode_stake_wager');
            if (!res.ok) { showToast(res.message, 'red'); return; }
            modeCloseSheet();
            showToast('Stake placed — ' + s.wager + ' Grit on ' + total + ' completions in ' + s.days + ' days', 'green', null, 'diamond');
            modesRenderPage();
        };

        // ══ FOCUS WINDOW ══════════════════════════════════════════════════
        function focusRenderSetup() {
            var s = _modeSetup;
            var cost = MODE_COST.focus;
            var html = modeSheetHead('Focus Window', 'Rhythm');
            html += '<div class="modal-body md-body">' +
                      '<p class="md-lede">One slot a day. Anything logged inside it earns +' +
                        Math.round(FOCUS_MULTIPLIER * 100) + '% XP.</p>' +
                      '<label class="md-label">Every day, between</label>' +
                      '<div class="md-time-row">' +
                        '<input type="time" class="md-input md-time" data-md-focus="ws" value="' + modeEsc(s.windowStart) + '" ' +
                          'onchange="modeSetField(\'windowStart\',this.value)">' +
                        '<span class="md-time-and">and</span>' +
                        '<input type="time" class="md-input md-time" data-md-focus="we" value="' + modeEsc(s.windowEnd) + '" ' +
                          'onchange="modeSetField(\'windowEnd\',this.value)">' +
                      '</div>' +
                      '<label class="md-label">For</label>' +
                      modeSliderHtml('days', FOCUS_MIN_DAYS, FOCUS_MAX_DAYS, s.days, {
                          unit: 'days', side: 'focusEnds', label: 'Days',
                          loLabel: FOCUS_MIN_DAYS + ' days', hiLabel: FOCUS_MAX_DAYS + ' days' }) +
                      '<p class="md-hint">The slot never moves — that is the mechanism. Bonuses never stack.</p>' +
                    '</div>' +
                    modeSheetFoot('Open the window', 'focusStart()', !modeAffordable(cost), modeCostLine(cost));
            modeSheet(html);
            modeSyncLive();
        }

        window.focusStart = async function () {
            var s = _modeSetup;
            if (!s) return;
            if (modeMins(s.windowStart) === null || modeMins(s.windowEnd) === null) {
                showToast('Pick a start and an end time.', 'red'); return;
            }
            if (modeMins(s.windowStart) === modeMins(s.windowEnd)) {
                showToast('The window needs to be longer than nothing.', 'red'); return;
            }
            var res = await modesActivate('focus', {
                windowStart: s.windowStart, windowEnd: s.windowEnd,
                targetDays: s.days, daysElapsed: 0, lastCountedDay: modesToday(),
                bonusXP: 0, bonusCount: 0
            }, MODE_COST.focus, 'mode_focus');
            if (!res.ok) { showToast(res.message, 'red'); return; }
            modeCloseSheet();
            showToast('Focus Window open — ' + modeTimeLabel(s.windowStart) + ' to ' +
                      modeTimeLabel(s.windowEnd), 'green');
            modesRenderPage();
        };

        // ══ PACT ══════════════════════════════════════════════════════════
        function pactRenderSetup() {
            var s = _modeSetup;
            var friends = (window.userData.friends || []);
            if (!friends.length) {
                modeSheet(modeSheetHead('Pact Mode', 'Together') +
                    '<div class="modal-body md-body">' +
                      '<p class="md-empty">A Pact needs someone to make it with. Add a friend on the Social tab first.</p>' +
                    '</div>');
                return;
            }
            var html = modeSheetHead('Pact Mode', 'Together');

            if (!s.partnerUid) {
                html += '<div class="modal-body md-body">' +
                          '<p class="md-lede">Two people, two targets, one outcome. ' + phIcon('diamond', { weight: 'fill', lead: true }) + PACT_WAGER +
                            ' each — if either falls short, both stakes go.</p>' +
                          '<label class="md-label">Who with?</label>' +
                          '<div class="md-picker">' + friends.map(function (u) {
                              var p = (window._friendProfileCache || {})[u] || {};
                              return '<button type="button" class="md-pick" ' +
                                       'onclick="pactPickPartner(\'' + modeEsc(u) + '\')">' +
                                       '<span class="md-pick-name">' + modeEsc(p.displayName || 'Adventurer') + '</span>' +
                                       (p.level ? '<span class="md-pick-meta">Lv ' + p.level + '</span>' : '') +
                                     '</button>';
                          }).join('') + '</div>' +
                        '</div>';
            } else {
                html += '<div class="modal-body md-body">' +
                          '<div class="md-step">With</div>' +
                          '<div class="md-step-name">' + modeEsc(giftFriendName(s.partnerUid)) + '</div>' +

                          '<label class="md-label">Your activities</label>' +
                          modePickerHtml(PACT_MAX_ACTS, {}) +
                          pactTargetRowsHtml('pactBump') +
                          '<p class="md-hint">They pick their own — it does not have to match, ' +
                            'and it does not have to be the same number of things.</p>' +

                          '<label class="md-label">Window</label>' +
                          modeSliderHtml('days', PACT_MIN_DAYS, 60, s.days, {
                              unit: 'days', side: 'pactEnds', label: 'Days',
                              loLabel: PACT_MIN_DAYS + ' days', hiLabel: '60 days' }) +
                          '<p class="md-hint">Starts the day after they accept, so you get the same window.</p>' +
                        '</div>' +
                        modeSheetFoot('Send the request', 'pactSend()',
                                      modeStartBlocked(), modeCostLine(PACT_WAGER),
                                      pactWarnHtml());
            }
            modeSheet(html);
            modeSyncLive();
        }

        // The picked activities with a target stepper each — Stake Mode's rows,
        // used verbatim, because both sheets are asking the same question and
        // there is no reason for a Pact to answer it in a different shape.
        function pactTargetRowsHtml(bumpFn) {
            var s = _modeSetup;
            if (!s.picks || !s.picks.length) return '';
            if (!s.targets) s.targets = {};
            var acts = modeEligibleActivities();
            return '<div class="md-targets">' + s.picks.map(function (id) {
                var a = acts.filter(function (x) { return x.id === id; })[0] || {};
                var v = s.targets[id] || 1;
                return '<div class="md-target-row">' +
                         '<span class="md-target-name">' + modeEsc(a.name || '') + '</span>' +
                         modeStepperHtml(bumpFn + '(\'' + modeEsc(id) + '\',-1)', v,
                                         bumpFn + '(\'' + modeEsc(id) + '\',1)',
                                         { atMin: v <= 1, atMax: v >= 200 }) +
                       '</div>';
            }).join('') + '</div>' +
            '<p class="md-hint">Total completions inside the window — not one a day.</p>';
        }

        function pactTotalTarget() {
            var s = _modeSetup;
            if (!s || !s.picks) return 0;
            return s.picks.reduce(function (n, id) { return n + ((s.targets || {})[id] || 1); }, 0);
        }

        // Why the send button is dead, on the footer where the button is —
        // a disabled control whose reason is three screens up is a dead end.
        function pactWarnHtml() {
            var s = _modeSetup;
            if (!s) return '';
            if (!s.picks || !s.picks.length) return '<p class="md-warn">Pick at least one activity.</p>';
            var total = pactTotalTarget();
            if (total >= PACT_MIN_TARGET) return '';
            return '<p class="md-warn">A Pact needs ' + PACT_MIN_TARGET +
                   '+ completions in total. You have ' + total + '.</p>';
        }

        window.pactBump = function (id, delta) {
            if (!_modeSetup) return;
            if (!_modeSetup.targets) _modeSetup.targets = {};
            var v = (_modeSetup.targets[id] || 1) + delta;
            _modeSetup.targets[id] = Math.max(1, Math.min(200, v));
            pactRenderSetup();
        };

        // Builds the term both sheets send, from whatever is picked right now.
        // An activity deleted between picking and sending is dropped rather
        // than written as a dangling id nobody can ever complete.
        function pactBuildTerm() {
            var s = _modeSetup;
            var items = [];
            (s.picks || []).forEach(function (id) {
                var act = gritFindActivity(id);
                if (!act) return;
                items.push({ activityId: String(id),
                             activityName: act.name || 'Activity',
                             target: Math.max(1, (s.targets || {})[id] || 1) });
            });
            return items.length ? { items: items } : null;
        }

        window.pactPickPartner = async function (uid) {
            if (!_modeSetup) return;
            try { await giftEnsureFriendNames(); } catch (e) {}
            _modeSetup.partnerUid = uid;
            pactRenderSetup();
        };

        window.pactSend = async function () {
            var s = _modeSetup;
            if (!s || !s.partnerUid) return;
            var term = pactBuildTerm();
            if (!term) { showToast('Those activities no longer exist.', 'red'); return; }
            try {
                await pactCreate(s.partnerUid, giftFriendName(s.partnerUid), term, s.days);
                modeCloseSheet();
                showToast('Request sent to ' + giftFriendName(s.partnerUid) +
                          ' — your ' + PACT_WAGER + ' Grit is held until they answer.', 'green', null, 'handshake');
                modesRenderPage();
            } catch (e) { showToast(modeErrText(e), 'red'); }
        };

        window.pactOpenAccept = async function (id) {
            var p = pactGet(id);
            if (!p) { await pactFetch(true); p = pactGet(id); }
            if (!p) { showToast('That Pact is no longer available.', 'red'); return; }
            _modeSetup = { kind: 'pactAccept', pactId: id, picks: [], targets: {}, query: '' };
            pactRenderAccept();
        };

        function pactRenderAccept() {
            var s = _modeSetup;
            var p = pactGet(s.pactId);
            if (!p) { modeCloseSheet(); return; }
            var from = pactName(p, p.createdBy);

            var html = modeSheetHead('Pact with ' + from, 'Accept');
            html += '<div class="modal-body md-body">' +
                      '<div class="md-summary">' +
                        '<div class="md-summary-row"><strong>' + modeEsc(from) + '</strong> — ' +
                          modeEsc(pactTermSummary(p, p.createdBy)) +
                          ' over ' + p.durationDays + ' days.</div>' +
                      '</div>' +
                      '<p class="md-lede">Pick your own activities and targets. Same window, separate goals.</p>' +

                      '<label class="md-label">Your activities</label>' +
                      modePickerHtml(PACT_MAX_ACTS, {}) +
                      pactTargetRowsHtml('pactAcceptBump') +
                      '<p class="md-hint">Starts tomorrow and runs ' + p.durationDays + ' days for both of you.</p>' +
                    '</div>' +
                    modeSheetFoot('Accept and stake ' + p.stake + ' Grit', 'pactDoAccept()',
                                  modeStartBlocked(), modeCostLine(p.stake), pactWarnHtml());
            modeSheet(html);
            modeSyncLive();
        }

        window.pactAcceptBump = function (id, delta) {
            if (!_modeSetup) return;
            if (!_modeSetup.targets) _modeSetup.targets = {};
            var v = (_modeSetup.targets[id] || 1) + delta;
            _modeSetup.targets[id] = Math.max(1, Math.min(200, v));
            pactRenderAccept();
        };

        window.pactDoAccept = async function () {
            var s = _modeSetup;
            if (!s) return;
            var term = pactBuildTerm();
            if (!term) { showToast('Those activities no longer exist.', 'red'); return; }
            try {
                var out = await pactAccept(s.pactId, term);
                modeCloseSheet();
                showToast('Pact set with ' + out.partnerName + ' — it starts tomorrow.', 'green');
                modesRenderPage();
            } catch (e) { showToast(modeErrText(e), 'red'); }
        };

        // ══════════════════════════════════════════════════════════════════
        //  RESOLUTION CARD / MILESTONE / OVERLAY / CHECK-IN
        // ══════════════════════════════════════════════════════════════════

        function modesShowResolution(res, onClose) {
            if (!res) { if (onClose) onClose(); return; }
            var existing = document.getElementById('modeResolveCard');
            if (existing) existing.remove();

            var won = res.outcome === 'won';
            var el = document.createElement('div');
            el.id = 'modeResolveCard';
            el.className = 'md-res-scrim md-res-' + (won ? 'win' : 'lose');
            el.innerHTML =
                '<div class="md-res" role="dialog" aria-modal="true">' +
                  '<div class="md-res-icon">' + phIcon(MODE_META[res.kind] ? MODE_META[res.kind].icon : 'diamond', { block: true }) + '</div>' +
                  '<div class="md-res-title">' + modeEsc(res.title) + '</div>' +
                  '<div class="md-res-headline">' + modeEsc(res.headline) + '</div>' +
                  (res.lines && res.lines.length
                    ? '<div class="md-res-lines">' + res.lines.map(function (l) {
                        return '<div class="md-res-line">' + modeEsc(l) + '</div>';
                      }).join('') + '</div>'
                    : '') +
                  (res.note ? '<p class="md-res-note">' + modeEsc(res.note) + '</p>' : '') +
                  '<button type="button" class="md-btn md-btn-primary md-btn-wide" id="modeResOk">Done</button>' +
                '</div>';
            document.body.appendChild(el);
            function close() {
                el.classList.add('is-leaving');
                setTimeout(function () { el.remove(); if (onClose) onClose(); }, 240);
            }
            el.querySelector('#modeResOk').onclick = close;
            el.addEventListener('click', function (e) { if (e.target === el) close(); });
        }

        function modesShowMilestone(h, frac, targetDays) {
            var pct = Math.round(frac * 100);
            var quote = habitQuote((h.completions || 0) + pct);
            var el = document.createElement('div');
            el.className = 'md-mile-scrim';
            el.innerHTML =
                '<div class="md-mile">' +
                  '<div class="md-mile-pct">' + pct + '%</div>' +
                  '<div class="md-mile-name">' + modeEsc(h.activityName) + '</div>' +
                  '<div class="md-mile-count">' + (h.completions || 0) + ' of ' + targetDays + ' days</div>' +
                  '<p class="md-mile-quote">“' + modeEsc(quote) + '”</p>' +
                  '<button type="button" class="md-btn md-btn-primary md-btn-wide">Keep going</button>' +
                '</div>';
            document.body.appendChild(el);
            function close() { el.classList.add('is-leaving'); setTimeout(function () { el.remove(); }, 220); }
            el.querySelector('button').onclick = close;
            el.addEventListener('click', function (e) { if (e.target === el) close(); });
            setTimeout(close, 9000);
        }

        // ── The habit focus overlay (spec §1) ─────────────────────────────
        // Around the window, opening the app puts one habit in front of
        // everything else. It is a deliberate moment of friction, not a wall:
        // one tap clears it for the rest of the day — and one tap MARKS it,
        // right here. Sending someone off to another page to tick a box was
        // the long way round to the only thing this screen is asking for.
        function habitMaybeShowOverlay() {
            if (document.getElementById('modeHabitOverlay')) return;
            if (document.getElementById('modeResolveCard')) return;
            var h = habitOverlayDue();
            if (!h) return;
            var a = modesActive();
            var nowMins = modeMinutesNow();
            var s = modeMins(h.windowStart), e = modeMins(h.windowEnd);
            var before = nowMins < s;
            var after = !before && nowMins > e;
            var markable = modeCanMark(h.activityId);

            var el = document.createElement('div');
            el.id = 'modeHabitOverlay';
            el.className = 'md-ov';
            el.innerHTML =
                '<button type="button" class="md-ov-close" aria-label="Close">' +
                  '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
                '</button>' +
                '<div class="md-ov-inner">' +
                  '<div class="md-ov-eyebrow">' + (before ? 'Coming up' : after ? 'Window closing' : 'Right now') + '</div>' +
                  '<div class="md-ov-name">' + modeEsc(h.activityName) + '</div>' +
                  '<div class="md-ov-window">' + modeTimeLabel(h.windowStart) + ' – ' + modeTimeLabel(h.windowEnd) + '</div>' +
                  (h.anchor ? '<div class="md-ov-anchor">' + modeEsc(h.anchor) + '</div>' : '') +
                  (h.why ? '<p class="md-ov-why">“' + modeEsc(h.why) + '”</p>' : '') +
                  '<div class="md-ov-count">' + (h.completions || 0) + ' of ' + ((a && a.daysElapsed) || 0) + ' days achieved</div>' +
                  (markable
                    ? '<button type="button" class="md-btn md-btn-primary md-btn-wide md-ov-mark">Mark it done</button>'
                    : '<div class="md-ov-already">Already marked today</div>') +
                  '<button type="button" class="md-ov-later md-ov-go">Open the activity</button>' +
                  '<button type="button" class="md-ov-later">Not now</button>' +
                '</div>';
            document.body.appendChild(el);

            function leave() {
                el.classList.add('is-leaving');
                setTimeout(function () { el.remove(); }, 220);
            }
            function dismiss() {
                h.overlayDismissedDay = modesToday();
                saveUserData().catch(function () {});
                leave();
            }
            el.querySelector('.md-ov-close').onclick = dismiss;
            el.querySelector('.md-ov-later:not(.md-ov-go)').onclick = dismiss;
            el.querySelector('.md-ov-go').onclick = function () {
                dismiss();
                setTimeout(function () { window.modeGoToActivity(h.activityId); }, 260);
            };
            var mark = el.querySelector('.md-ov-mark');
            if (mark) mark.onclick = async function () {
                mark.disabled = true;
                var done = await window.modeMark(h.activityId);
                if (!done) { mark.disabled = false; return; }
                // Marked: the reason to be here is gone, so the overlay goes
                // too — and it does not come back today.
                h.overlayDismissedDay = modesToday();
                el.querySelector('.md-ov-inner').classList.add('is-marked');
                setTimeout(leave, 640);
            };
        }
        window.habitMaybeShowOverlay = habitMaybeShowOverlay;

        function modesShowInsuranceCheckIn(a, days) {
            var el = document.createElement('div');
            el.className = 'md-mile-scrim';
            el.innerHTML =
                '<div class="md-mile">' +
                  '<div class="md-mile-name">Insurance has been on ' + days + ' days</div>' +
                  '<p class="md-mile-quote">Still want it? It keeps running either way.</p>' +
                  '<div class="md-sheet-foot md-sheet-foot-2">' +
                    '<button type="button" class="md-btn" id="mdInsReview">Review it</button>' +
                    '<button type="button" class="md-btn md-btn-primary" id="mdInsKeep">Keep it on</button>' +
                  '</div>' +
                '</div>';
            document.body.appendChild(el);
            function close() { el.classList.add('is-leaving'); setTimeout(function () { el.remove(); }, 220); }
            el.querySelector('#mdInsKeep').onclick = close;
            el.querySelector('#mdInsReview').onclick = function () {
                close();
                setTimeout(function () { try { window.mkGoModes && window.mkGoModes(); } catch (e) {} }, 200);
            };
            el.addEventListener('click', function (e) { if (e.target === el) close(); });
        }

        // ══════════════════════════════════════════════════════════════════
        //  WIRING
        // ══════════════════════════════════════════════════════════════════

        (function () {
            var _orig = window.completeActivity;
            if (typeof _orig !== 'function') return;
            window.completeActivity = async function (di, pi, ai) {
                var act = null;
                try { act = window.userData.dimensions[di].paths[pi].activities[ai]; } catch (e) {}
                var before = act ? (act.completionCount || 0) : 0;
                await _orig.apply(this, arguments);
                // Only when the completion actually landed — canCompleteActivity
                // and the once-per-day guard both return early without one.
                if (act && (act.completionCount || 0) > before) {
                    try { modesOnCompletion(act); } catch (e) { console.warn('Mode completion hook failed', e); }
                }
            };
        })();

        (function () {
            var _orig = window.undoActivity;
            if (typeof _orig !== 'function') return;
            window.undoActivity = async function (di, pi, ai) {
                var act = null;
                try { act = window.userData.dimensions[di].paths[pi].activities[ai]; } catch (e) {}
                var before = act ? (act.completionCount || 0) : 0;
                await _orig.apply(this, arguments);
                if (act && (act.completionCount || 0) < before) {
                    try { modesOnUndo(act); } catch (e) { console.warn('Mode undo hook failed', e); }
                }
            };
        })();

        // Berserk repaints the whole app, so the class has to survive a theme
        // change and a tab switch.
        (function () {
            var _orig = window.applyThemePreset;
            if (typeof _orig !== 'function') return;
            window.applyThemePreset = function () {
                var r = _orig.apply(this, arguments);
                modesApplyTheme();
                return r;
            };
        })();

        (function () {
            var _orig = window.switchTab;
            if (typeof _orig !== 'function') return;
            window.switchTab = function () {
                var r = _orig.apply(this, arguments);
                modesRefreshBanner();
                return r;
            };
        })();

        // ════════════════════════════════════════════════════════════════════
        // ══ END MODES ═══════════════════════════════════════════════════════
        // ════════════════════════════════════════════════════════════════════
